export default Header;

import React from 'react';
import { GridSettings, GridImage } from '../types';

interface SidebarProps {
  settings: GridSettings;
  onSettingsChange: (settings: GridSettings) => void;
  onAddFile: () => void;
  onAddFolder: () => void;
  images: GridImage[];
}

const Sidebar: React.FC<SidebarProps> = ({ settings, onSettingsChange, onAddFile, onAddFolder, images }) => {
  const handleChange = (key: keyof GridSettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  const handleDownload = () => {
    const canvas = document.getElementById('grid-canvas') as HTMLCanvasElement;
    if (!canvas) return;

    const link = document.createElement('a');
    link.download = `grid-collage-${new Date().getTime()}.png`;
    link.href = canvas.toDataURL('image/png', 1.0);
    link.click();
  };

  return (
    <div className="space-y-8">
      {/* Upload Actions */}
      <div className="space-y-3">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Arquivos</h3>
        <button 
          onClick={onAddFile}
          className="w-full flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white py-2.5 px-4 rounded-lg font-medium transition-all shadow-md active:scale-95"
        >
          <i className="fas fa-file-upload"></i>
          Adicionar Arquivos
        </button>
        <button 
          onClick={onAddFolder}
          className="w-full flex items-center justify-center gap-2 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 py-2.5 px-4 rounded-lg font-medium transition-all shadow-sm active:scale-95"
        >
          <i className="fas fa-folder-open"></i>
          Importar Pasta
        </button>
      </div>

      {/* Grid Configuration */}
      <div className="space-y-4">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Configuração da Grid</h3>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-600">Largura (px)</label>
            <input 
              type="number" 
              value={settings.canvasWidth} 
              onChange={(e) => handleChange('canvasWidth', parseInt(e.target.value) || 0)}
              className="w-full border border-slate-200 rounded-md p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-600">Altura (px)</label>
            <input 
              type="number" 
              value={settings.canvasHeight} 
              onChange={(e) => handleChange('canvasHeight', parseInt(e.target.value) || 0)}
              className="w-full border border-slate-200 rounded-md p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
            />
          </div>
        </div>

        <div className="space-y-1">
          <label className="text-xs font-semibold text-slate-600">Colunas ({settings.columns})</label>
          <input 
            type="range" 
            min="1" 
            max="12" 
            value={settings.columns} 
            onChange={(e) => handleChange('columns', parseInt(e.target.value))}
            className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
          />
        </div>

        <div className="space-y-1">
          <label className="text-xs font-semibold text-slate-600">Espaçamento Interno ({settings.innerSpacing}px)</label>
          <input 
            type="range" 
            min="0" 
            max="100" 
            value={settings.innerSpacing} 
            onChange={(e) => handleChange('innerSpacing', parseInt(e.target.value))}
            className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
          />
        </div>

        <div className="space-y-1">
          <label className="text-xs font-semibold text-slate-600">Bordas Externas ({settings.outerMargin}px)</label>
          <input 
            type="range" 
            min="0" 
            max="200" 
            value={settings.outerMargin} 
            onChange={(e) => handleChange('outerMargin', parseInt(e.target.value))}
            className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
          />
        </div>

        <div className="space-y-1">
          <label className="text-xs font-semibold text-slate-600">Cor de Fundo</label>
          <div className="flex gap-2 items-center">
            <input 
              type="color" 
              value={settings.backgroundColor} 
              onChange={(e) => handleChange('backgroundColor', e.target.value)}
              className="w-10 h-10 border-none rounded-md cursor-pointer"
            />
            <span className="text-xs font-mono text-slate-500 uppercase">{settings.backgroundColor}</span>
          </div>
        </div>
      </div>

      {/* Export */}
      <div className="pt-4">
        <button 
          disabled={images.length === 0}
          onClick={handleDownload}
          className={`w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg font-bold transition-all shadow-md active:scale-95 ${
            images.length === 0 
            ? 'bg-slate-200 text-slate-400 cursor-not-allowed' 
            : 'bg-emerald-600 hover:bg-emerald-700 text-white'
          }`}
        >
          <i className="fas fa-download"></i>
          Salvar Imagem (Alta Qualidade)
        </button>
        <p className="text-[10px] text-center text-slate-400 mt-2">
          Exporta no formato PNG mantendo a resolução total.
        </p>
      </div>
    </div>
  );
};

export default Sidebar;

import React from 'react';
import { GridImage } from '../types';

interface ImageListProps {
  images: GridImage[];
  onRemove: (id: string) => void;
  onMove: (index: number, direction: 'up' | 'down') => void;
}

const ImageList: React.FC<ImageListProps> = ({ images, onRemove, onMove }) => {
  if (images.length === 0) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-8 text-slate-400 text-center">
        <i className="fas fa-images text-4xl mb-4 opacity-20"></i>
        <p className="text-sm">Nenhuma imagem adicionada ainda.</p>
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-y-auto p-4 space-y-3">
      {images.map((img, index) => (
        <div 
          key={img.id} 
          className="group flex items-center gap-3 bg-slate-50 border border-slate-200 p-2 rounded-lg hover:border-indigo-300 hover:bg-white transition-all shadow-sm"
        >
          <div className="w-12 h-12 flex-shrink-0 bg-slate-200 rounded overflow-hidden">
            <img src={img.previewUrl} alt="Preview" className="w-full h-full object-cover" />
          </div>

          <div className="flex-1 min-w-0">
            <p className="text-xs font-medium text-slate-700 truncate">{img.file.name}</p>
            <p className="text-[10px] text-slate-400">{img.width}x{img.height} px</p>
          </div>

          <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
            <div className="flex flex-col gap-1">
              <button 
                onClick={() => onMove(index, 'up')}
                disabled={index === 0}
                className={`p-1 text-slate-400 hover:text-indigo-600 transition-colors ${index === 0 ? 'invisible' : ''}`}
                title="Mover para cima"
              >
                <i className="fas fa-chevron-up text-[10px]"></i>
              </button>
              <button 
                onClick={() => onMove(index, 'down')}
                disabled={index === images.length - 1}
                className={`p-1 text-slate-400 hover:text-indigo-600 transition-colors ${index === images.length - 1 ? 'invisible' : ''}`}
                title="Mover para baixo"
              >
                <i className="fas fa-chevron-down text-[10px]"></i>
              </button>
            </div>
            <button 
              onClick={() => onRemove(img.id)}
              className="p-2 text-slate-400 hover:text-red-500 transition-colors"
              title="Remover"
            >
              <i className="fas fa-times"></i>
            </button>
          </div>
        </div>
      ))}
    </div>
  );
};

export default ImageList;

import React, { useRef, useEffect, useState } from 'react';
import { GridImage, GridSettings } from '../types';

interface GridPreviewProps {
  images: GridImage[];
  settings: GridSettings;
}

const GridPreview: React.FC<GridPreviewProps> = ({ images, settings }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [scaleFactor, setScaleFactor] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const renderGrid = async () => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // 1. Setup Canvas
      canvas.width = settings.canvasWidth;
      canvas.height = settings.canvasHeight;

      // 2. Background
      ctx.fillStyle = settings.backgroundColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      if (images.length === 0) return;

      // 3. Calculate Grid
      const cols = settings.columns;
      const margin = settings.outerMargin;
      const spacing = settings.innerSpacing;

      const availableWidth = canvas.width - (2 * margin) - ((cols - 1) * spacing);
      const cellWidth = availableWidth / cols;

      // In this mode, we calculate cell heights dynamically or keep them uniform
      // User requested "maintain aspect ratio", so we'll treat each row height
      // based on the images in it. To keep a "grid", we usually use uniform cells.
      // Let's implement uniform cells but fit images inside them preserving ratio.

      const rows = Math.ceil(images.length / cols);
      const availableHeight = canvas.height - (2 * margin) - ((rows - 1) * spacing);
      const cellHeight = availableHeight / rows;

      const loadAndDraw = async (imgObj: GridImage, index: number) => {
        return new Promise<void>((resolve) => {
          const col = index % cols;
          const row = Math.floor(index / cols);

          const x = margin + (col * (cellWidth + spacing));
          const y = margin + (row * (cellHeight + spacing));

          const img = new Image();
          img.onload = () => {
            // Calculate best fit maintaining aspect ratio (Object-fit: contain)
            let drawW = cellWidth;
            let drawH = cellWidth / imgObj.aspectRatio;

            if (drawH > cellHeight) {
              drawH = cellHeight;
              drawW = cellHeight * imgObj.aspectRatio;
            }

            const offsetX = x + (cellWidth - drawW) / 2;
            const offsetY = y + (cellHeight - drawH) / 2;

            ctx.drawImage(img, offsetX, offsetY, drawW, drawH);
            resolve();
          };
          img.src = imgObj.previewUrl;
        });
      };

      for (let i = 0; i < images.length; i++) {
        await loadAndDraw(images[i], i);
      }
    };

    renderGrid();
  }, [images, settings]);

  // Handle auto-scaling the preview to fit the container
  useEffect(() => {
    const handleResize = () => {
      if (!containerRef.current) return;
      const { clientWidth, clientHeight } = containerRef.current;
      const padding = 40;
      const scaleX = (clientWidth - padding) / settings.canvasWidth;
      const scaleY = (clientHeight - padding) / settings.canvasHeight;
      setScaleFactor(Math.min(scaleX, scaleY, 1)); // Don't scale up past original size
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.canvasWidth, settings.canvasHeight]);

  return (
    <div ref={containerRef} className="w-full h-full flex items-center justify-center overflow-hidden">
      <div 
        className="shadow-2xl bg-white border border-slate-300 relative"
        style={{
          width: settings.canvasWidth * scaleFactor,
          height: settings.canvasHeight * scaleFactor,
          transition: 'all 0.3s ease-out'
        }}
      >
        <canvas 
          id="grid-canvas"
          ref={canvasRef}
          style={{
            width: '100%',
            height: '100%',
            display: 'block'
          }}
        />

        {/* Dimensions Badge */}
        <div className="absolute -bottom-8 left-0 right-0 text-center">
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
            {settings.canvasWidth} x {settings.canvasHeight} px (Preview: {Math.round(scaleFactor * 100)}%)
          </span>
        </div>
      </div>

      {images.length === 0 && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-slate-300">
          <i className="fas fa-layer-group text-8xl mb-6 opacity-20"></i>
          <h2 className="text-xl font-semibold">Preview da Grid</h2>
          <p className="text-sm">Adicione imagens para começar a criar seu mural</p>
        </div>
      )}
    </div>
  );
};

export default GridPreview;

export interface GridImage {
  id: string;
  file: File;
  previewUrl: string;
  width: number;
  height: number;
  aspectRatio: number;
}

export interface GridSettings {
  canvasWidth: number;
  canvasHeight: number;
  columns: number;
  innerSpacing: number;
  outerMargin: number;
  backgroundColor: string;
  isTransparent: boolean;
  backgroundImageUrl?: string;
}

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import Sidebar from './components/Sidebar';
import GridPreview from './components/GridPreview';
import ImageList from './components/ImageList';
import Header from './components/Header';
import { GridImage, GridSettings } from './types';

const App: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [settings, setSettings] = useState<GridSettings>({
    canvasWidth: 2048,
    canvasHeight: 2048,
    columns: 3,
    innerSpacing: 5,
    outerMargin: 5,
    backgroundColor: '#0f172a',
    isTransparent: false
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  const processFiles = async (files: FileList | File[]) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    const newImagesPromises = Array.from(files)
      .filter(file => validTypes.includes(file.type))
      .map(file => {
        return new Promise<GridImage>((resolve) => {
          const img = new Image();
          const url = URL.createObjectURL(file);
          img.onload = () => {
            resolve({
              id: uuidv4(),
              file,
              previewUrl: url,
              width: img.width,
              height: img.height,
              aspectRatio: img.width / img.height
            });
          };
          img.src = url;
        });
      });

    const newImages = await Promise.all(newImagesPromises);
    setImages(prev => [...prev, ...newImages]);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      processFiles(e.target.files);
    }
    if (e.target) e.target.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => {
      const target = prev.find(img => img.id === id);
      if (target) URL.revokeObjectURL(target.previewUrl);
      return prev.filter(img => img.id !== id);
    });
  };

  const moveImage = (index: number, direction: 'up' | 'down') => {
    const newImages = [...images];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex >= 0 && targetIndex < newImages.length) {
      [newImages[index], newImages[targetIndex]] = [newImages[targetIndex], newImages[index]];
      setImages(newImages);
    }
  };

  const clearAll = () => {
    if (window.confirm('Tem certeza que deseja remover todos os itens?')) {
      images.forEach(img => URL.revokeObjectURL(img.previewUrl));
      setImages([]);
    }
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-950 text-slate-200">
      <Header itemCount={images.length} onClear={clearAll} />

      <main className="flex flex-1 overflow-hidden">
        {/* Sidebar Left: Settings */}
        <div className="w-80 flex-shrink-0 border-r border-slate-800 bg-slate-900 p-6 overflow-y-auto">
          <Sidebar 
            settings={settings} 
            onSettingsChange={setSettings} 
            onAddFile={() => fileInputRef.current?.click()}
            onAddFolder={() => folderInputRef.current?.click()}
            images={images}
          />
        </div>

        {/* Center: Preview */}
        <div className="flex-1 overflow-hidden relative flex flex-col items-center justify-center p-8 bg-slate-950">
           <GridPreview images={images} settings={settings} />
        </div>

        {/* Sidebar Right: Image List */}
        <div className="w-80 flex-shrink-0 border-l border-slate-800 bg-slate-900 overflow-hidden flex flex-col">
          <div className="p-4 border-b border-slate-800 font-semibold text-slate-200 flex justify-between items-center">
            <span>Ordem das Imagens</span>
            <span className="text-xs bg-indigo-900/50 text-indigo-300 px-2 py-1 rounded-full border border-indigo-500/30">
              {images.length} itens
            </span>
          </div>
          <ImageList 
            images={images} 
            onRemove={removeImage} 
            onMove={moveImage}
          />
        </div>
      </main>

      {/* Hidden inputs */}
      <input 
        type="file" 
        multiple 
        accept=".jpg,.jpeg,.png,.webp" 
        className="hidden" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
      />
      <input 
        type="file" 
        webkitdirectory="" 
        // @ts-ignore
        directory="" 
        className="hidden" 
        ref={folderInputRef} 
        onChange={handleFileChange} 
      />
    </div>
  );
};

export default App;

import React from 'react';

interface HeaderProps {
  itemCount: number;
  onClear: () => void;
}

const Header: React.FC<HeaderProps> = ({ itemCount, onClear }) => {
  return (
    <header className="h-16 border-b border-slate-800 bg-slate-900 px-6 flex items-center justify-between shadow-lg z-10">
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-indigo-500/20 shadow-md">
          <i className="fas fa-th-large text-xl"></i>
