      let filesArray = Array.from(e.target.files) as File[];

      // If the input is the folder input, filter out files in subdirectories
      if (e.target === folderInputRef.current) {
        filesArray = filesArray.filter(file => {
          // webkitRelativePath is "folderName/fileName.ext" for top-level
          // it is "folderName/subFolder/fileName.ext" for nested files
          // Fix: Safely access webkitRelativePath via casting to any
          const path = (file as any).webkitRelativePath || '';
          const pathParts = path.split('/');
          return pathParts.length === 2;
        });
      }

      processFiles(filesArray);
    }
    if (e.target) e.target.value = '';
  };

  const removeImage = (id: string) => {
