import React, { useState } from 'react';
import TopNav from './components/TopNav';
import GridTool from './tools/GridTool';
import ResizerTool from './tools/ResizerTool';
import FramingTool from './tools/FramingTool';

export type ToolType = 'grid' | 'framing' | 'resizer' | 'trim' | 'max-resize';
export type ThemeType = 'dark' | 'light' | 'pastel' | 'midnight';

const App: React.FC = () => {
  const [activeTool, setActiveTool] = useState<ToolType>('grid');
  const [theme, setTheme] = useState<ThemeType>('dark');

  const renderTool = () => {
    switch (activeTool) {
      case 'grid':
        return <GridTool />;
      case 'resizer':
        return <ResizerTool />;
      case 'framing':
        return <FramingTool />;
      default:
        return (
          <div className="flex-1 flex items-center justify-center opacity-50 bg-theme-main">
            <div className="text-center text-theme-main">
              <i className="fas fa-tools text-6xl mb-4"></i>
              <h2 className="text-2xl font-bold uppercase tracking-widest">Módulo em Desenvolvimento</h2>
              <p className="text-xs opacity-50 mt-2">Estamos preparando esta ferramenta para você.</p>
            </div>
          </div>
        );
    }
  };

  return (
    <div 
      className="flex flex-col h-screen overflow-hidden transition-colors duration-300" 
      data-theme={theme}
      style={{ backgroundColor: 'var(--bg-main)', color: 'var(--text-main)' }}
    >
      <TopNav 
        activeTool={activeTool} 
        onToolChange={setActiveTool} 
        currentTheme={theme}
        onThemeChange={setTheme}
      />

      <main className="flex-1 flex overflow-hidden">
        {renderTool()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import SidebarResizer from '../components/SidebarResizer';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage } from '../types';

export type ResizeMode = 'fit' | 'fill' | 'stretch';

const ResizerTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [settings, setSettings] = useState({
    width: 1080,
    height: 1080,
    mode: 'fit' as ResizeMode,
    lockAspectRatio: true
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      files.forEach(file => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          setImages(prev => [...prev, {
            id: uuidv4(),
            file,
            previewUrl: url,
            width: img.width,
            height: img.height,
            aspectRatio: img.width / img.height
          }]);
        };
        img.src = url;
      });
    }
  };

  const currentImg = images[selectedIdx];

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme">
        <SidebarResizer 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAdd={() => fileInputRef.current?.click()}
          onDownloadAll={() => alert('Download em massa iniciado...')}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden">
        <Header itemCount={images.length} onClear={() => setImages([])} />
        <div className="flex-1 flex items-center justify-center p-12 relative">
          {currentImg ? (
            <div className="relative group transition-all duration-500 shadow-2xl border border-theme"
                 style={{ 
                   width: settings.width * 0.4, 
                   height: settings.height * 0.4,
                   backgroundColor: 'var(--bg-panel)'
                 }}>
              <img 
                src={currentImg.previewUrl} 
                className={`w-full h-full ${settings.mode === 'fit' ? 'object-contain' : settings.mode === 'fill' ? 'object-cover' : 'object-fill'}`}
                alt="Preview" 
              />
              <div className="absolute -top-10 left-0 text-[10px] font-black uppercase opacity-40">Visualização de Saída</div>
            </div>
          ) : (
            <div className="text-center opacity-20">
              <i className="fas fa-expand-arrows-alt text-8xl mb-4"></i>
              <p className="font-black uppercase tracking-[0.2em]">Aguardando Imagens</p>
            </div>
          )}
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col">
        <div className="p-3 border-b border-theme font-black text-[10px] uppercase tracking-widest text-theme-muted">
          Fila de Processamento
        </div>
        <ImageList 
          images={images} 
          onRemove={(id) => setImages(images.filter(img => img.id !== id))}
          onMove={() => {}} 
        />
      </aside>
      <input type="file" multiple className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

