import React, { useState, useRef, useEffect } from 'react';
import { GridImage, FrameSettings } from '../types';

interface InteractiveEditorProps {
  loteImages: GridImage[];
  frameSettings: FrameSettings;
  onUpdateImage: (id: string, updates: Partial<GridImage>) => void;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
}

const InteractiveEditor: React.FC<InteractiveEditorProps> = ({ 
  loteImages, 
  frameSettings, 
  onUpdateImage,
  selectedId,
  onSelect
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [initialPos, setInitialPos] = useState({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent, img: GridImage) => {
    e.stopPropagation();
    onSelect(img.id);
    setIsDragging(true);
    setDragStart({ x: e.clientX, y: e.clientY });
    setInitialPos({ x: img.x || 0, y: img.y || 0 });
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (!isDragging || !selectedId) return;

    const dx = e.clientX - dragStart.x;
    const dy = e.clientY - dragStart.y;

    onUpdateImage(selectedId, {
      x: initialPos.x + dx,
      y: initialPos.y + dy
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, selectedId, dragStart, initialPos]);

  return (
    <div 
      ref={containerRef}
      className="relative shadow-2xl overflow-hidden border border-theme bg-theme-panel"
      style={{ 
        width: frameSettings.canvasWidth * 0.4, 
        height: frameSettings.canvasHeight * 0.4,
        backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)',
        backgroundSize: '20px 20px'
      }}
      onClick={() => onSelect(null)}
    >
      {/* Camada 1: Lote (Imagens Arrastáveis) */}
      {loteImages.map((img) => (
        <div
          key={img.id}
          className={`absolute cursor-move transition-shadow ${selectedId === img.id ? 'ring-2 ring-theme-accent' : ''}`}
          style={{
            left: (img.x || 0) * 0.4,
            top: (img.y || 0) * 0.4,
            width: (img.width * (img.scale || 1)) * 0.4,
            transform: `rotate(${img.rotation || 0}deg)`,
            zIndex: 10
          }}
          onMouseDown={(e) => handleMouseDown(e, img)}
        >
          <img src={img.previewUrl} className="w-full h-auto pointer-events-none select-none" />
        </div>
      ))}

      {/* Camada 2: Moldura (Fixa e no Topo) */}
      <div 
        className="absolute inset-0 pointer-events-none z-20"
        style={{
          border: frameSettings.frameImageUrl ? 'none' : `${frameSettings.borderWidth * 0.4}px solid ${frameSettings.borderColor}`,
          borderRadius: `${frameSettings.borderRadius * 0.4}px`,
        }}
      >
        {frameSettings.frameImageUrl && (
          <img src={frameSettings.frameImageUrl} className="w-full h-full object-fill" />
        )}
      </div>

      <div className="absolute -bottom-10 left-0 right-0 text-center opacity-40">
        <span className="text-[9px] font-black uppercase">Modo Interativo: Arraste as imagens atrás do frame</span>
      </div>
    </div>
  );
};

export default InteractiveEditor;

import React, { useState, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import SidebarFraming from '../components/SidebarFraming';
import InteractiveEditor from '../components/InteractiveEditor';
import Header from '../components/Header';
import { GridImage, FrameSettings } from '../types';

const FramingTool: React.FC = () => {
  const [loteImages, setLoteImages] = useState<GridImage[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [settings, setSettings] = useState<FrameSettings>({
    borderWidth: 20,
    borderColor: '#ffffff',
    borderRadius: 0,
    padding: 0,
    shadow: 10,
    canvasWidth: 1080,
    canvasHeight: 1080
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const frameInputRef = useRef<HTMLInputElement>(null);

  const handleLoteFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      files.forEach(file => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          setLoteImages(prev => [...prev, {
            id: uuidv4(),
            file,
            previewUrl: url,
            width: img.width,
            height: img.height,
            aspectRatio: img.width / img.height,
            x: 50,
            y: 50,
            scale: 0.5,
            rotation: 0
          }]);
        };
        img.src = url;
      });
    }
  };

  const handleFrameFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const url = URL.createObjectURL(file);
      const img = new Image();
      img.onload = () => {
        setSettings(prev => ({
          ...prev,
          frameImageUrl: url,
          frameImageName: file.name,
          canvasWidth: img.width,
          canvasHeight: img.height
        }));
      };
      img.src = url;
    }
  };

  const updateImage = (id: string, updates: Partial<GridImage>) => {
    setLoteImages(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
  };

  const moveLayer = (index: number, direction: 'up' | 'down') => {
    const newImages = [...loteImages];
    const target = direction === 'up' ? index - 1 : index + 1;
    if (target >= 0 && target < newImages.length) {
      [newImages[index], newImages[target]] = [newImages[target], newImages[index]];
      setLoteImages(newImages);
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarFraming 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddLote={() => fileInputRef.current?.click()}
          onAddFrame={() => frameInputRef.current?.click()}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden">
        <Header itemCount={loteImages.length} onClear={() => setLoteImages([])} />
        <div className="flex-1 flex items-center justify-center p-12">
          <InteractiveEditor 
            loteImages={loteImages}
            frameSettings={settings}
            selectedId={selectedId}
            onSelect={setSelectedId}
            onUpdateImage={updateImage}
          />
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col">
        {/* Camadas Partição 3 */}
        <div className="flex-1 flex flex-col overflow-hidden">

          {/* Seção 1: Overlays (Futuro) */}
          <div className="p-3 border-b border-theme bg-black/5">
             <span className="text-[9px] font-black uppercase tracking-widest opacity-40">Overlays / Extras</span>
             <div className="mt-2 text-[8px] opacity-30 italic">Nenhum item adicionado</div>
          </div>

          {/* Seção 2: Moldura Ativa */}
          <div className="p-3 border-b border-theme bg-theme-panel">
             <span className="text-[9px] font-black uppercase tracking-widest opacity-40">Moldura Ativa (Topo)</span>
             <div className="mt-2 flex items-center gap-2 p-2 rounded border border-theme bg-theme-side">
                <i className="fas fa-magic text-theme-accent"></i>
                <span className="text-[10px] font-bold truncate">
                  {settings.frameImageName || 'Moldura Gerada'}
                </span>
                <i className="fas fa-lock ml-auto text-[8px] opacity-30"></i>
             </div>
          </div>

          {/* Seção 3: Lote (Imagens) */}
          <div className="flex-1 flex flex-col overflow-hidden">
            <div className="p-3 bg-black/5 border-b border-theme flex justify-between items-center">
              <span className="text-[9px] font-black uppercase tracking-widest opacity-40">Imagens do Lote (Base)</span>
              <span className="text-[8px] bg-theme-accent text-white px-2 py-0.5 rounded-full">{loteImages.length}</span>
            </div>

            <div className="flex-1 overflow-y-auto p-2 space-y-1">
              {loteImages.map((img, idx) => (
                <div 
                  key={img.id}
                  onClick={() => setSelectedId(img.id)}
                  className={`flex items-center gap-2 p-2 rounded-lg border transition-all cursor-pointer ${selectedId === img.id ? 'border-theme-accent bg-theme-accent/5' : 'border-theme bg-theme-panel hover:bg-black/5'}`}
                >
                  <img src={img.previewUrl} className="w-8 h-8 rounded object-cover border border-theme" />
                  <span className="text-[10px] font-bold truncate flex-1">{img.file.name}</span>
                  <div className="flex gap-1">
                    <button onClick={(e) => { e.stopPropagation(); moveLayer(idx, 'up'); }} className="p-1 hover:text-theme-accent"><i className="fas fa-chevron-up text-[8px]"></i></button>
                    <button onClick={(e) => { e.stopPropagation(); setLoteImages(loteImages.filter(i => i.id !== img.id)); }} className="p-1 hover:text-red-500"><i className="fas fa-trash text-[8px]"></i></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </aside>

      <input type="file" multiple className="hidden" ref={fileInputRef} onChange={handleLoteFiles} />
      <input type="file" className="hidden" ref={frameInputRef} onChange={handleFrameFile} />
    </div>
  );
};

export default FramingTool;

import React from 'react';
import { FrameSettings } from '../types';

interface SidebarFramingProps {
  settings: FrameSettings;
  onSettingsChange: (s: FrameSettings) => void;
  onAddLote: () => void;
  onAddFrame: () => void;
}

const SidebarFraming: React.FC<SidebarFramingProps> = ({ settings, onSettingsChange, onAddLote, onAddFrame }) => {
  const handleChange = (key: keyof FrameSettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  return (
    <div className="p-6 space-y-8">
      <div className="space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Importação</h3>
        <div className="grid grid-cols-1 gap-2">
          <button onClick={onAddLote} className="w-full py-2.5 rounded-lg font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase">
            <i className="fas fa-layer-group"></i> Carregar Lote
          </button>
          <button onClick={onAddFrame} className="w-full py-2.5 rounded-lg font-black text-[10px] border border-theme bg-theme-panel text-theme-main shadow-sm flex items-center justify-center gap-2 uppercase hover:bg-black/5">
            <i className="fas fa-image"></i> Moldura Custom (PNG)
          </button>
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex justify-between items-center border-b border-theme pb-2">
           <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Ajustes do Frame</h3>
           {settings.frameImageUrl && (
             <button 
               onClick={() => handleChange('frameImageUrl', undefined)}
               className="text-[8px] font-black text-red-500 uppercase"
             >
               Remover Moldura
             </button>
           )}
        </div>

        {!settings.frameImageUrl ? (
          <div className="space-y-4 animate-in fade-in duration-300">
            {[
              { label: 'Borda (px)', key: 'borderWidth', min: 0, max: 200 },
              { label: 'Cantos (px)', key: 'borderRadius', min: 0, max: 200 },
              { label: 'Sombra', key: 'shadow', min: 0, max: 100 },
            ].map(ctrl => (
              <div key={ctrl.key} className="space-y-1.5">
                <div className="flex justify-between">
                  <label className="text-[9px] font-bold opacity-60 uppercase">{ctrl.label}</label>
                  <span className="text-[9px] font-black text-theme-accent">{(settings as any)[ctrl.key]}</span>
                </div>
                <input 
                  type="range" 
                  min={ctrl.min} max={ctrl.max} 
                  value={(settings as any)[ctrl.key]}
                  onChange={(e) => handleChange(ctrl.key as any, parseInt(e.target.value))}
                  className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer"
                  style={{ accentColor: 'var(--accent)' }}
                />
              </div>
            ))}

            <div className="flex items-center gap-2 pt-2">
              <input 
                type="color" 
                value={settings.borderColor}
                onChange={(e) => handleChange('borderColor', e.target.value)}
                className="w-10 h-8 bg-transparent cursor-pointer rounded border border-theme p-0.5"
              />
              <span className="text-[10px] font-mono opacity-50 uppercase">{settings.borderColor}</span>
            </div>
          </div>
        ) : (
          <div className="p-4 bg-theme-accent/5 rounded-xl border border-theme-accent/20 text-center">
            <i className="fas fa-info-circle text-theme-accent mb-2"></i>
            <p className="text-[9px] font-medium leading-relaxed opacity-70">
              Moldura personalizada ativa. Os controles de borda nativos foram desabilitados para priorizar o seu PNG.
            </p>
          </div>
        )}

        <div className="space-y-4 pt-4 border-t border-theme">
          <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Área de Trabalho</h3>
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="text-[8px] font-bold opacity-50 uppercase">Largura</label>
              <input 
                type="number" 
                value={settings.canvasWidth} 
                onChange={(e) => handleChange('canvasWidth', parseInt(e.target.value) || 0)}
                className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none"
              />
            </div>
            <div>
              <label className="text-[8px] font-bold opacity-50 uppercase">Altura</label>
              <input 
                type="number" 
                value={settings.canvasHeight} 
                onChange={(e) => handleChange('canvasHeight', parseInt(e.target.value) || 0)}
                className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none"
              />
            </div>
          </div>
        </div>
      </div>

      <div className="pt-4">
        <button className="w-full py-3 rounded-xl font-black text-xs bg-theme-accent text-theme-inv shadow-xl flex items-center justify-center gap-2 group relative overflow-hidden active:scale-95">
           <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
           <i className="fas fa-magic z-10"></i> <span className="z-10">Exportar Lote Emoldurado</span>
        </button>
      </div>
    </div>
  );
