                <i className="fas fa-lock text-[8px] opacity-30"></i>
             </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            <div className="p-3 bg-black/5 border-b border-theme flex justify-between items-center">
              <span className="text-[9px] font-black uppercase tracking-widest opacity-30">Imagens (Lote)</span>
              <span className="text-[8px] font-mono opacity-40">{loteImages.length} Camadas</span>
            </div>

            <div 
              className="flex-1 overflow-y-auto p-2 space-y-2"
              onDragLeave={() => setDragOverIndex(null)}
            >
              {loteImages.map((img, idx) => (
                <React.Fragment key={img.id}>
                  {/* Placeholder Visual quando o item é arrastado por cima */}
                  {dragOverIndex === idx && draggedIndex !== idx && (
                    <div className="h-12 border-2 border-dashed border-theme-accent/30 rounded-lg bg-theme-accent/5 animate-pulse transition-all"></div>
