                    onDrop={() => handleDrop(idx)}
                    onClick={() => setSelectedId(img.id)}
                    className={`group flex flex-col gap-2 p-2 rounded-lg border transition-all cursor-move relative
                      ${selectedId === img.id ? 'border-theme-accent bg-theme-accent/5 ring-1 ring-theme-accent/20 z-10' : 'border-theme bg-theme-panel hover:bg-black/5'}
