                        className="p-1.5 text-theme-muted hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <i className="fas fa-times text-[10px]"></i>
                      </button>
                    </div>

                    {selectedId === img.id && (
                      <div className="pt-2 mt-1 border-t border-theme-accent/10 space-y-3 p-1 animate-in slide-in-from-top-2 duration-300">
