    setLoteImages(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
  };

  const handleDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    const ghost = new Image();
    ghost.src = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
    e.dataTransfer.setDragImage(ghost, 0, 0);
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null) return;
    setDragOverIndex(index);
  };

  const handleDrop = (index: number) => {
    if (draggedIndex === null) return;
    const newImages = [...loteImages];
    const draggedItem = newImages[draggedIndex];
    newImages.splice(draggedIndex, 1);
    newImages.splice(index, 0, draggedItem);
    setLoteImages(newImages);
    setDraggedIndex(null);
    setDragOverIndex(null);
  };

  const clearAll = () => {
    if (window.confirm('Deseja limpar todas as imagens?')) {
      loteImages.forEach(img => URL.revokeObjectURL(img.previewUrl));
      setLoteImages([]);
      setSelectedId(null);
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarFraming 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddLote={() => fileInputRef.current?.click()}
          onAddFrame={() => frameInputRef.current?.click()}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden bg-theme-main relative">
        <Header itemCount={loteImages.length} onClear={clearAll} />

        {/* BARRA DE FERRAMENTAS DE SELEÇÃO (Top Toolbar) */}
        <div className={`h-14 border-b border-theme flex items-center px-6 gap-6 transition-all duration-300 ${!selectedImage ? 'opacity-20 grayscale pointer-events-none' : 'opacity-100'}`}
             style={{ backgroundColor: 'var(--bg-side)' }}>

          <div className="flex items-center gap-4 border-r border-theme pr-6">
             <div className="flex flex-col">
               <span className="text-[8px] font-black uppercase opacity-40">Transformar</span>
               <div className="flex items-center gap-2 mt-1">
                 <button onClick={() => updateImage(selectedId!, { rotation: (selectedImage?.rotation || 0) - 90 })} className="p-1.5 hover:bg-theme-accent/20 rounded border border-theme transition-colors">
                   <i className="fas fa-undo text-[10px]"></i>
                 </button>
                 <button onClick={() => updateImage(selectedId!, { rotation: (selectedImage?.rotation || 0) + 90 })} className="p-1.5 hover:bg-theme-accent/20 rounded border border-theme transition-colors">
                   <i className="fas fa-redo text-[10px]"></i>
                 </button>
               </div>
             </div>

             <div className="flex flex-col w-40">
               <div className="flex justify-between items-center mb-1">
                 <span className="text-[8px] font-black uppercase opacity-40">Escala</span>
                 <span className="text-[10px] font-mono font-black text-theme-accent">{Math.round((selectedImage?.scale || 1) * 100)}%</span>
               </div>
               <input 
                 type="range" min="0.05" max="3" step="0.01"
                 value={selectedImage?.scale || 1}
                 onChange={(e) => updateImage(selectedId!, { scale: parseFloat(e.target.value) })}
                 className="w-full h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer"
                 style={{ accentColor: 'var(--accent)' }}
               />
             </div>
          </div>

          <div className="flex items-center gap-6 text-theme-main">
            <div className="flex flex-col">
              <span className="text-[8px] font-black uppercase opacity-40">Posição</span>
              <div className="flex gap-2 font-mono text-[10px] mt-1">
                <span className="opacity-60">X:</span> <span className="font-bold text-theme-accent">{Math.round(selectedImage?.x || 0)}</span>
                <span className="opacity-60">Y:</span> <span className="font-bold text-theme-accent">{Math.round(selectedImage?.y || 0)}</span>
              </div>
            </div>

            <div className="flex flex-col">
              <span className="text-[8px] font-black uppercase opacity-40">Tamanho Atual</span>
              <div className="flex gap-2 font-mono text-[10px] mt-1">
                <span className="opacity-60">W:</span> <span className="font-bold">{Math.round((selectedImage?.width || 0) * (selectedImage?.scale || 1))}px</span>
                <span className="opacity-60">H:</span> <span className="font-bold">{Math.round((selectedImage?.height || 0) * (selectedImage?.scale || 1))}px</span>
              </div>
            </div>
          </div>

          <button 
            onClick={() => { setLoteImages(loteImages.filter(i => i.id !== selectedId)); setSelectedId(null); }}
            className="ml-auto px-3 py-1.5 rounded border border-red-500/30 text-red-500 text-[9px] font-black uppercase hover:bg-red-500 hover:text-white transition-all"
          >
            Remover Camada
          </button>
        </div>

        <div className="flex-1 flex items-center justify-center p-12 overflow-hidden">
          <InteractiveEditor 
            loteImages={loteImages}
            frameSettings={settings}
            selectedId={selectedId}
            onSelect={setSelectedId}
            onUpdateImage={updateImage}
          />
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col">
        <div className="flex-1 flex flex-col overflow-hidden">
          <div className="p-4 border-b border-theme bg-black/5 flex items-center justify-between">
             <span className="text-[10px] font-black uppercase tracking-widest opacity-40">Painel de Camadas</span>
             <i className="fas fa-layer-group text-[10px] opacity-20"></i>
          </div>

          <div className="p-3 border-b border-theme bg-theme-panel">
             <span className="text-[9px] font-black uppercase tracking-widest opacity-30 block mb-2">Camada de Moldura</span>
             <div className="flex items-center gap-2 p-2 rounded-lg border border-theme bg-theme-side shadow-sm">
                <i className="fas fa-magic text-theme-accent text-[10px]"></i>
                <span className="text-[10px] font-bold truncate flex-1">
                  {settings.frameImageName || 'Moldura do Sistema'}
                </span>
                <i className="fas fa-lock text-[8px] opacity-30"></i>
             </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            <div className="p-3 bg-black/5 border-b border-theme">
              <span className="text-[9px] font-black uppercase tracking-widest opacity-30">Conteúdo do Lote</span>
            </div>

            <div 
              className="flex-1 overflow-y-auto p-2 space-y-2"
              onDragLeave={() => setDragOverIndex(null)}
            >
              {loteImages.map((img, idx) => (
                <React.Fragment key={img.id}>
                  {dragOverIndex === idx && draggedIndex !== idx && (
                    <div className="h-14 border-2 border-dashed border-theme-accent/30 rounded-lg bg-theme-accent/5 animate-pulse transition-all"></div>
                  )}

                  <div 
                    draggable
                    onDragStart={(e) => handleDragStart(e, idx)}
                    onDragOver={(e) => handleDragOver(e, idx)}
                    onDragEnd={() => { setDraggedIndex(null); setDragOverIndex(null); }}
                    onDrop={() => handleDrop(idx)}
                    onClick={() => setSelectedId(img.id)}
                    className={`group flex items-center gap-3 p-2 rounded-lg border transition-all cursor-move relative
                      ${selectedId === img.id ? 'border-theme-accent bg-theme-accent/5 ring-1 ring-theme-accent/20 z-10 shadow-lg' : 'border-theme bg-theme-panel hover:bg-black/5'}
                      ${draggedIndex === idx ? 'opacity-20 scale-95 border-dashed' : 'opacity-100 scale-100 shadow-sm'}
                    `}
                  >
                    <div className="flex flex-col gap-0.5 opacity-20 group-hover:opacity-100 transition-opacity">
                      <div className="w-3 h-[1.5px] bg-current"></div>
                      <div className="w-3 h-[1.5px] bg-current"></div>
                      <div className="w-3 h-[1.5px] bg-current"></div>
                    </div>

                    <div className="relative">
                      <img src={img.previewUrl} className="w-10 h-10 rounded-md object-cover border border-theme bg-white shadow-inner" />
                      <div className="absolute -top-1.5 -left-1.5 w-4 h-4 rounded-full bg-theme-panel border border-theme flex items-center justify-center text-[7px] font-black">
                        {loteImages.length - idx}
                      </div>
                    </div>

                    <div className="flex-1 min-w-0">
                      <span className="text-[10px] font-bold truncate block">{img.file.name}</span>
                      <span className="text-[8px] opacity-40 uppercase tracking-widest">{img.width}x{img.height}</span>
                    </div>

                    <div className={`transition-opacity ${selectedId === img.id ? 'opacity-100' : 'opacity-0'}`}>
                       <i className="fas fa-edit text-theme-accent text-[8px]"></i>
                    </div>
                  </div>
                </React.Fragment>
              ))}

              {dragOverIndex === loteImages.length && draggedIndex !== null && (
                <div className="h-14 border-2 border-dashed border-theme-accent/30 rounded-lg bg-theme-accent/5 animate-pulse"></div>
              )}
            </div>
          </div>
        </div>
      </aside>

      <input type="file" multiple className="hidden" ref={fileInputRef} onChange={handleLoteFiles} />
      <input type="file" className="hidden" ref={frameInputRef} onChange={handleFrameFile} />
    </div>
  );
};

export default FramingTool;

import React, { useState } from 'react';
import TopNav from './components/TopNav';
import GridTool from './tools/GridTool';
import ResizerTool from './tools/ResizerTool';
import FramingTool from './tools/FramingTool';

export type ToolType = 'grid' | 'framing' | 'resizer' | 'trim' | 'max-resize';
export type ThemeType = 'dark' | 'light' | 'pastel' | 'midnight';

const App: React.FC = () => {
  const [activeTool, setActiveTool] = useState<ToolType>('framing');
  const [theme, setTheme] = useState<ThemeType>('midnight');

  const renderTool = () => {
    switch (activeTool) {
      case 'grid':
        return <GridTool />;
      case 'resizer':
        return <ResizerTool />;
      case 'framing':
        return <FramingTool />;
      default:
        return (
          <div className="flex-1 flex items-center justify-center opacity-50 bg-theme-main">
            <div className="text-center text-theme-main">
              <i className="fas fa-tools text-6xl mb-4"></i>
              <h2 className="text-2xl font-bold uppercase tracking-widest">Módulo em Desenvolvimento</h2>
              <p className="text-xs opacity-50 mt-2">Estamos preparando esta ferramenta para você.</p>
            </div>
          </div>
        );
    }
  };

  return (
    <div 
      className="flex flex-col h-screen overflow-hidden transition-colors duration-300" 
      data-theme={theme}
      style={{ backgroundColor: 'var(--bg-main)', color: 'var(--text-main)' }}
    >
      <TopNav 
        activeTool={activeTool} 
        onToolChange={setActiveTool} 
        currentTheme={theme}
        onThemeChange={setTheme}
      />

      <main className="flex-1 flex overflow-hidden">
        {renderTool()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import SidebarFraming from '../components/SidebarFraming';
import InteractiveEditor from '../components/InteractiveEditor';
import Header from '../components/Header';
import { GridImage, FrameSettings } from '../types';

interface BatchItemState {
  x: number;
  y: number;
  scale: number;
  rotation: number;
}

const FramingTool: React.FC = () => {
  // Lote Principal (Sequencial)
  const [mainBatch, setMainBatch] = useState<GridImage[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [batchStates, setBatchStates] = useState<Record<string, BatchItemState>>({});
  const [autoSave, setAutoSave] = useState(true);

  // Elementos Extras (Camadas livres)
  const [extraLayers, setExtraLayers] = useState<GridImage[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const [settings, setSettings] = useState<FrameSettings>({
    borderWidth: 20,
    borderColor: '#ffffff',
    borderRadius: 0,
    padding: 0,
    shadow: 10,
    canvasWidth: 1080,
    canvasHeight: 1080
  });

  const mainFileInputRef = useRef<HTMLInputElement>(null);
  const extraFileInputRef = useRef<HTMLInputElement>(null);
  const frameInputRef = useRef<HTMLInputElement>(null);

  // Imagem atual do lote principal
  const currentMainImage = mainBatch[currentIndex];

  // Recupera ou cria o estado para a imagem atual do lote
  const currentTransform = useMemo(() => {
    if (!currentMainImage) return null;
    return batchStates[currentMainImage.id] || {
      x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1),
      y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1),
      scale: 0.2,
      rotation: 0
    };
  }, [currentMainImage, batchStates, settings.canvasWidth, settings.canvasHeight]);

  const selectedElement = useMemo(() => {
    if (selectedId === 'main') return { ...currentMainImage, ...currentTransform };
    return extraLayers.find(img => img.id === selectedId);
  }, [selectedId, currentMainImage, currentTransform, extraLayers]);

  const handleMainFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const newImages: GridImage[] = [];
      files.forEach(file => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          setMainBatch(prev => [...prev, {
            id: uuidv4(),
            file,
            previewUrl: url,
            width: img.width,
            height: img.height,
            aspectRatio: img.width / img.height
          }]);
        };
        img.src = url;
      });
    }
  };

  const handleExtraFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      files.forEach(file => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          setExtraLayers(prev => [...prev, {
            id: uuidv4(),
            file,
            previewUrl: url,
            width: img.width,
            height: img.height,
            aspectRatio: img.width / img.height,
            x: 100,
            y: 100,
            scale: 0.15,
            rotation: 0
          }]);
        };
        img.src = url;
      });
    }
  };

  const updateTransform = (id: string, updates: Partial<BatchItemState | GridImage>) => {
    if (id === 'main' && currentMainImage) {
      setBatchStates(prev => ({
        ...prev,
        [currentMainImage.id]: { ...currentTransform!, ...updates as any }
      }));
    } else {
      setExtraLayers(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
    }
  };

  const handleNext = () => {
    if (currentIndex < mainBatch.length - 1) {
      if (autoSave) { /* Logica futura de push para queue de export */ }
      setCurrentIndex(prev => prev + 1);
      setSelectedId('main');
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
      setSelectedId('main');
    }
  };

  const clearAll = () => {
    if (window.confirm('Limpar projeto?')) {
      setMainBatch([]);
      setExtraLayers([]);
      setBatchStates({});
      setCurrentIndex(0);
      setSelectedId(null);
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarFraming 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddLote={() => mainFileInputRef.current?.click()}
          onAddExtras={() => extraFileInputRef.current?.click()}
          onAddFrame={() => frameInputRef.current?.click()}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden bg-theme-main relative">
        <Header itemCount={mainBatch.length + extraLayers.length} onClear={clearAll} />

        {/* TOOLBAR DE NAVEGAÇÃO E CONTROLE */}
        <div className="h-16 border-b border-theme flex items-center px-6 justify-between bg-theme-side/50 backdrop-blur-sm">

          {/* Navegação de Lote */}
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-1 bg-black/20 p-1 rounded-lg border border-theme">
              <button 
                disabled={currentIndex === 0}
                onClick={handlePrev}
                className="w-10 h-10 flex items-center justify-center rounded-md hover:bg-theme-accent/20 disabled:opacity-20 transition-all"
              >
                <i className="fas fa-chevron-left"></i>
              </button>
              <div className="px-4 text-center min-w-[100px]">
                <span className="block text-[8px] font-black uppercase opacity-40">Progresso</span>
                <span className="text-[11px] font-mono font-bold">
                  {mainBatch.length > 0 ? `${currentIndex + 1} / ${mainBatch.length}` : '0 / 0'}
                </span>
              </div>
              <button 
                disabled={currentIndex >= mainBatch.length - 1}
                onClick={handleNext}
                className="w-10 h-10 flex items-center justify-center rounded-md hover:bg-theme-accent/20 disabled:opacity-20 transition-all"
              >
                <i className="fas fa-chevron-right"></i>
              </button>
            </div>

            <label className="flex items-center gap-2 cursor-pointer group">
              <div className={`w-4 h-4 rounded border border-theme flex items-center justify-center transition-all ${autoSave ? 'bg-theme-accent border-theme-accent' : 'bg-transparent'}`}>
                {autoSave && <i className="fas fa-check text-[8px] text-white"></i>}
                <input type="checkbox" className="hidden" checked={autoSave} onChange={e => setAutoSave(e.target.checked)} />
              </div>
              <span className="text-[9px] font-black uppercase opacity-50 group-hover:opacity-100 transition-opacity">Salvar ao Avançar</span>
            </label>
          </div>

          {/* Ferramentas de Transformação */}
          <div className={`flex items-center gap-6 transition-all ${!selectedElement ? 'opacity-20 grayscale pointer-events-none' : 'opacity-100'}`}>
            <div className="flex flex-col">
              <span className="text-[8px] font-black uppercase opacity-40">Posição</span>
              <div className="flex gap-2 font-mono text-[10px] mt-1">
                <span className="opacity-40">X:</span> <span className="text-theme-accent font-bold">{Math.round(selectedElement?.x || 0)}</span>
                <span className="opacity-40 ml-2">Y:</span> <span className="text-theme-accent font-bold">{Math.round(selectedElement?.y || 0)}</span>
              </div>
            </div>

            <div className="flex flex-col">
               <span className="text-[8px] font-black uppercase opacity-40">Tamanho</span>
               <div className="flex gap-2 font-mono text-[10px] mt-1">
                 <span className="opacity-40">W:</span> <span>{Math.round((selectedElement?.width || 0) * (selectedElement?.scale || 1))}px</span>
               </div>
            </div>

            <div className="w-32 flex flex-col">
               <div className="flex justify-between items-center mb-1">
                 <span className="text-[8px] font-black uppercase opacity-40">Escala</span>
                 <span className="text-[9px] font-mono text-theme-accent">{Math.round((selectedElement?.scale || 1) * 100)}%</span>
               </div>
               <input 
                 type="range" min="0.01" max="3" step="0.01"
                 value={selectedElement?.scale || 1}
                 onChange={(e) => updateTransform(selectedId!, { scale: parseFloat(e.target.value) })}
                 className="w-full h-1 bg-theme-accent/20 rounded-lg appearance-none cursor-pointer accent-theme-accent"
               />
            </div>

            <div className="flex gap-1">
               <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) - 90 })} className="p-2 border border-theme rounded hover:bg-theme-accent/10"><i className="fas fa-undo text-[10px]"></i></button>
               <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) + 90 })} className="p-2 border border-theme rounded hover:bg-theme-accent/10"><i className="fas fa-redo text-[10px]"></i></button>
            </div>
          </div>
        </div>

        <div className="flex-1 flex items-center justify-center p-12 overflow-hidden">
          <InteractiveEditor 
            loteImages={extraLayers}
            mainImage={currentMainImage ? { ...currentMainImage, ...currentTransform! } : null}
            frameSettings={settings}
            selectedId={selectedId}
            onSelect={setSelectedId}
            onUpdateImage={updateTransform}
          />
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col">
        {/* Lista de Fila (Main Batch) */}
        <div className="flex-1 flex flex-col border-b border-theme overflow-hidden">
          <div className="p-4 bg-black/5 flex justify-between items-center">
            <span className="text-[10px] font-black uppercase tracking-widest opacity-40">Fila do Lote</span>
            <span className="text-[9px] font-mono bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">{mainBatch.length}</span>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {mainBatch.map((img, idx) => (
              <div 
                key={img.id}
                onClick={() => { setCurrentIndex(idx); setSelectedId('main'); }}
                className={`flex items-center gap-3 p-2 rounded-lg border transition-all cursor-pointer ${currentIndex === idx ? 'border-theme-accent bg-theme-accent/10' : 'border-transparent hover:bg-black/5 opacity-60'}`}
              >
                <img src={img.previewUrl} className="w-8 h-8 rounded object-cover border border-theme" />
                <span className="text-[10px] font-bold truncate flex-1">{img.file.name}</span>
                {currentIndex === idx && <i className="fas fa-play text-theme-accent text-[8px] animate-pulse"></i>}
              </div>
            ))}
          </div>
        </div>

        {/* Lista de Extras (Layers) */}
        <div className="h-1/3 flex flex-col overflow-hidden">
          <div className="p-4 bg-black/5 flex justify-between items-center">
            <span className="text-[10px] font-black uppercase tracking-widest opacity-40">Elementos Extras</span>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-2">
            {extraLayers.map(img => (
              <div 
                key={img.id}
                onClick={() => setSelectedId(img.id)}
                className={`flex items-center gap-3 p-2 rounded-lg border transition-all cursor-pointer ${selectedId === img.id ? 'border-theme-accent bg-theme-accent/5' : 'border-theme bg-theme-panel'}`}
              >
                <img src={img.previewUrl} className="w-8 h-8 rounded object-cover border border-theme" />
                <span className="text-[10px] font-medium truncate flex-1">{img.file.name}</span>
                <button onClick={(e) => { e.stopPropagation(); setExtraLayers(extraLayers.filter(l => l.id !== img.id)); }} className="text-theme-muted hover:text-red-500"><i className="fas fa-times text-[10px]"></i></button>
              </div>
            ))}
            {extraLayers.length === 0 && <div className="text-center py-8 opacity-20 text-[9px] font-bold uppercase">Nenhum extra</div>}
          </div>
        </div>
      </aside>

      <input type="file" multiple accept="image/*" className="hidden" ref={mainFileInputRef} onChange={handleMainFiles} />
      <input type="file" multiple accept="image/*" className="hidden" ref={extraFileInputRef} onChange={handleExtraFiles} />
      <input type="file" accept="image/png" className="hidden" ref={frameInputRef} onChange={handleFrameFile} />
    </div>
  );
};

export default FramingTool;

import React from 'react';
import { FrameSettings } from '../types';

