              <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) + 90 })} className="w-8 h-8 flex items-center justify-center border border-theme rounded hover:bg-theme-accent/10 transition-colors"><i className="fas fa-redo text-[10px]"></i></button>
            </div>

            <button 
              onClick={() => {
                if(selectedId === 'main') return;
                setExtraLayers(prev => prev.filter(l => l.id !== selectedId));
                setSelectedId(null);
              }}
              disabled={selectedId === 'main'}
              className="ml-4 text-[9px] font-black uppercase tracking-tighter text-red-500/50 hover:text-red-500 transition-colors disabled:opacity-0"
            >
