             {/* INDICADOR DE DIMENSÃO DO CANVAS */}
             <div className="bg-theme-side/80 backdrop-blur-md border border-theme px-4 py-2 rounded-xl shadow-lg animate-in slide-in-from-right-4 duration-700 delay-100">
                <div className="flex flex-col">
                  <span className="text-[7px] font-black uppercase opacity-40 tracking-widest mb-0.5">Dimensões Finais</span>
                  <div className="flex items-center gap-2 text-[11px] font-mono font-black text-theme-main">
                    <span className="text-theme-accent">{settings.canvasWidth}</span>
                    <span className="opacity-20">×</span>
                    <span className="text-theme-accent">{settings.canvasHeight}</span>
