          </div>
        </div>
      </div>

      <div className="pt-4 space-y-4 border-t border-theme">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Modo de Saída</h3>

        <div className="grid grid-cols-1 gap-2">
          <button 
            onClick={() => toggleIndividual(true)}
            className={`flex items-center gap-3 p-3 rounded-xl border transition-all text-left ${exportOptions.downloadIndividual ? 'bg-theme-accent/10 border-theme-accent shadow-sm' : 'bg-theme-panel/30 border-theme opacity-60 hover:opacity-100'}`}
          >
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadIndividual ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
              {exportOptions.downloadIndividual && <div className="w-1.5 h-1.5 rounded-full bg-white"></div>}
            </div>
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase leading-tight">Arquivos Separados</span>
              <span className="text-[8px] opacity-50 uppercase">Download um por um</span>
            </div>
          </button>

          <button 
            onClick={() => toggleZip(true)}
            className={`flex items-center gap-3 p-3 rounded-xl border transition-all text-left ${exportOptions.downloadZip ? 'bg-theme-accent/10 border-theme-accent shadow-sm' : 'bg-theme-panel/30 border-theme opacity-60 hover:opacity-100'}`}
          >
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadZip ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
              {exportOptions.downloadZip && <div className="w-1.5 h-1.5 rounded-full bg-white"></div>}
            </div>
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase leading-tight">Pacote Compactado</span>
              <span className="text-[8px] opacity-50 uppercase">Tudo em um arquivo .ZIP</span>
            </div>
          </button>
        </div>
      </div>

      <div className="pt-4 space-y-4 mt-auto">
        <label className="flex items-center gap-3 p-3 rounded-lg border border-theme bg-theme-panel/50 cursor-pointer group transition-all hover:bg-theme-accent/5 active:scale-[0.98]">
          <div className={`w-4 h-4 rounded border border-theme flex items-center justify-center transition-all ${autoSave ? 'bg-theme-accent border-theme-accent' : 'bg-transparent'}`}>
            {autoSave && <i className="fas fa-check text-[8px] text-white"></i>}
            <input type="checkbox" className="hidden" checked={autoSave} onChange={e => onAutoSaveChange(e.target.checked)} />
          </div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase tracking-tight text-theme-main">Salvar ao Avançar</span>
            <span className="text-[8px] opacity-40 uppercase">Avança e prepara exportação</span>
          </div>
        </label>

        <button 
          onClick={onProcessAll}
          disabled={isProcessing || total === 0}
          className="w-full py-4 rounded-xl font-black text-[11px] bg-theme-accent text-theme-inv shadow-2xl flex items-center justify-center gap-2 group relative overflow-hidden active:scale-95 uppercase tracking-widest transition-all disabled:opacity-50 disabled:grayscale"
        >
           <div className="absolute inset-0 bg-white/20 opacity-0 group-hover:opacity-100 transition-opacity"></div>
           {isProcessing ? (
             <>
               <i className="fas fa-spinner animate-spin z-10"></i>
               <span className="z-10">Processando {progress}/{total}...</span>
             </>
           ) : (
             <>
               <i className="fas fa-file-export z-10"></i> 
               <span className="z-10">Processar Todas</span>
             </>
           )}
        </button>
      </div>
    </div>
  );
};

export default SidebarFraming;

import React, { useState, useRef, useMemo } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarFraming from '../components/SidebarFraming';
import InteractiveEditor from '../components/InteractiveEditor';
import Header from '../components/Header';
import { GridImage, FrameSettings } from '../types';

interface BatchItemState {
  x: number;
  y: number;
  scale: number;
  rotation: number;
}

const FramingTool: React.FC = () => {
  const [mainBatch, setMainBatch] = useState<GridImage[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [batchStates, setBatchStates] = useState<Record<string, BatchItemState>>({});
  const [autoSave, setAutoSave] = useState(true);
  const [extraLayers, setExtraLayers] = useState<GridImage[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [zoom, setZoom] = useState(0.4); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);

  // Opções de Exportação
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);

  const [settings, setSettings] = useState<FrameSettings>({
    borderWidth: 20,
    borderColor: '#ffffff',
    borderRadius: 0,
    padding: 0,
    shadow: 10,
    canvasWidth: 1080,
    canvasHeight: 1080
  });

  const mainFileInputRef = useRef<HTMLInputElement>(null);
  const extraFileInputRef = useRef<HTMLInputElement>(null);
  const frameInputRef = useRef<HTMLInputElement>(null);

  const currentMainImage = mainBatch[currentIndex];

  const currentTransform = useMemo(() => {
    if (!currentMainImage) return null;
    return batchStates[currentMainImage.id] || {
      x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1),
      y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1),
      scale: 0.2,
      rotation: 0
    };
  }, [currentMainImage, batchStates, settings.canvasWidth, settings.canvasHeight]);

  const selectedElement = useMemo(() => {
    if (selectedId === 'main') return { ...currentMainImage, ...currentTransform };
    return extraLayers.find(img => img.id === selectedId);
  }, [selectedId, currentMainImage, currentTransform, extraLayers]);

  const handleMainFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      files.forEach(file => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          setMainBatch(prev => [...prev, {
            id: uuidv4(),
            file,
            previewUrl: url,
            width: img.width,
            height: img.height,
            aspectRatio: img.width / img.height
          }]);
        };
        img.src = url;
      });
    }
  };

  const handleExtraFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      files.forEach(file => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          setExtraLayers(prev => [...prev, {
            id: uuidv4(),
            file,
            previewUrl: url,
            width: img.width,
            height: img.height,
            aspectRatio: img.width / img.height,
            x: 100,
            y: 100,
            scale: 0.15,
            rotation: 0
          }]);
        };
        img.src = url;
      });
    }
  };

  const handleFrameFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const url = URL.createObjectURL(file);
      const img = new Image();
      img.onload = () => {
        setSettings(prev => ({
          ...prev,
          frameImageUrl: url,
          frameImageName: file.name,
          canvasWidth: img.width,
          canvasHeight: img.height
        }));
      };
      img.src = url;
    }
    if (e.target) e.target.value = '';
  };

  const updateTransform = (id: string, updates: Partial<BatchItemState | GridImage>) => {
    if (id === 'main' && currentMainImage) {
      setBatchStates(prev => ({
        ...prev,
        [currentMainImage.id]: { ...currentTransform!, ...updates as any }
      }));
    } else {
      setExtraLayers(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
    }
  };

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = url;
    });
  };

  const handleProcessAll = async () => {
    if (mainBatch.length === 0) return;
    if (!downloadIndividual && !downloadZip) {
      alert("Selecione pelo menos uma opção de exportação (Individual ou ZIP).");
      return;
    }

    setIsProcessing(true);
    setProcessProgress(0);

    const canvas = document.createElement('canvas');
    canvas.width = settings.canvasWidth;
    canvas.height = settings.canvasHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const zip = downloadZip ? new JSZip() : null;

    try {
      // Pré-carregar extras e moldura (não mudam por imagem)
      const extraImgs = await Promise.all(extraLayers.map(l => loadImage(l.previewUrl)));
      let frameImg: HTMLImageElement | null = null;
      if (settings.frameImageUrl) {
        frameImg = await loadImage(settings.frameImageUrl);
      }

      // Referência do transform atual para usar como "Template" em imagens não mexidas
      const templateTransform = currentTransform || {
        x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1),
        y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1),
        scale: 0.2,
        rotation: 0
      };

      for (let i = 0; i < mainBatch.length; i++) {
        setProcessProgress(i + 1);
        const item = mainBatch[i];

        // CORREÇÃO: Usa o estado específico SE existir, senão usa o template da imagem atual
        const transform = batchStates[item.id] || { ...templateTransform };

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // 1. Desenhar Imagem Principal
        const mainImgObj = await loadImage(item.previewUrl);
        ctx.save();
        const drawW = item.width * transform.scale;
        const drawH = item.height * transform.scale;

        ctx.translate(transform.x + drawW / 2, transform.y + drawH / 2);
        ctx.rotate((transform.rotation * Math.PI) / 180);
        ctx.drawImage(mainImgObj, -drawW / 2, -drawH / 2, drawW, drawH);
        ctx.restore();

        // 2. Desenhar Extras
        extraLayers.forEach((layer, idx) => {
          ctx.save();
          const lW = layer.width * (layer.scale || 1);
          const lH = layer.height * (layer.scale || 1);
          ctx.translate((layer.x || 0) + lW / 2, (layer.y || 0) + lH / 2);
          ctx.rotate(((layer.rotation || 0) * Math.PI) / 180);
          ctx.drawImage(extraImgs[idx], -lW / 2, -lH / 2, lW, lH);
          ctx.restore();
        });

        // 3. Desenhar Moldura
        if (frameImg) {
          ctx.drawImage(frameImg, 0, 0, canvas.width, canvas.height);
        } else {
          ctx.strokeStyle = settings.borderColor;
          ctx.lineWidth = settings.borderWidth;
          if (settings.borderRadius > 0) {
            ctx.beginPath();
            ctx.roundRect(settings.borderWidth / 2, settings.borderWidth / 2, canvas.width - settings.borderWidth, canvas.height - settings.borderWidth, settings.borderRadius);
            ctx.stroke();
          } else {
            ctx.strokeRect(settings.borderWidth / 2, settings.borderWidth / 2, canvas.width - settings.borderWidth, canvas.height - settings.borderWidth);
          }
        }

        const dataUrl = canvas.toDataURL('image/png');
        const fileName = `miau_framed_${item.file.name.split('.')[0]}.png`;

        // 4. Download Individual
        if (downloadIndividual) {
          const link = document.createElement('a');
          link.download = fileName;
          link.href = dataUrl;
          document.body.appendChild(link); // Garantia de funcionamento em alguns navegadores
          link.click();
          document.body.removeChild(link);
          await new Promise(r => setTimeout(r, 400)); // Delay um pouco maior para evitar bloqueios
        }

        // 5. Adicionar ao ZIP
        if (zip) {
          const base64Data = dataUrl.split(',')[1];
          zip.file(fileName, base64Data, { base64: true });
        }
      }

      // Finalizar e baixar ZIP
      if (zip) {
        const content = await zip.generateAsync({ type: "blob" });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(content);
        link.download = `miau_lote_processado_${new Date().getTime()}.zip`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      }

    } catch (err) {
      console.error("Erro ao processar lote:", err);
      alert("Ocorreu um erro ao gerar as imagens.");
    } finally {
      setIsProcessing(false);
      setProcessProgress(0);
    }
  };

  const handleNext = () => {
    if (currentIndex < mainBatch.length - 1) {
      setCurrentIndex(prev => prev + 1);
      setSelectedId('main');
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
      setSelectedId('main');
    }
  };

  const clearAll = () => {
    if (window.confirm('Limpar projeto?')) {
      mainBatch.forEach(img => URL.revokeObjectURL(img.previewUrl));
      extraLayers.forEach(img => URL.revokeObjectURL(img.previewUrl));
      setMainBatch([]);
      setExtraLayers([]);
      setBatchStates({});
      setCurrentIndex(0);
      setSelectedId(null);
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarFraming 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddLote={() => mainFileInputRef.current?.click()}
          onAddExtras={() => extraFileInputRef.current?.click()}
          onAddFrame={() => frameInputRef.current?.click()}
          autoSave={autoSave}
          onAutoSaveChange={setAutoSave}
          onProcessAll={handleProcessAll}
          isProcessing={isProcessing}
          progress={processProgress}
          total={mainBatch.length}
          exportOptions={{
            downloadIndividual,
            setDownloadIndividual,
            downloadZip,
            setDownloadZip
          }}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden bg-theme-main relative">
        <Header itemCount={mainBatch.length + extraLayers.length} onClear={clearAll} />

        <div className="h-14 border-b border-theme flex items-center px-6 gap-8 bg-theme-side/30 backdrop-blur-sm">
          <div className={`flex items-center gap-8 transition-all duration-300 ${!selectedElement ? 'opacity-20 grayscale pointer-events-none' : 'opacity-100'}`}>
            <div className="flex flex-col">
              <span className="text-[8px] font-black uppercase opacity-40">Posição Atual</span>
              <div className="flex gap-3 font-mono text-[10px] mt-1">
                <span className="opacity-40">X:</span> <span className="text-theme-accent font-bold">{Math.round(selectedElement?.x || 0)}</span>
                <span className="opacity-40 ml-1">Y:</span> <span className="text-theme-accent font-bold">{Math.round(selectedElement?.y || 0)}</span>
              </div>
            </div>

            <div className="flex flex-col">
              <span className="text-[8px] font-black uppercase opacity-40">Dimensão</span>
              <div className="flex gap-2 font-mono text-[10px] mt-1">
                <span className="opacity-40">W:</span> <span>{Math.round((selectedElement?.width || 0) * (selectedElement?.scale || 1))}px</span>
              </div>
            </div>

            <div className="w-40 flex flex-col">
              <div className="flex justify-between items-center mb-1">
                <span className="text-[8px] font-black uppercase opacity-40">Escala do Elemento</span>
                <span className="text-[10px] font-mono text-theme-accent font-black">{Math.round((selectedElement?.scale || 1) * 100)}%</span>
              </div>
              <input 
                type="range" min="0.01" max="3" step="0.01"
                value={selectedElement?.scale || 1}
                onChange={(e) => updateTransform(selectedId!, { scale: parseFloat(e.target.value) })}
                className="w-full h-1 bg-theme-accent/20 rounded-lg appearance-none cursor-pointer accent-theme-accent"
              />
            </div>

            <div className="flex gap-1.5 pl-4 border-l border-theme">
              <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) - 90 })} className="w-8 h-8 flex items-center justify-center border border-theme rounded hover:bg-theme-accent/10 transition-colors"><i className="fas fa-undo text-[10px]"></i></button>
              <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) + 90 })} className="w-8 h-8 flex items-center justify-center border border-theme rounded hover:bg-theme-accent/10 transition-colors"><i className="fas fa-redo text-[10px]"></i></button>
            </div>
          </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-8 overflow-hidden relative">
          <div className="flex-1 flex items-center justify-center w-full h-full overflow-auto scrollbar-hide">
            <InteractiveEditor 
              loteImages={extraLayers}
              mainImage={currentMainImage ? { ...currentMainImage, ...currentTransform! } : null}
              frameSettings={settings}
              selectedId={selectedId}
              onSelect={setSelectedId}
              onUpdateImage={updateTransform}
              zoom={zoom}
            />
          </div>

          <div className="mt-8 flex items-center gap-6 bg-theme-side/80 border border-theme py-1.5 px-6 rounded-full shadow-2xl backdrop-blur-md animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
              <i className="fas fa-search text-[10px] opacity-20"></i>
              <input 
                type="range" min="0.05" max="1.5" step="0.05"
                value={zoom}
                onChange={(e) => setZoom(parseFloat(e.target.value))}
                className="w-24 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent"
              />
              <span className="text-[9px] font-mono opacity-40 min-w-[25px]">{Math.round(zoom * 100)}%</span>
            </div>

            <div className="flex items-center gap-4">
              <button 
                disabled={currentIndex === 0}
                onClick={handlePrev}
                className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"
              >
                <i className="fas fa-chevron-left text-[9px]"></i>
              </button>

              <div className="flex flex-col items-center min-w-[60px]">
                <span className="text-[10px] font-mono font-black text-theme-accent">
                  {mainBatch.length > 0 ? `${currentIndex + 1} / ${mainBatch.length}` : '0 / 0'}
                </span>
              </div>

              <button 
                disabled={currentIndex >= mainBatch.length - 1}
                onClick={handleNext}
                className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"
              >
                <i className="fas fa-chevron-right text-[9px]"></i>
              </button>
            </div>

            <div className="flex items-center gap-3 pl-6 border-l border-theme/50">
              <i className="fas fa-expand-alt text-[10px] opacity-20"></i>
              <div className="flex items-baseline gap-1 font-mono text-[10px] opacity-50">
                <span className="font-bold">{settings.canvasWidth}</span>
                <span className="opacity-30 text-[8px]">×</span>
                <span className="font-bold">{settings.canvasHeight}</span>
                <span className="text-[8px] opacity-40 ml-0.5">px</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col">
        <div className="flex-1 flex flex-col border-b border-theme overflow-hidden">
          <div className="p-4 bg-black/5 flex justify-between items-center border-b border-theme">
            <span className="text-[10px] font-black uppercase tracking-widest opacity-40">Fila do Lote</span>
            <span className="text-[9px] font-mono bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">{mainBatch.length}</span>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {mainBatch.map((img, idx) => (
              <div 
                key={img.id}
                onClick={() => { setCurrentIndex(idx); setSelectedId('main'); }}
                className={`flex items-center gap-3 p-2 rounded-lg border transition-all cursor-pointer ${currentIndex === idx ? 'border-theme-accent bg-theme-accent/10 shadow-sm' : 'border-transparent hover:bg-black/5 opacity-60'}`}
              >
                <img src={img.previewUrl} className="w-8 h-8 rounded object-cover border border-theme" />
                <span className="text-[10px] font-bold truncate flex-1">{img.file.name}</span>
                {currentIndex === idx && <i className="fas fa-play text-theme-accent text-[8px]"></i>}
              </div>
            ))}
          </div>
        </div>

        <div className="h-1/3 flex flex-col overflow-hidden bg-black/5">
          <div className="p-4 bg-black/5 flex justify-between items-center border-b border-theme">
            <span className="text-[10px] font-black uppercase tracking-widest opacity-40">Extras</span>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-2">
            {extraLayers.map(img => (
              <div 
                key={img.id}
                onClick={() => setSelectedId(img.id)}
                className={`flex items-center gap-3 p-2 rounded-lg border transition-all cursor-pointer ${selectedId === img.id ? 'border-theme-accent bg-theme-accent/5' : 'border-theme bg-theme-panel'}`}
              >
                <img src={img.previewUrl} className="w-8 h-8 rounded object-cover border border-theme" />
                <span className="text-[10px] font-medium truncate flex-1">{img.file.name}</span>
                <button onClick={(e) => { e.stopPropagation(); setExtraLayers(extraLayers.filter(l => l.id !== img.id)); if(selectedId === img.id) setSelectedId(null); }} className="text-theme-muted hover:text-red-500 transition-colors"><i className="fas fa-times text-[10px]"></i></button>
              </div>
            ))}
          </div>
        </div>
      </aside>

      <input type="file" multiple accept="image/*" className="hidden" ref={mainFileInputRef} onChange={handleMainFiles} />
      <input type="file" multiple accept="image/*" className="hidden" ref={extraFileInputRef} onChange={handleExtraFiles} />
      <input type="file" accept="image/png" className="hidden" ref={frameInputRef} onChange={handleFrameFile} />
    </div>
  );
};

export default FramingTool;

import React from 'react';
import { FrameSettings } from '../types';

interface SidebarFramingProps {
  settings: FrameSettings;
  onSettingsChange: (s: FrameSettings) => void;
  onAddLote: () => void;
  onAddExtras: () => void;
  onAddFrame: () => void;
  autoSave: boolean;
  onAutoSaveChange: (v: boolean) => void;
  onProcessAll?: () => void;
  isProcessing?: boolean;
  progress?: number;
  total?: number;
  exportOptions: {
    downloadIndividual: boolean;
    setDownloadIndividual: (v: boolean) => void;
    downloadZip: boolean;
    setDownloadZip: (v: boolean) => void;
  };
}

const SidebarFraming: React.FC<SidebarFramingProps> = ({ 
  settings, 
  onSettingsChange, 
  onAddLote, 
  onAddExtras, 
  onAddFrame,
  autoSave,
  onAutoSaveChange,
  onProcessAll,
  isProcessing = false,
  progress = 0,
  total = 0,
  exportOptions
}) => {
  const handleChange = (key: keyof FrameSettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  // Função para garantir comportamento de rádio/toggle
  const selectMode = (mode: 'individual' | 'zip') => {
    if (mode === 'individual') {
      exportOptions.setDownloadIndividual(true);
      exportOptions.setDownloadZip(false);
    } else {
      exportOptions.setDownloadIndividual(false);
      exportOptions.setDownloadZip(true);
    }
  };

  return (
    <div className="p-6 space-y-8">
      <div className="space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Fluxo de Trabalho</h3>
        <div className="grid grid-cols-1 gap-2">
          <button onClick={onAddLote} className="w-full py-3.5 rounded-xl font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase group relative overflow-hidden transition-transform active:scale-95">
            <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
            <i className="fas fa-images"></i> 1. Carregar Lote Principal
          </button>
          <div className="grid grid-cols-2 gap-2">
            <button onClick={onAddExtras} className="py-2.5 rounded-lg font-black text-[9px] border border-theme bg-theme-panel text-theme-main shadow-sm flex items-center justify-center gap-2 uppercase hover:bg-black/5 transition-colors">
              <i className="fas fa-plus"></i> Extras
            </button>
            <button onClick={onAddFrame} className="py-2.5 rounded-lg font-black text-[9px] border border-theme bg-theme-panel text-theme-main shadow-sm flex items-center justify-center gap-2 uppercase hover:bg-black/5 transition-colors">
              <i className="fas fa-border-all"></i> Moldura
            </button>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Configurações Base</h3>

        {!settings.frameImageUrl ? (
          <div className="space-y-4 animate-in fade-in duration-300">
            {[
              { label: 'Espessura Borda', key: 'borderWidth', min: 0, max: 200 },
              { label: 'Arredondamento', key: 'borderRadius', min: 0, max: 200 },
              { label: 'Sombra Interna', key: 'shadow', min: 0, max: 100 },
            ].map(ctrl => (
              <div key={ctrl.key} className="space-y-1.5">
                <div className="flex justify-between">
                  <label className="text-[9px] font-bold opacity-60 uppercase">{ctrl.label}</label>
                  <span className="text-[9px] font-black text-theme-accent">{(settings as any)[ctrl.key]}</span>
                </div>
                <input 
                  type="range" 
                  min={ctrl.min} max={ctrl.max} 
                  value={(settings as any)[ctrl.key]}
                  onChange={(e) => handleChange(ctrl.key as any, parseInt(e.target.value))}
                  className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer"
                  style={{ accentColor: 'var(--accent)' }}
                />
              </div>
            ))}

            <div className="flex items-center justify-between pt-2">
               <label className="text-[9px] font-bold opacity-60 uppercase">Cor da Borda</label>
               <div className="flex items-center gap-3">
                 <span className="text-[9px] font-mono opacity-40 uppercase">{settings.borderColor}</span>
                 <input 
                    type="color" 
                    value={settings.borderColor} 
                    onChange={(e) => handleChange('borderColor', e.target.value)}
                    className="w-8 h-8 rounded-lg border border-theme cursor-pointer bg-theme-panel p-0.5 overflow-hidden transition-transform active:scale-90"
                 />
               </div>
            </div>
          </div>
        ) : (
          <div className="p-3 bg-theme-accent/5 rounded-lg border border-theme-accent/20 flex gap-3 items-center">
            <i className="fas fa-check-circle text-theme-accent text-xs"></i>
            <div className="flex-1 min-w-0">
              <p className="text-[9px] font-black uppercase text-theme-accent">Moldura Ativa</p>
              <p className="text-[8px] opacity-50 truncate">{settings.frameImageName}</p>
            </div>
            <button onClick={() => handleChange('frameImageUrl', undefined)} className="text-red-500 hover:scale-110 transition-transform p-1"><i className="fas fa-trash-alt text-[10px]"></i></button>
          </div>
        )}

        <div className="space-y-4 pt-4 border-t border-theme">
          <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Resolução de Saída</h3>
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="text-[8px] font-bold opacity-50 uppercase mb-1 block">Largura</label>
              <input 
                type="number" 
                value={settings.canvasWidth} 
                onChange={(e) => handleChange('canvasWidth', parseInt(e.target.value) || 0)}
                className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none font-mono"
              />
            </div>
            <div>
              <label className="text-[8px] font-bold opacity-50 uppercase mb-1 block">Altura</label>
              <input 
                type="number" 
                value={settings.canvasHeight} 
                onChange={(e) => handleChange('canvasHeight', parseInt(e.target.value) || 0)}
                className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none font-mono"
              />
            </div>
          </div>
        </div>
      </div>

      <div className="pt-4 space-y-4 border-t border-theme">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Modo de Exportação</h3>

        <div className="grid grid-cols-1 gap-2">
          <button 
            onClick={() => selectMode('individual')}
            className={`flex items-center gap-3 p-3 rounded-xl border transition-all text-left ${exportOptions.downloadIndividual ? 'bg-theme-accent/10 border-theme-accent shadow-sm' : 'bg-theme-panel/30 border-theme opacity-60 hover:opacity-100'}`}
          >
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadIndividual ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
              {exportOptions.downloadIndividual && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in duration-200"></div>}
            </div>
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase leading-tight">Arquivos Separados</span>
              <span className="text-[8px] opacity-50 uppercase">Individual (um por um)</span>
            </div>
          </button>

          <button 
            onClick={() => selectMode('zip')}
            className={`flex items-center gap-3 p-3 rounded-xl border transition-all text-left ${exportOptions.downloadZip ? 'bg-theme-accent/10 border-theme-accent shadow-sm' : 'bg-theme-panel/30 border-theme opacity-60 hover:opacity-100'}`}
          >
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadZip ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
              {exportOptions.downloadZip && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in duration-200"></div>}
            </div>
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase leading-tight">Compactar Tudo (.ZIP)</span>
              <span className="text-[8px] opacity-50 uppercase">Ideal para grandes lotes</span>
            </div>
          </button>
        </div>
      </div>

      <div className="pt-4 space-y-4 mt-auto">
        <label className="flex items-center gap-3 p-3 rounded-lg border border-theme bg-theme-panel/50 cursor-pointer group transition-all hover:bg-theme-accent/5 active:scale-[0.98]">
          <div className={`w-4 h-4 rounded border border-theme flex items-center justify-center transition-all ${autoSave ? 'bg-theme-accent border-theme-accent' : 'bg-transparent'}`}>
            {autoSave && <i className="fas fa-check text-[8px] text-white"></i>}
            <input type="checkbox" className="hidden" checked={autoSave} onChange={e => onAutoSaveChange(e.target.checked)} />
          </div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase tracking-tight text-theme-main">Salvar ao Avançar</span>
            <span className="text-[8px] opacity-40 uppercase">Preserva ajustes ao trocar item</span>
          </div>
        </label>

        <button 
          onClick={onProcessAll}
          disabled={isProcessing || total === 0}
          className="w-full py-4 rounded-xl font-black text-[11px] bg-theme-accent text-theme-inv shadow-2xl flex items-center justify-center gap-2 group relative overflow-hidden active:scale-95 uppercase tracking-widest transition-all disabled:opacity-50 disabled:grayscale"
        >
           <div className="absolute inset-0 bg-white/20 opacity-0 group-hover:opacity-100 transition-opacity"></div>
           {isProcessing ? (
             <>
               <i className="fas fa-spinner animate-spin z-10"></i>
               <span className="z-10">Gerando {progress} de {total}...</span>
             </>
           ) : (
             <>
               <i className="fas fa-bolt z-10"></i> 
               <span className="z-10">Processar Lote Inteiro</span>
             </>
           )}
        </button>
      </div>
    </div>
  );
};

export default SidebarFraming;

import React, { useState, useRef, useMemo } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarFraming from '../components/SidebarFraming';
import InteractiveEditor from '../components/InteractiveEditor';
import Header from '../components/Header';
import { GridImage, FrameSettings } from '../types';

interface BatchItemState {
  x: number;
  y: number;
  scale: number;
  rotation: number;
}

const FramingTool: React.FC = () => {
  const [mainBatch, setMainBatch] = useState<GridImage[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [batchStates, setBatchStates] = useState<Record<string, BatchItemState>>({});
  const [autoSave, setAutoSave] = useState(true);
  const [extraLayers, setExtraLayers] = useState<GridImage[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [zoom, setZoom] = useState(0.4); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);

  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);

  const [settings, setSettings] = useState<FrameSettings>({
    borderWidth: 20,
    borderColor: '#ffffff',
    borderRadius: 0,
    padding: 0,
    shadow: 10,
    canvasWidth: 1080,
    canvasHeight: 1080
  });

  const mainFileInputRef = useRef<HTMLInputElement>(null);
  const extraFileInputRef = useRef<HTMLInputElement>(null);
  const frameInputRef = useRef<HTMLInputElement>(null);

  const currentMainImage = mainBatch[currentIndex];

  const currentTransform = useMemo(() => {
    if (!currentMainImage) return null;
    return batchStates[currentMainImage.id] || {
      x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1),
      y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1),
      scale: 0.2,
      rotation: 0
    };
  }, [currentMainImage, batchStates, settings.canvasWidth, settings.canvasHeight]);

  const selectedElement = useMemo(() => {
    if (selectedId === 'main') return { ...currentMainImage, ...currentTransform };
    return extraLayers.find(img => img.id === selectedId);
  }, [selectedId, currentMainImage, currentTransform, extraLayers]);

  const handleMainFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      files.forEach(file => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          setMainBatch(prev => [...prev, {
            id: uuidv4(),
            file,
            previewUrl: url,
            width: img.width,
            height: img.height,
            aspectRatio: img.width / img.height
          }]);
        };
        img.src = url;
      });
    }
    if (e.target) e.target.value = '';
  };

  const handleExtraFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      files.forEach(file => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          setExtraLayers(prev => [...prev, {
            id: uuidv4(),
            file,
            previewUrl: url,
            width: img.width,
            height: img.height,
            aspectRatio: img.width / img.height,
            x: 100,
            y: 100,
            scale: 0.15,
            rotation: 0
          }]);
        };
        img.src = url;
      });
    }
    if (e.target) e.target.value = '';
  };

  const handleFrameFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const url = URL.createObjectURL(file);
      const img = new Image();
      img.onload = () => {
        setSettings(prev => ({
          ...prev,
          frameImageUrl: url,
          frameImageName: file.name,
          canvasWidth: img.width,
          canvasHeight: img.height
        }));
      };
      img.src = url;
    }
    if (e.target) e.target.value = '';
  };

  const updateTransform = (id: string, updates: Partial<BatchItemState | GridImage>) => {
    if (id === 'main' && currentMainImage) {
      setBatchStates(prev => ({
        ...prev,
        [currentMainImage.id]: { ...currentTransform!, ...updates as any }
      }));
    } else {
      setExtraLayers(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
    }
  };

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error(`Falha ao carregar imagem: ${url}`));
      img.src = url;
    });
  };

  const handleProcessAll = async () => {
    if (mainBatch.length === 0) return;

    setIsProcessing(true);
    setProcessProgress(0);

    // Canvas oculto para renderização em alta
    const canvas = document.createElement('canvas');
    canvas.width = settings.canvasWidth;
    canvas.height = settings.canvasHeight;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const zip = downloadZip ? new JSZip() : null;

    try {
      // 1. Pré-carregar recursos globais (Extras e Moldura)
      const extraImgs = await Promise.all(extraLayers.map(l => loadImage(l.previewUrl)));
      let frameImg: HTMLImageElement | null = null;
      if (settings.frameImageUrl) {
        frameImg = await loadImage(settings.frameImageUrl);
      }

      // Referência do transform atual (o que o usuário está vendo na tela)
      // Se outras imagens não foram editadas, elas usarão este posicionamento.
      const fallbackTransform = currentTransform || {
        x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1),
        y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1),
        scale: 0.2,
        rotation: 0
      };

      // 2. Loop principal de processamento
      for (let i = 0; i < mainBatch.length; i++) {
        setProcessProgress(i + 1);
        const item = mainBatch[i];

        // Prioriza o estado específico do item, se não existir usa o fallback (template)
        const transform = batchStates[item.id] || { ...fallbackTransform };

        // Limpar canvas para o novo frame
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // A. Desenhar Imagem Principal do Lote
        const mainImgObj = await loadImage(item.previewUrl);
        ctx.save();
        const drawW = item.width * transform.scale;
        const drawH = item.height * transform.scale;
        ctx.translate(transform.x + drawW / 2, transform.y + drawH / 2);
        ctx.rotate((transform.rotation * Math.PI) / 180);
        ctx.drawImage(mainImgObj, -drawW / 2, -drawH / 2, drawW, drawH);
        ctx.restore();

        // B. Desenhar Camadas Extras
        extraLayers.forEach((layer, idx) => {
          ctx.save();
          const lW = layer.width * (layer.scale || 1);
          const lH = layer.height * (layer.scale || 1);
          ctx.translate((layer.x || 0) + lW / 2, (layer.y || 0) + lH / 2);
          ctx.rotate(((layer.rotation || 0) * Math.PI) / 180);
          ctx.drawImage(extraImgs[idx], -lW / 2, -lH / 2, lW, lH);
          ctx.restore();
        });

        // C. Desenhar Moldura ou Borda Simples
        if (frameImg) {
          ctx.drawImage(frameImg, 0, 0, canvas.width, canvas.height);
        } else {
          ctx.strokeStyle = settings.borderColor;
          ctx.lineWidth = settings.borderWidth;
          if (settings.borderRadius > 0) {
            ctx.beginPath();
            // Fallback para roundRect se necessário
            if (ctx.roundRect) {
              ctx.roundRect(settings.borderWidth / 2, settings.borderWidth / 2, canvas.width - settings.borderWidth, canvas.height - settings.borderWidth, settings.borderRadius);
            } else {
              ctx.rect(settings.borderWidth / 2, settings.borderWidth / 2, canvas.width - settings.borderWidth, canvas.height - settings.borderWidth);
            }
            ctx.stroke();
          } else {
            ctx.strokeRect(settings.borderWidth / 2, settings.borderWidth / 2, canvas.width - settings.borderWidth, canvas.height - settings.borderWidth);
          }
        }

        // D. Exportar Resultado
        const dataUrl = canvas.toDataURL('image/png', 1.0);
        const cleanName = item.file.name.replace(/\.[^/.]+$/, "");
        const fileName = `miau_${cleanName}.png`;

        if (downloadIndividual) {
          const link = document.createElement('a');
          link.download = fileName;
          link.href = dataUrl;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          // Pequena pausa para evitar bloqueio de múltiplos downloads pelo navegador
          await new Promise(r => setTimeout(r, 400));
        }

        if (zip) {
          const base64Data = dataUrl.split(',')[1];
          zip.file(fileName, base64Data, { base64: true });
        }
      }

      // 3. Finalizar e baixar o ZIP se ativo
      if (zip) {
        const zipBlob = await zip.generateAsync({ type: "blob" });
        const zipUrl = URL.createObjectURL(zipBlob);
        const link = document.createElement('a');
        link.href = zipUrl;
        link.download = `lote_miau_tools_${Date.now()}.zip`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        setTimeout(() => URL.revokeObjectURL(zipUrl), 5000);
      }

    } catch (err) {
      console.error("Erro no processamento:", err);
      alert("Ocorreu um erro ao processar o lote. Verifique se as imagens são válidas.");
    } finally {
      setIsProcessing(false);
      setProcessProgress(0);
    }
  };

  const handleNext = () => {
    if (currentIndex < mainBatch.length - 1) {
      setCurrentIndex(prev => prev + 1);
      setSelectedId('main');
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
      setSelectedId('main');
    }
  };

  const clearAll = () => {
    if (window.confirm('Deseja realmente limpar todo o projeto?')) {
      mainBatch.forEach(img => URL.revokeObjectURL(img.previewUrl));
      extraLayers.forEach(img => URL.revokeObjectURL(img.previewUrl));
      setMainBatch([]);
      setExtraLayers([]);
      setBatchStates({});
      setCurrentIndex(0);
      setSelectedId(null);
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarFraming 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddLote={() => mainFileInputRef.current?.click()}
          onAddExtras={() => extraFileInputRef.current?.click()}
          onAddFrame={() => frameInputRef.current?.click()}
          autoSave={autoSave}
          onAutoSaveChange={setAutoSave}
          onProcessAll={handleProcessAll}
          isProcessing={isProcessing}
          progress={processProgress}
          total={mainBatch.length}
          exportOptions={{
            downloadIndividual,
            setDownloadIndividual,
            downloadZip,
            setDownloadZip
          }}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden bg-theme-main relative">
        <Header itemCount={mainBatch.length + extraLayers.length} onClear={clearAll} />

        <div className="h-14 border-b border-theme flex items-center px-6 gap-8 bg-theme-side/30 backdrop-blur-sm">
          <div className={`flex items-center gap-8 transition-all duration-300 ${!selectedElement ? 'opacity-20 grayscale pointer-events-none' : 'opacity-100'}`}>
            <div className="flex flex-col">
              <span className="text-[8px] font-black uppercase opacity-40">Posição Atual</span>
              <div className="flex gap-3 font-mono text-[10px] mt-1">
                <span className="opacity-40">X:</span> <span className="text-theme-accent font-bold">{Math.round(selectedElement?.x || 0)}</span>
                <span className="opacity-40 ml-1">Y:</span> <span className="text-theme-accent font-bold">{Math.round(selectedElement?.y || 0)}</span>
              </div>
            </div>

            <div className="flex flex-col">
              <span className="text-[8px] font-black uppercase opacity-40">Dimensão Real</span>
              <div className="flex gap-2 font-mono text-[10px] mt-1">
                <span className="opacity-40">W:</span> <span>{Math.round((selectedElement?.width || 0) * (selectedElement?.scale || 1))}px</span>
              </div>
            </div>

            <div className="w-40 flex flex-col">
              <div className="flex justify-between items-center mb-1">
                <span className="text-[8px] font-black uppercase opacity-40">Tamanho do Objeto</span>
                <span className="text-[10px] font-mono text-theme-accent font-black">{Math.round((selectedElement?.scale || 1) * 100)}%</span>
              </div>
              <input 
                type="range" min="0.01" max="4" step="0.01"
                value={selectedElement?.scale || 1}
                onChange={(e) => updateTransform(selectedId!, { scale: parseFloat(e.target.value) })}
                className="w-full h-1 bg-theme-accent/20 rounded-lg appearance-none cursor-pointer accent-theme-accent"
              />
            </div>

            <div className="flex gap-1.5 pl-4 border-l border-theme">
              <button title="Girar -90º" onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) - 90 })} className="w-8 h-8 flex items-center justify-center border border-theme rounded hover:bg-theme-accent/10 transition-colors"><i className="fas fa-undo text-[10px]"></i></button>
              <button title="Girar +90º" onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) + 90 })} className="w-8 h-8 flex items-center justify-center border border-theme rounded hover:bg-theme-accent/10 transition-colors"><i className="fas fa-redo text-[10px]"></i></button>
            </div>
          </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-8 overflow-hidden relative">
          <div className="flex-1 flex items-center justify-center w-full h-full overflow-auto scrollbar-hide">
            <InteractiveEditor 
              loteImages={extraLayers}
              mainImage={currentMainImage ? { ...currentMainImage, ...currentTransform! } : null}
              frameSettings={settings}
              selectedId={selectedId}
              onSelect={setSelectedId}
              onUpdateImage={updateTransform}
              zoom={zoom}
            />
          </div>

          <div className="mt-8 flex items-center gap-6 bg-theme-side/80 border border-theme py-1.5 px-6 rounded-full shadow-2xl backdrop-blur-md animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
              <i className="fas fa-search text-[10px] opacity-20"></i>
              <input 
                type="range" min="0.05" max="2" step="0.05"
                value={zoom}
                onChange={(e) => setZoom(parseFloat(e.target.value))}
                className="w-24 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent"
              />
              <span className="text-[9px] font-mono opacity-40 min-w-[25px]">{Math.round(zoom * 100)}%</span>
            </div>

            <div className="flex items-center gap-4">
              <button 
                disabled={currentIndex === 0}
                onClick={handlePrev}
                className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"
              >
                <i className="fas fa-chevron-left text-[9px]"></i>
              </button>

              <div className="flex flex-col items-center min-w-[60px]">
                <span className="text-[10px] font-mono font-black text-theme-accent">
                  {mainBatch.length > 0 ? `${currentIndex + 1} / ${mainBatch.length}` : '0 / 0'}
                </span>
              </div>

              <button 
                disabled={currentIndex >= mainBatch.length - 1}
                onClick={handleNext}
                className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"
              >
                <i className="fas fa-chevron-right text-[9px]"></i>
              </button>
            </div>

            <div className="flex items-center gap-3 pl-6 border-l border-theme/50">
              <i className="fas fa-expand-alt text-[10px] opacity-20"></i>
              <div className="flex items-baseline gap-1 font-mono text-[10px] opacity-50">
                <span className="font-bold">{settings.canvasWidth}</span>
                <span className="opacity-30 text-[8px]">×</span>
                <span className="font-bold">{settings.canvasHeight}</span>
                <span className="text-[8px] opacity-40 ml-0.5">px</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col">
