import ResizerTool from './tools/ResizerTool';
import FramingTool from './tools/FramingTool';

export type ToolType = 'grid' | 'framing' | 'resizer' | 'max-resize';
export type ThemeType = 'dark' | 'light' | 'pastel' | 'midnight';

const App: React.FC = () => {
  const [activeTool, setActiveTool] = useState<ToolType>('resizer');
  const [theme, setTheme] = useState<ThemeType>('midnight');
  const [showAbout, setShowAbout] = useState(false);

  // Sincroniza o tema com o elemento raiz (html) para que o body e outros elementos fora do root respondam
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);

  const renderTool = () => {
    switch (activeTool) {
      case 'grid':
        return <GridTool />;
      case 'resizer':
        return <ResizerTool />;
      case 'framing':
        return <FramingTool />;
      default:
        return (
          <div className="flex-1 flex items-center justify-center opacity-50 bg-theme-main">
            <div className="text-center text-theme-main">
              <i className="fas fa-tools text-6xl mb-4"></i>
              <h2 className="text-2xl font-bold uppercase tracking-widest">Módulo em Desenvolvimento</h2>
              <p className="text-xs opacity-50 mt-2">Estamos preparando esta ferramenta para você.</p>
            </div>
          </div>
        );
    }
  };

  return (
    <div 
      className="flex flex-col h-screen overflow-hidden transition-colors duration-300 relative bg-theme-main text-theme-main" 
    >
      <TopNav 
        activeTool={activeTool} 
        onToolChange={setActiveTool} 
        currentTheme={theme}
        onThemeChange={setTheme}
        onShowAbout={() => setShowAbout(true)}
      />

      <main className="flex-1 flex overflow-hidden">
        {renderTool()}
      </main>

      {/* MODAL SOBRE - MIAUTOOLS COMMUNITY EDITION */}
      {showAbout && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 backdrop-blur-md bg-black/40 animate-in fade-in duration-300">
          <div className="max-w-lg w-full bg-theme-side border border-theme rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden group">
            {/* Linha Decorativa Superior (Tricolor) */}
            <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-orange-500 via-neutral-900 to-amber-100"></div>

            <button 
              onClick={() => setShowAbout(false)}
              className="absolute top-8 right-8 text-theme-muted hover:text-theme-main transition-colors w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-panel"
            >
              <i className="fas fa-times"></i>
            </button>

            <div className="flex flex-col items-center text-center">
              {/* Ícone Pulsante */}
              <div className="w-20 h-20 rounded-3xl bg-theme-accent flex items-center justify-center text-theme-inv shadow-2xl mb-8 rotate-3 group-hover:rotate-0 transition-all duration-500 relative">
                <div className="absolute inset-0 bg-theme-accent rounded-3xl animate-ping opacity-20"></div>
                <i className="fas fa-paw text-4xl z-10"></i>
              </div>

              <div className="space-y-2 mb-8">
                <h2 className="text-3xl font-black tracking-tighter">
                  <span className="miau-text">Miau</span>Tools
                </h2>
                <div className="flex items-center gap-2 justify-center opacity-40">
                  <div className="h-[1px] w-4 bg-current"></div>
                  <p className="text-[9px] font-black uppercase tracking-[0.4em]">Mercado de Inovação de Artes e Utilitários</p>
                  <div className="h-[1px] w-4 bg-current"></div>
                </div>
              </div>

              <div className="space-y-6 text-sm leading-relaxed text-theme-main/80 text-justify mb-10">
                <p>
                  A <span className="font-bold text-theme-accent">MiauTools</span> é uma ferramenta de edição de código aberto desenvolvida pelo grupo <span className="font-bold uppercase">Miau</span>. 
                  O projeto nasceu como uma solução interna para otimizar nossos fluxos de criação e cresceu para se tornar uma iniciativa de código aberto.
                </p>

                <div className="grid grid-cols-3 gap-3 text-center">
                  <div className="p-3 rounded-2xl bg-theme-panel border border-theme hover:border-theme-accent transition-colors">
                    <i className="fas fa-leaf text-theme-accent mb-2 text-xs"></i>
                    <h4 className="text-[8px] font-black uppercase mb-1">Simplicidade</h4>
                    <p className="text-[8px] opacity-60 leading-tight">Interface limpa para focar no que importa.</p>
                  </div>
                  <div className="p-3 rounded-2xl bg-theme-panel border border-theme hover:border-theme-accent transition-colors">
                    <i className="fas fa-book-open text-theme-accent mb-2 text-xs"></i>
                    <h4 className="text-[8px] font-black uppercase mb-1">Aprendizado</h4>
                    <p className="text-[8px] opacity-60 leading-tight">Código aberto para crescermos juntos.</p>
                  </div>
                  <div className="p-3 rounded-2xl bg-theme-panel border border-theme hover:border-theme-accent transition-colors">
                    <i className="fas fa-hands-helping text-theme-accent mb-2 text-xs"></i>
                    <h4 className="text-[8px] font-black uppercase mb-1">Colaboração</h4>
                    <p className="text-[8px] opacity-60 leading-tight">Feito pela comunidade, para todos.</p>
                  </div>
                </div>

                <p className="italic text-center opacity-60 text-xs">
                  "Onde a tecnologia encontra a simplicidade da criação."
                </p>
              </div>

              <div className="pt-8 border-t border-theme w-full flex flex-col items-center gap-6">
                <div className="flex gap-6">
                  <a href="#" title="GitHub" className="w-12 h-12 rounded-2xl bg-theme-panel flex items-center justify-center hover:text-theme-accent hover:border-theme-accent transition-all border border-theme shadow-sm group/icon">
                    <i className="fab fa-github text-xl group-hover/icon:scale-110 transition-transform"></i>
                  </a>
                  <a href="#" title="Instagram" className="w-12 h-12 rounded-2xl bg-theme-panel flex items-center justify-center hover:text-theme-accent hover:border-theme-accent transition-all border border-theme shadow-sm group/icon">
                    <i className="fab fa-instagram text-xl group-hover/icon:scale-110 transition-transform"></i>
                  </a>
                  <a href="#" title="Discord" className="w-12 h-12 rounded-2xl bg-theme-panel flex items-center justify-center hover:text-theme-accent hover:border-theme-accent transition-all border border-theme shadow-sm group/icon">
                    <i className="fab fa-discord text-xl group-hover/icon:scale-110 transition-transform"></i>
                  </a>
                </div>

                <div className="flex flex-col items-center gap-1">
                  <span className="text-[9px] font-bold opacity-30 uppercase tracking-widest">Versão 1.0.0 Alpha • Open Source Project</span>
                  <div className="flex items-center gap-2 text-[8px] font-bold text-theme-accent opacity-50 uppercase tracking-tighter">
                    <span>Simplicity</span>
                    <span className="w-1 h-1 rounded-full bg-current"></span>
                    <span>Learning</span>
                    <span className="w-1 h-1 rounded-full bg-current"></span>
                    <span>Collaboration</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { ToolType, ThemeType } from '../App';

interface TopNavProps {
  activeTool: ToolType;
  onToolChange: (tool: ToolType) => void;
  currentTheme: ThemeType;
  onThemeChange: (theme: ThemeType) => void;
  onShowAbout: () => void;
}

const TopNav: React.FC<TopNavProps> = ({ activeTool, onToolChange, currentTheme, onThemeChange, onShowAbout }) => {
  const [showSettings, setShowSettings] = useState(false);
  const settingsRef = useRef<HTMLDivElement>(null);

  const tools = [
    { id: 'grid', label: 'Grid Maker', icon: 'fa-th-large' },
    { id: 'framing', label: 'Bulk Framing', icon: 'fa-expand-arrows-alt' },
    { id: 'resizer', label: 'Master Resizer', icon: 'fa-expand-arrows-alt' },
    { id: 'max-resize', label: 'Max-Bound Resize', icon: 'fa-vector-square' },
  ];

  const themes = [
    { id: 'dark', label: 'Dark Edition', color: '#020617', icon: 'fa-moon' },
    { id: 'light', label: 'Clean Light', color: '#f8fafc', icon: 'fa-sun' },
    { id: 'pastel', label: 'Sweet Pastel', color: '#fff1f2', icon: 'fa-heart' },
    { id: 'midnight', label: 'Midnight Purple', color: '#0c0a09', icon: 'fa-vial' },
  ];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (settingsRef.current && !settingsRef.current.contains(event.target as Node)) {
        setShowSettings(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <nav className="h-10 border-b flex items-center justify-between px-4 z-50 shadow-sm relative" 
         style={{ backgroundColor: 'var(--bg-side)', borderColor: 'var(--border)' }}>

      <div className="flex items-center gap-3">
        {/* LOGO COM SUPORTE CHANFRADO (CHAMFERED) */}
        <div className="logo-support h-7">
           <div className="flex items-center gap-2">
             <i className="fas fa-paw text-[9px] text-white/90"></i>
             <span className="miau-text text-lg tracking-tighter select-none leading-none pt-0.5">Miau</span>
           </div>
        </div>

        <span className="font-black text-[11px] tracking-[0.2em] uppercase opacity-80" style={{ color: 'var(--accent)' }}>Tools</span>
      </div>

      <div className="flex items-center gap-1 p-0.5 rounded-lg border"
           style={{ backgroundColor: 'rgba(0,0,0,0.03)', borderColor: 'var(--border)' }}>
        {tools.map((tool) => (
          <button
            key={tool.id}
            onClick={() => onToolChange(tool.id as ToolType)}
            className={`flex items-center gap-2 px-3 py-1 rounded-md text-[10px] font-bold transition-all duration-200 whitespace-nowrap uppercase tracking-tight relative group`}
            style={{
              backgroundColor: activeTool === tool.id ? 'var(--accent)' : 'transparent',
              color: activeTool === tool.id ? 'var(--text-inv)' : 'var(--text-muted)'
            }}
          >
            {activeTool !== tool.id && (
              <div className="absolute inset-0 bg-black/5 opacity-0 group-hover:opacity-100 rounded-md transition-opacity"></div>
            )}

            <i className={`fas ${tool.icon} text-[9px] z-10 ${activeTool === tool.id ? 'opacity-100' : 'opacity-40'}`}></i>
            <span className="z-10">{tool.label}</span>
          </button>
        ))}

        <div className="w-[1px] h-4 mx-1" style={{ backgroundColor: 'var(--border)' }}></div>

        <div className="relative" ref={settingsRef}>
          <button 
            onClick={() => setShowSettings(!showSettings)}
            className="p-1.5 transition-all hover:bg-black/5 rounded-md"
            style={{ color: showSettings ? 'var(--accent)' : 'var(--text-muted)' }}
          >
            <i className="fas fa-cog text-[11px]"></i>
          </button>

          {showSettings && (
            <div className="absolute right-0 mt-2 w-52 rounded-xl border shadow-2xl p-1.5 z-[100] animate-in fade-in zoom-in duration-200 overflow-hidden"
                 style={{ backgroundColor: 'var(--bg-side)', borderColor: 'var(--border)' }}>

              <div className="px-3 py-2 mb-1 border-b" style={{ borderColor: 'var(--border)' }}>
                <span className="text-[9px] font-black uppercase tracking-widest block opacity-50" style={{ color: 'var(--text-main)' }}>
                  Visual do Studio
                </span>
              </div>

              <div className="space-y-0.5 py-1">
                {themes.map((t) => (
                  <button
                    key={t.id}
                    onClick={() => { onThemeChange(t.id as ThemeType); setShowSettings(false); }}
                    className="w-full flex items-center gap-3 px-3 py-2 rounded-lg text-xs font-semibold theme-item-transition relative group overflow-hidden"
                    style={{ 
                      color: currentTheme === t.id ? 'var(--accent)' : 'var(--text-main)',
                      backgroundColor: currentTheme === t.id ? 'var(--ui-selected)' : 'transparent'
                    }}
                  >
                    {currentTheme !== t.id && (
                      <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity" 
                           style={{ backgroundColor: 'var(--ui-hover)' }}></div>
                    )}
                    <div className="w-3.5 h-3.5 rounded-full border border-black/10 shadow-inner z-10 flex items-center justify-center overflow-hidden" 
                         style={{ backgroundColor: t.color }}>
                      {currentTheme === t.id && <i className="fas fa-check text-[6px] text-white"></i>}
                    </div>
                    <span className="flex-1 text-left z-10">{t.label}</span>
                  </button>
                ))}
              </div>

              <div className="pt-1 mt-1 border-t" style={{ borderColor: 'var(--border)' }}>
                <button 
                  onClick={() => { onShowAbout(); setShowSettings(false); }}
                  className="w-full flex items-center gap-3 px-3 py-2 rounded-lg text-xs font-bold text-theme-muted hover:text-theme-accent hover:bg-theme-accent/5 transition-all"
                >
                  <i className="fas fa-info-circle text-[10px]"></i>
                  <span>Sobre o MiauTools</span>
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </nav>
  );
};

export default TopNav;

import React from 'react';
import { ResizeMode } from '../tools/ResizerTool';

interface SidebarResizerProps {
  settings: any;
  onSettingsChange: (s: any) => void;
  onAdd: () => void;
  onSave: () => void;
  isProcessing?: boolean;
  progress?: number;
  total?: number;
  exportOptions: {
    downloadIndividual: boolean;
    setDownloadIndividual: (v: boolean) => void;
    downloadZip: boolean;
    setDownloadZip: (v: boolean) => void;
  };
}

const SidebarResizer: React.FC<SidebarResizerProps> = ({ 
  settings, 
  onSettingsChange, 
  onAdd, 
  onSave,
  isProcessing = false,
  progress = 0,
  total = 0,
  exportOptions
}) => {
  const modes: { id: ResizeMode; label: string; icon: string; desc: string }[] = [
    { id: 'fit', label: 'Conter (Fit)', icon: 'fa-compress', desc: 'Mantém tudo visível' },
    { id: 'fill', label: 'Cobrir (Fill)', icon: 'fa-expand', desc: 'Preenche sem bordas' },
    { id: 'stretch', label: 'Esticar', icon: 'fa-arrows-alt', desc: 'Ignora proporções' },
    { id: 'trim', label: 'Aparar (Trim)', icon: 'fa-crop', desc: 'Remove bordas extras' },
  ];

  const selectMode = (mode: 'individual' | 'zip') => {
    if (mode === 'individual') {
      exportOptions.setDownloadIndividual(true);
      exportOptions.setDownloadZip(false);
    } else {
      exportOptions.setDownloadIndividual(false);
      exportOptions.setDownloadZip(true);
    }
  };

  const setMethod = (method: 'fixed' | 'proportional') => {
    onSettingsChange({ ...settings, activeMethod: method });
  };

  return (
    <div className="p-5 space-y-6 h-full overflow-y-auto scrollbar-hide flex flex-col">
      {/* BOX: IMPORTAÇÃO */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Entrada de Arquivos</h3>
        <button onClick={onAdd} className="w-full py-3.5 rounded-xl font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase group relative overflow-hidden transition-transform active:scale-95">
          <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <i className="fas fa-images"></i> Adicionar Lote
        </button>
      </div>

      {/* BOX: REDIMENSIONAMENTO FIXO */}
      <div className={`p-4 rounded-2xl border transition-all duration-300 space-y-4 ${settings.activeMethod === 'fixed' ? 'bg-theme-accent/5 border-theme-accent shadow-sm' : 'border-theme bg-theme-panel/10 opacity-80'}`}>
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 flex justify-between">
          <span>Redimensionamento Fixo</span>
          {settings.activeMethod === 'fixed' && <i className="fas fa-check-circle text-theme-accent"></i>}
        </h3>
        <div className="grid grid-cols-2 gap-3">
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase">Largura (px)</label>
            <input 
              type="number" 
              value={settings.width}
              onChange={(e) => onSettingsChange({ ...settings, width: parseInt(e.target.value) || 0 })}
              className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] text-theme-main font-mono outline-none focus:border-theme-accent transition-colors"
            />
          </div>
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase">Altura (px)</label>
            <input 
              type="number" 
              value={settings.height}
              onChange={(e) => onSettingsChange({ ...settings, height: parseInt(e.target.value) || 0 })}
              className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] text-theme-main font-mono outline-none focus:border-theme-accent transition-colors"
            />
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-[8px] font-bold opacity-50 uppercase block">Modo de Escala</label>
          <div className="flex flex-col gap-1.5">
            {modes.map(mode => (
              <button
                key={mode.id}
                onClick={() => onSettingsChange({ ...settings, mode: mode.id, activeMethod: 'fixed' })}
                className={`flex items-center gap-3 px-3 py-1.5 rounded-lg border transition-all text-left ${settings.mode === mode.id && settings.activeMethod === 'fixed' ? 'bg-theme-accent text-white border-theme-accent shadow-sm' : 'bg-theme-panel/50 border-theme opacity-60 hover:opacity-100'}`}
              >
                <i className={`fas ${mode.icon} text-[9px]`}></i>
                <span className="text-[9px] font-black uppercase flex-1">{mode.label}</span>
                {settings.mode === mode.id && settings.activeMethod === 'fixed' && <div className="w-1 h-1 rounded-full bg-white animate-in zoom-in"></div>}
              </button>
            ))}
          </div>
        </div>

        <button 
          onClick={() => setMethod('fixed')} 
          className={`w-full py-2.5 rounded-xl font-black text-[9px] border flex items-center justify-center gap-2 uppercase tracking-widest transition-all active:scale-95 ${settings.activeMethod === 'fixed' ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-panel border-theme text-theme-main'}`}
        >
           <i className="fas fa-expand-arrows-alt"></i> Aplicar Fixo
        </button>
      </div>

      {/* BOX: REDIMENSIONAMENTO PROPORCIONAL */}
      <div className={`p-4 rounded-2xl border transition-all duration-300 space-y-4 ${settings.activeMethod === 'proportional' ? 'bg-theme-accent/5 border-theme-accent shadow-sm' : 'border-theme bg-theme-panel/10 opacity-80'}`}>
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 flex justify-between">
          <span>Redimensionamento Proporcional</span>
          {settings.activeMethod === 'proportional' && <i className="fas fa-check-circle text-theme-accent"></i>}
        </h3>

        <div className="space-y-1">
          <label className="text-[8px] font-bold opacity-50 uppercase">Tamanho Alvo (px)</label>
          <input 
            type="number" 
            placeholder="Ex: 1080"
            value={settings.boundSize || ''}
            onChange={(e) => onSettingsChange({ ...settings, boundSize: parseInt(e.target.value) || 0 })}
            className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] text-theme-main font-mono outline-none focus:border-theme-accent transition-colors"
          />
        </div>

        <div className="grid grid-cols-2 gap-2">
          <button 
            onClick={() => onSettingsChange({ ...settings, boundType: 'max', activeMethod: 'proportional' })}
            className={`flex items-center gap-2 p-2 rounded-lg border transition-all text-left ${settings.boundType === 'max' && settings.activeMethod === 'proportional' ? 'bg-theme-accent/20 border-theme-accent shadow-sm' : 'bg-theme-panel border-theme opacity-60'}`}
          >
            <div className={`w-3 h-3 rounded-full border flex items-center justify-center ${settings.boundType === 'max' && settings.activeMethod === 'proportional' ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
              {settings.boundType === 'max' && settings.activeMethod === 'proportional' && <div className="w-1 h-1 rounded-full bg-white"></div>}
            </div>
            <span className="text-[9px] font-black uppercase">Máximo</span>
          </button>

          <button 
            onClick={() => onSettingsChange({ ...settings, boundType: 'min', activeMethod: 'proportional' })}
            className={`flex items-center gap-2 p-2 rounded-lg border transition-all text-left ${settings.boundType === 'min' && settings.activeMethod === 'proportional' ? 'bg-theme-accent/20 border-theme-accent shadow-sm' : 'bg-theme-panel border-theme opacity-60'}`}
          >
            <div className={`w-3 h-3 rounded-full border flex items-center justify-center ${settings.boundType === 'min' && settings.activeMethod === 'proportional' ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
              {settings.boundType === 'min' && settings.activeMethod === 'proportional' && <div className="w-1 h-1 rounded-full bg-white"></div>}
            </div>
            <span className="text-[9px] font-black uppercase">Mínimo</span>
          </button>
        </div>

        <button 
          onClick={() => setMethod('proportional')}
          className={`w-full py-2.5 rounded-xl font-black text-[9px] border flex items-center justify-center gap-2 uppercase tracking-widest transition-all active:scale-95 ${settings.activeMethod === 'proportional' ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-panel border-theme text-theme-main'}`}
        >
           <i className="fas fa-compress-arrows-alt"></i> Aplicar Proporcional
        </button>
      </div>

      {/* BOX: MODO DE EXPORTAÇÃO */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Modo de Exportação</h3>
        <div className="grid grid-cols-1 gap-2">
          <button 
            onClick={() => selectMode('individual')}
            className={`flex items-center gap-3 p-3 rounded-xl border transition-all text-left ${exportOptions.downloadIndividual ? 'bg-theme-accent/10 border-theme-accent shadow-sm' : 'bg-theme-panel/30 border-theme opacity-60 hover:opacity-100'}`}
          >
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadIndividual ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
              {exportOptions.downloadIndividual && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in duration-200"></div>}
            </div>
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase leading-tight">Arquivos Separados</span>
              <span className="text-[8px] opacity-50 uppercase tracking-tighter">Um por um</span>
            </div>
          </button>

          <button 
            onClick={() => selectMode('zip')}
            className={`flex items-center gap-3 p-3 rounded-xl border transition-all text-left ${exportOptions.downloadZip ? 'bg-theme-accent/10 border-theme-accent shadow-sm' : 'bg-theme-panel/30 border-theme opacity-60 hover:opacity-100'}`}
          >
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadZip ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
              {exportOptions.downloadZip && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in duration-200"></div>}
            </div>
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase leading-tight">Compactado (.ZIP)</span>
              <span className="text-[8px] opacity-50 uppercase tracking-tighter">Pacote Único</span>
            </div>
          </button>
        </div>
      </div>

      {/* BOX: AÇÃO FINAL */}
      <div className="mt-auto pt-4">
        <button 
          onClick={onSave} 
          disabled={isProcessing || total === 0}
          className="w-full py-4 rounded-xl font-black text-[11px] bg-theme-accent text-theme-inv shadow-2xl flex items-center justify-center gap-2 group relative overflow-hidden active:scale-95 uppercase tracking-widest disabled:opacity-50"
        >
           <div className="absolute inset-0 bg-white/20 opacity-0 group-hover:opacity-100 transition-opacity"></div>
           {isProcessing ? (
             <>
               <i className="fas fa-spinner animate-spin"></i>
               <span>Processando {progress}/{total}</span>
             </>
           ) : (
             <>
               <i className="fas fa-save"></i> <span>Salvar</span>
             </>
           )}
        </button>
      </div>
    </div>
  );
};

