    { id: 'fit', label: 'Conter (Fit)', icon: 'fa-compress' },
    { id: 'fill', label: 'Cobrir (Fill)', icon: 'fa-expand' },
    { id: 'stretch', label: 'Esticar', icon: 'fa-arrows-alt' },
