  const selectMode = (mode: 'individual' | 'zip') => {
    if (mode === 'individual') {
      exportOptions.setDownloadIndividual(true);
      exportOptions.setDownloadZip(false);
    } else {
      exportOptions.setDownloadIndividual(false);
      exportOptions.setDownloadZip(true);
    }
  };

  return (
    <div className="p-5 space-y-6 h-full overflow-y-auto scrollbar-hide flex flex-col">
      {/* ENTRADA */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Entrada</h3>
        <button onClick={onAdd} className="w-full py-3.5 rounded-xl font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase group relative overflow-hidden transition-transform active:scale-95">
          <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <i className="fas fa-plus-circle"></i> Importar Lote
        </button>
      </div>

      {/* BOX: REDIMENSIONAMENTO FIXO */}
      <div className={`p-4 rounded-2xl border transition-all duration-300 space-y-4 ${settings.activeMethod === 'fixed' && !settings.useTrim ? 'bg-theme-accent/5 border-theme-accent shadow-sm' : 'border-theme bg-theme-panel/10 opacity-80'}`}>
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 flex justify-between">
          <span>Redimensionamento Fixo</span>
          {settings.activeMethod === 'fixed' && !settings.useTrim && <i className="fas fa-check-circle text-theme-accent"></i>}
        </h3>
        <div className="grid grid-cols-2 gap-3">
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase">Largura (px)</label>
            <input 
              type="number" 
              value={settings.width}
              onChange={(e) => onSettingsChange({ ...settings, width: parseInt(e.target.value) || 0, activeMethod: 'fixed', useTrim: false })}
              className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] text-theme-main font-mono outline-none focus:border-theme-accent"
            />
          </div>
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase">Altura (px)</label>
            <input 
              type="number" 
              value={settings.height}
              onChange={(e) => onSettingsChange({ ...settings, height: parseInt(e.target.value) || 0, activeMethod: 'fixed', useTrim: false })}
              className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] text-theme-main font-mono outline-none focus:border-theme-accent"
            />
          </div>
        </div>
        <div className="space-y-2">
          <label className="text-[8px] font-bold opacity-50 uppercase block">Modo de Escala</label>
          <div className="flex flex-col gap-1.5">
            {modes.map(mode => (
              <button
                key={mode.id}
                onClick={() => onSettingsChange({ ...settings, mode: mode.id, activeMethod: 'fixed', useTrim: false })}
                className={`flex items-center gap-3 px-3 py-1.5 rounded-lg border transition-all text-left ${settings.mode === mode.id && settings.activeMethod === 'fixed' && !settings.useTrim ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-panel/50 border-theme opacity-60 hover:opacity-100'}`}
              >
                <i className={`fas ${mode.icon} text-[9px]`}></i>
                <span className="text-[9px] font-black uppercase">{mode.label}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* BOX: RECORTE (TRIM) - ESPELHANDO O ESTILO DO FIXO */}
      <div className={`p-4 rounded-2xl border transition-all duration-300 space-y-4 ${settings.useTrim ? 'bg-theme-accent/5 border-theme-accent shadow-sm' : 'border-theme bg-theme-panel/10 opacity-80'}`}>
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 flex justify-between">
          <span>Recorte Automático</span>
          {settings.useTrim && <i className="fas fa-crop text-theme-accent"></i>}
        </h3>

        <div className="grid grid-cols-1 gap-3">
          <div className="space-y-2">
            <div className="flex justify-between items-center px-1">
              <label className="text-[8px] font-bold opacity-50 uppercase">Margem Interna (px)</label>
              <span className="text-[10px] font-mono font-black text-theme-accent">{settings.trimMargin}px</span>
            </div>
            <input 
              type="range" 
              min="0" max="50" 
              value={settings.trimMargin}
              onChange={(e) => onSettingsChange({ ...settings, trimMargin: parseInt(e.target.value), useTrim: true })}
              className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent"
            />
          </div>
        </div>

        <button 
          onClick={() => onSettingsChange({ ...settings, useTrim: !settings.useTrim })}
          className={`w-full py-3 rounded-xl font-black text-[10px] border flex items-center justify-center gap-3 uppercase tracking-widest transition-all active:scale-95 ${settings.useTrim ? 'bg-theme-accent text-white border-theme-accent shadow-lg' : 'bg-theme-panel border-theme text-theme-main opacity-60 hover:opacity-100'}`}
        >
           <i className="fas fa-expand-arrows-alt"></i>
           <span>{settings.useTrim ? 'Modo Trim Ativo' : 'Ativar Recorte Trim'}</span>
        </button>
      </div>

      {/* EXPORTAÇÃO */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Exportação</h3>
        <div className="grid grid-cols-1 gap-2">
          <button onClick={() => selectMode('individual')} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${exportOptions.downloadIndividual ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/30 border-theme opacity-60'}`}>
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadIndividual ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>{exportOptions.downloadIndividual && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in"></div>}</div>
            <span className="text-[10px] font-black uppercase">Separados</span>
          </button>
          <button onClick={() => selectMode('zip')} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${exportOptions.downloadZip ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/30 border-theme opacity-60'}`}>
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadZip ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>{exportOptions.downloadZip && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in"></div>}</div>
            <span className="text-[10px] font-black uppercase">Pacote (.ZIP)</span>
          </button>
        </div>
      </div>

      <div className="mt-auto pt-4">
        <button onClick={onSave} disabled={isProcessing || total === 0} className="w-full py-4 rounded-xl font-black text-[11px] bg-theme-accent text-theme-inv shadow-2xl flex items-center justify-center gap-2 uppercase tracking-widest disabled:opacity-50 active:scale-95 transition-transform">
           {isProcessing ? <><i className="fas fa-spinner animate-spin"></i> {progress}/{total}</> : <><i className="fas fa-save"></i> Salvar Lote</>}
        </button>
      </div>
    </div>
  );
};

export default SidebarResizer;

import React, { useState, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarResizer from '../components/SidebarResizer';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage } from '../types';

export type ResizeMode = 'fit' | 'fill' | 'stretch';
export type ResizeMethod = 'fixed' | 'proportional';

const ResizerTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);

  const [settings, setSettings] = useState({
    width: 1080,
    height: 1080,
    mode: 'fit' as ResizeMode,
    useTrim: false,
    trimMargin: 0,
    lockAspectRatio: true,
    boundSize: 1080,
    boundType: 'max' as 'max' | 'min',
    activeMethod: 'fixed' as ResizeMethod
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // IMPORTAÇÃO ROBUSTA: Processa todos os arquivos antes de atualizar o estado final
  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;

    const files = Array.from(e.target.files);
    const loadedImages: GridImage[] = [];

    for (const file of files) {
      try {
        const url = URL.createObjectURL(file);
        const img = await new Promise<HTMLImageElement>((resolve, reject) => {
          const i = new Image();
          i.onload = () => resolve(i);
          i.onerror = reject;
          i.src = url;
        });

        loadedImages.push({
          id: uuidv4(),
          file,
          previewUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height
        });
      } catch (err) {
        console.error("Falha ao carregar arquivo:", file.name);
      }
    }

    if (loadedImages.length > 0) {
      setImages(prev => [...prev, ...loadedImages]);
    }

    // Limpa o input para permitir novas seleções
    if (e.target) e.target.value = '';
  };

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error("Erro ao carregar imagem"));
      img.src = url;
    });
  };

  // Algoritmo de Trim: Escaneia pixels não transparentes
  const getTrimBounds = (canvas: HTMLCanvasElement, ctx: CanvasRenderingContext2D) => {
    const { width, height } = canvas;
    const imageData = ctx.getImageData(0, 0, width, height).data;
    let minX = width, minY = height, maxX = 0, maxY = 0;
    let found = false;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const alpha = imageData[(y * width + x) * 4 + 3];
        if (alpha > 0) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
          found = true;
        }
      }
    }

    if (!found) return { x: 0, y: 0, w: width, h: height };

    return {
      x: minX,
      y: minY,
      w: (maxX - minX) + 1,
      h: (maxY - minY) + 1
    };
  };

  const handleSave = async () => {
    if (images.length === 0) return;

    setIsProcessing(true);
    setProcessProgress(0);

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const zip = downloadZip ? new JSZip() : null;

    try {
      for (let i = 0; i < images.length; i++) {
        setProcessProgress(i + 1);
        const item = images[i];
        const imgObj = await loadImage(item.previewUrl);

        if (settings.useTrim) {
          // MODO RECORTE TRIM
          canvas.width = item.width;
          canvas.height = item.height;
          ctx.clearRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(imgObj, 0, 0);

          const bounds = getTrimBounds(canvas, ctx);
          const margin = settings.trimMargin;

          canvas.width = bounds.w + (margin * 2);
          canvas.height = bounds.h + (margin * 2);
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          ctx.drawImage(
            imgObj, 
            bounds.x, bounds.y, bounds.w, bounds.h,
            margin, margin, bounds.w, bounds.h
          );
        } else {
          // MODO REDIMENSIONAMENTO PADRÃO
          let finalWidth = settings.width;
          let finalHeight = settings.height;
          let drawW = finalWidth;
          let drawH = finalHeight;
          let offsetX = 0;
          let offsetY = 0;

          if (settings.activeMethod === 'proportional') {
            const size = settings.boundSize;
            if (settings.boundType === 'max') {
              if (item.width >= item.height) {
                finalWidth = size;
                finalHeight = size / item.aspectRatio;
              } else {
                finalHeight = size;
                finalWidth = size * item.aspectRatio;
              }
            } else {
              if (item.width >= item.height) {
                finalHeight = size;
                finalWidth = size * item.aspectRatio;
              } else {
                finalWidth = size;
                finalHeight = size / item.aspectRatio;
              }
            }
            drawW = finalWidth;
            drawH = finalHeight;
          }

          canvas.width = finalWidth;
          canvas.height = finalHeight;
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          if (settings.activeMethod === 'fixed') {
            if (settings.mode === 'fit') {
              const ratio = Math.min(canvas.width / item.width, canvas.height / item.height);
              drawW = item.width * ratio;
              drawH = item.height * ratio;
              offsetX = (canvas.width - drawW) / 2;
              offsetY = (canvas.height - drawH) / 2;
            } else if (settings.mode === 'fill') {
              const ratio = Math.max(canvas.width / item.width, canvas.height / item.height);
              drawW = item.width * ratio;
              drawH = item.height * ratio;
              offsetX = (canvas.width - drawW) / 2;
              offsetY = (canvas.height - drawH) / 2;
            }
          }
          ctx.drawImage(imgObj, offsetX, offsetY, drawW, drawH);
        }

        const dataUrl = canvas.toDataURL('image/png', 1.0);
        const fileName = `${item.file.name.split('.')[0]}_miau.png`;

        if (downloadIndividual) {
          const link = document.createElement('a');
          link.download = fileName;
          link.href = dataUrl;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          await new Promise(r => setTimeout(r, 400));
        }

        if (zip) {
          const base64Data = dataUrl.split(',')[1];
          zip.file(fileName, base64Data, { base64: true });
        }
      }

      if (zip) {
        const content = await zip.generateAsync({ type: "blob" });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(content);
        link.download = `master_resize_lote_${Date.now()}.zip`;
        link.click();
      }
    } catch (err) {
      console.error(err);
      alert("Erro ao processar lote.");
    } finally {
      setIsProcessing(false);
      setProcessProgress(0);
    }
  };

  const currentImg = images[selectedIdx];

  const clearAll = () => {
    if (window.confirm('Limpar fila Master?')) {
      images.forEach(img => URL.revokeObjectURL(img.previewUrl));
      setImages([]);
      setSelectedIdx(0);
    }
  };

  const getPreviewSize = () => {
    if (!currentImg) return { w: 1080, h: 1080 };
    if (settings.useTrim) return { w: currentImg.width, h: currentImg.height };
    if (settings.activeMethod === 'fixed') return { w: settings.width, h: settings.height };
    const size = settings.boundSize || 1080;
    return currentImg.width >= currentImg.height 
      ? { w: size, h: size / currentImg.aspectRatio } 
      : { w: size * currentImg.aspectRatio, h: size };
  };

  const preview = getPreviewSize();

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarResizer 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAdd={() => fileInputRef.current?.click()}
          onSave={handleSave}
          isProcessing={isProcessing}
          progress={processProgress}
          total={images.length}
          exportOptions={{
            downloadIndividual,
            setDownloadIndividual,
            downloadZip,
            setDownloadZip
          }}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={clearAll} />

        <div className="flex-1 flex items-center justify-center p-12 overflow-hidden bg-black/5">
          {currentImg ? (
            <div className="flex flex-col items-center gap-6 animate-in fade-in zoom-in duration-500">
               <div 
                className="relative shadow-2xl border border-theme bg-theme-panel group overflow-hidden"
                style={{ 
                   width: Math.min(preview.w * 0.4, 600), 
                   height: Math.min(preview.h * 0.4, 600),
                   backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)',
                   backgroundSize: '20px 20px'
                 }}>
                <img 
                  src={currentImg.previewUrl} 
                  className={`w-full h-full transition-all duration-300 ${settings.useTrim ? 'object-contain scale-90' : settings.activeMethod === 'proportional' ? 'object-contain' : settings.mode === 'fit' ? 'object-contain' : settings.mode === 'fill' ? 'object-cover' : 'object-fill'}`}
                  alt="Preview" 
                />
                {settings.useTrim && (
                  <div className="absolute inset-4 border border-theme-accent/30 border-dashed rounded flex items-center justify-center pointer-events-none">
                     <span className="bg-theme-accent text-white text-[7px] font-black uppercase px-2 py-0.5 rounded shadow-lg">Modo Trim: +{settings.trimMargin}px</span>
                  </div>
                )}
              </div>
              <div className="flex flex-col items-center gap-2">
                <p className="text-[10px] font-black uppercase opacity-30 tracking-widest bg-theme-panel px-4 py-1.5 rounded-full border border-theme shadow-sm">
                   {settings.useTrim ? 'Visualização Trim' : 'Preview Redimensionado'}
                </p>
                <p className="text-[8px] font-bold opacity-20 uppercase tracking-tight">{currentImg.width}x{currentImg.height}px → {Math.round(preview.w)}x{Math.round(preview.h)}px</p>
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-images text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Fila Master Vazia</p>
              <p className="text-[10px] font-bold uppercase opacity-50">Selecione arquivos para começar</p>
            </div>
          )}
        </div>

        {images.length > 1 && (
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-theme-side/90 border border-theme px-6 py-2 rounded-full shadow-2xl backdrop-blur-md">
            <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(prev => prev - 1)} className="w-8 h-8 rounded-full hover:bg-theme-accent/10 disabled:opacity-10 transition-all flex items-center justify-center"><i className="fas fa-chevron-left text-xs"></i></button>
            <span className="text-[10px] font-mono font-black text-theme-accent min-w-[60px] text-center">{selectedIdx + 1} / {images.length}</span>
            <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(prev => prev + 1)} className="w-8 h-8 rounded-full hover:bg-theme-accent/10 disabled:opacity-10 transition-all flex items-center justify-center"><i className="fas fa-chevron-right text-xs"></i></button>
          </div>
        )}
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <div className="p-4 border-b border-theme font-black text-[10px] uppercase tracking-widest text-theme-muted bg-black/5 flex justify-between items-center">
          <span>Fila de Imagens</span>
          <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">{images.length}</span>
        </div>
        <div className="flex-1 overflow-y-auto">
          <ImageList images={images} onRemove={(id) => {
             const newImgs = images.filter(img => img.id !== id);
             setImages(newImgs);
             if (selectedIdx >= newImgs.length) setSelectedIdx(Math.max(0, newImgs.length - 1));
          }} onMove={() => {}} />
        </div>
      </aside>
      <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

