import React, { useState, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import Sidebar from '../components/Sidebar';
import GridPreview from '../components/GridPreview';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage, GridSettings } from '../types';

const GridTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [settings, setSettings] = useState<GridSettings>({
    canvasWidth: 2048,
    canvasHeight: 2048,
    columns: 3,
    innerSpacing: 5,
    outerMargin: 5,
    backgroundColor: '#0f172a',
    isTransparent: false
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  // IMPORTAÇÃO SEQUENCIAL ROBUSTA
  const processFiles = async (files: File[]) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    const filteredFiles = files.filter(file => validTypes.includes(file.type));
    const newImages: GridImage[] = [];

    for (const file of filteredFiles) {
      try {
        const url = URL.createObjectURL(file);
        const img = await new Promise<HTMLImageElement>((resolve, reject) => {
          const i = new Image();
          i.onload = () => resolve(i);
          i.onerror = reject;
          i.src = url;
        });

        newImages.push({
          id: uuidv4(),
          file,
          previewUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height
        });
      } catch (err) {
        console.error("Erro ao processar imagem:", file.name);
      }
    }

    if (newImages.length > 0) {
      setImages(prev => [...prev, ...newImages]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      let filesArray = Array.from(e.target.files) as File[];
      processFiles(filesArray);
    }
    if (e.target) e.target.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => {
      const target = prev.find(img => img.id === id);
      if (target) URL.revokeObjectURL(target.previewUrl);
      return prev.filter(img => img.id !== id);
    });
  };

  const moveImage = (index: number, direction: 'up' | 'down') => {
    const newImages = [...images];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex >= 0 && targetIndex < newImages.length) {
      [newImages[index], newImages[targetIndex]] = [newImages[targetIndex], newImages[index]];
      setImages(newImages);
    }
  };

  const handleExport = async () => {
    const canvas = document.getElementById('grid-canvas') as HTMLCanvasElement;
    if (!canvas) return;

    const fileName = `grid_${Date.now()}.png`;
    const dataUrl = canvas.toDataURL('image/png', 1.0);

    if (downloadIndividual) {
      const link = document.createElement('a');
      link.download = fileName;
      link.href = dataUrl;
      link.click();
    }

    if (downloadZip) {
      const zip = new JSZip();
      const base64Data = dataUrl.split(',')[1];
      zip.file(fileName, base64Data, { base64: true });
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `grid_pack_${Date.now()}.zip`;
      link.click();
    }
  };

  const clearAll = () => {
    if (window.confirm('Remover todos os itens da galeria?')) {
      images.forEach(img => {
        if (img.previewUrl) URL.revokeObjectURL(img.previewUrl);
      });
      setImages([]);
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden">
      <aside className="w-80 flex-shrink-0 border-r overflow-y-auto bg-theme-side border-theme">
        <Sidebar 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddFile={() => fileInputRef.current?.click()}
          onAddFolder={() => folderInputRef.current?.click()}
          images={images}
          exportOptions={{
            downloadIndividual,
            setDownloadIndividual,
            downloadZip,
            setDownloadZip
          }}
          onExport={handleExport}
        />
      </aside>

      <section className="flex-1 overflow-hidden relative flex flex-col bg-theme-main">
        <Header itemCount={images.length} onClear={clearAll} />
        <div className="flex-1 relative flex items-center justify-center p-8 bg-black/5">
          <GridPreview images={images} settings={settings} />
        </div>
      </section>

      <aside className="w-80 flex-shrink-0 border-l overflow-hidden flex flex-col bg-theme-side border-theme">
        <div className="p-4 border-b font-black text-[10px] uppercase tracking-widest flex justify-between items-center text-theme-muted bg-black/5">
          <span>Galeria da Grid</span>
          <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">
            {images.length}
          </span>
        </div>
        <ImageList 
          images={images} 
          onRemove={removeImage} 
          onMove={moveImage}
        />
      </aside>

      <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
      <input 
        type="file" 
        {...({ webkitdirectory: "" } as any)} 
        className="hidden" 
        ref={folderInputRef} 
        onChange={handleFileChange} 
      />
    </div>
  );
};

export default GridTool;

import React, { useState, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarResizer from '../components/SidebarResizer';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage } from '../types';

export type ResizeMode = 'fit' | 'fill' | 'stretch';
export type ResizeMethod = 'fixed' | 'proportional';

const ResizerTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);

  const [settings, setSettings] = useState({
    width: 1080,
    height: 1080,
    mode: 'fit' as ResizeMode,
    useTrim: false,
    trimMargin: 0,
    lockAspectRatio: true,
    boundSize: 1080,
    boundType: 'max' as 'max' | 'min',
    activeMethod: 'fixed' as ResizeMethod
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // IMPORTAÇÃO DE ALTA PERFORMANCE: Paralela com tratamento de erro por arquivo
  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;

    const files = Array.from(e.target.files);

    // Processa todos em paralelo para velocidade máxima
    const promises = files.map(async (file) => {
      // Verifica TIFF (Navegadores não suportam nativamente)
      if (file.name.toLowerCase().endsWith('.tiff') || file.name.toLowerCase().endsWith('.tif')) {
        throw new Error(`O formato TIFF não é suportado pelo navegador: ${file.name}`);
      }

      const url = URL.createObjectURL(file);
      return new Promise<GridImage>((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
          resolve({
            id: uuidv4(),
            file,
            previewUrl: url,
            width: img.width,
            height: img.height,
            aspectRatio: img.width / img.height
          });
        };
        img.onerror = () => {
          URL.revokeObjectURL(url);
          reject(new Error(`Erro ao carregar imagem: ${file.name}`));
        };
        img.src = url;
      });
    });

    const results = await Promise.allSettled(promises);

    const successfulImages = results
      .filter((result): result is PromiseFulfilledResult<GridImage> => result.status === 'fulfilled')
      .map(result => result.value);

    const failedCount = results.filter(result => result.status === 'rejected').length;

    if (successfulImages.length > 0) {
      setImages(prev => [...prev, ...successfulImages]);
    }

    if (failedCount > 0) {
      console.warn(`${failedCount} arquivo(s) não puderam ser carregados (provavelmente formatos não suportados como TIFF).`);
      alert(`${failedCount} arquivo(s) falharam. Verifique o console para detalhes (TIFFs não são suportados).`);
    }

    if (e.target) e.target.value = '';
  };

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error("Erro ao carregar"));
      img.src = url;
    });
  };

  // SMART TRIM: Detecção agressiva de bordas
  const getTrimBounds = (canvas: HTMLCanvasElement, ctx: CanvasRenderingContext2D) => {
    const { width, height } = canvas;
    const imageData = ctx.getImageData(0, 0, width, height).data;
    let minX = width, minY = height, maxX = 0, maxY = 0;
    let found = false;

    // Escaneia pixels buscando qualquer canal alfa > 0 (transparência não-total)
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const alpha = imageData[(y * width + x) * 4 + 3];
        if (alpha > 0) { 
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
          found = true;
        }
      }
    }

    if (!found) return { x: 0, y: 0, w: width, h: height };

    // Retorna as coordenadas exatas do conteúdo
    return {
      x: minX,
      y: minY,
      w: (maxX - minX) + 1,
      h: (maxY - minY) + 1
    };
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true);
    setProcessProgress(0);

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const zip = downloadZip ? new JSZip() : null;

    try {
      for (let i = 0; i < images.length; i++) {
        setProcessProgress(i + 1);
        const item = images[i];
        const imgObj = await loadImage(item.previewUrl);

        if (settings.useTrim) {
          // Processo de TRIM
          canvas.width = item.width;
          canvas.height = item.height;
          ctx.clearRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(imgObj, 0, 0);

          const bounds = getTrimBounds(canvas, ctx);
          const margin = settings.trimMargin;

          // Cria canvas no tamanho exato do conteúdo + margem
          canvas.width = bounds.w + (margin * 2);
          canvas.height = bounds.h + (margin * 2);
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          ctx.drawImage(
            imgObj, 
            bounds.x, bounds.y, bounds.w, bounds.h, // O que copiar (recortado)
            margin, margin, bounds.w, bounds.h     // Onde colar (com margem)
          );
        } else {
          // Redimensionamento Padrão
          let finalWidth = settings.width;
          let finalHeight = settings.height;
          let drawW = finalWidth;
          let drawH = finalHeight;
          let offsetX = 0;
          let offsetY = 0;

          if (settings.activeMethod === 'proportional') {
            const size = settings.boundSize;
            if (settings.boundType === 'max') {
              if (item.width >= item.height) {
                finalWidth = size;
                finalHeight = size / item.aspectRatio;
              } else {
                finalHeight = size;
                finalWidth = size * item.aspectRatio;
              }
            } else {
              if (item.width >= item.height) {
                finalHeight = size;
                finalWidth = size * item.aspectRatio;
              } else {
                finalWidth = size;
                finalHeight = size / item.aspectRatio;
              }
            }
            drawW = finalWidth;
            drawH = finalHeight;
          }

          canvas.width = finalWidth;
          canvas.height = finalHeight;
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          if (settings.activeMethod === 'fixed') {
            if (settings.mode === 'fit') {
              const ratio = Math.min(canvas.width / item.width, canvas.height / item.height);
              drawW = item.width * ratio;
              drawH = item.height * ratio;
              offsetX = (canvas.width - drawW) / 2;
              offsetY = (canvas.height - drawH) / 2;
            } else if (settings.mode === 'fill') {
              const ratio = Math.max(canvas.width / item.width, canvas.height / item.height);
              drawW = item.width * ratio;
              drawH = item.height * ratio;
              offsetX = (canvas.width - drawW) / 2;
              offsetY = (canvas.height - drawH) / 2;
            }
          }
          ctx.drawImage(imgObj, offsetX, offsetY, drawW, drawH);
        }

        const dataUrl = canvas.toDataURL('image/png', 1.0);
        const fileName = `${item.file.name.split('.')[0]}_miau.png`;

        if (downloadIndividual) {
          const link = document.createElement('a');
          link.download = fileName;
          link.href = dataUrl;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          await new Promise(r => setTimeout(r, 400));
        }

        if (zip) {
          const base64Data = dataUrl.split(',')[1];
          zip.file(fileName, base64Data, { base64: true });
        }
      }

      if (zip) {
        const content = await zip.generateAsync({ type: "blob" });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(content);
        link.download = `master_resize_${Date.now()}.zip`;
        link.click();
      }
    } catch (err) {
      console.error(err);
      alert("Erro ao processar lote.");
    } finally {
      setIsProcessing(false);
      setProcessProgress(0);
    }
  };

  const currentImg = images[selectedIdx];

  const clearAll = () => {
    if (window.confirm('Limpar fila Master?')) {
      images.forEach(img => URL.revokeObjectURL(img.previewUrl));
      setImages([]);
      setSelectedIdx(0);
    }
  };

  const getPreviewSize = () => {
    if (!currentImg) return { w: 1080, h: 1080 };
    if (settings.useTrim) return { w: currentImg.width, h: currentImg.height };
    if (settings.activeMethod === 'fixed') return { w: settings.width, h: settings.height };
    const size = settings.boundSize || 1080;
    return currentImg.width >= currentImg.height 
      ? { w: size, h: size / currentImg.aspectRatio } 
      : { w: size * currentImg.aspectRatio, h: size };
  };

  const preview = getPreviewSize();

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarResizer 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAdd={() => fileInputRef.current?.click()}
          onSave={handleSave}
          isProcessing={isProcessing}
          progress={processProgress}
          total={images.length}
          exportOptions={{
            downloadIndividual,
            setDownloadIndividual,
            downloadZip,
            setDownloadZip
          }}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={clearAll} />

        <div className="flex-1 flex items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex flex-col items-center gap-6 animate-in fade-in zoom-in duration-500">
               <div 
                className="relative shadow-2xl border border-theme bg-theme-panel group overflow-hidden"
                style={{ 
                   width: Math.min(preview.w * 0.4, 600), 
                   height: Math.min(preview.h * 0.4, 600),
                   backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)',
                   backgroundSize: '20px 20px'
                 }}>
                <img 
                  src={currentImg.previewUrl} 
                  className={`w-full h-full transition-all duration-300 ${settings.useTrim ? 'object-contain scale-90' : settings.activeMethod === 'proportional' ? 'object-contain' : settings.mode === 'fit' ? 'object-contain' : settings.mode === 'fill' ? 'object-cover' : 'object-fill'}`}
                  alt="Preview" 
                />
                {settings.useTrim && (
                  <div className="absolute inset-4 border border-theme-accent/30 border-dashed rounded flex items-center justify-center pointer-events-none">
                     <span className="bg-theme-accent text-white text-[7px] font-black uppercase px-2 py-0.5 rounded shadow-lg">Trim Ativo: +{settings.trimMargin}px</span>
                  </div>
                )}
              </div>
              <div className="flex flex-col items-center gap-2 text-center">
