        // O canal Alpha é o 4º valor de cada pixel (índice 3, 7, 11...)
        const alphaIndex = (y * width + x) * 4 + 3;
        const alpha = imageData[alphaIndex];

        // Se o pixel não for totalmente transparente (alpha > 0)
        if (alpha > 0) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
          foundSolidPixel = true;
        }
