        const item = images[i];
        const imgObj = await loadImage(item.previewUrl);

        if (settings.useTrim) {
          // LÓGICA DE AUTO CROP
          // 1. Prepara canvas temporário para ler os pixels originais
          canvas.width = item.width;
          canvas.height = item.height;
          ctx.clearRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(imgObj, 0, 0);

          // 2. Calcula os limites do conteúdo visível
          const bounds = getTrimBounds(canvas, ctx);
          const margin = settings.trimMargin;

          // 3. Define o tamanho final (Conteúdo + Margem de Respiro)
          canvas.width = bounds.w + (margin * 2);
          canvas.height = bounds.h + (margin * 2);
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          // 4. Desenha apenas a parte recortada centralizada
          ctx.drawImage(
            imgObj, 
            bounds.x, bounds.y, bounds.w, bounds.h, // O que copiar
            margin, margin, bounds.w, bounds.h     // Onde colar
          );
        } else {
          // Lógica de Redimensionamento Padrão
          let finalWidth = settings.width;
          let finalHeight = settings.height;
          let drawW = finalWidth;
          let drawH = finalHeight;
          let offsetX = 0;
          let offsetY = 0;

          if (settings.activeMethod === 'proportional') {
            const size = settings.boundSize;
            if (settings.boundType === 'max') {
              if (item.width >= item.height) {
                finalWidth = size;
                finalHeight = size / item.aspectRatio;
              } else {
                finalHeight = size;
                finalWidth = size * item.aspectRatio;
              }
            } else {
              if (item.width >= item.height) {
                finalHeight = size;
                finalWidth = size * item.aspectRatio;
              } else {
                finalWidth = size;
                finalHeight = size / item.aspectRatio;
              }
            }
            drawW = finalWidth;
            drawH = finalHeight;
          }

          canvas.width = finalWidth;
          canvas.height = finalHeight;
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          if (settings.activeMethod === 'fixed') {
            if (settings.mode === 'fit') {
              const ratio = Math.min(canvas.width / item.width, canvas.height / item.height);
              drawW = item.width * ratio;
              drawH = item.height * ratio;
              offsetX = (canvas.width - drawW) / 2;
              offsetY = (canvas.height - drawH) / 2;
            } else if (settings.mode === 'fill') {
              const ratio = Math.max(canvas.width / item.width, canvas.height / item.height);
              drawW = item.width * ratio;
              drawH = item.height * ratio;
              offsetX = (canvas.width - drawW) / 2;
              offsetY = (canvas.height - drawH) / 2;
            } else if (settings.mode === 'stretch') {
               drawW = finalWidth;
               drawH = finalHeight;
            }
          }
          ctx.drawImage(imgObj, offsetX, offsetY, drawW, drawH);
        }

        const dataUrl = canvas.toDataURL('image/png', 1.0);
        const fileName = `${item.file.name.split('.')[0]}_miau.png`;

        if (downloadIndividual) {
          const link = document.createElement('a');
          link.download = fileName;
          link.href = dataUrl;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          await new Promise(r => setTimeout(r, 400));
        }

        if (zip) {
          const base64Data = dataUrl.split(',')[1];
          zip.file(fileName, base64Data, { base64: true });
        }
      }

      if (zip) {
        const content = await zip.generateAsync({ type: "blob" });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(content);
        link.download = `master_trim_${Date.now()}.zip`;
        link.click();
      }
    } catch (err) {
      console.error(err);
      alert("Erro ao processar lote.");
    } finally {
      setIsProcessing(false);
      setProcessProgress(0);
    }
  };

  const currentImg = images[selectedIdx];

  const clearAll = () => {
    if (window.confirm('Limpar fila Master?')) {
      images.forEach(img => URL.revokeObjectURL(img.previewUrl));
      setImages([]);
      setSelectedIdx(0);
    }
  };

  const getPreviewSize = () => {
    if (!currentImg) return { w: 1080, h: 1080 };
    if (settings.useTrim) return { w: currentImg.width, h: currentImg.height };
    if (settings.activeMethod === 'fixed') return { w: settings.width, h: settings.height };
    const size = settings.boundSize || 1080;
    return currentImg.width >= currentImg.height 
      ? { w: size, h: size / currentImg.aspectRatio } 
      : { w: size * currentImg.aspectRatio, h: size };
  };

  const preview = getPreviewSize();

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarResizer 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAdd={() => fileInputRef.current?.click()}
          onSave={handleSave}
          isProcessing={isProcessing}
          progress={processProgress}
          total={images.length}
          exportOptions={{
            downloadIndividual,
            setDownloadIndividual,
            downloadZip,
            setDownloadZip
          }}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={clearAll} />

        <div className="flex-1 flex items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex flex-col items-center gap-6 animate-in fade-in zoom-in duration-500">
               <div 
                className="relative shadow-2xl border border-theme bg-theme-panel group overflow-hidden"
                style={{ 
                   width: Math.min(preview.w * 0.4, 600), 
                   height: Math.min(preview.h * 0.4, 600),
                   backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)',
                   backgroundSize: '20px 20px'
                 }}>
                <img 
                  src={currentImg.previewUrl} 
                  className={`w-full h-full transition-all duration-300 ${settings.useTrim ? 'object-contain scale-95 opacity-80' : settings.activeMethod === 'proportional' ? 'object-contain' : settings.mode === 'fit' ? 'object-contain' : settings.mode === 'fill' ? 'object-cover' : 'object-fill'}`}
                  alt="Preview" 
                />
                {settings.useTrim && (
                  <div className="absolute inset-0 border-2 border-theme-accent/30 border-dashed rounded flex items-center justify-center pointer-events-none bg-theme-accent/5">
                     <div className="flex flex-col items-center gap-2">
                        <i className="fas fa-magic text-theme-accent text-2xl animate-pulse"></i>
                        <span className="bg-theme-accent text-white text-[8px] font-black uppercase px-3 py-1 rounded-full shadow-lg">Smart Auto-Crop Ativo</span>
                        <span className="text-[7px] font-bold text-theme-accent opacity-60">Removendo Transparência Vazia</span>
                     </div>
                  </div>
                )}
              </div>
              <div className="flex flex-col items-center gap-2 text-center">
                <p className="text-[10px] font-black uppercase opacity-30 tracking-widest bg-theme-panel px-4 py-1.5 rounded-full border border-theme shadow-sm">
                   {settings.useTrim ? 'Auto Crop Analysis' : 'Preview Redimensionado'}
                </p>
                <p className="text-[8px] font-bold opacity-20 uppercase tracking-tight">
                  {currentImg.width}x{currentImg.height}px → {settings.useTrim ? 'Saída Dinâmica (Ajustada)' : `${Math.round(preview.w)}x${Math.round(preview.h)}px`}
                </p>
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-expand-arrows-alt text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Master Resizer</p>
              <p className="text-[10px] font-bold uppercase tracking-widest">Aguardando Imagens</p>
            </div>
          )}
        </div>

        {images.length > 1 && (
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-theme-side/90 border border-theme px-6 py-2 rounded-full shadow-2xl backdrop-blur-md">
            <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(prev => prev - 1)} className="w-8 h-8 rounded-full hover:bg-theme-accent/10 disabled:opacity-10 transition-all flex items-center justify-center"><i className="fas fa-chevron-left text-xs"></i></button>
            <span className="text-[10px] font-mono font-black text-theme-accent min-w-[60px] text-center">{selectedIdx + 1} / {images.length}</span>
            <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(prev => prev + 1)} className="w-8 h-8 rounded-full hover:bg-theme-accent/10 disabled:opacity-10 transition-all flex items-center justify-center"><i className="fas fa-chevron-right text-xs"></i></button>
          </div>
        )}
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <div className="p-4 border-b border-theme font-black text-[10px] uppercase tracking-widest text-theme-muted bg-black/5 flex justify-between items-center">
          <span>Fila Master</span>
          <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">{images.length}</span>
        </div>
        <div className="flex-1 overflow-y-auto">
          <ImageList images={images} onRemove={(id) => {
             const newImgs = images.filter(img => img.id !== id);
             setImages(newImgs);
             if (selectedIdx >= newImgs.length) setSelectedIdx(Math.max(0, newImgs.length - 1));
          }} onMove={() => {}} />
        </div>
      </aside>
      <input type="file" multiple accept="image/png, image/jpeg, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default ResizerTool;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarResizer from '../components/SidebarResizer';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage } from '../types';

export type ResizeMode = 'fit' | 'fill' | 'stretch';
export type ResizeMethod = 'fixed' | 'proportional';

interface CropBounds {
  x: number; y: number; w: number; h: number;
}

const ResizerTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [currentTrimBounds, setCurrentTrimBounds] = useState<CropBounds | null>(null);

  const [settings, setSettings] = useState({
    width: 1080,
    height: 1080,
    mode: 'fit' as ResizeMode,
    useTrim: false,
    trimMargin: 0,
    lockAspectRatio: true,
    boundSize: 1080,
    boundType: 'max' as 'max' | 'min',
    activeMethod: 'fixed' as ResizeMethod
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  // Calcula os limites de transparência (Bounding Box)
  const getTrimBounds = (img: HTMLImageElement | HTMLCanvasElement) => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return null;

    canvas.width = img.width;
    canvas.height = img.height;
    ctx.drawImage(img, 0, 0);

    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
    let minX = canvas.width, minY = canvas.height, maxX = 0, maxY = 0;
    let found = false;

    for (let y = 0; y < canvas.height; y++) {
      for (let x = 0; x < canvas.width; x++) {
        if (imageData[(y * canvas.width + x) * 4 + 3] > 0) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
          found = true;
        }
      }
    }

    if (!found) return { x: 0, y: 0, w: canvas.width, h: canvas.height };
    return { x: minX, y: minY, w: (maxX - minX) + 1, h: (maxY - minY) + 1 };
  };

  // Atualiza o cálculo do recorte sempre que a imagem selecionada mudar
  useEffect(() => {
    const updateBounds = async () => {
      if (!images[selectedIdx]) {
        setCurrentTrimBounds(null);
        return;
      }
      const img = await loadImage(images[selectedIdx].previewUrl);
      const bounds = getTrimBounds(img);
      setCurrentTrimBounds(bounds);
    };
    updateBounds();
  }, [selectedIdx, images]);

  // Atualiza o Canvas de Preview em Tempo Real
  useEffect(() => {
    const drawPreview = async () => {
      if (!previewCanvasRef.current || !images[selectedIdx] || !currentTrimBounds) return;
      const canvas = previewCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const img = await loadImage(images[selectedIdx].previewUrl);
      const margin = settings.trimMargin;

      if (settings.useTrim) {
        canvas.width = currentTrimBounds.w + (margin * 2);
        canvas.height = currentTrimBounds.h + (margin * 2);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(
          img,
          currentTrimBounds.x, currentTrimBounds.y, currentTrimBounds.w, currentTrimBounds.h,
          margin, margin, currentTrimBounds.w, currentTrimBounds.h
        );
      } else {
        // Preview de redimensionamento padrão (simplificado para o canvas)
        canvas.width = settings.width;
        canvas.height = settings.height;
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        let drawW = canvas.width;
        let drawH = canvas.height;
        let ox = 0, oy = 0;

        const ratio = Math.min(canvas.width / img.width, canvas.height / img.height);
        drawW = img.width * ratio;
        drawH = img.height * ratio;
        ox = (canvas.width - drawW) / 2;
        oy = (canvas.height - drawH) / 2;

        ctx.drawImage(img, ox, oy, drawW, drawH);
      }
    };
    drawPreview();
  }, [selectedIdx, images, currentTrimBounds, settings.useTrim, settings.trimMargin, settings.width, settings.height]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const files = Array.from(e.target.files) as File[];
    const promises = files.map(async (file) => {
      if (file.name.toLowerCase().endsWith('.tiff') || file.name.toLowerCase().endsWith('.tif')) {
        throw new Error(`TIFF não suportado: ${file.name}`);
      }
      const url = URL.createObjectURL(file);
      return new Promise<GridImage>((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve({ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height });
        img.onerror = () => { URL.revokeObjectURL(url); reject(new Error("Erro")); };
        img.src = url;
      });
    });
    const results = await Promise.allSettled(promises);
    const successful = results.filter((r): r is PromiseFulfilledResult<GridImage> => r.status === 'fulfilled').map(r => r.value);
    if (successful.length > 0) setImages(prev => [...prev, ...successful]);
    if (e.target) e.target.value = '';
  };

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error("Erro"));
      img.src = url;
    });
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true);
    setProcessProgress(0);
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;
    const zip = downloadZip ? new JSZip() : null;

    try {
      for (let i = 0; i < images.length; i++) {
        setProcessProgress(i + 1);
        const item = images[i];
        const imgObj = await loadImage(item.previewUrl);

        if (settings.useTrim) {
          const bounds = getTrimBounds(imgObj);
          if (bounds) {
            const margin = settings.trimMargin;
            canvas.width = bounds.w + (margin * 2);
            canvas.height = bounds.h + (margin * 2);
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.drawImage(imgObj, bounds.x, bounds.y, bounds.w, bounds.h, margin, margin, bounds.w, bounds.h);
          }
        } else {
          canvas.width = settings.width;
          canvas.height = settings.height;
          ctx.clearRect(0, 0, canvas.width, canvas.height);
          const ratio = Math.min(canvas.width / item.width, canvas.height / item.height);
          const dW = item.width * ratio;
          const dH = item.height * ratio;
          ctx.drawImage(imgObj, (canvas.width - dW) / 2, (canvas.height - dH) / 2, dW, dH);
        }

        const dataUrl = canvas.toDataURL('image/png', 1.0);
        const fileName = `${item.file.name.split('.')[0]}_miau.png`;
        if (downloadIndividual) {
          const link = document.createElement('a');
          link.download = fileName; link.href = dataUrl;
          document.body.appendChild(link); link.click(); document.body.removeChild(link);
          await new Promise(r => setTimeout(r, 400));
        }
        if (zip) zip.file(fileName, dataUrl.split(',')[1], { base64: true });
      }
      if (zip) {
        const content = await zip.generateAsync({ type: "blob" });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(content); link.download = `master_export_${Date.now()}.zip`; link.click();
      }
    } catch (err) { console.error(err); } finally { setIsProcessing(false); setProcessProgress(0); }
  };

  const currentImg = images[selectedIdx];
  const previewSize = settings.useTrim && currentTrimBounds 
    ? { w: currentTrimBounds.w + (settings.trimMargin * 2), h: currentTrimBounds.h + (settings.trimMargin * 2) }
    : { w: settings.width, h: settings.height };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarResizer 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAdd={() => fileInputRef.current?.click()}
          onSave={handleSave}
          isProcessing={isProcessing}
          progress={processProgress}
          total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />

        <div className="flex-1 flex items-center justify-center p-12 overflow-hidden bg-black/10 relative">
          {currentImg ? (
            <div className="flex flex-col items-center gap-6 animate-in fade-in zoom-in duration-500">
               {/* BANNER DE STATUS NO TOPO DO PREVIEW */}
               {settings.useTrim && (
                 <div className="absolute top-6 left-1/2 -translate-x-1/2 flex items-center gap-2 bg-theme-accent text-white px-4 py-1.5 rounded-full shadow-lg z-20 border border-white/20 scale-90">
                    <i className="fas fa-magic text-[10px]"></i>
                    <span className="text-[9px] font-black uppercase tracking-[0.2em]">Auto Crop Ativado</span>
                 </div>
               )}

               <div 
                className="relative shadow-2xl border border-theme bg-theme-panel group overflow-hidden"
                style={{ 
                   width: Math.min(previewSize.w * 0.4, 600), 
                   height: Math.min(previewSize.h * 0.4, 600),
                   backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                   backgroundSize: '16px 16px'
                 }}>
                <canvas 
                  ref={previewCanvasRef}
                  className="w-full h-full object-contain"
                />
              </div>

              <div className="flex flex-col items-center gap-2 text-center">
                <p className="text-[10px] font-black uppercase opacity-40 tracking-widest bg-theme-panel px-4 py-1.5 rounded-full border border-theme">
                   {settings.useTrim ? 'Visualização do Recorte Real' : 'Visualização Fixo'}
                </p>
                <p className="text-[8px] font-bold opacity-30 uppercase">
                  {currentImg.width}x{currentImg.height}px → {Math.round(previewSize.w)}x{Math.round(previewSize.h)}px
                </p>
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-expand-arrows-alt text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Master Resizer</p>
            </div>
          )}
        </div>

        {images.length > 1 && (
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-theme-side/90 border border-theme px-6 py-2 rounded-full shadow-2xl backdrop-blur-md">
            <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(prev => prev - 1)} className="w-8 h-8 rounded-full hover:bg-theme-accent/10 disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
            <span className="text-[10px] font-mono font-black text-theme-accent min-w-[60px] text-center">{selectedIdx + 1} / {images.length}</span>
            <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(prev => prev + 1)} className="w-8 h-8 rounded-full hover:bg-theme-accent/10 disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-xs"></i></button>
          </div>
        )}
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <div className="p-4 border-b border-theme font-black text-[10px] uppercase tracking-widest text-theme-muted bg-black/5 flex justify-between items-center">
          <span>Fila Master</span>
          <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">{images.length}</span>
        </div>
        <div className="flex-1 overflow-y-auto">
          <ImageList images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} />
        </div>
      </aside>
      <input type="file" multiple accept="image/png, image/jpeg, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default ResizerTool;

import React from 'react';
import { ResizeMode } from '../tools/ResizerTool';

interface SidebarResizerProps {
  settings: any;
  onSettingsChange: (s: any) => void;
  onAdd: () => void;
  onSave: () => void;
  isProcessing?: boolean;
  progress?: number;
  total?: number;
  exportOptions: {
    downloadIndividual: boolean;
    setDownloadIndividual: (v: boolean) => void;
    downloadZip: boolean;
    setDownloadZip: (v: boolean) => void;
  };
}

const SidebarResizer: React.FC<SidebarResizerProps> = ({ 
  settings, 
  onSettingsChange, 
  onAdd, 
  onSave,
  isProcessing = false,
  progress = 0,
  total = 0,
  exportOptions
}) => {
  const modes: { id: ResizeMode; label: string; icon: string }[] = [
    { id: 'fit', label: 'Conter (Fit)', icon: 'fa-compress' },
    { id: 'fill', label: 'Cobrir (Fill)', icon: 'fa-expand' },
    { id: 'stretch', label: 'Esticar', icon: 'fa-arrows-alt' },
  ];

  const selectMode = (mode: 'individual' | 'zip') => {
    if (mode === 'individual') {
      exportOptions.setDownloadIndividual(true);
      exportOptions.setDownloadZip(false);
    } else {
      exportOptions.setDownloadIndividual(false);
      exportOptions.setDownloadZip(true);
    }
  };

  return (
    <div className="p-5 space-y-6 h-full overflow-y-auto scrollbar-hide flex flex-col">
      {/* ENTRADA */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Entrada</h3>
