import React, { useRef, useEffect, useCallback } from 'react';
import { GridImage, GridSettings } from '../types';

interface GridPreviewProps {
  images: GridImage[];
  settings: GridSettings;
  zoom?: number;
}

const GridPreview: React.FC<GridPreviewProps> = ({ images, settings, zoom = 0.4 }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const renderRequestId = useRef<number>(0);

  const drawGrid = useCallback(async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Sincroniza o tamanho do canvas com as configurações
    if (canvas.width !== settings.canvasWidth || canvas.height !== settings.canvasHeight) {
      canvas.width = settings.canvasWidth;
      canvas.height = settings.canvasHeight;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!settings.isTransparent) {
      ctx.fillStyle = settings.backgroundColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    if (images.length === 0) return;

    const cols = settings.columns;
    const margin = settings.outerMargin;
    const spacing = settings.innerSpacing;

    const availableWidth = canvas.width - (2 * margin) - ((cols - 1) * spacing);
    const cellWidth = availableWidth / cols;
    const rows = Math.ceil(images.length / cols);
    const availableHeight = canvas.height - (2 * margin) - ((rows - 1) * spacing);
    const cellHeight = availableHeight / rows;

    const loadAndDraw = (imgObj: GridImage, index: number) => {
      return new Promise<void>((resolve) => {
        const col = index % cols;
        const row = Math.floor(index / cols);
        const x = margin + (col * (cellWidth + spacing));
        const y = margin + (row * (cellHeight + spacing));

        const img = new Image();
        img.onload = () => {
          let drawW = cellWidth;
          let drawH = cellWidth / imgObj.aspectRatio;
          if (drawH > cellHeight) {
            drawH = cellHeight;
            drawW = cellHeight * imgObj.aspectRatio;
          }
          const offsetX = x + (cellWidth - drawW) / 2;
          const offsetY = y + (cellHeight - drawH) / 2;
          ctx.drawImage(img, offsetX, offsetY, drawW, drawH);
          resolve();
        };
        img.src = imgObj.previewUrl;
      });
    };

    // Desenha as imagens sequencialmente ou em paralelo (aqui usamos Promise.all para ser mais rápido)
    await Promise.all(images.map((img, i) => loadAndDraw(img, i)));
  }, [images, settings]);

  useEffect(() => {
    // Cancela qualquer renderização pendente
    if (renderRequestId.current) {
      cancelAnimationFrame(renderRequestId.current);
    }

    // Agenda a renderização usando requestAnimationFrame para evitar flickering
    renderRequestId.current = requestAnimationFrame(() => {
      drawGrid();
    });

    return () => {
      if (renderRequestId.current) {
        cancelAnimationFrame(renderRequestId.current);
      }
    };
  }, [drawGrid]);

  return (
    <div className="w-full h-full flex items-center justify-center overflow-auto scrollbar-hide">
      <div 
        className="shadow-2xl relative border bg-theme-panel rounded-lg overflow-hidden transition-all duration-300"
        style={{
          width: settings.canvasWidth * zoom,
          height: settings.canvasHeight * zoom,
          borderColor: 'var(--border)',
          backgroundImage: settings.isTransparent ? 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)' : 'none',
          backgroundSize: '20px 20px',
          willChange: 'width, height'
        }}
      >
        <canvas 
          id="grid-canvas" 
          ref={canvasRef} 
          className="w-full h-full block" 
          style={{ imageRendering: 'auto' }}
        />
      </div>
    </div>
  );
};

