import React, { useState, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import Sidebar from '../components/Sidebar';
import GridPreview from '../components/GridPreview';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage, GridSettings } from '../types';

const GridTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [settings, setSettings] = useState<GridSettings>({
    canvasWidth: 2048,
    canvasHeight: 2048,
    columns: 3,
    innerSpacing: 5,
    outerMargin: 5,
    backgroundColor: '#0f172a',
    isTransparent: false
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  const processFiles = async (files: File[]) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    const filteredFiles = files.filter(file => validTypes.includes(file.type));
    const newImages: GridImage[] = [];

    for (const file of filteredFiles) {
      try {
        const url = URL.createObjectURL(file);
        const img = await new Promise<HTMLImageElement>((resolve, reject) => {
          const i = new Image();
          i.onload = () => resolve(i);
          i.onerror = reject;
          i.src = url;
        });

        newImages.push({
          id: uuidv4(),
          file,
          previewUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height
        });
      } catch (err) {
        console.error("Erro ao processar imagem:", file.name);
      }
    }

    if (newImages.length > 0) {
      setImages(prev => [...prev, ...newImages]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      let filesArray = Array.from(e.target.files) as File[];
      processFiles(filesArray);
    }
    if (e.target) e.target.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => {
      const target = prev.find(img => img.id === id);
      if (target) URL.revokeObjectURL(target.previewUrl);
      return prev.filter(img => img.id !== id);
    });
  };

  const moveImage = (index: number, direction: 'up' | 'down') => {
    const newImages = [...images];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex >= 0 && targetIndex < newImages.length) {
      [newImages[index], newImages[targetIndex]] = [newImages[targetIndex], newImages[index]];
      setImages(newImages);
    }
  };

  const handleExport = async () => {
    const canvas = document.getElementById('grid-canvas') as HTMLCanvasElement;
    if (!canvas) return;

    const fileName = `grid_${Date.now()}.png`;
    const dataUrl = canvas.toDataURL('image/png', 1.0);

    if (downloadIndividual) {
      const link = document.createElement('a');
      link.download = fileName;
      link.href = dataUrl;
      link.click();
    }

    if (downloadZip) {
      const zip = new JSZip();
      const base64Data = dataUrl.split(',')[1];
      zip.file(fileName, base64Data, { base64: true });
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `grid_pack_${Date.now()}.zip`;
      link.click();
    }
  };

  const clearAll = () => {
    if (window.confirm('Remover todos os itens da galeria?')) {
      images.forEach(img => {
        if (img.previewUrl) URL.revokeObjectURL(img.previewUrl);
      });
      setImages([]);
      setOffset({ x: 0, y: 0 });
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden">
      <aside className="w-80 flex-shrink-0 border-r overflow-y-auto bg-theme-side border-theme">
        <Sidebar 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddFile={() => fileInputRef.current?.click()}
          onAddFolder={() => folderInputRef.current?.click()}
          images={images}
          exportOptions={{
            downloadIndividual,
            setDownloadIndividual,
            downloadZip,
            setDownloadZip
          }}
          onExport={handleExport}
        />
      </aside>

      <section className="flex-1 overflow-hidden relative flex flex-col bg-theme-main">
        <Header itemCount={images.length} onClear={clearAll} />

        <div className="flex-1 relative flex flex-col items-center justify-center bg-black/5 overflow-hidden">

          <div className="flex-1 w-full h-full cursor-grab active:cursor-grabbing">
            <GridPreview 
              images={images} 
              settings={settings} 
              zoom={zoom} 
              offset={offset}
              onOffsetChange={setOffset}
            />
          </div>

          {/* PAINEL DE METADATA (RESOLUÇÃO) - ESTILO GLASS */}
          {images.length > 0 && (
            <div className="absolute bottom-24 flex flex-col items-center gap-4 animate-in fade-in slide-in-from-bottom-4 duration-700 pointer-events-none">
              <div className="flex items-center gap-4 bg-theme-side/70 border border-theme/40 px-5 py-2.5 rounded-2xl shadow-2xl backdrop-blur-xl">
                <div className="flex flex-col items-start leading-none gap-1">
                  <span className="text-[7px] font-black uppercase opacity-30 tracking-widest">Layout</span>
                  <span className="text-[11px] font-mono font-bold opacity-60 tracking-tighter">
                    {settings.columns} Cols <span className="opacity-30 mx-0.5">/</span> {Math.ceil(images.length / settings.columns)} Rows
                  </span>
                </div>

                <div className="w-[1px] h-6 bg-theme/50 mx-1"></div>

                <div className="flex flex-col items-start leading-none gap-1 text-right">
                  <span className="text-[7px] font-black uppercase text-theme-accent tracking-widest">Canvas Final</span>
                  <span className="text-[11px] font-mono font-black text-theme-accent tracking-tighter">
                    {settings.canvasWidth}<span className="opacity-40 mx-0.5">×</span>{settings.canvasHeight}
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* BARRA DE CONTROLE DE VIEW - ESTILO GLASS INTEGRADO */}
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme/40 py-1.5 px-6 rounded-full shadow-2xl backdrop-blur-md z-50">
            <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
              <i className="fas fa-search text-[10px] opacity-20"></i>
              <input 
                type="range" 
                min="0.05" 
                max="2" 
                step="0.01" 
                value={zoom} 
                onChange={(e) => setZoom(parseFloat(e.target.value))} 
                className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" 
              />
              <span className="text-[9px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
            </div>

            <button 
              onClick={() => { setOffset({ x: 0, y: 0 }); setZoom(0.4); }}
              className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main transition-all group"
              title="Reset View"
            >
              <i className="fas fa-undo-alt text-[9px] opacity-40 group-hover:opacity-100"></i>
            </button>
          </div>
        </div>
      </section>

      <aside className="w-80 flex-shrink-0 border-l overflow-hidden flex flex-col bg-theme-side border-theme">
        <div className="p-4 border-b font-black text-[10px] uppercase tracking-widest flex justify-between items-center text-theme-muted bg-black/5">
          <span>Galeria da Grid</span>
          <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">
            {images.length}
          </span>
        </div>
        <ImageList 
          images={images} 
          onRemove={removeImage} 
          onMove={moveImage}
        />
      </aside>

      <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
      <input 
        type="file" 
        {...({ webkitdirectory: "" } as any)} 
        className="hidden" 
        ref={folderInputRef} 
        onChange={handleFileChange} 
      />
    </div>
  );
};

export default GridTool;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GridImage, FrameSettings } from '../types';

interface InteractiveEditorProps {
  mainImage: (GridImage & { x: number, y: number, scale: number, rotation: number }) | null;
  loteImages: GridImage[];
  frameSettings: FrameSettings;
  onUpdateImage: (id: string, updates: Partial<GridImage>) => void;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  zoom?: number;
}

const InteractiveEditor: React.FC<InteractiveEditorProps> = ({ 
  mainImage,
  loteImages, 
  frameSettings, 
  onUpdateImage,
  selectedId,
  onSelect,
  zoom = 0.4
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragInfo = useRef({
    startX: 0,
    startY: 0,
    initialPosX: 0,
    initialPosY: 0,
    id: '',
    animationFrameId: 0
  });

  const handleMouseDown = (e: React.MouseEvent, id: string, x: number, y: number) => {
    e.stopPropagation();
    onSelect(id);
    setIsDragging(true);

    dragInfo.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialPosX: x,
      initialPosY: y,
      id: id,
      animationFrameId: 0
    };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging || !selectedId) return;

    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }

    dragInfo.current.animationFrameId = requestAnimationFrame(() => {
      const dx = e.clientX - dragInfo.current.startX;
      const dy = e.clientY - dragInfo.current.startY;

      onUpdateImage(dragInfo.current.id, {
        x: dragInfo.current.initialPosX + (dx / zoom),
        y: dragInfo.current.initialPosY + (dy / zoom)
      });
    });
  }, [isDragging, selectedId, zoom, onUpdateImage]);

  const handleMouseUp = useCallback(() => {
    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }
    setIsDragging(false);
  }, []);

  const handleWheel = useCallback((e: WheelEvent) => {
    if (!selectedId) return;
    e.preventDefault();

    const element = selectedId === 'main' 
      ? mainImage 
      : loteImages.find(img => img.id === selectedId);

    if (element) {
      const delta = e.deltaY > 0 ? -0.02 : 0.02;
      const currentScale = (element as any).scale || 1;
      const newScale = Math.max(0.01, Math.min(5, currentScale + delta));
      onUpdateImage(selectedId, { scale: newScale });
    }
  }, [selectedId, mainImage, loteImages, onUpdateImage]);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove, { passive: true });
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  useEffect(() => {
    const container = containerRef.current;
    if (container) {
      container.addEventListener('wheel', handleWheel, { passive: false });
    }
    return () => {
      if (container) container.removeEventListener('wheel', handleWheel);
    };
  }, [handleWheel]);

  const SelectionOverlay = ({ isActive }: { isActive: boolean }) => (
    isActive ? (
      <div className="absolute inset-[-4px] border-[3px] border-theme-accent rounded shadow-[0_0_20px_rgba(79,70,229,0.5)] z-50 pointer-events-none animate-pulse">
        <div className="absolute -top-1.5 -left-1.5 w-3 h-3 bg-theme-accent border border-white rounded-full"></div>
        <div className="absolute -top-1.5 -right-1.5 w-3 h-3 bg-theme-accent border border-white rounded-full"></div>
        <div className="absolute -bottom-1.5 -left-1.5 w-3 h-3 bg-theme-accent border border-white rounded-full"></div>
        <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 bg-theme-accent border border-white rounded-full"></div>
      </div>
    ) : null
  );

  return (
    <div 
      ref={containerRef}
      className="relative shadow-2xl border border-theme bg-theme-panel transition-[width,height] duration-300 ease-out"
      style={{ 
        width: frameSettings.canvasWidth * zoom, 
        height: frameSettings.canvasHeight * zoom,
        minWidth: frameSettings.canvasWidth * zoom,
        minHeight: frameSettings.canvasHeight * zoom,
        backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)',
        backgroundSize: '20px 20px'
      }}
      onMouseDown={() => onSelect(null)}
    >
      {mainImage && (
        <div
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === 'main' ? 'z-30 opacity-100' : 'z-10 opacity-70'}`}
          style={{
            left: mainImage.x * zoom,
            top: mainImage.y * zoom,
            width: (mainImage.width * mainImage.scale) * zoom,
            transform: `rotate(${mainImage.rotation}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, 'main', mainImage.x, mainImage.y)}
        >
          <img src={mainImage.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === 'main'} />
        </div>
      )}

      {loteImages.map((img) => (
        <div
          key={img.id}
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === img.id ? 'z-40 opacity-100' : 'z-20 opacity-70'}`}
          style={{
            left: (img.x || 0) * zoom,
            top: (img.y || 0) * zoom,
            width: (img.width * (img.scale || 1)) * zoom,
            transform: `rotate(${img.rotation || 0}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, img.id, img.x || 0, img.y || 0)}
        >
          <img src={img.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === img.id} />
        </div>
      ))}

      <div 
        className="absolute inset-0 pointer-events-none z-[100] transition-all duration-300"
        style={{
          border: frameSettings.frameImageUrl ? 'none' : `${frameSettings.borderWidth * zoom}px solid ${frameSettings.borderColor}`,
          borderRadius: `${frameSettings.borderRadius * zoom}px`,
          boxShadow: `inset 0 0 ${frameSettings.shadow * zoom}px rgba(0,0,0,0.2)`
        }}
      >
        {frameSettings.frameImageUrl && (
          <img src={frameSettings.frameImageUrl} className="w-full h-full object-fill" />
        )}
      </div>
    </div>
  );
};

export default InteractiveEditor;

import React, { useState, useRef, useMemo, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarFraming from '../components/SidebarFraming';
import InteractiveEditor from '../components/InteractiveEditor';
import Header from '../components/Header';
import { GridImage, FrameSettings } from '../types';

interface BatchItemState { x: number; y: number; scale: number; rotation: number; }

const FramingTool: React.FC = () => {
  const [mainBatch, setMainBatch] = useState<GridImage[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [batchStates, setBatchStates] = useState<Record<string, BatchItemState>>({});
  const [autoSave, setAutoSave] = useState(true);
  const [extraLayers, setExtraLayers] = useState<GridImage[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [zoom, setZoom] = useState(0.4); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [settings, setSettings] = useState<FrameSettings>({ borderWidth: 20, borderColor: '#ffffff', borderRadius: 0, padding: 0, shadow: 10, canvasWidth: 1080, canvasHeight: 1080 });

  const [isScaling, setIsScaling] = useState(false);
  const scaleDragRef = useRef({ lastX: 0, currentScale: 1 });

  const mainFileInputRef = useRef<HTMLInputElement>(null);
  const extraFileInputRef = useRef<HTMLInputElement>(null);
  const frameInputRef = useRef<HTMLInputElement>(null);

  const currentMainImage = mainBatch[currentIndex];
  const currentTransform = useMemo(() => {
    if (!currentMainImage) return null;
    return batchStates[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 };
  }, [currentMainImage, batchStates, settings.canvasWidth, settings.canvasHeight]);

  const selectedElement = useMemo(() => {
    if (selectedId === 'main') return { ...currentMainImage, ...currentTransform };
    return extraLayers.find(img => img.id === selectedId);
  }, [selectedId, currentMainImage, currentTransform, extraLayers]);

  const updateTransform = useCallback((id: string, updates: Partial<BatchItemState | GridImage>) => {
    if (id === 'main' && currentMainImage) {
      setBatchStates(prev => ({ 
        ...prev, 
        [currentMainImage.id]: { 
          ...(prev[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 }), 
          ...updates as any 
        } 
      }));
    } else {
      setExtraLayers(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
    }
  }, [currentMainImage, settings]);

  // Lógica de Escala Suave (Infinite Drag)
  const onScaleMouseDown = (e: React.MouseEvent) => {
    if (!selectedId || !selectedElement) return;
    setIsScaling(true);
    scaleDragRef.current = {
      lastX: e.clientX,
      currentScale: selectedElement.scale || 1
    };
    document.body.style.cursor = 'none';
  };

  useEffect(() => {
    if (!isScaling) return;

    const handleMouseMove = (e: MouseEvent) => {
      const deltaX = e.clientX - scaleDragRef.current.lastX;
      scaleDragRef.current.lastX = e.clientX;

      const sensitivity = 0.005;
      const newScale = Math.max(0.01, Math.min(5, scaleDragRef.current.currentScale + (deltaX * sensitivity)));
      scaleDragRef.current.currentScale = newScale;

      updateTransform(selectedId!, { scale: newScale });
    };

    const handleMouseUp = () => {
      setIsScaling(false);
      document.body.style.cursor = 'default';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isScaling, selectedId, updateTransform]);

  const removeExtraLayer = (id: string) => {
    setExtraLayers(prev => prev.filter(img => img.id !== id));
    if (selectedId === id) setSelectedId(null);
  };

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image(); img.crossOrigin = "anonymous";
      img.onload = () => resolve(img); img.onerror = () => reject(new Error("Erro"));
      img.src = url;
    });
  };

  const handleProcessAll = async () => {
    if (mainBatch.length === 0) return;
    setIsProcessing(true); setProcessProgress(0);
    const canvas = document.createElement('canvas');
    canvas.width = settings.canvasWidth; canvas.height = settings.canvasHeight;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;
    const zip = downloadZip ? new JSZip() : null;
    try {
      const extraImgs = await Promise.all(extraLayers.map(l => loadImage(l.previewUrl)));
      let frameImg: HTMLImageElement | null = null;
      if (settings.frameImageUrl) frameImg = await loadImage(settings.frameImageUrl);

      const fallbackTransform = currentTransform || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 };

      for (let i = 0; i < mainBatch.length; i++) {
        setProcessProgress(i + 1);
        const item = mainBatch[i]; const transform = batchStates[item.id] || { ...fallbackTransform };
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const mainImgObj = await loadImage(item.previewUrl);
        ctx.save();
        const drawW = item.width * transform.scale, drawH = item.height * transform.scale;
        ctx.translate(transform.x + drawW / 2, transform.y + drawH / 2); ctx.rotate((transform.rotation * Math.PI) / 180);
        ctx.drawImage(mainImgObj, -drawW / 2, -drawH / 2, drawW, drawH); ctx.restore();

        extraLayers.forEach((layer, idx) => {
          ctx.save(); const lW = layer.width * (layer.scale || 1), lH = layer.height * (layer.scale || 1);
          ctx.translate((layer.x || 0) + lW / 2, (layer.y || 0) + lH / 2); ctx.rotate(((layer.rotation || 0) * Math.PI) / 180);
          ctx.drawImage(extraImgs[idx], -lW / 2, -lH / 2, lW, lH); ctx.restore();
        });

        if (frameImg) ctx.drawImage(frameImg, 0, 0, canvas.width, canvas.height);
        else {
          ctx.strokeStyle = settings.borderColor; ctx.lineWidth = settings.borderWidth;
          ctx.strokeRect(settings.borderWidth / 2, settings.borderWidth / 2, canvas.width - settings.borderWidth, canvas.height - settings.borderWidth);
        }

        const dataUrl = canvas.toDataURL('image/png', 1.0);
        const fileName = `miau_${item.file.name.replace(/\.[^/.]+$/, "")}.png`;
        if (downloadIndividual) {
          const link = document.createElement('a'); link.download = fileName; link.href = dataUrl;
          document.body.appendChild(link); link.click(); document.body.removeChild(link);
          await new Promise(r => setTimeout(r, 400));
        }
        if (zip) zip.file(fileName, dataUrl.split(',')[1], { base64: true });
      }
      if (zip) {
        const zipBlob = await zip.generateAsync({ type: "blob" });
        const link = document.createElement('a'); link.href = URL.createObjectURL(zipBlob);
        link.download = `miau_tools_${Date.now()}.zip`; link.click();
      }
    } finally { setIsProcessing(false); setProcessProgress(0); }
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarFraming settings={settings} onSettingsChange={setSettings} onAddLote={() => mainFileInputRef.current?.click()} onAddExtras={() => extraFileInputRef.current?.click()} onAddFrame={() => frameInputRef.current?.click()} autoSave={autoSave} onAutoSaveChange={setAutoSave} onProcessAll={handleProcessAll} isProcessing={isProcessing} progress={processProgress} total={mainBatch.length} exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }} />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden bg-theme-main relative">
        <Header itemCount={mainBatch.length + extraLayers.length} onClear={() => {setMainBatch([]); setExtraLayers([]); setBatchStates({});}} />

        {/* BARRA DE TRANSFORMAÇÃO POLIDA */}
        <div className="h-14 border-b border-theme flex items-center px-6 gap-8 bg-theme-side/50 backdrop-blur-xl z-30">
          <div className={`flex items-center gap-8 transition-all duration-500 ${!selectedElement ? 'opacity-5 grayscale pointer-events-none translate-y-2' : 'opacity-100 translate-y-0'}`}>
            <div className="flex flex-col gap-1">
              <span className="text-[7px] font-black uppercase opacity-40 tracking-[0.2em]">Scale Control</span>
              <div 
                onMouseDown={onScaleMouseDown}
                className="flex items-center gap-3 bg-theme-panel/40 border border-theme hover:border-theme-accent px-4 py-1.5 rounded-lg cursor-ew-resize transition-all group"
              >
                <i className={`fas fa-expand-alt text-[9px] ${isScaling ? 'text-theme-accent scale-125' : 'opacity-30'} transition-all`}></i>
                <div className="w-24 h-1 bg-theme/20 rounded-full relative overflow-hidden">
                  <div 
                    className="absolute inset-y-0 left-0 bg-theme-accent transition-all duration-100" 
                    style={{ width: `${Math.min(100, (selectedElement?.scale || 1) * 33)}%` }}
                  ></div>
                </div>
                <span className="text-[10px] font-mono text-theme-accent font-black w-10 text-right">{Math.round((selectedElement?.scale || 1) * 100)}%</span>
              </div>
            </div>

            <div className="h-8 w-[1px] bg-theme/50"></div>

            <div className="flex flex-col gap-1">
              <span className="text-[7px] font-black uppercase opacity-40 tracking-[0.2em]">Rotation</span>
              <div className="flex gap-1.5 bg-theme-panel/40 p-1 rounded-lg border border-theme">
                <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) - 15 })} className="w-7 h-7 flex items-center justify-center rounded hover:bg-theme-accent/20 transition-all active:scale-90"><i className="fas fa-undo text-[9px]"></i></button>
                <div className="w-10 flex items-center justify-center text-[10px] font-mono font-black opacity-60">{(selectedElement?.rotation || 0)}°</div>
                <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) + 15 })} className="w-7 h-7 flex items-center justify-center rounded hover:bg-theme-accent/20 transition-all active:scale-90"><i className="fas fa-redo text-[9px]"></i></button>
              </div>
            </div>

            <div className="flex flex-col gap-0.5 ml-auto">
              <span className="text-[7px] font-black uppercase opacity-30 leading-none">Global Position</span>
              <span className="text-[10px] font-mono text-theme-accent font-black tracking-tighter">
                X:{Math.round(selectedElement?.x || 0)} <span className="opacity-20 mx-1">/</span> Y:{Math.round(selectedElement?.y || 0)}
              </span>
            </div>
          </div>

          {!selectedElement && mainBatch.length > 0 && (
            <div className="flex items-center gap-3 animate-pulse">
              <i className="fas fa-mouse-pointer text-[10px] opacity-20"></i>
              <span className="text-[9px] font-black uppercase opacity-20 tracking-widest">Selecione uma imagem para editar</span>
            </div>
          )}
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-8 overflow-hidden relative">
          <div className="flex-1 flex items-center justify-center w-full h-full overflow-auto scrollbar-hide">
            <InteractiveEditor loteImages={extraLayers} mainImage={currentMainImage ? { ...currentMainImage, ...currentTransform! } : null} frameSettings={settings} selectedId={selectedId} onSelect={setSelectedId} onUpdateImage={updateTransform} zoom={zoom} />
          </div>

          {/* ZOOM BAR GLASS */}
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme/40 py-1.5 px-6 rounded-full shadow-2xl backdrop-blur-md z-50">
            <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
              <i className="fas fa-search text-[10px] opacity-20"></i>
              <input type="range" min="0.05" max="2" step="0.01" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
              <span className="text-[9px] font-mono opacity-40 min-w-[25px]">{Math.round(zoom * 100)}%</span>
            </div>
            <div className="flex items-center gap-4">
              <button disabled={currentIndex === 0} onClick={() => { setCurrentIndex(prev => prev - 1); setSelectedId('main'); }} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[9px]"></i></button>
              <span className="text-[10px] font-mono font-black text-theme-accent min-w-[60px] text-center">{mainBatch.length > 0 ? `${currentIndex + 1} / ${mainBatch.length}` : '0 / 0'}</span>
              <button disabled={currentIndex >= mainBatch.length - 1} onClick={() => { setCurrentIndex(prev => prev + 1); setSelectedId('main'); }} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[9px]"></i></button>
            </div>
          </div>
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        {/* FILA DO LOTE */}
        <div className="h-1/2 flex flex-col border-b border-theme overflow-hidden">
          <div className="p-3 bg-black/5 flex justify-between items-center border-b border-theme">
            <span className="text-[9px] font-black uppercase tracking-widest opacity-40">Lote Principal</span>
            <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">{mainBatch.length}</span>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {mainBatch.map((img, idx) => (
              <div key={img.id} onClick={() => { setCurrentIndex(idx); setSelectedId('main'); }} className={`flex items-center gap-3 p-2 rounded-lg border transition-all cursor-pointer ${currentIndex === idx && selectedId === 'main' ? 'border-theme-accent bg-theme-accent/10' : 'border-transparent opacity-60'}`}>
                <img src={img.previewUrl} className="w-7 h-7 rounded object-cover border border-theme" />
                <span className="text-[9px] font-bold truncate flex-1">{img.file.name}</span>
              </div>
            ))}
          </div>
        </div>

        {/* CAMADAS EXTRAS */}
        <div className="h-1/2 flex flex-col overflow-hidden bg-black/5">
          <div className="p-3 bg-black/5 flex justify-between items-center border-b border-theme">
            <span className="text-[9px] font-black uppercase tracking-widest opacity-40">Camadas Extras</span>
            <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">{extraLayers.length}</span>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {extraLayers.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center opacity-20 text-center px-4">
                <i className="fas fa-layer-group text-2xl mb-2"></i>
                <p className="text-[8px] font-black uppercase">Nenhum elemento extra</p>
              </div>
            ) : (
              extraLayers.map((img) => (
                <div key={img.id} onClick={() => setSelectedId(img.id)} className={`flex items-center gap-3 p-2 rounded-lg border transition-all cursor-pointer group ${selectedId === img.id ? 'border-theme-accent bg-theme-accent/10' : 'border-transparent opacity-60'}`}>
                  <img src={img.previewUrl} className="w-7 h-7 rounded object-cover border border-theme" />
                  <span className="text-[9px] font-bold truncate flex-1">{img.file.name}</span>
                  <button onClick={(e) => { e.stopPropagation(); removeExtraLayer(img.id); }} className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-500 transition-all">
                    <i className="fas fa-times text-[10px]"></i>
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      </aside>

      <input type="file" multiple accept="image/*" className="hidden" ref={mainFileInputRef} onChange={(e) => {
        if (e.target.files) (Array.from(e.target.files) as File[]).forEach(file => {
          const img = new Image(); const url = URL.createObjectURL(file);
          img.onload = () => setMainBatch(prev => [...prev, { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height }]);
          img.src = url;
        });
      }} />
      <input type="file" multiple accept="image/*" className="hidden" ref={extraFileInputRef} onChange={(e) => {
        if (e.target.files) (Array.from(e.target.files) as File[]).forEach(file => {
          const img = new Image(); const url = URL.createObjectURL(file);
          img.onload = () => setExtraLayers(prev => [...prev, { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height, x: 100, y: 100, scale: 0.15, rotation: 0 }]);
          img.src = url;
        });
      }} />
      <input type="file" accept="image/png" className="hidden" ref={frameInputRef} onChange={(e) => {
        if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0]; const url = URL.createObjectURL(file);
          const img = new Image(); img.onload = () => setSettings(prev => ({ ...prev, frameImageUrl: url, frameImageName: file.name, canvasWidth: img.width, canvasHeight: img.height }));
          img.src = url;
        }
      }} />
    </div>
  );
};

export default FramingTool;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GridImage, FrameSettings } from '../types';

interface InteractiveEditorProps {
  mainImage: (GridImage & { x: number, y: number, scale: number, rotation: number }) | null;
  loteImages: GridImage[];
  frameSettings: FrameSettings;
  onUpdateImage: (id: string, updates: Partial<GridImage>) => void;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  zoom?: number;
}

const InteractiveEditor: React.FC<InteractiveEditorProps> = ({ 
  mainImage,
  loteImages, 
  frameSettings, 
  onUpdateImage,
  selectedId,
  onSelect,
  zoom = 0.4
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragInfo = useRef({
    startX: 0,
    startY: 0,
    initialPosX: 0,
    initialPosY: 0,
    id: '',
    animationFrameId: 0
  });

  const handleMouseDown = (e: React.MouseEvent, id: string, x: number, y: number) => {
    e.stopPropagation();
    onSelect(id);
    setIsDragging(true);

    dragInfo.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialPosX: x,
      initialPosY: y,
      id: id,
      animationFrameId: 0
    };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging || !selectedId) return;

    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }

    dragInfo.current.animationFrameId = requestAnimationFrame(() => {
      const dx = e.clientX - dragInfo.current.startX;
      const dy = e.clientY - dragInfo.current.startY;

      onUpdateImage(dragInfo.current.id, {
        x: dragInfo.current.initialPosX + (dx / zoom),
        y: dragInfo.current.initialPosY + (dy / zoom)
      });
    });
  }, [isDragging, selectedId, zoom, onUpdateImage]);

  const handleMouseUp = useCallback(() => {
    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }
    setIsDragging(false);
  }, []);

  const handleWheel = useCallback((e: WheelEvent) => {
    if (!selectedId) return;
    e.preventDefault();

    const element = selectedId === 'main' 
      ? mainImage 
      : loteImages.find(img => img.id === selectedId);

    if (element) {
      const delta = e.deltaY > 0 ? -0.02 : 0.02;
      const currentScale = (element as any).scale || 1;
      const newScale = Math.max(0.01, Math.min(5, currentScale + delta));
      onUpdateImage(selectedId, { scale: newScale });
    }
  }, [selectedId, mainImage, loteImages, onUpdateImage]);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove, { passive: true });
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  useEffect(() => {
    const container = containerRef.current;
    if (container) {
      container.addEventListener('wheel', handleWheel, { passive: false });
    }
    return () => {
      if (container) container.removeEventListener('wheel', handleWheel);
    };
  }, [handleWheel]);

  const SelectionOverlay = ({ isActive }: { isActive: boolean }) => (
    isActive ? (
      <div className="absolute inset-[-2px] border-2 border-dashed border-theme-accent rounded shadow-[0_0_15px_rgba(79,70,229,0.3)] z-50 pointer-events-none">
        {/* Removido os pontos das extremidades para evitar confusão com handles de redimensionamento */}
      </div>
    ) : null
  );

  return (
    <div 
      ref={containerRef}
      className="relative shadow-2xl border border-theme bg-theme-panel transition-[width,height] duration-300 ease-out"
      style={{ 
        width: frameSettings.canvasWidth * zoom, 
        height: frameSettings.canvasHeight * zoom,
        minWidth: frameSettings.canvasWidth * zoom,
        minHeight: frameSettings.canvasHeight * zoom,
        backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)',
        backgroundSize: '20px 20px'
      }}
      onMouseDown={() => onSelect(null)}
    >
      {mainImage && (
        <div
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === 'main' ? 'z-30 opacity-100' : 'z-10 opacity-70'}`}
          style={{
            left: mainImage.x * zoom,
            top: mainImage.y * zoom,
            width: (mainImage.width * mainImage.scale) * zoom,
            transform: `rotate(${mainImage.rotation}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, 'main', mainImage.x, mainImage.y)}
        >
          <img src={mainImage.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === 'main'} />
        </div>
      )}

      {loteImages.map((img) => (
        <div
          key={img.id}
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === img.id ? 'z-40 opacity-100' : 'z-20 opacity-70'}`}
          style={{
            left: (img.x || 0) * zoom,
            top: (img.y || 0) * zoom,
            width: (img.width * (img.scale || 1)) * zoom,
            transform: `rotate(${img.rotation || 0}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, img.id, img.x || 0, img.y || 0)}
        >
          <img src={img.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === img.id} />
        </div>
      ))}

      <div 
        className="absolute inset-0 pointer-events-none z-[100] transition-all duration-300"
        style={{
          border: frameSettings.frameImageUrl ? 'none' : `${frameSettings.borderWidth * zoom}px solid ${frameSettings.borderColor}`,
          borderRadius: `${frameSettings.borderRadius * zoom}px`,
          boxShadow: `inset 0 0 ${frameSettings.shadow * zoom}px rgba(0,0,0,0.2)`
        }}
      >
        {frameSettings.frameImageUrl && (
          <img src={frameSettings.frameImageUrl} className="w-full h-full object-fill" />
        )}
      </div>
    </div>
  );
};

export default InteractiveEditor;

import React, { useState, useRef, useMemo, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarFraming from '../components/SidebarFraming';
import InteractiveEditor from '../components/InteractiveEditor';
import Header from '../components/Header';
import { GridImage, FrameSettings } from '../types';

interface BatchItemState { x: number; y: number; scale: number; rotation: number; }

const FramingTool: React.FC = () => {
  const [mainBatch, setMainBatch] = useState<GridImage[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [batchStates, setBatchStates] = useState<Record<string, BatchItemState>>({});
  const [autoSave, setAutoSave] = useState(true);
  const [extraLayers, setExtraLayers] = useState<GridImage[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [zoom, setZoom] = useState(0.4); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [settings, setSettings] = useState<FrameSettings>({ borderWidth: 20, borderColor: '#ffffff', borderRadius: 0, padding: 0, shadow: 10, canvasWidth: 1080, canvasHeight: 1080 });

  const [isScaling, setIsScaling] = useState(false);
  const scaleDragRef = useRef({ lastX: 0, currentScale: 1 });

  const mainFileInputRef = useRef<HTMLInputElement>(null);
  const extraFileInputRef = useRef<HTMLInputElement>(null);
  const frameInputRef = useRef<HTMLInputElement>(null);

  const currentMainImage = mainBatch[currentIndex];
  const currentTransform = useMemo(() => {
    if (!currentMainImage) return null;
    return batchStates[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 };
  }, [currentMainImage, batchStates, settings.canvasWidth, settings.canvasHeight]);

  const selectedElement = useMemo(() => {
    if (selectedId === 'main') return { ...currentMainImage, ...currentTransform };
    return extraLayers.find(img => img.id === selectedId);
  }, [selectedId, currentMainImage, currentTransform, extraLayers]);

  const updateTransform = useCallback((id: string, updates: Partial<BatchItemState | GridImage>) => {
    if (id === 'main' && currentMainImage) {
      setBatchStates(prev => ({ 
        ...prev, 
        [currentMainImage.id]: { 
          ...(prev[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 }), 
          ...updates as any 
        } 
      }));
    } else {
      setExtraLayers(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
    }
  }, [currentMainImage, settings]);

  // Lógica de Escala Suave (Infinite Drag)
  const onScaleMouseDown = (e: React.MouseEvent) => {
    if (!selectedId || !selectedElement) return;
    setIsScaling(true);
    scaleDragRef.current = {
      lastX: e.clientX,
      currentScale: selectedElement.scale || 1
    };
    document.body.style.cursor = 'none';
  };

  useEffect(() => {
    if (!isScaling) return;

    const handleMouseMove = (e: MouseEvent) => {
      const deltaX = e.clientX - scaleDragRef.current.lastX;
      scaleDragRef.current.lastX = e.clientX;

      const sensitivity = 0.005;
      const newScale = Math.max(0.01, Math.min(5, scaleDragRef.current.currentScale + (deltaX * sensitivity)));
      scaleDragRef.current.currentScale = newScale;

      updateTransform(selectedId!, { scale: newScale });
    };

    const handleMouseUp = () => {
      setIsScaling(false);
      document.body.style.cursor = 'default';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isScaling, selectedId, updateTransform]);

  const removeExtraLayer = (id: string) => {
    setExtraLayers(prev => prev.filter(img => img.id !== id));
    if (selectedId === id) setSelectedId(null);
  };

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image(); img.crossOrigin = "anonymous";
      img.onload = () => resolve(img); img.onerror = () => reject(new Error("Erro"));
      img.src = url;
    });
  };

  const handleProcessAll = async () => {
    if (mainBatch.length === 0) return;
    setIsProcessing(true); setProcessProgress(0);
    const canvas = document.createElement('canvas');
    canvas.width = settings.canvasWidth; canvas.height = settings.canvasHeight;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;
    const zip = downloadZip ? new JSZip() : null;
    try {
      const extraImgs = await Promise.all(extraLayers.map(l => loadImage(l.previewUrl)));
      let frameImg: HTMLImageElement | null = null;
      if (settings.frameImageUrl) frameImg = await loadImage(settings.frameImageUrl);

      const fallbackTransform = currentTransform || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 };

