import React, { useRef, useEffect, useCallback, useState } from 'react';
import { GridImage, GridSettings } from '../types';

interface GridPreviewProps {
  images: GridImage[];
  settings: GridSettings;
  zoom?: number;
  offset: { x: number, y: number };
  onOffsetChange: (offset: { x: number, y: number }) => void;
}

const GridPreview: React.FC<GridPreviewProps> = ({ 
  images, 
  settings, 
  zoom = 0.4,
  offset,
  onOffsetChange
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const renderRequestId = useRef<number>(0);
  const imageCache = useRef<Map<string, HTMLImageElement>>(new Map());
  const [isDragging, setIsDragging] = useState(false);
  const [currentCanvasHeight, setCurrentCanvasHeight] = useState(settings.canvasHeight);
  const [calculatedCols, setCalculatedCols] = useState(settings.columns);

  const dragInfo = useRef({
    startX: 0,
    startY: 0,
    initialOffsetX: 0,
    initialOffsetY: 0,
    animationFrameId: 0
  });

  // Pré-carrega imagens
  useEffect(() => {
    const loadImages = async () => {
      const promises = images.map(img => {
        if (imageCache.current.has(img.id)) return Promise.resolve();
        return new Promise<void>((resolve) => {
          const i = new Image();
          i.onload = () => {
            imageCache.current.set(img.id, i);
            resolve();
          };
          i.src = img.previewUrl;
        });
      });
      await Promise.all(promises);
      requestAnimationFrame(() => drawGrid());
    };
    loadImages();
  }, [images]);

  const drawGrid = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const isAuto = settings.layoutMode === 'auto';
    const margin = settings.outerMargin;
    const spacing = settings.innerSpacing;
    const scaleFactor = 1 + ((settings.itemScale || 0) / 100);

    let cols = settings.columns;

    // LÓGICA AUTO-FLOW: CALCULAR COLUNAS PARA ATINGIR O FORMATO DO CONJUNTO
    if (isAuto && images.length > 0) {
      // Razão de aspecto alvo para o bloco total
      let targetRatio = 1; // Square
      if (settings.targetShape === 'portrait') targetRatio = 0.65; // Mais vertical
      if (settings.targetShape === 'landscape') targetRatio = 1.6; // Mais horizontal

      // Consideramos a média da razão de aspecto das imagens para um cálculo mais preciso
      const avgItemRatio = images.reduce((acc, img) => acc + img.aspectRatio, 0) / images.length;

      /**
       * Fórmula de aproximação:
       * Queremos que (Cols * avgRatio) / (Rows) ≈ TargetRatio
       * Como Rows ≈ Items / Cols
       * (Cols^2 * avgRatio) / Items ≈ TargetRatio
       * Cols ≈ sqrt( (TargetRatio * Items) / avgRatio )
       */
      const optimalCols = Math.max(1, Math.round(Math.sqrt((targetRatio * images.length) / avgItemRatio)));
      cols = optimalCols;
      if (calculatedCols !== cols) setCalculatedCols(cols);
    }

    let finalCanvasWidth = settings.canvasWidth;
    let finalCanvasHeight = settings.canvasHeight;

    if (isAuto) {
      // No modo auto, as células são dimensionadas uniformemente mas as imagens tentam caber nelas (Fit)
      // Calculamos o tamanho da célula baseada na largura desejada e no sizer
      const baseCellWidth = (settings.canvasWidth - (2 * margin) - ((cols - 1) * spacing)) / cols;
      const cellWidth = baseCellWidth * scaleFactor;

      // Para manter a forma original, a altura da linha deve ser baseada no item mais alto ou numa média
      // No modo Grid Auto, usaremos uma altura de linha baseada na largura da célula (Quadrada por padrão)
      const cellHeight = cellWidth; // Célula quadrada guia
      const rows = Math.ceil(images.length / cols);

      finalCanvasHeight = (rows * cellHeight) + (2 * margin) + ((rows - 1) * spacing);
      finalCanvasWidth = (cols * cellWidth) + (2 * margin) + ((cols - 1) * spacing);

      if (images.length === 0) {
        finalCanvasHeight = settings.canvasHeight;
        finalCanvasWidth = settings.canvasWidth;
      }

      if (currentCanvasHeight !== finalCanvasHeight) {
        setCurrentCanvasHeight(finalCanvasHeight);
      }
    }

    if (canvas.width !== finalCanvasWidth || canvas.height !== finalCanvasHeight) {
      canvas.width = finalCanvasWidth;
      canvas.height = finalCanvasHeight;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!settings.isTransparent) {
      ctx.fillStyle = settings.backgroundColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    if (images.length === 0) return;

    const actualCellWidth = (canvas.width - (2 * margin) - ((cols - 1) * spacing)) / cols;
    const rows = Math.ceil(images.length / cols);
    const actualCellHeight = (canvas.height - (2 * margin) - ((rows - 1) * spacing)) / rows;

    images.forEach((imgObj, index) => {
      const img = imageCache.current.get(imgObj.id);
      if (!img) return;

      const col = index % cols;
      const row = Math.floor(index / cols);
      const x = margin + (col * (actualCellWidth + spacing));
      const y = margin + (row * (actualCellHeight + spacing));

      // Lógica de FIT: Mantém a proporção original dentro da célula calculada
      let drawW = actualCellWidth;
      let drawH = actualCellWidth / imgObj.aspectRatio;

      if (drawH > actualCellHeight) {
        drawH = actualCellHeight;
        drawW = actualCellHeight * imgObj.aspectRatio;
      }

      // Centraliza a imagem na célula
      const offsetX = x + (actualCellWidth - drawW) / 2;
      const offsetY = y + (actualCellHeight - drawH) / 2;

      ctx.drawImage(img, offsetX, offsetY, drawW, drawH);
    });
  }, [images, settings, currentCanvasHeight, calculatedCols]);

  useEffect(() => {
    if (renderRequestId.current) cancelAnimationFrame(renderRequestId.current);
    renderRequestId.current = requestAnimationFrame(() => drawGrid());
    return () => {
      if (renderRequestId.current) cancelAnimationFrame(renderRequestId.current);
    };
  }, [drawGrid, settings]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    dragInfo.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialOffsetX: offset.x,
      initialOffsetY: offset.y,
      animationFrameId: 0
    };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging) return;

    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }

    dragInfo.current.animationFrameId = requestAnimationFrame(() => {
      const dx = e.clientX - dragInfo.current.startX;
      const dy = e.clientY - dragInfo.current.startY;

      onOffsetChange({
        x: dragInfo.current.initialOffsetX + dx,
        y: dragInfo.current.initialOffsetY + dy
      });
    });
  }, [isDragging, onOffsetChange]);

  const handleMouseUp = useCallback(() => {
    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }
    setIsDragging(false);
  }, []);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  const isAuto = settings.layoutMode === 'auto';

  // Cálculo final de dimensões para a View do editor
  let actualCols = settings.columns;
  if (isAuto && images.length > 0) actualCols = calculatedCols;

  const margin = settings.outerMargin;
  const spacing = settings.innerSpacing;
  const scaleFactor = 1 + ((settings.itemScale || 0) / 100);

  const baseCellW = (settings.canvasWidth - (2 * margin) - ((actualCols - 1) * spacing)) / actualCols;
  const cellW = baseCellW * (isAuto ? scaleFactor : 1);
  const cellH = cellW; // Usamos guia quadrada para o view

  const finalW = isAuto ? (actualCols * cellW) + (2 * margin) + ((actualCols - 1) * spacing) : settings.canvasWidth;
  const finalH = isAuto ? currentCanvasHeight : settings.canvasHeight;

  return (
    <div 
      ref={containerRef}
      className="w-full h-full flex items-center justify-center relative select-none overflow-hidden"
      onMouseDown={handleMouseDown}
    >
      <div 
        className="shadow-2xl relative border bg-theme-panel flex-shrink-0 transition-all duration-300 ease-out"
        style={{
          width: finalW * zoom,
          height: finalH * zoom,
          minWidth: finalW * zoom,
          minHeight: finalH * zoom,
          transform: `translate(${offset.x}px, ${offset.y}px)`,
          borderColor: 'var(--border)',
          backgroundImage: settings.isTransparent ? 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)' : 'none',
          backgroundSize: '20px 20px',
          willChange: 'transform, width, height'
        }}
      >
        <canvas 
          id="grid-canvas" 
          ref={canvasRef} 
          className="w-full h-full block" 
          style={{ imageRendering: 'auto' }}
        />
      </div>
    </div>
  );
};

export default GridPreview;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import Sidebar from '../components/Sidebar';
import GridPreview from '../components/GridPreview';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage, GridSettings } from '../types';

const GridTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [settings, setSettings] = useState<GridSettings>({
    canvasWidth: 2048,
    canvasHeight: 2048,
    columns: 3,
    innerSpacing: 5,
    outerMargin: 5,
    backgroundColor: '#0f172a',
    isTransparent: false,
    layoutMode: 'grid',
    itemScale: 0,
    targetShape: 'square'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  const processFiles = async (files: File[]) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    const filteredFiles = files.filter(file => validTypes.includes(file.type));
    const newImages: GridImage[] = [];

    for (const file of filteredFiles) {
      try {
        const url = URL.createObjectURL(file);
        const img = await new Promise<HTMLImageElement>((resolve, reject) => {
          const i = new Image();
          i.onload = () => resolve(i);
          i.onerror = reject;
          i.src = url;
        });

        newImages.push({
          id: uuidv4(),
          file,
          previewUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height,
          visible: true
        });
      } catch (err) {
        console.error("Erro ao processar imagem:", file.name);
      }
    }

    if (newImages.length > 0) {
      setImages(prev => [...prev, ...newImages]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      let filesArray = Array.from(e.target.files) as File[];
      processFiles(filesArray);
    }
    if (e.target) e.target.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => {
      const target = prev.find(img => img.id === id);
      if (target) URL.revokeObjectURL(target.previewUrl);
      return prev.filter(img => img.id !== id);
    });
  };

  const moveImage = (index: number, direction: 'up' | 'down') => {
    const newImages = [...images];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex >= 0 && targetIndex < newImages.length) {
      [newImages[index], newImages[targetIndex]] = [newImages[targetIndex], newImages[index]];
      setImages(newImages);
    }
  };

  const handleExport = async () => {
    const canvas = document.getElementById('grid-canvas') as HTMLCanvasElement;
    if (!canvas) return;

    const fileName = `grid_${Date.now()}.png`;
    const dataUrl = canvas.toDataURL('image/png', 1.0);

    if (downloadIndividual) {
      const link = document.createElement('a');
      link.download = fileName;
      link.href = dataUrl;
      link.click();
    }

    if (downloadZip) {
      const zip = new JSZip();
      const base64Data = dataUrl.split(',')[1];
      zip.file(fileName, base64Data, { base64: true });
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `grid_pack_${Date.now()}.zip`;
      link.click();
    }
  };

  const clearAll = useCallback(() => {
    images.forEach(img => {
      if (img.previewUrl) URL.revokeObjectURL(img.previewUrl);
    });
    setImages([]);
    setOffset({ x: 0, y: 0 });
    setZoom(0.4);
  }, [images]);

  return (
    <div className="flex-1 flex overflow-hidden">
      <aside className="w-80 flex-shrink-0 border-r overflow-y-auto bg-theme-side border-theme">
        <Sidebar 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddFile={() => fileInputRef.current?.click()}
          onAddFolder={() => folderInputRef.current?.click()}
          images={images}
          exportOptions={{
            downloadIndividual,
            setDownloadIndividual,
            downloadZip,
            setDownloadZip
          }}
          onExport={handleExport}
        />
      </aside>

      <section className="flex-1 overflow-hidden relative flex flex-col bg-theme-main">
        <Header itemCount={images.length} onClear={clearAll} />

        <div className="flex-1 relative flex flex-col items-center justify-center bg-black/5 overflow-hidden">

          <div className="flex-1 w-full h-full cursor-grab active:cursor-grabbing">
            <GridPreview 
              images={images} 
              settings={settings} 
              zoom={zoom} 
              offset={offset}
              onOffsetChange={setOffset}
            />
          </div>

          {/* PAINEL DE METADATA (RESOLUÇÃO) - ESTILO GLASS */}
          {images.length > 0 && (
            <div className="absolute bottom-24 flex flex-col items-center gap-4 animate-in fade-in slide-in-from-bottom-4 duration-700 pointer-events-none">
              <div className="flex items-center gap-4 bg-theme-side/70 border border-theme/40 px-5 py-2.5 rounded-2xl shadow-2xl backdrop-blur-xl">
                <div className="flex flex-col items-start leading-none gap-1">
                  <span className="text-[7px] font-black uppercase opacity-30 tracking-widest">Configuração</span>
                  <span className="text-[11px] font-mono font-bold opacity-60 tracking-tighter">
                    {settings.layoutMode === 'auto' ? `Auto ${settings.targetShape}` : `${settings.columns} Colunas`}
                  </span>
                </div>

                <div className="w-[1px] h-6 bg-theme/50 mx-1"></div>

                <div className="flex flex-col items-start leading-none gap-1 text-right">
                  <span className="text-[7px] font-black uppercase text-theme-accent tracking-widest">Canvas Estivado</span>
                  <span className="text-[11px] font-mono font-black text-theme-accent tracking-tighter">
                    {Math.round(settings.canvasWidth)}<span className="opacity-40 mx-0.5">×</span>{settings.layoutMode === 'auto' ? 'Dinamica' : settings.canvasHeight}
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* BARRA DE CONTROLE DE VIEW - ESTILO GLASS INTEGRADO */}
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme/40 py-1.5 px-6 rounded-full shadow-2xl backdrop-blur-md z-50">
            <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
              <i className="fas fa-search text-[10px] opacity-20"></i>
              <input 
                type="range" 
                min="0.05" 
                max="2" 
                step="0.01" 
                value={zoom} 
                onChange={(e) => setZoom(parseFloat(e.target.value))} 
                className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" 
              />
              <span className="text-[9px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
            </div>

            <button 
              onClick={() => { setOffset({ x: 0, y: 0 }); setZoom(0.4); }}
              className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main transition-all group"
              title="Reset View"
            >
              <i className="fas fa-undo-alt text-[9px] opacity-40 group-hover:opacity-100"></i>
            </button>
          </div>
        </div>
      </section>

      <aside className="w-80 flex-shrink-0 border-l overflow-hidden flex flex-col bg-theme-side border-theme">
        <div className="p-4 border-b font-black text-[10px] uppercase tracking-widest flex justify-between items-center text-theme-muted bg-black/5">
          <span>Galeria da Grid</span>
          <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">
            {images.length}
          </span>
        </div>
        <ImageList 
          images={images} 
          onRemove={removeImage} 
          onMove={moveImage}
        />
      </aside>

      <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
      <input 
        type="file" 
        {...({ webkitdirectory: "" } as any)} 
        className="hidden" 
        ref={folderInputRef} 
        onChange={handleFileChange} 
      />
    </div>
  );
};

export default GridTool;

export interface GridImage {
  id: string;
  file: File;
  previewUrl: string;
  width: number;
  height: number;
  aspectRatio: number;
  isActive?: boolean; // Novo: controla se está na grid ou nos removidos
  visible?: boolean;
}

export interface GridSettings {
  canvasWidth: number;
  canvasHeight: number;
  columns: number;
  innerSpacing: number;
  outerMargin: number;
  backgroundColor: string;
  isTransparent: boolean;
  backgroundImageUrl?: string;
  layoutMode?: 'grid' | 'auto';
  itemScale?: number;
  targetShape?: 'square' | 'portrait' | 'landscape';
}

import React from 'react';
import { GridSettings, GridImage } from '../types';

interface SidebarProps {
  settings: GridSettings;
  onSettingsChange: (settings: GridSettings) => void;
  onAddFile: () => void;
  onAddFolder: () => void;
  images: GridImage[];
  onUpdateActiveCount: (count: number) => void;
  exportOptions: {
    downloadIndividual: boolean;
    setDownloadIndividual: (v: boolean) => void;
    downloadZip: boolean;
    setDownloadZip: (v: boolean) => void;
  };
  onExport: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  settings, 
  onSettingsChange, 
  onAddFile, 
  onAddFolder, 
  images,
  onUpdateActiveCount,
  exportOptions,
  onExport
}) => {
  const handleChange = (key: keyof GridSettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  const activeCount = images.filter(img => img.isActive).length;

  const isAuto = settings.layoutMode === 'auto';

  return (
    <div className="p-5 space-y-6 h-full overflow-y-auto scrollbar-hide flex flex-col">
      {/* BOX: CONTEÚDO */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Entrada de Mídia</h3>
        <div className="space-y-2">
          <button 
            onClick={onAddFile}
            className="w-full flex items-center justify-center gap-2 py-3.5 px-4 rounded-xl font-black text-[10px] transition-all active:scale-95 shadow-lg hover:opacity-90 relative group overflow-hidden uppercase bg-theme-accent text-theme-inv"
          >
            <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
            <i className="fas fa-plus-circle z-10"></i> <span className="z-10">Adicionar Fotos</span>
          </button>
          <button 
            onClick={onAddFolder}
            className="w-full flex items-center justify-center gap-2 py-2.5 px-4 rounded-lg font-bold text-[9px] border transition-all active:scale-95 shadow-sm hover:bg-black/10 relative group overflow-hidden uppercase border-theme bg-theme-panel text-theme-main"
          >
            <i className="fas fa-folder z-10"></i> <span className="z-10">Pasta Completa</span>
          </button>
        </div>
      </div>

      {/* BOX: INTELIGÊNCIA DE LAYOUT */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <div className="flex items-center justify-between border-b border-theme pb-2">
          <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Organização</h3>
          {isAuto && <i className="fas fa-robot text-theme-accent text-[10px]"></i>}
        </div>

        <div className="flex p-1 bg-theme-panel/50 rounded-xl border border-theme">
          <button 
            onClick={() => handleChange('layoutMode', 'grid')}
            className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${!isAuto ? 'bg-theme-accent text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}
          >
            Manual
          </button>
          <button 
            onClick={() => handleChange('layoutMode', 'auto')}
            className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${isAuto ? 'bg-theme-accent text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}
          >
            Auto-Flow
          </button>
        </div>

        {isAuto && (
          <div className="space-y-5 animate-in fade-in slide-in-from-top-2">
             <div className="space-y-3">
              <div className="flex justify-between items-center px-1">
                <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide">Itens na Grid</label>
                <span className="text-[9px] font-black text-theme-accent">{activeCount} / {images.length}</span>
              </div>
              <input 
                type="range" 
                min="1" max={images.length || 1} 
                value={activeCount} 
                onChange={(e) => onUpdateActiveCount(parseInt(e.target.value))}
                className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide px-1">Formato do Conjunto</label>
              <div className="grid grid-cols-3 gap-1.5">
                {[
                  { id: 'square', label: '1:1', icon: 'fa-square' },
                  { id: 'portrait', label: '3:4', icon: 'fa-columns' },
                  { id: 'landscape', label: '4:3', icon: 'fa-grip-horizontal' },
                ].map(shape => (
                  <button
                    key={shape.id}
                    onClick={() => handleChange('targetShape', shape.id)}
                    className={`flex flex-col items-center justify-center gap-1.5 py-3 rounded-xl border transition-all ${settings.targetShape === shape.id ? 'bg-theme-accent border-theme-accent text-white shadow-lg' : 'bg-theme-panel/50 border-theme opacity-50 hover:opacity-100'}`}
                  >
                    <i className={`fas ${shape.icon} text-[10px]`}></i>
                    <span className="text-[7px] font-black uppercase">{shape.label}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* BOX: DIMENSÕES & ESPAÇAMENTO */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-5">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Dimensões & Escala</h3>

        <div className={`grid grid-cols-2 gap-3 transition-all ${isAuto ? 'opacity-30 pointer-events-none grayscale' : ''}`}>
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase block">Largura</label>
            <input 
              type="number" 
              value={settings.canvasWidth} 
              onChange={(e) => handleChange('canvasWidth', parseInt(e.target.value) || 0)}
              className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none font-mono"
            />
          </div>
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase block">Altura</label>
            <input 
              type="number" 
              value={settings.canvasHeight} 
              onChange={(e) => handleChange('canvasHeight', parseInt(e.target.value) || 0)}
              className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none font-mono"
            />
          </div>
        </div>

        <div className="space-y-5">
           <div className="space-y-3 pt-2 border-t border-theme/20">
              <div className="flex justify-between items-center px-1">
                <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide">Sizer (Zoom Elementos)</label>
                <span className="text-[9px] font-black text-theme-accent">{settings.itemScale || 0}%</span>
              </div>
              <input 
                type="range" 
                min="-50" max="50" 
                value={settings.itemScale || 0} 
                onChange={(e) => handleChange('itemScale', parseInt(e.target.value))}
                className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent"
              />
            </div>

          {[
            { label: 'Colunas', key: 'columns', min: 1, max: 12, hideOnAuto: true },
            { label: 'Espaçamento', key: 'innerSpacing', min: 0, max: 200 },
            { label: 'Margem Externa', key: 'outerMargin', min: 0, max: 200 }
          ].map((item) => (
            <div key={item.key} className={`space-y-2 transition-all ${(item.hideOnAuto && isAuto) ? 'hidden' : ''}`}>
              <div className="flex justify-between items-center px-1">
                <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide">{item.label}</label>
                <span className="text-[9px] font-black text-theme-accent">{(settings as any)[item.key]}</span>
              </div>
              <input 
                type="range" 
                min={item.min} max={item.max} 
                value={(settings as any)[item.key]} 
                onChange={(e) => handleChange(item.key as any, parseInt(e.target.value))}
                className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer"
                style={{ accentColor: 'var(--accent)' }}
              />
            </div>
          ))}
        </div>
      </div>

      {/* BOX: APARÊNCIA */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Estética do Fundo</h3>
        <div className="flex items-center gap-2">
           <button 
              onClick={() => handleChange('isTransparent', !settings.isTransparent)}
              className={`flex-1 flex items-center justify-center gap-2 py-2.5 px-3 rounded-xl border text-[9px] font-black transition-all ${settings.isTransparent ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-panel border-theme opacity-60'}`}
           >
              <i className={`fas ${settings.isTransparent ? 'fa-check-circle' : 'fa-circle-notch'}`}></i>
              <span>Transparência</span>
           </button>
           <input 
              type="color" 
              value={settings.backgroundColor} 
              onChange={(e) => {
                handleChange('backgroundColor', e.target.value);
                handleChange('isTransparent', false);
              }}
              className="w-10 h-10 bg-theme-panel rounded-xl cursor-pointer border border-theme p-1"
            />
        </div>
      </div>

      {/* BOTÃO FINAL: EXPORTAR */}
      <div className="mt-auto pt-4">
        <button 
          disabled={images.length === 0}
          onClick={onExport}
          className="w-full flex items-center justify-center gap-3 py-4 px-4 rounded-xl font-black text-[11px] transition-all active:scale-95 shadow-2xl disabled:opacity-30 uppercase tracking-widest bg-theme-accent text-theme-inv relative group overflow-hidden"
        >
          <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <i className="fas fa-file-export z-10"></i> <span className="z-10">Exportar Resultado</span>
        </button>
      </div>
    </div>
  );
};

