import React, { useRef, useEffect, useCallback, useState } from 'react';
import { GridImage, GridSettings } from '../types';

interface GridPreviewProps {
  images: GridImage[];
  settings: GridSettings;
  zoom?: number;
  offset: { x: number, y: number };
  onOffsetChange: (offset: { x: number, y: number }) => void;
}

const GridPreview: React.FC<GridPreviewProps> = ({ 
  images, 
  settings, 
  zoom = 0.4,
  offset,
  onOffsetChange
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const renderRequestId = useRef<number>(0);
  const imageCache = useRef<Map<string, HTMLImageElement>>(new Map());
  const [isDragging, setIsDragging] = useState(false);
  const [currentCanvasHeight, setCurrentCanvasHeight] = useState(settings.canvasHeight);
  const [calculatedCols, setCalculatedCols] = useState(settings.columns);

  const dragInfo = useRef({
    startX: 0,
    startY: 0,
    initialOffsetX: 0,
    initialOffsetY: 0,
    animationFrameId: 0
  });

  const activeImages = images.filter(img => img.isActive);

  // Pré-carrega imagens
  useEffect(() => {
    const loadImages = async () => {
      const promises = activeImages.map(img => {
        if (imageCache.current.has(img.id)) return Promise.resolve();
        return new Promise<void>((resolve) => {
          const i = new Image();
          i.onload = () => {
            imageCache.current.set(img.id, i);
            resolve();
          };
          i.src = img.previewUrl;
        });
      });
      await Promise.all(promises);
      requestAnimationFrame(() => drawGrid());
    };
    loadImages();
  }, [images]);

  const drawGrid = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const isAuto = settings.layoutMode === 'auto';
    const margin = settings.outerMargin;
    const spacing = settings.innerSpacing;
    const scaleFactor = 1 + ((settings.itemScale || 0) / 100);

    let cols = settings.columns;

    // LÓGICA AUTO-FLOW DINÂMICA
    if (isAuto && activeImages.length > 0) {
      let targetRatio = 1;
      if (settings.targetShape === 'portrait') targetRatio = 0.65;
      if (settings.targetShape === 'landscape') targetRatio = 1.6;

      const avgItemRatio = activeImages.reduce((acc, img) => acc + img.aspectRatio, 0) / activeImages.length;
      const optimalCols = Math.max(1, Math.round(Math.sqrt((targetRatio * activeImages.length) / avgItemRatio)));
      cols = optimalCols;
      if (calculatedCols !== cols) setCalculatedCols(cols);
    }

    let finalCanvasWidth = settings.canvasWidth;
    let finalCanvasHeight = settings.canvasHeight;

    if (isAuto) {
      const baseCellWidth = (settings.canvasWidth - (2 * margin) - ((cols - 1) * spacing)) / cols;
      const cellWidth = baseCellWidth * scaleFactor;
      const cellHeight = cellWidth; // Guia quadrada para o grid auto
      const rows = Math.ceil(activeImages.length / cols);

      finalCanvasHeight = (rows * cellHeight) + (2 * margin) + ((rows - 1) * spacing);
      finalCanvasWidth = (cols * cellWidth) + (2 * margin) + ((cols - 1) * spacing);

      if (activeImages.length === 0) {
        finalCanvasHeight = settings.canvasHeight;
        finalCanvasWidth = settings.canvasWidth;
      }

      if (currentCanvasHeight !== finalCanvasHeight) {
        setCurrentCanvasHeight(finalCanvasHeight);
      }
    }

    if (canvas.width !== finalCanvasWidth || canvas.height !== finalCanvasHeight) {
      canvas.width = finalCanvasWidth;
      canvas.height = finalCanvasHeight;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!settings.isTransparent) {
      ctx.fillStyle = settings.backgroundColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    if (activeImages.length === 0) return;

    const actualCellWidth = (canvas.width - (2 * margin) - ((cols - 1) * spacing)) / cols;
    const rows = Math.ceil(activeImages.length / cols);
    const actualCellHeight = (canvas.height - (2 * margin) - ((rows - 1) * spacing)) / rows;

    activeImages.forEach((imgObj, index) => {
      const img = imageCache.current.get(imgObj.id);
      if (!img) return;

      const col = index % cols;
      const row = Math.floor(index / cols);
      const x = margin + (col * (actualCellWidth + spacing));
      const y = margin + (row * (actualCellHeight + spacing));

      let drawW = actualCellWidth;
      let drawH = actualCellWidth / imgObj.aspectRatio;

      if (drawH > actualCellHeight) {
        drawH = actualCellHeight;
        drawW = actualCellHeight * imgObj.aspectRatio;
      }

      const offsetX = x + (actualCellWidth - drawW) / 2;
      const offsetY = y + (actualCellHeight - drawH) / 2;

      ctx.drawImage(img, offsetX, offsetY, drawW, drawH);
    });
  }, [activeImages, settings, currentCanvasHeight, calculatedCols]);

  useEffect(() => {
    if (renderRequestId.current) cancelAnimationFrame(renderRequestId.current);
    renderRequestId.current = requestAnimationFrame(() => drawGrid());
    return () => {
      if (renderRequestId.current) cancelAnimationFrame(renderRequestId.current);
    };
  }, [drawGrid, settings]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    dragInfo.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialOffsetX: offset.x,
      initialOffsetY: offset.y,
      animationFrameId: 0
    };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging) return;

    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }

    dragInfo.current.animationFrameId = requestAnimationFrame(() => {
      const dx = e.clientX - dragInfo.current.startX;
      const dy = e.clientY - dragInfo.current.startY;

      onOffsetChange({
        x: dragInfo.current.initialOffsetX + dx,
        y: dragInfo.current.initialOffsetY + dy
      });
    });
  }, [isDragging, onOffsetChange]);

  const handleMouseUp = useCallback(() => {
    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }
    setIsDragging(false);
  }, []);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  const isAuto = settings.layoutMode === 'auto';
  let actualCols = settings.columns;
  if (isAuto && activeImages.length > 0) actualCols = calculatedCols;

  const margin = settings.outerMargin;
  const spacing = settings.innerSpacing;
  const scaleFactor = 1 + ((settings.itemScale || 0) / 100);

  const baseCellW = (settings.canvasWidth - (2 * margin) - ((actualCols - 1) * spacing)) / actualCols;
  const cellW = baseCellW * (isAuto ? scaleFactor : 1);

  const finalW = isAuto ? (actualCols * cellW) + (2 * margin) + ((actualCols - 1) * spacing) : settings.canvasWidth;
  const finalH = isAuto ? currentCanvasHeight : settings.canvasHeight;

  return (
    <div 
      ref={containerRef}
      className="w-full h-full flex items-center justify-center relative select-none overflow-hidden"
      onMouseDown={handleMouseDown}
    >
      <div 
        className="shadow-2xl relative border bg-theme-panel flex-shrink-0 transition-all duration-300 ease-out"
        style={{
          width: finalW * zoom,
          height: finalH * zoom,
          minWidth: finalW * zoom,
          minHeight: finalH * zoom,
          transform: `translate(${offset.x}px, ${offset.y}px)`,
          borderColor: 'var(--border)',
          backgroundImage: settings.isTransparent ? 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)' : 'none',
          backgroundSize: '20px 20px',
          willChange: 'transform, width, height'
        }}
      >
        <canvas 
          id="grid-canvas" 
          ref={canvasRef} 
          className="w-full h-full block" 
        />
      </div>
    </div>
  );
};

export default GridPreview;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import Sidebar from '../components/Sidebar';
import GridPreview from '../components/GridPreview';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage, GridSettings } from '../types';

const GridTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [settings, setSettings] = useState<GridSettings>({
    canvasWidth: 2048,
    canvasHeight: 2048,
    columns: 3,
    innerSpacing: 5,
    outerMargin: 5,
    backgroundColor: '#0f172a',
    isTransparent: false,
    layoutMode: 'grid',
    itemScale: 0,
    targetShape: 'square'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  const processFiles = async (files: File[]) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    const filteredFiles = files.filter(file => validTypes.includes(file.type));
    const newImages: GridImage[] = [];

    for (const file of filteredFiles) {
      try {
        const url = URL.createObjectURL(file);
        const img = await new Promise<HTMLImageElement>((resolve, reject) => {
          const i = new Image();
          i.onload = () => resolve(i);
          i.onerror = reject;
          i.src = url;
        });

        newImages.push({
          id: uuidv4(),
          file,
          previewUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height,
          isActive: true, // Por padrão todos entram ativos
          visible: true
        });
      } catch (err) {
        console.error("Erro ao processar imagem:", file.name);
      }
    }

    if (newImages.length > 0) {
      setImages(prev => [...prev, ...newImages]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      let filesArray = Array.from(e.target.files) as File[];
      processFiles(filesArray);
    }
    if (e.target) e.target.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => {
      const target = prev.find(img => img.id === id);
      if (target) URL.revokeObjectURL(target.previewUrl);
      return prev.filter(img => img.id !== id);
    });
  };

  const toggleActive = (id: string) => {
    setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img));
  };

  const updateActiveCount = (count: number) => {
    setImages(prev => prev.map((img, idx) => ({
      ...img,
      isActive: idx < count
    })));
  };

  const moveImage = (index: number, direction: 'up' | 'down') => {
    // Apenas movemos entre a lista completa de imagens
    const newImages = [...images];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex >= 0 && targetIndex < newImages.length) {
      [newImages[index], newImages[targetIndex]] = [newImages[targetIndex], newImages[index]];
      setImages(newImages);
    }
  };

  const handleExport = async () => {
    const canvas = document.getElementById('grid-canvas') as HTMLCanvasElement;
    if (!canvas) return;
    const fileName = `grid_${Date.now()}.png`;
    const dataUrl = canvas.toDataURL('image/png', 1.0);

    if (downloadIndividual) {
      const link = document.createElement('a');
      link.download = fileName; link.href = dataUrl; link.click();
    }
    if (downloadZip) {
      const zip = new JSZip();
      zip.file(fileName, dataUrl.split(',')[1], { base64: true });
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `grid_miau_${Date.now()}.zip`; link.click();
    }
  };

  const clearAll = useCallback(() => {
    images.forEach(img => { if (img.previewUrl) URL.revokeObjectURL(img.previewUrl); });
    setImages([]); setOffset({ x: 0, y: 0 }); setZoom(0.4);
  }, [images]);

  const activeCount = images.filter(img => img.isActive).length;

  return (
    <div className="flex-1 flex overflow-hidden">
      <aside className="w-80 flex-shrink-0 border-r overflow-y-auto bg-theme-side border-theme">
        <Sidebar 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddFile={() => fileInputRef.current?.click()}
          onAddFolder={() => folderInputRef.current?.click()}
          images={images}
          onUpdateActiveCount={updateActiveCount}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onExport={handleExport}
        />
      </aside>

      <section className="flex-1 overflow-hidden relative flex flex-col bg-theme-main">
        <Header itemCount={images.length} onClear={clearAll} />

        <div className="flex-1 relative flex flex-col items-center justify-center bg-black/5 overflow-hidden">
          <div className="flex-1 w-full h-full cursor-grab active:cursor-grabbing">
            <GridPreview 
              images={images} 
              settings={settings} 
              zoom={zoom} 
              offset={offset}
              onOffsetChange={setOffset}
            />
          </div>

          {/* PAINEL DE INFO DINÂMICO */}
          {images.length > 0 && (
            <div className="absolute bottom-24 flex flex-col items-center gap-4 animate-in fade-in slide-in-from-bottom-4 duration-700 pointer-events-none">
              <div className="flex items-center gap-4 bg-theme-side/70 border border-theme/40 px-5 py-2.5 rounded-2xl shadow-2xl backdrop-blur-xl">
                <div className="flex flex-col items-start leading-none gap-1">
                  <span className="text-[7px] font-black uppercase opacity-30 tracking-widest">Processamento</span>
                  <span className="text-[11px] font-mono font-bold opacity-60 tracking-tighter">
                    {settings.layoutMode === 'auto' ? 'Auto Intelligent' : 'Manual Grid'}
                  </span>
                </div>
                <div className="w-[1px] h-6 bg-theme/50 mx-1"></div>
                <div className="flex flex-col items-start leading-none gap-1 text-right">
                  <span className="text-[7px] font-black uppercase text-theme-accent tracking-widest">Ativos na Grid</span>
                  <span className="text-[11px] font-mono font-black text-theme-accent tracking-tighter">
                    {activeCount} <span className="opacity-40">de</span> {images.length}
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* VIEW CONTROLLER */}
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme/40 py-1.5 px-6 rounded-full shadow-2xl backdrop-blur-md z-50">
            <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
              <i className="fas fa-search text-[10px] opacity-20"></i>
              <input type="range" min="0.05" max="2" step="0.01" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
              <span className="text-[9px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
            </div>
            <button onClick={() => { setOffset({ x: 0, y: 0 }); setZoom(0.4); }} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main transition-all group" title="Reset View">
              <i className="fas fa-undo-alt text-[9px] opacity-40 group-hover:opacity-100"></i>
            </button>
          </div>
        </div>
      </section>

      <aside className="w-80 flex-shrink-0 border-l overflow-hidden flex flex-col bg-theme-side border-theme">
        <div className="p-4 border-b font-black text-[10px] uppercase tracking-widest flex justify-between items-center text-theme-muted bg-black/5">
          <span>Gerenciador de Itens</span>
          <i className="fas fa-list-ul opacity-40"></i>
        </div>
        <ImageList 
          images={images} 
          onRemove={removeImage} 
          onMove={moveImage}
          onToggleActive={toggleActive}
        />
      </aside>

      <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
      <input type="file" {...({ webkitdirectory: "" } as any)} className="hidden" ref={folderInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default GridTool;

