import React from 'react';
import { AlphaEdgeSettings } from '../types';

interface SidebarAlphaEdgeProps {
  settings: AlphaEdgeSettings;
  onSettingsChange: (s: AlphaEdgeSettings) => void;
  onAdd: () => void;
  onSave: () => void;
  isProcessing?: boolean;
  progress?: number;
  total?: number;
  exportOptions: {
    downloadIndividual: boolean;
    setDownloadIndividual: (v: boolean) => void;
    downloadZip: boolean;
    setDownloadZip: (v: boolean) => void;
  };
}

const SidebarAlphaEdge: React.FC<SidebarAlphaEdgeProps> = ({ 
  settings, 
  onSettingsChange, 
  onAdd, 
  onSave,
  isProcessing = false,
  progress = 0,
  total = 0,
  exportOptions
}) => {
  const handleChange = (key: keyof AlphaEdgeSettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  const selectMode = (mode: 'individual' | 'zip') => {
    if (mode === 'individual') {
      exportOptions.setDownloadIndividual(true);
      exportOptions.setDownloadZip(false);
    } else {
      exportOptions.setDownloadIndividual(false);
      exportOptions.setDownloadZip(true);
    }
  };

  return (
    <div className="p-5 space-y-6 h-full overflow-y-auto scrollbar-hide flex flex-col">
      {/* BOX: ENTRADA */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Arquivos Alpha</h3>
        <button onClick={onAdd} className="w-full py-3.5 rounded-xl font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase group relative overflow-hidden transition-transform active:scale-95">
          <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <i className="fas fa-file-image"></i> Importar PNGs
        </button>
      </div>

      {/* BOX: CONFIGURAÇÕES DA BORDA */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-5">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Estilo da Borda</h3>

        <div className="space-y-4">
          <div className="space-y-2">
            <div className="flex justify-between items-center px-1">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide">Espessura</label>
              <span className="text-[9px] font-black text-theme-accent">{settings.thickness}px</span>
            </div>
            <input 
              type="range" min="0" max="100" value={settings.thickness} 
              onChange={(e) => handleChange('thickness', parseInt(e.target.value))}
              className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent"
            />
          </div>

          <div className="space-y-2">
            <div className="flex justify-between items-center px-1">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide">Suavização (Blur)</label>
              <span className="text-[9px] font-black text-theme-accent">{settings.softness}px</span>
            </div>
            <input 
              type="range" min="0" max="50" value={settings.softness} 
              onChange={(e) => handleChange('softness', parseInt(e.target.value))}
              className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent"
            />
          </div>

          <div className="space-y-2">
            <div className="flex justify-between items-center px-1">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide">Opacidade</label>
              <span className="text-[9px] font-black text-theme-accent">{settings.opacity}%</span>
            </div>
            <input 
              type="range" min="0" max="100" value={settings.opacity} 
              onChange={(e) => handleChange('opacity', parseInt(e.target.value))}
              className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent"
            />
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-theme/20">
             <label className="text-[9px] font-bold opacity-60 uppercase">Cor da Borda</label>
             <input 
                type="color" value={settings.color} 
                onChange={(e) => handleChange('color', e.target.value)}
                className="w-8 h-8 rounded-lg border border-theme cursor-pointer bg-theme-panel p-0.5"
             />
          </div>
        </div>
      </div>

      {/* BOX: EXPORTAÇÃO */}
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Salvar Resultados</h3>
        <div className="grid grid-cols-1 gap-2">
          <button onClick={() => selectMode('individual')} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${exportOptions.downloadIndividual ? 'bg-theme-accent/10 border-theme-accent shadow-sm' : 'bg-theme-panel/30 border-theme opacity-60'}`}>
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadIndividual ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>{exportOptions.downloadIndividual && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in"></div>}</div>
            <span className="text-[9px] font-black uppercase">Ficheiros Separados</span>
          </button>
          <button onClick={() => selectMode('zip')} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${exportOptions.downloadZip ? 'bg-theme-accent/10 border-theme-accent shadow-sm' : 'bg-theme-panel/30 border-theme opacity-60'}`}>
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${exportOptions.downloadZip ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>{exportOptions.downloadZip && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in"></div>}</div>
            <span className="text-[9px] font-black uppercase">Arquivo .ZIP</span>
          </button>
        </div>
      </div>

      <div className="mt-auto pt-4">
        <button onClick={onSave} disabled={isProcessing || total === 0} className="w-full py-4 rounded-xl font-black text-[11px] bg-theme-accent text-theme-inv shadow-2xl flex items-center justify-center gap-2 uppercase tracking-widest disabled:opacity-50 active:scale-95 group relative overflow-hidden">
           <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
           {isProcessing ? <><i className="fas fa-spinner animate-spin"></i> {progress}/{total}</> : <><i className="fas fa-magic"></i> Gerar e Salvar</>}
        </button>
      </div>
    </div>
  );
};

