  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);

  const [settings, setSettings] = useState<AlphaEdgeSettings>({
    thickness: 10,
    softness: 2,
    opacity: 100,
    color: '#ffffff',
    padding: 60
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings) => {
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const pad = config.padding;
    canvas.width = img.width + (pad * 2);
    canvas.height = img.height + (pad * 2);

    // Canvas temporário para criar a silhueta expandida
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = canvas.width;
    tempCanvas.height = canvas.height;
    const tCtx = tempCanvas.getContext('2d');
    if (!tCtx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 1. CRIAR SILHUETA SÓLIDA
    tCtx.save();
    tCtx.translate(pad, pad);
    tCtx.drawImage(img, 0, 0);
    tCtx.globalCompositeOperation = 'source-in';
    tCtx.fillStyle = config.color;
    tCtx.fillRect(-pad, -pad, canvas.width, canvas.height);
    tCtx.restore();

    // 2. EXPANDIR (THICKNESS) USANDO BLUR + CONTRASTE DE ALPHA
    // Desenhamos a silhueta com blur na canvas principal
    ctx.save();
    if (config.thickness > 0) {
      // Aplicamos o blur que define a espessura
      ctx.filter = `blur(${config.thickness}px)`;
      ctx.drawImage(tempCanvas, 0, 0);

      // TRUQUE DE MESTRE: Endurecer o Alpha (Threshold)
      // O contraste alto no canal alpha transforma o gradiente do blur em borda sólida
      // Aplicamos via pixels para precisão total
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;
      for (let i = 0; i < data.length; i += 4) {
        const alpha = data[i + 3];
        // Se o alpha for maior que 128 (meio termo), vira 255 (sólido)
        // Isso cria a borda "fat" e única
        data[i + 3] = alpha > 120 ? 255 : 0;
      }
      ctx.putImageData(imageData, 0, 0);
    }
    ctx.restore();

    // 3. SUAVIZAÇÃO EXTERNA (SOFTNESS/DISPERSÃO)
    // Agora que temos a borda sólida, aplicamos o desfoque final de suavização
    if (config.softness > 0) {
      const softCanvas = document.createElement('canvas');
      softCanvas.width = canvas.width;
      softCanvas.height = canvas.height;
      const sCtx = softCanvas.getContext('2d');
      if (sCtx) {
        sCtx.filter = `blur(${config.softness}px)`;
        sCtx.drawImage(canvas, 0, 0);

        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.globalAlpha = config.opacity / 100;
        ctx.drawImage(softCanvas, 0, 0);
        ctx.globalAlpha = 1.0;
      }
    }

    // 4. DESENHAR IMAGEM ORIGINAL POR CIMA
    ctx.save();
    ctx.translate(pad, pad);
    ctx.drawImage(img, 0, 0);
    ctx.restore();
  }, []);

  useEffect(() => {
    const updatePreview = async () => {
      if (!previewCanvasRef.current || !images[selectedIdx]) return;
      const img = new Image();
      img.src = images[selectedIdx].previewUrl;
      img.onload = () => drawEdge(img, previewCanvasRef.current!, settings);
    };
    updatePreview();
  }, [selectedIdx, images, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = [];
    for (const file of files) {
      const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const i = new Image();
        i.onload = () => resolve(i);
        i.src = url;
      });
      newImgs.push({ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height });
    }
    setImages(prev => [...prev, ...newImgs]);
    if (e.target) e.target.value = '';
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    const zip = downloadZip ? new JSZip() : null;

    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i];
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl;
      });
      await drawEdge(img, canvas, settings);

      const dataUrl = canvas.toDataURL('image/png');
      const name = `${item.file.name.split('.')[0]}_miau_edge.png`;

      if (downloadIndividual) {
        const link = document.createElement('a'); link.download = name; link.href = dataUrl;
        link.click();
        await new Promise(r => setTimeout(r, 400));
      }
      if (zip) zip.file(name, dataUrl.split(',')[1], { base64: true });
    }

    if (zip) {
      const blob = await zip.generateAsync({ type: 'blob' });
      const link = document.createElement('a'); link.href = URL.createObjectURL(blob);
      link.download = `miau_edges_${Date.now()}.zip`; link.click();
    }
    setIsProcessing(false);
  };

  const currentImg = images[selectedIdx];

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={setSettings}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-lg"
                style={{ 
