import React, { useRef, useEffect, useCallback, useState } from 'react';
import { GridImage, GridSettings } from '../types';

interface GridPreviewProps {
  images: GridImage[];
  settings: GridSettings;
  zoom?: number;
  offset: { x: number, y: number };
  onOffsetChange: (offset: { x: number, y: number }) => void;
}

const GridPreview: React.FC<GridPreviewProps> = ({ 
  images, 
  settings, 
  zoom = 0.4,
  offset,
  onOffsetChange
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const renderRequestId = useRef<number>(0);
  const imageCache = useRef<Map<string, HTMLImageElement>>(new Map());
  const [isDragging, setIsDragging] = useState(false);
  const [currentCanvasHeight, setCurrentCanvasHeight] = useState(settings.canvasHeight);
  const [calculatedCols, setCalculatedCols] = useState(settings.columns);

  const dragInfo = useRef({
    startX: 0,
    startY: 0,
    initialOffsetX: 0,
    initialOffsetY: 0,
    animationFrameId: 0
  });

  const activeImages = images.filter(img => img.isActive);

  useEffect(() => {
    const loadImages = async () => {
      const promises = activeImages.map(img => {
        if (imageCache.current.has(img.id)) return Promise.resolve();
        return new Promise<void>((resolve) => {
          const i = new Image();
          i.onload = () => {
            imageCache.current.set(img.id, i);
            resolve();
          };
          i.src = img.previewUrl;
        });
      });
      await Promise.all(promises);
      requestAnimationFrame(() => drawGrid());
    };
    loadImages();
  }, [images]);

  const drawGrid = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const isAuto = settings.layoutMode === 'auto';
    const margin = settings.outerMargin;
    const spacing = settings.innerSpacing;
    const scaleFactor = 1 + ((settings.itemScale || 0) / 100);

    let cols = settings.columns;

    if (isAuto && activeImages.length > 0) {
      let targetRatio = 1;
      if (settings.targetShape === 'portrait') targetRatio = 0.65;
      if (settings.targetShape === 'landscape') targetRatio = 1.6;
      const avgItemRatio = activeImages.reduce((acc, img) => acc + img.aspectRatio, 0) / activeImages.length;
      cols = Math.max(1, Math.round(Math.sqrt((targetRatio * activeImages.length) / avgItemRatio)));
      if (calculatedCols !== cols) setCalculatedCols(cols);
    }

    let finalCanvasWidth = settings.canvasWidth;
    let finalCanvasHeight = settings.canvasHeight;

    if (isAuto) {
      const baseCellWidth = (settings.canvasWidth - (2 * margin) - ((cols - 1) * spacing)) / cols;
      const cellWidth = baseCellWidth * scaleFactor;
      const cellHeight = cellWidth;
      const rows = Math.ceil(activeImages.length / cols);
      finalCanvasHeight = (rows * cellHeight) + (2 * margin) + ((rows - 1) * spacing);
      finalCanvasWidth = (cols * cellWidth) + (2 * margin) + ((cols - 1) * spacing);
      if (currentCanvasHeight !== finalCanvasHeight) setCurrentCanvasHeight(finalCanvasHeight);
    }

    canvas.width = finalCanvasWidth;
    canvas.height = finalCanvasHeight;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!settings.isTransparent) {
      ctx.fillStyle = settings.backgroundColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    if (activeImages.length === 0) return;

    const actualCellWidth = (canvas.width - (2 * margin) - ((cols - 1) * spacing)) / cols;
    const rows = Math.ceil(activeImages.length / cols);
    const actualCellHeight = (canvas.height - (2 * margin) - ((rows - 1) * spacing)) / rows;

    activeImages.forEach((imgObj, index) => {
      const img = imageCache.current.get(imgObj.id);
      if (!img) return;
      const col = index % cols;
      const row = Math.floor(index / cols);
      const x = margin + (col * (actualCellWidth + spacing));
      const y = margin + (row * (actualCellHeight + spacing));
      let drawW = actualCellWidth;
      let drawH = actualCellWidth / imgObj.aspectRatio;
      if (drawH > actualCellHeight) {
        drawH = actualCellHeight;
        drawW = actualCellHeight * imgObj.aspectRatio;
      }
      ctx.drawImage(img, x + (actualCellWidth - drawW) / 2, y + (actualCellHeight - drawH) / 2, drawW, drawH);
    });
  }, [activeImages, settings, currentCanvasHeight, calculatedCols]);

  useEffect(() => {
    drawGrid();
  }, [drawGrid, settings]);

  return (
    <div 
      ref={containerRef}
      className="w-full h-full flex items-center justify-center relative select-none overflow-hidden"
      onMouseDown={(e) => {
        setIsDragging(true);
        dragInfo.current = { startX: e.clientX, startY: e.clientY, initialOffsetX: offset.x, initialOffsetY: offset.y, animationFrameId: 0 };
      }}
      onMouseMove={(e) => {
        if (!isDragging) return;
        const dx = e.clientX - dragInfo.current.startX;
        const dy = e.clientY - dragInfo.current.startY;
        onOffsetChange({ x: dragInfo.current.initialOffsetX + dx, y: dragInfo.current.initialOffsetY + dy });
      }}
      onMouseUp={() => setIsDragging(false)}
      style={{ backgroundColor: settings.isTransparent ? 'transparent' : settings.backgroundColor }}
    >
      <div 
        className="shadow-2xl relative border flex-shrink-0 transition-transform duration-300"
        style={{
          width: canvasRef.current?.width ? canvasRef.current.width * zoom : settings.canvasWidth * zoom,
          height: canvasRef.current?.height ? canvasRef.current.height * zoom : settings.canvasHeight * zoom,
          transform: `translate(${offset.x}px, ${offset.y}px)`,
          borderColor: 'var(--border)',
          backgroundImage: settings.isTransparent ? 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)' : 'none',
          backgroundSize: '20px 20px'
        }}
      >
        <canvas ref={canvasRef} className="w-full h-full block" />
      </div>
    </div>
  );
};

export default GridPreview;

import React, { useRef, useEffect, useState } from 'react';
import { AdvancedBorderSettings } from '../types';

interface AdvancedBorderModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: AdvancedBorderSettings;
  onUpdate: (s: AdvancedBorderSettings) => void;
  baseImageUrl: string | null;
}

const AdvancedBorderModal: React.FC<AdvancedBorderModalProps> = ({ isOpen, onClose, settings, onUpdate, baseImageUrl }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const shapes: { id: AdvancedBorderSettings['shapeType'], icon: string }[] = [
    { id: 'circle', icon: 'fa-circle' },
    { id: 'square', icon: 'fa-square' },
    { id: 'triangle', icon: 'fa-caret-up' },
    { id: 'x', icon: 'fa-times' },
    { id: 'heart', icon: 'fa-heart' },
    { id: 'diamond', icon: 'fa-clone' }
  ];

  useEffect(() => {
    if (!isOpen || !canvasRef.current || !baseImageUrl) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.src = baseImageUrl;
    img.onload = () => {
      canvas.width = 520;
      canvas.height = 520;
      ctx.clearRect(0, 0, 520, 520);

      const ratio = Math.min(300 / img.width, 300 / img.height);
      const w = img.width * ratio;
      const h = img.height * ratio;
      const x = (520 - w) / 2;
      const y = (520 - h) / 2;

      // Desenhar arte base
      ctx.globalAlpha = 0.3;
      ctx.drawImage(img, x, y, w, h);
      ctx.globalAlpha = 1.0;

      if (settings.enabled) {
        // Mock de repetição visual no preview do modal
        // Em um cenário real, usaríamos o algoritmo de contorno
        ctx.fillStyle = settings.color;
        const steps = 40 - settings.spacing;
        const radius = Math.max(w, h) / 2 + 10;

        ctx.save();
        ctx.translate(260, 260);
        ctx.rotate((settings.globalRotation * Math.PI) / 180);

        for (let i = 0; i < steps; i++) {
          const angle = (i / steps) * Math.PI * 2;
          const px = Math.cos(angle) * radius;
          const py = Math.sin(angle) * radius;

          ctx.save();
          ctx.translate(px, py);
          ctx.rotate((settings.individualRotation * Math.PI) / 180);
          drawShape(ctx, settings.shapeType, settings.size);
          ctx.restore();
        }
        ctx.restore();
      }
    };
  }, [isOpen, settings, baseImageUrl]);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      ctx.moveTo(0, s); ctx.bezierCurveTo(-s, 0, -s, -s, 0, -s); ctx.bezierCurveTo(s, -s, s, 0, 0, s);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 backdrop-blur-xl bg-black/60 animate-in fade-in duration-300">
      <div className="bg-theme-side border border-theme w-full max-w-5xl rounded-[2.5rem] shadow-2xl flex overflow-hidden h-[85vh]">
        {/* LADO ESQUERDO: PREVIEW */}
        <div className="flex-1 bg-black/20 flex items-center justify-center relative p-10">
           <div className="absolute top-6 left-6 flex items-center gap-2 opacity-40">
              <i className="fas fa-microchip text-xs"></i>
              <span className="text-[10px] font-black uppercase tracking-[0.3em]">Scatter Engine v1.0</span>
           </div>
           <div className="relative rounded-2xl overflow-hidden shadow-inner border border-white/5 bg-theme-panel/20">
              <canvas ref={canvasRef} className="block" />
           </div>
        </div>

        {/* LADO DIREITO: CONTROLES */}
        <div className="w-96 border-l border-theme p-8 flex flex-col gap-8 overflow-y-auto bg-theme-side">
          <div className="flex justify-between items-center">
            <h2 className="text-xl font-black uppercase tracking-tighter miau-text">Editor de Borda</h2>
            <button onClick={onClose} className="w-8 h-8 rounded-full bg-theme-panel hover:bg-theme-accent text-theme-main transition-all flex items-center justify-center">
              <i className="fas fa-times text-xs"></i>
            </button>
          </div>

          <div className="space-y-6">
            <button 
              onClick={() => onUpdate({ ...settings, enabled: !settings.enabled })}
              className={`w-full py-3 rounded-xl font-black text-[10px] uppercase border transition-all ${settings.enabled ? 'bg-theme-accent text-white border-theme-accent shadow-lg' : 'bg-theme-panel border-theme opacity-50'}`}
            >
              {settings.enabled ? 'Repetidor Ativo' : 'Ativar Repetidor'}
            </button>

            <div className="space-y-3">
              <label className="text-[9px] font-black uppercase opacity-40 tracking-widest">Elemento de Repetição</label>
              <div className="grid grid-cols-3 gap-2">
                {shapes.map(s => (
                  <button 
                    key={s.id} 
                    onClick={() => onUpdate({ ...settings, shapeType: s.id })}
                    className={`h-12 rounded-xl border flex items-center justify-center text-lg transition-all ${settings.shapeType === s.id ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-panel border-theme opacity-40 hover:opacity-100'}`}
                  >
                    <i className={`fas ${s.icon}`}></i>
                  </button>
                ))}
              </div>
            </div>

            {[
              { label: 'Tamanho Forma', key: 'size', min: 5, max: 100 },
              { label: 'Densidade / Espaço', key: 'spacing', min: 1, max: 35 },
              { label: 'Giro Individual', key: 'individualRotation', min: 0, max: 360 },
              { label: 'Giro Global', key: 'globalRotation', min: 0, max: 360 },
            ].map(ctrl => (
              <div key={ctrl.key} className="space-y-2">
                <div className="flex justify-between items-center">
                  <label className="text-[9px] font-black uppercase opacity-40">{ctrl.label}</label>
                  <span className="text-[10px] font-mono font-bold text-theme-accent">{(settings as any)[ctrl.key]}</span>
                </div>
                <input 
                  type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]}
                  onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })}
                  className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent"
                />
              </div>
            ))}

            <div className="flex items-center justify-between pt-4 border-t border-theme">
              <label className="text-[9px] font-black uppercase opacity-40">Cor do Elemento</label>
              <input 
                type="color" value={settings.color} 
                onChange={(e) => onUpdate({ ...settings, color: e.target.value })}
                className="w-10 h-10 rounded-xl border border-theme p-1 bg-theme-panel cursor-pointer"
              />
            </div>
          </div>

          <div className="mt-auto">
             <button onClick={onClose} className="w-full py-4 rounded-2xl bg-theme-accent text-theme-inv font-black uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-transform">
                Aplicar e Fechar
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

