  file: File;
  previewUrl: string;
  width: number;
  height: number;
  aspectRatio: number;
  isActive?: boolean;
  visible?: boolean;
  x?: number;
  y?: number;
  scale?: number;
  rotation?: number;
}

export interface GridSettings {
  canvasWidth: number;
  canvasHeight: number;
  columns: number;
  innerSpacing: number;
  outerMargin: number;
  backgroundColor: string;
  isTransparent: boolean;
  backgroundImageUrl?: string;
  layoutMode?: 'grid' | 'auto';
  itemScale?: number;
  targetShape?: 'square' | 'portrait' | 'landscape';
}

export interface AdvancedBorderSettings {
  enabled: boolean;
  shapeType: 'circle' | 'square' | 'triangle' | 'x' | 'heart' | 'diamond';
  size: number;
  spacingX: number;
  spacingY: number;
  color: string;
  bgColor: string;
  individualRotation: number;
  globalRotation: number;
  offsetX: number;
  offsetY: number;
}

export interface AlphaEdgeSettings {
  thickness: number;
  softness: number;
  opacity: number;
  color: string;
  padding: number;
  advanced?: AdvancedBorderSettings;
}

import React, { useRef, useEffect } from 'react';
import { AdvancedBorderSettings } from '../types';

interface AdvancedBorderModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: AdvancedBorderSettings;
  onUpdate: (s: AdvancedBorderSettings) => void;
  baseImageUrl: string | null;
}

const AdvancedBorderModal: React.FC<AdvancedBorderModalProps> = ({ isOpen, onClose, settings, onUpdate, baseImageUrl }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const shapes: { id: AdvancedBorderSettings['shapeType'], icon: string }[] = [
    { id: 'circle', icon: 'fa-circle' },
    { id: 'square', icon: 'fa-square' },
    { id: 'triangle', icon: 'fa-caret-up' },
    { id: 'x', icon: 'fa-times' },
    { id: 'heart', icon: 'fa-heart' },
    { id: 'diamond', icon: 'fa-clone' }
  ];

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      ctx.moveTo(0, s); ctx.bezierCurveTo(-s, 0, -s, -s, 0, -s); ctx.bezierCurveTo(s, -s, s, 0, 0, s);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const renderPattern = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    ctx.save();
    // 1. Fundo
    ctx.fillStyle = config.bgColor;
    ctx.fillRect(0, 0, w, h);

    // 2. Transformação Global
    ctx.translate(w / 2 + config.offsetX, h / 2 + config.offsetY);
    ctx.rotate((config.globalRotation * Math.PI) / 180);
    ctx.translate(-w / 2, -h / 2);

    // 3. Grid de Repetição
    ctx.fillStyle = config.color;
    const stepX = config.size + config.spacingX;
    const stepY = config.size + config.spacingY;

    // Cobrir uma área maior para rotações não cortarem o padrão
    const overflow = 2;
    for (let x = -w * overflow; x < w * overflow; x += stepX) {
      for (let y = -h * overflow; y < h * overflow; y += stepY) {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate((config.individualRotation * Math.PI) / 180);
        drawShape(ctx, config.shapeType, config.size);
        ctx.restore();
      }
    }
    ctx.restore();
  };

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = 520;
    canvas.height = 520;
    renderPattern(ctx, 520, 520, settings);

    // Overlay opaco da imagem original para contexto
    if (baseImageUrl) {
        const img = new Image();
        img.src = baseImageUrl;
        img.onload = () => {
            ctx.save();
            ctx.globalAlpha = 0.2;
            const ratio = Math.min(300 / img.width, 300 / img.height);
            ctx.drawImage(img, (520 - img.width * ratio) / 2, (520 - img.height * ratio) / 2, img.width * ratio, img.height * ratio);
            ctx.restore();
        };
    }
  }, [isOpen, settings, baseImageUrl]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 backdrop-blur-xl bg-black/60 animate-in fade-in duration-300">
      <div className="bg-theme-side border border-theme w-full max-w-6xl rounded-[2.5rem] shadow-2xl flex overflow-hidden h-[90vh]">

        {/* LADO ESQUERDO: PREVIEW */}
        <div className="flex-1 bg-black/20 flex flex-col items-center justify-center relative p-10 gap-6">
           <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-theme-accent flex items-center justify-center text-white shadow-lg">
                <i className="fas fa-th"></i>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-40">Miau Grid Engine</span>
                <span className="text-lg font-black tracking-tighter uppercase">Estúdio de Estampa</span>
              </div>
           </div>

           <div className="relative rounded-[2rem] overflow-hidden shadow-2xl border-4 border-white/5 bg-theme-panel/20 p-2">
              <canvas ref={canvasRef} className="block rounded-[1.5rem] shadow-inner" />
           </div>

           <div className="flex gap-4 opacity-40 text-[9px] font-black uppercase tracking-widest">
              <span>Preview 1:1</span>
              <span>•</span>
              <span>Vector Sharp</span>
           </div>
        </div>

        {/* LADO DIREITO: CONTROLES */}
        <div className="w-[420px] border-l border-theme p-8 flex flex-col gap-6 overflow-y-auto bg-theme-side">
          <div className="flex justify-between items-center mb-2">
             <div 
               onClick={() => onUpdate({ ...settings, enabled: !settings.enabled })}
               className={`flex items-center gap-3 px-4 py-2 rounded-full cursor-pointer transition-all border ${settings.enabled ? 'bg-theme-accent/20 border-theme-accent text-theme-accent' : 'bg-theme-panel border-theme opacity-40'}`}
             >
                <div className={`w-2 h-2 rounded-full ${settings.enabled ? 'bg-theme-accent animate-pulse' : 'bg-current'}`}></div>
                <span className="text-[10px] font-black uppercase tracking-widest">{settings.enabled ? 'Padrão Ativo' : 'Desativado'}</span>
             </div>
             <button onClick={onClose} className="w-10 h-10 rounded-full bg-theme-panel hover:bg-theme-accent text-theme-main hover:text-white transition-all flex items-center justify-center shadow-lg"><i className="fas fa-times"></i></button>
          </div>

          <div className="space-y-6">
            {/* SHAPES */}
            <div className="space-y-3">
              <label className="text-[9px] font-black uppercase opacity-40 tracking-widest">Forma da Estampa</label>
              <div className="grid grid-cols-6 gap-2">
                {shapes.map(s => (
                  <button 
                    key={s.id} onClick={() => onUpdate({ ...settings, shapeType: s.id })}
                    className={`h-12 rounded-xl border flex items-center justify-center text-lg transition-all ${settings.shapeType === s.id ? 'bg-theme-accent text-white border-theme-accent shadow-lg scale-105' : 'bg-theme-panel border-theme opacity-40 hover:opacity-100'}`}
                  >
                    <i className={`fas ${s.icon}`}></i>
                  </button>
                ))}
              </div>
            </div>

            {/* GRID CONTROLS */}
            <div className="grid grid-cols-2 gap-4">
               {[
                 { label: 'Tamanho', key: 'size', min: 2, max: 200 },
                 { label: 'Giro Indiv.', key: 'individualRotation', min: 0, max: 360 },
                 { label: 'Espaço X', key: 'spacingX', min: 0, max: 100 },
                 { label: 'Espaço Y', key: 'spacingY', min: 0, max: 100 },
                 { label: 'Posição X', key: 'offsetX', min: -500, max: 500 },
                 { label: 'Posição Y', key: 'offsetY', min: -500, max: 500 },
                 { label: 'Giro Global', key: 'globalRotation', min: 0, max: 360 },
               ].map(ctrl => (
                <div key={ctrl.key} className="space-y-1.5">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[8px] font-black uppercase opacity-40">{ctrl.label}</label>
                    <span className="text-[9px] font-mono font-bold text-theme-accent">{(settings as any)[ctrl.key]}</span>
                  </div>
                  <input 
                    type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]}
                    onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })}
                    className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent"
                  />
                </div>
               ))}
            </div>

            {/* COLORS */}
            <div className="flex gap-4 pt-4 border-t border-theme/20">
               <div className="flex-1 space-y-2">
                 <label className="text-[9px] font-black uppercase opacity-40 block text-center">Cor Forma</label>
                 <div className="relative group">
                    <input type="color" value={settings.color} onChange={(e) => onUpdate({ ...settings, color: e.target.value })} className="w-full h-12 rounded-xl border border-theme p-1 bg-theme-panel cursor-pointer" />
                 </div>
               </div>
               <div className="flex-1 space-y-2">
                 <label className="text-[9px] font-black uppercase opacity-40 block text-center">Cor Fundo</label>
                 <input type="color" value={settings.bgColor} onChange={(e) => onUpdate({ ...settings, bgColor: e.target.value })} className="w-full h-12 rounded-xl border border-theme p-1 bg-theme-panel cursor-pointer" />
               </div>
            </div>
          </div>

          <button onClick={onClose} className="mt-auto w-full py-5 rounded-2xl bg-theme-accent text-white font-black uppercase text-[11px] tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3">
             <i className="fas fa-check-circle"></i>
             Aplicar Estampa na Borda
          </button>
        </div>
      </div>
    </div>
  );
};

export default AdvancedBorderModal;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarAlphaEdge from '../components/SidebarAlphaEdge';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import AdvancedBorderModal from '../components/AdvancedBorderModal';
import { GridImage, AlphaEdgeSettings, AdvancedBorderSettings } from '../types';

const AlphaEdgeTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);

  const [settings, setSettings] = useState<AlphaEdgeSettings>({
    thickness: 15,
    softness: 2,
    opacity: 100,
    color: '#ffffff',
    padding: 120,
    advanced: {
      enabled: false,
      shapeType: 'circle',
      size: 15,
      spacingX: 10,
      spacingY: 10,
      color: '#ffffff',
      bgColor: '#000000',
      individualRotation: 0,
      globalRotation: 0,
      offsetX: 0,
      offsetY: 0
    }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      ctx.moveTo(0, s); ctx.bezierCurveTo(-s, 0, -s, -s, 0, -s); ctx.bezierCurveTo(s, -s, s, 0, 0, s);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const drawPattern = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    ctx.save();
    ctx.fillStyle = config.bgColor;
    ctx.fillRect(0, 0, w, h);
    ctx.translate(w / 2 + config.offsetX, h / 2 + config.offsetY);
    ctx.rotate((config.globalRotation * Math.PI) / 180);
    ctx.translate(-w / 2, -h / 2);
    ctx.fillStyle = config.color;
    const stepX = config.size + config.spacingX;
    const stepY = config.size + config.spacingY;
    const overflow = 2;
    for (let x = -w * overflow; x < w * overflow; x += stepX) {
      for (let y = -h * overflow; y < h * overflow; y += stepY) {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate((config.individualRotation * Math.PI) / 180);
        drawShape(ctx, config.shapeType, config.size);
        ctx.restore();
      }
    }
    ctx.restore();
  };

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings) => {
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const pad = config.padding;
    canvas.width = img.width + (pad * 2);
    canvas.height = img.height + (pad * 2);

    const silCanvas = document.createElement('canvas');
    silCanvas.width = canvas.width;
    silCanvas.height = canvas.height;
    const sCtx = silCanvas.getContext('2d');
    if (!sCtx) return;

    sCtx.save();
    sCtx.translate(pad, pad);
    sCtx.drawImage(img, 0, 0);
    sCtx.globalCompositeOperation = 'source-in';
    sCtx.fillStyle = config.color;
    sCtx.fillRect(-pad, -pad, canvas.width, canvas.height);
    sCtx.restore();

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 1. GERAR MÁSCARA DA BORDA EXPANDIDA
    if (config.thickness > 0) {
      const expansionCanvas = document.createElement('canvas');
      expansionCanvas.width = canvas.width;
      expansionCanvas.height = canvas.height;
      const eCtx = expansionCanvas.getContext('2d');
      if (eCtx) {
        const radius = config.thickness;
        eCtx.filter = `blur(${radius / 2}px)`; 
        const steps = 12;
        for (let i = 0; i < steps; i++) {
          const angle = (i / steps) * Math.PI * 2;
          eCtx.drawImage(silCanvas, Math.cos(angle) * (radius/2), Math.sin(angle) * (radius/2));
        }
        eCtx.drawImage(silCanvas, 0, 0);
        const imgData = eCtx.getImageData(0, 0, canvas.width, canvas.height);
        const data = imgData.data;
        for (let i = 0; i < data.length; i += 4) if (data[i + 3] > 20) data[i + 3] = 255;
        eCtx.putImageData(imgData, 0, 0);

        // 2. APLICAR PADRÃO OU COR SÓLIDA
        ctx.save();
        ctx.globalAlpha = config.opacity / 100;
        if (config.softness > 0) ctx.filter = `blur(${config.softness}px)`;

        // Desenha a expansão
        ctx.drawImage(expansionCanvas, 0, 0);

        // Se o padrão estiver ativo, usamos a expansão como máscara
        if (config.advanced?.enabled) {
           ctx.globalCompositeOperation = 'source-in';
           drawPattern(ctx, canvas.width, canvas.height, config.advanced);
        }
        ctx.restore();
      }
    }

    // 3. DESENHAR IMAGEM ORIGINAL NO TOPO
    ctx.save();
    ctx.translate(pad, pad);
    ctx.drawImage(img, 0, 0);
    ctx.restore();
  }, []);

  useEffect(() => {
    const updatePreview = async () => {
      if (!previewCanvasRef.current || !images[selectedIdx]) return;
      const img = new Image();
      img.src = images[selectedIdx].previewUrl;
      img.onload = () => drawEdge(img, previewCanvasRef.current!, settings);
    };
    updatePreview();
  }, [selectedIdx, images, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = [];
    for (const file of files) {
      const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const i = new Image();
        i.onload = () => resolve(i);
        i.src = url;
      });
      newImgs.push({ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height, isActive: true });
    }
    setImages(prev => [...prev, ...newImgs]);
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i];
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl;
      });
      await drawEdge(img, canvas, settings);
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a'); link.download = `${item.file.name.split('.')[0]}_miau.png`; link.href = dataUrl; link.click();
      await new Promise(r => setTimeout(r, 400));
    }
    setIsProcessing(false);
  };

  const currentImg = images[selectedIdx];

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={setSettings}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onOpenAdvanced={() => setIsModalOpen(true)}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-lg"
                style={{ 
                  width: (currentImg.width + settings.padding * 2) * zoom,
                  height: (currentImg.height + settings.padding * 2) * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <canvas ref={previewCanvasRef} className="w-full h-full block" />
              </div>

              <div className="absolute bottom-24 left-8 flex flex-col items-start gap-4 z-40 pointer-events-none">
                <div className="flex items-center gap-3 bg-theme-side/90 border border-theme/40 px-4 py-2 rounded-full shadow-2xl backdrop-blur-3xl">
                   <div className="flex items-center gap-1.5 bg-theme-accent text-white px-2 py-1 rounded-full border border-white/10">
                      <i className="fas fa-wand-magic-sparkles text-[8px]"></i>
                      <span className="text-[8px] font-black uppercase">Alpha Pro</span>
                   </div>
                   <div className="flex items-center gap-3">
                      <div className="flex flex-col leading-none">
                        <span className="text-[6px] font-black uppercase opacity-30">Expansion</span>
                        <span className="text-[10px] font-mono font-black text-theme-accent">+{settings.thickness}px</span>
                      </div>
                      {settings.advanced?.enabled && (
                        <>
                          <div className="w-[1px] h-4 bg-theme/30"></div>
                          <div className="flex flex-col leading-none">
                            <span className="text-[6px] font-black uppercase opacity-30">Pattern</span>
                            <span className="text-[10px] font-mono font-black text-theme-accent">Active</span>
                          </div>
                        </>
                      )}
                   </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Alpha Edge Master</p>
            </div>
          )}

          {currentImg && (
            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-6 py-2 rounded-full shadow-2xl backdrop-blur-md z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-24 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[9px] font-mono opacity-40 w-8">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-4">
                <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(prev => prev - 1)} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10"><i className="fas fa-chevron-left text-[9px]"></i></button>
                <span className="text-[10px] font-mono font-black text-theme-accent min-w-[50px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(prev => prev + 1)} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10"><i className="fas fa-chevron-right text-[9px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <div className="p-4 border-b border-theme font-black text-[10px] uppercase text-theme-muted bg-black/5 flex justify-between items-center">
          <span>Gerenciador Alpha</span>
          <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">{images.length}</span>
        </div>
        <ImageList 
          images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} onToggleActive={(id) => setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img))} 
        />
      </aside>

      <AdvancedBorderModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}
        settings={settings.advanced!} onUpdate={(adv) => setSettings({ ...settings, advanced: adv })}
        baseImageUrl={currentImg?.previewUrl || null}
      />
      <input type="file" multiple accept="image/png, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default AlphaEdgeTool;

export interface GridImage {
  id: string;
  file: File;
  previewUrl: string;
  width: number;
  height: number;
  aspectRatio: number;
  isActive?: boolean;
  visible?: boolean;
  x?: number;
  y?: number;
  scale?: number;
  rotation?: number;
}

export interface GridSettings {
