import React, { useRef, useEffect, useState } from 'react';
import { AdvancedBorderSettings } from '../types';

interface AdvancedBorderModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: AdvancedBorderSettings;
  onUpdate: (s: AdvancedBorderSettings) => void;
  baseImageUrl: string | null;
}

const AdvancedBorderModal: React.FC<AdvancedBorderModalProps> = ({ isOpen, onClose, settings, onUpdate, baseImageUrl }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [guideImg, setGuideImg] = useState<HTMLImageElement | null>(null);

  const shapes: { id: AdvancedBorderSettings['shapeType'], icon: string }[] = [
    { id: 'circle', icon: 'fa-circle' },
    { id: 'square', icon: 'fa-square' },
    { id: 'triangle', icon: 'fa-caret-up' },
    { id: 'x', icon: 'fa-times' },
    { id: 'heart', icon: 'fa-heart' },
    { id: 'diamond', icon: 'fa-clone' }
  ];

  // Carregar imagem de guia uma única vez para evitar flicker
  useEffect(() => {
    if (baseImageUrl) {
      const img = new Image();
      img.src = baseImageUrl;
      img.onload = () => setGuideImg(img);
    }
  }, [baseImageUrl]);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      ctx.moveTo(0, s); ctx.bezierCurveTo(-s, 0, -s, -s, 0, -s); ctx.bezierCurveTo(s, -s, s, 0, 0, s);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const renderPreview = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const w = 520;
    const h = 520;
    canvas.width = w;
    canvas.height = h;

    ctx.clearRect(0, 0, w, h);

    // 1. GRID ENGINE
    if (settings.gridEnabled) {
      ctx.save();
      ctx.fillStyle = settings.bgColor;
      ctx.fillRect(0, 0, w, h);
      ctx.translate(w / 2 + settings.offsetX, h / 2 + settings.offsetY);
      ctx.rotate((settings.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = settings.color;
      const stepX = settings.size + settings.spacingX;
      const stepY = settings.size + settings.spacingY;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save();
          ctx.translate(x, y);
          ctx.rotate((settings.individualRotation * Math.PI) / 180);
          drawShape(ctx, settings.shapeType, settings.size);
          ctx.restore();
        }
      }
      ctx.restore();
    } else {
      ctx.fillStyle = settings.bgColor;
      ctx.fillRect(0, 0, w, h);
    }

    // 2. SCATTER ENGINE (Repetidor de Contorno)
    if (settings.scatterEnabled) {
      ctx.save();
      ctx.fillStyle = settings.color;
      const steps = settings.scatterDensity;
      const radius = 180 + settings.scatterRadiusOffset;
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2;
        const px = w / 2 + Math.cos(angle) * radius;
        const py = h / 2 + Math.sin(angle) * radius;
        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(angle + (settings.scatterIndividualRotation * Math.PI) / 180);
        drawShape(ctx, settings.shapeType, settings.scatterSize);
        ctx.restore();
      }
      ctx.restore();
    }

    // 3. IMAGEM DE GUIA (Sempre no topo, com transparência para não "disputar")
    if (guideImg) {
      ctx.save();
      ctx.globalAlpha = 0.4;
      const ratio = Math.min(300 / guideImg.width, 300 / guideImg.height);
      const dw = guideImg.width * ratio;
      const dh = guideImg.height * ratio;
      ctx.drawImage(guideImg, (w - dw) / 2, (h - dh) / 2, dw, dh);
      ctx.restore();
    }
  };

  useEffect(() => {
    if (isOpen) renderPreview();
  }, [isOpen, settings, guideImg]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 backdrop-blur-xl bg-black/60 animate-in fade-in duration-300">
      <div className="bg-theme-side border border-theme w-full max-w-6xl rounded-[3rem] shadow-2xl flex overflow-hidden h-[90vh]">

        {/* PREVIEW CENTRAL */}
        <div className="flex-1 bg-black/20 flex flex-col items-center justify-center relative p-10 gap-6 border-r border-theme/30">
           <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-theme-accent flex items-center justify-center text-white shadow-lg rotate-3">
                <i className="fas fa-microchip"></i>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-40">Miau Dual Engine</span>
                <span className="text-xl font-black tracking-tighter uppercase">Border Pattern Studio</span>
              </div>
           </div>

           <div className="relative rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white/5 bg-theme-panel/20 p-2">
              <canvas ref={canvasRef} className="block rounded-[2rem] shadow-inner" />
           </div>

           <div className="flex gap-4 opacity-40 text-[9px] font-black uppercase tracking-widest bg-theme-panel/40 px-4 py-2 rounded-full border border-theme">
              <span>Grid + Scatter Sync</span>
              <span>•</span>
              <span>Layer Guide On</span>
           </div>
        </div>

        {/* CONTROLES LATERAIS */}
        <div className="w-[440px] p-8 flex flex-col gap-6 overflow-y-auto bg-theme-side custom-scrollbar">
          <div className="flex justify-between items-center mb-2">
             <button 
                onClick={() => onUpdate({ ...settings, enabled: !settings.enabled })}
                className={`flex items-center gap-3 px-5 py-2.5 rounded-full font-black text-[10px] uppercase tracking-widest transition-all border ${settings.enabled ? 'bg-theme-accent text-white border-theme-accent shadow-lg' : 'bg-theme-panel border-theme opacity-40'}`}
             >
                <div className={`w-2 h-2 rounded-full ${settings.enabled ? 'bg-white animate-pulse' : 'bg-current'}`}></div>
                {settings.enabled ? 'Motor Ligado' : 'Motor Desligado'}
             </button>
             <button onClick={onClose} className="w-10 h-10 rounded-full bg-theme-panel hover:bg-red-500 hover:text-white text-theme-main transition-all flex items-center justify-center shadow-lg"><i className="fas fa-times"></i></button>
          </div>

          <div className="space-y-8">
            {/* SELETOR DE FORMA GLOBAL */}
            <div className="space-y-3 bg-theme-panel/20 p-4 rounded-2xl border border-theme/50">
              <label className="text-[9px] font-black uppercase opacity-40 tracking-widest flex items-center gap-2">
                <i className="fas fa-shapes text-theme-accent"></i> Forma da Estampa
              </label>
              <div className="grid grid-cols-6 gap-2">
                {shapes.map(s => (
                  <button 
                    key={s.id} onClick={() => onUpdate({ ...settings, shapeType: s.id })}
                    className={`h-12 rounded-xl border flex items-center justify-center text-lg transition-all ${settings.shapeType === s.id ? 'bg-theme-accent text-white border-theme-accent shadow-lg scale-105' : 'bg-theme-panel border-theme opacity-30 hover:opacity-100 hover:bg-theme-panel/50'}`}
                  >
                    <i className={`fas ${s.icon}`}></i>
                  </button>
                ))}
              </div>
            </div>

            {/* MOTOR 1: GRID PATTERN */}
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h4 className="text-[11px] font-black uppercase tracking-widest text-theme-accent">1. Grid Pattern Engine</h4>
                <button 
                  onClick={() => onUpdate({ ...settings, gridEnabled: !settings.gridEnabled })}
                  className={`w-8 h-4 rounded-full relative transition-all ${settings.gridEnabled ? 'bg-theme-accent' : 'bg-theme-panel'}`}
                >
                  <div className={`absolute top-0.5 w-3 h-3 rounded-full bg-white transition-all ${settings.gridEnabled ? 'right-0.5' : 'left-0.5'}`}></div>
                </button>
              </div>

              <div className={`grid grid-cols-2 gap-x-6 gap-y-4 transition-all ${!settings.gridEnabled && 'opacity-20 pointer-events-none grayscale'}`}>
                 {[
                   { label: 'Tamanho', key: 'size', min: 2, max: 150 },
                   { label: 'Espaço X', key: 'spacingX', min: 0, max: 100 },
                   { label: 'Espaço Y', key: 'spacingY', min: 0, max: 100 },
                   { label: 'Giro Indiv.', key: 'individualRotation', min: 0, max: 360 },
                   { label: 'Giro Global', key: 'globalRotation', min: 0, max: 360 },
                   { label: 'Offset X', key: 'offsetX', min: -500, max: 500 },
                 ].map(ctrl => (
                  <div key={ctrl.key} className="space-y-2">
                    <div className="flex justify-between items-center px-1">
                      <label className="text-[8px] font-black uppercase opacity-40">{ctrl.label}</label>
                      <span className="text-[9px] font-mono font-bold text-theme-accent">{(settings as any)[ctrl.key]}</span>
                    </div>
                    <input type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]} onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })} className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent" />
                  </div>
                 ))}
              </div>
            </div>

            {/* MOTOR 2: SCATTER ENGINE (O NOVO REPETIDOR DE BAIXO) */}
            <div className="space-y-4 pt-6 border-t border-theme/20">
              <div className="flex items-center justify-between">
                <h4 className="text-[11px] font-black uppercase tracking-widest text-theme-accent">2. Scatter Engine</h4>
                <button 
                  onClick={() => onUpdate({ ...settings, scatterEnabled: !settings.scatterEnabled })}
                  className={`w-8 h-4 rounded-full relative transition-all ${settings.scatterEnabled ? 'bg-theme-accent' : 'bg-theme-panel'}`}
                >
                  <div className={`absolute top-0.5 w-3 h-3 rounded-full bg-white transition-all ${settings.scatterEnabled ? 'right-0.5' : 'left-0.5'}`}></div>
                </button>
              </div>

              <div className={`grid grid-cols-2 gap-x-6 gap-y-4 transition-all ${!settings.scatterEnabled && 'opacity-20 pointer-events-none grayscale'}`}>
                 {[
                   { label: 'Tam. Scatter', key: 'scatterSize', min: 5, max: 150 },
                   { label: 'Densidade', key: 'scatterDensity', min: 4, max: 100 },
                   { label: 'Ajuste Raio', key: 'scatterRadiusOffset', min: -100, max: 200 },
                   { label: 'Giro Indiv.', key: 'scatterIndividualRotation', min: 0, max: 360 },
                 ].map(ctrl => (
                  <div key={ctrl.key} className="space-y-2">
                    <div className="flex justify-between items-center px-1">
                      <label className="text-[8px] font-black uppercase opacity-40">{ctrl.label}</label>
                      <span className="text-[9px] font-mono font-bold text-theme-accent">{(settings as any)[ctrl.key]}</span>
                    </div>
                    <input type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]} onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })} className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent" />
                  </div>
                 ))}
              </div>
            </div>

            {/* PALETA DE CORES */}
            <div className="flex gap-4 pt-6 border-t border-theme/20">
               <div className="flex-1 space-y-2">
                 <label className="text-[9px] font-black uppercase opacity-40 block text-center">Cor Formas</label>
                 <input type="color" value={settings.color} onChange={(e) => onUpdate({ ...settings, color: e.target.value })} className="w-full h-12 rounded-xl border border-theme p-1 bg-theme-panel cursor-pointer shadow-inner" />
               </div>
               <div className="flex-1 space-y-2">
                 <label className="text-[9px] font-black uppercase opacity-40 block text-center">Cor Fundo</label>
                 <input type="color" value={settings.bgColor} onChange={(e) => onUpdate({ ...settings, bgColor: e.target.value })} className="w-full h-12 rounded-xl border border-theme p-1 bg-theme-panel cursor-pointer shadow-inner" />
               </div>
            </div>
          </div>

          <button onClick={onClose} className="mt-8 w-full py-5 rounded-2xl bg-theme-accent text-white font-black uppercase text-[11px] tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3">
             <i className="fas fa-save"></i>
             Sincronizar Motores e Fechar
          </button>
        </div>
      </div>
    </div>
  );
};

