import React, { useState, useRef, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import SidebarAlphaEdge from '../components/SidebarAlphaEdge';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import AdvancedBorderModal from '../components/AdvancedBorderModal';
import { GridImage, AlphaEdgeSettings, AdvancedBorderSettings } from '../types';

const AlphaEdgeTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);

  const [settings, setSettings] = useState<AlphaEdgeSettings>({
    thickness: 15,
    softness: 2,
    opacity: 100,
    color: '#ffffff',
    padding: 150,
    advanced: {
      enabled: false,
      gridEnabled: true,
      scatterEnabled: false,
      shapeType: 'circle',
      size: 15,
      spacingX: 10,
      spacingY: 10,
      color: '#ffffff',
      bgColor: '#000000',
      individualRotation: 0,
      globalRotation: 0,
      offsetX: 0,
      offsetY: 0,
      scatterSize: 20,
      scatterDensity: 40,
      scatterRadiusOffset: 0,
      scatterIndividualRotation: 0
    }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      ctx.moveTo(0, s); ctx.bezierCurveTo(-s, 0, -s, -s, 0, -s); ctx.bezierCurveTo(s, -s, s, 0, 0, s);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const drawDualEngine = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    ctx.save();

    // 1. Grid Engine
    if (config.gridEnabled) {
      ctx.save();
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, w, h);
      ctx.translate(w / 2 + config.offsetX, h / 2 + config.offsetY);
      ctx.rotate((config.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = config.color;
      const stepX = config.size + config.spacingX;
      const stepY = config.size + config.spacingY;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save();
          ctx.translate(x, y);
          ctx.rotate((config.individualRotation * Math.PI) / 180);
          drawShape(ctx, config.shapeType, config.size);
          ctx.restore();
        }
      }
      ctx.restore();
    } else {
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, w, h);
    }

    // 2. Scatter Engine (Sobre o Grid)
    if (config.scatterEnabled) {
      ctx.save();
      ctx.fillStyle = config.color;
      const steps = config.scatterDensity;
      const radius = Math.max(w, h) / 3 + config.scatterRadiusOffset;
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2;
        const px = w / 2 + Math.cos(angle) * radius;
        const py = h / 2 + Math.sin(angle) * radius;
        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(angle + (config.scatterIndividualRotation * Math.PI) / 180);
        drawShape(ctx, config.shapeType, config.scatterSize);
        ctx.restore();
      }
      ctx.restore();
    }

    ctx.restore();
  };

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings) => {
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const pad = config.padding;
    canvas.width = img.width + (pad * 2);
    canvas.height = img.height + (pad * 2);

    // Silhueta para máscara
    const silCanvas = document.createElement('canvas');
    silCanvas.width = canvas.width;
    silCanvas.height = canvas.height;
    const sCtx = silCanvas.getContext('2d');
    if (!sCtx) return;

    sCtx.save();
    sCtx.translate(pad, pad);
    sCtx.drawImage(img, 0, 0);
    sCtx.globalCompositeOperation = 'source-in';
    sCtx.fillStyle = '#ffffff';
    sCtx.fillRect(-pad, -pad, canvas.width, canvas.height);
    sCtx.restore();

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Gerar a expansão
    if (config.thickness > 0) {
      const expansionCanvas = document.createElement('canvas');
      expansionCanvas.width = canvas.width;
      expansionCanvas.height = canvas.height;
      const eCtx = expansionCanvas.getContext('2d');
      if (eCtx) {
        const radius = config.thickness;
        eCtx.filter = `blur(${radius / 2}px)`; 
        for (let i = 0; i < 12; i++) {
          const angle = (i / 12) * Math.PI * 2;
          eCtx.drawImage(silCanvas, Math.cos(angle) * (radius/2), Math.sin(angle) * (radius/2));
        }
        eCtx.drawImage(silCanvas, 0, 0);
        const imgData = eCtx.getImageData(0, 0, canvas.width, canvas.height);
        const data = imgData.data;
        for (let i = 0; i < data.length; i += 4) if (data[i + 3] > 20) data[i + 3] = 255;
        eCtx.putImageData(imgData, 0, 0);

        ctx.save();
        ctx.globalAlpha = config.opacity / 100;
        if (config.softness > 0) ctx.filter = `blur(${config.softness}px)`;

        // Se avançado ativo, o padrão preenche a expansão
        if (config.advanced?.enabled) {
           const patternLayer = document.createElement('canvas');
           patternLayer.width = canvas.width;
           patternLayer.height = canvas.height;
           const pCtx = patternLayer.getContext('2d');
           if (pCtx) {
              drawDualEngine(pCtx, canvas.width, canvas.height, config.advanced);
              // Aplicar máscara da expansão no padrão
              pCtx.globalCompositeOperation = 'destination-in';
              pCtx.drawImage(expansionCanvas, 0, 0);
              ctx.drawImage(patternLayer, 0, 0);
           }
        } else {
           // Cor sólida padrão se avançado estiver desligado
           ctx.drawImage(expansionCanvas, 0, 0);
           ctx.globalCompositeOperation = 'source-in';
           ctx.fillStyle = config.color;
           ctx.fillRect(0, 0, canvas.width, canvas.height);
        }
        ctx.restore();
      }
    }

    // Imagem original no topo
    ctx.save();
    ctx.translate(pad, pad);
    ctx.drawImage(img, 0, 0);
    ctx.restore();
  }, []);

  useEffect(() => {
    const updatePreview = async () => {
      if (!previewCanvasRef.current || !images[selectedIdx]) return;
      const img = new Image();
      img.src = images[selectedIdx].previewUrl;
      img.onload = () => drawEdge(img, previewCanvasRef.current!, settings);
    };
    updatePreview();
  }, [selectedIdx, images, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = [];
    for (const file of files) {
      const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const i = new Image();
        i.onload = () => resolve(i);
        i.src = url;
      });
      newImgs.push({ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height, isActive: true });
    }
    setImages(prev => [...prev, ...newImgs]);
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i];
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl;
      });
      await drawEdge(img, canvas, settings);
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a'); link.download = `${item.file.name.split('.')[0]}_miau.png`; link.href = dataUrl; link.click();
      await new Promise(r => setTimeout(r, 400));
    }
    setIsProcessing(false);
  };

  const currentImg = images[selectedIdx];

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={setSettings}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onOpenAdvanced={() => setIsModalOpen(true)}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-lg"
                style={{ 
                  width: (currentImg.width + settings.padding * 2) * zoom,
                  height: (currentImg.height + settings.padding * 2) * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <canvas ref={previewCanvasRef} className="w-full h-full block" />
              </div>

              <div className="absolute bottom-24 left-8 flex flex-col items-start gap-4 z-40 pointer-events-none">
                <div className="flex items-center gap-3 bg-theme-side/90 border border-theme/40 px-4 py-2 rounded-full shadow-2xl backdrop-blur-3xl">
                   <div className="flex items-center gap-1.5 bg-theme-accent text-white px-2 py-1 rounded-full border border-white/10">
                      <i className="fas fa-wand-magic-sparkles text-[8px]"></i>
                      <span className="text-[8px] font-black uppercase">Alpha Pro</span>
                   </div>
                   <div className="flex items-center gap-3">
                      <div className="flex flex-col leading-none">
                        <span className="text-[6px] font-black uppercase opacity-30">Expansion</span>
                        <span className="text-[10px] font-mono font-black text-theme-accent">+{settings.thickness}px</span>
                      </div>
                      {settings.advanced?.enabled && (
                        <>
                          <div className="w-[1px] h-4 bg-theme/30"></div>
                          <div className="flex flex-col leading-none">
                            <span className="text-[6px] font-black uppercase opacity-30">Dual Engine</span>
                            <span className="text-[10px] font-mono font-black text-theme-accent">Active</span>
                          </div>
                        </>
                      )}
                   </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Alpha Edge Master</p>
            </div>
          )}

          {currentImg && (
            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-6 py-2 rounded-full shadow-2xl backdrop-blur-md z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-24 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[9px] font-mono opacity-40 w-8">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-4">
                <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(prev => prev - 1)} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10"><i className="fas fa-chevron-left text-[9px]"></i></button>
                <span className="text-[10px] font-mono font-black text-theme-accent min-w-[50px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(prev => prev + 1)} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10"><i className="fas fa-chevron-right text-[9px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <div className="p-4 border-b border-theme font-black text-[10px] uppercase text-theme-muted bg-black/5 flex justify-between items-center">
          <span>Gerenciador Alpha</span>
          <span className="text-[9px] bg-theme-accent/20 text-theme-accent px-2 py-0.5 rounded">{images.length}</span>
        </div>
        <ImageList 
          images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} onToggleActive={(id) => setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img))} 
        />
      </aside>

      <AdvancedBorderModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}
        settings={settings.advanced!} onUpdate={(adv) => setSettings({ ...settings, advanced: adv })}
        baseImageUrl={currentImg?.previewUrl || null}
      />
      <input type="file" multiple accept="image/png, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

