import React, { useRef, useEffect, useState, useMemo } from 'react';
import { AdvancedBorderSettings } from '../types';

interface AdvancedBorderModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: AdvancedBorderSettings;
  onUpdate: (s: AdvancedBorderSettings) => void;
  baseImage: { url: string, width: number, height: number } | null;
}

const AdvancedBorderModal: React.FC<AdvancedBorderModalProps> = ({ isOpen, onClose, settings, onUpdate, baseImage }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [guideImg, setGuideImg] = useState<HTMLImageElement | null>(null);
  const [customShapeImg, setCustomShapeImg] = useState<HTMLImageElement | null>(null);

  // Sistema de Delta Drag (Ajuste Fino)
  const [isDeltaDragging, setIsDeltaDragging] = useState<string | null>(null);
  const deltaRef = useRef({ startX: 0, initialValue: 0 });

  const previewScale = useMemo(() => {
    if (!baseImage) return 1;
    return 520 / Math.max(baseImage.width, baseImage.height);
  }, [baseImage]);

  const shapes: { id: AdvancedBorderSettings['shapeType'], icon: string }[] = [
    { id: 'circle', icon: 'fa-circle' },
    { id: 'square', icon: 'fa-square' },
    { id: 'triangle', icon: 'fa-caret-up' },
    { id: 'x', icon: 'fa-times' },
    { id: 'heart', icon: 'fa-heart' },
    { id: 'diamond', icon: 'fa-clone' },
    { id: 'custom', icon: 'fa-upload' }
  ];

  useEffect(() => {
    if (baseImage?.url) {
      const img = new Image(); img.src = baseImage.url;
      img.onload = () => setGuideImg(img);
    }
  }, [baseImage?.url]);

  useEffect(() => {
    if (settings.customShapeUrl) {
      const img = new Image(); img.src = settings.customShapeUrl;
      img.onload = () => setCustomShapeImg(img);
    }
  }, [settings.customShapeUrl]);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    if (type === 'custom' && customShapeImg) {
      ctx.drawImage(customShapeImg, -s, -s, size, size);
      return;
    }
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      // Coração Melhorado
      ctx.moveTo(0, s * 0.6);
      ctx.bezierCurveTo(-s * 1.1, -s * 0.4, -s * 0.5, -s * 1.2, 0, -s * 0.4);
      ctx.bezierCurveTo(s * 0.5, -s * 1.2, s * 1.1, -s * 0.4, 0, s * 0.6);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const renderPreview = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const w = 520, h = 520;
    canvas.width = w; canvas.height = h;
    const s = previewScale;
    ctx.clearRect(0, 0, w, h);

    if (settings.gridEnabled) {
      ctx.save();
      ctx.fillStyle = settings.bgColor;
      ctx.fillRect(0, 0, w, h);
      ctx.translate(w / 2 + (settings.offsetX * s), h / 2 + (settings.offsetY * s));
      ctx.rotate((settings.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = settings.color;
      const stepX = (settings.size + settings.spacingX) * s;
      const stepY = (settings.size + settings.spacingY) * s;
      const drawSize = settings.size * s;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save(); ctx.translate(x, y); ctx.rotate((settings.individualRotation * Math.PI) / 180);
          drawShape(ctx, settings.shapeType, drawSize); ctx.restore();
        }
      }
      ctx.restore();
    } else {
      ctx.fillStyle = settings.bgColor; ctx.fillRect(0, 0, w, h);
    }

    if (settings.scatterEnabled) {
      ctx.save();
      ctx.fillStyle = settings.color;
      const steps = settings.scatterDensity;
      const baseRadius = Math.min(w, h) * 0.35;
      const radius = baseRadius + (settings.scatterRadiusOffset * s);
      const drawSize = settings.scatterSize * s;
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2;
        const px = w / 2 + Math.cos(angle) * radius;
        const py = h / 2 + Math.sin(angle) * radius;
        ctx.save(); ctx.translate(px, py); ctx.rotate(angle + (settings.scatterIndividualRotation * Math.PI) / 180);
        drawShape(ctx, settings.shapeType, drawSize); ctx.restore();
      }
      ctx.restore();
    }

    if (guideImg) {
      ctx.save(); ctx.globalAlpha = 0.4;
      const ratio = Math.min(350 / guideImg.width, 350 / guideImg.height);
      const dw = guideImg.width * ratio, dh = guideImg.height * ratio;
      ctx.drawImage(guideImg, (w - dw) / 2, (h - dh) / 2, dw, dh); ctx.restore();
    }
  };

  useEffect(() => { if (isOpen) renderPreview(); }, [isOpen, settings, guideImg, customShapeImg, previewScale]);

  // Lógica de Delta Drag
  const onDeltaStart = (e: React.MouseEvent, key: string, initial: number) => {
    e.preventDefault();
    setIsDeltaDragging(key);
    deltaRef.current = { startX: e.clientX, initialValue: initial };
    document.body.style.cursor = 'none';
  };

  useEffect(() => {
    if (!isDeltaDragging) return;
    const handleMove = (e: MouseEvent) => {
      const delta = e.clientX - deltaRef.current.startX;
      const sensitivity = 1;
      const newValue = deltaRef.current.initialValue + (delta * sensitivity);
      onUpdate({ ...settings, [isDeltaDragging]: Math.round(newValue) });
    };
    const handleUp = () => {
      setIsDeltaDragging(null);
      document.body.style.cursor = 'default';
    };
    window.addEventListener('mousemove', handleMove);
    window.addEventListener('mouseup', handleUp);
    return () => { window.removeEventListener('mousemove', handleMove); window.removeEventListener('mouseup', handleUp); };
  }, [isDeltaDragging, settings]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 backdrop-blur-xl bg-black/60">
      <div className="bg-theme-side border border-theme w-full max-w-6xl rounded-[3rem] shadow-2xl flex overflow-hidden h-[90vh]">
        <div className="flex-1 bg-black/20 flex flex-col items-center justify-center relative p-10 border-r border-theme/30">
           <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-theme-accent flex items-center justify-center text-white shadow-lg rotate-3">
                <i className="fas fa-magic"></i>
              </div>
              <div className="flex flex-col leading-none">
                <span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-40">Estúdio de Estampas</span>
                <span className="text-xl font-black tracking-tighter uppercase">Alpha Dual Engine</span>
              </div>
           </div>
           <div className="relative rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white/5 bg-theme-panel/20 p-2">
              <canvas ref={canvasRef} className="block rounded-[2rem]" />
           </div>
        </div>

        <div className="w-[440px] p-8 flex flex-col gap-6 overflow-y-auto bg-theme-side custom-scrollbar">
          <div className="flex justify-between items-center">
             <h3 className="text-xs font-black uppercase tracking-widest text-theme-accent">Configurações Avançadas</h3>
             <button onClick={onClose} className="w-8 h-8 rounded-full bg-theme-panel flex items-center justify-center hover:bg-red-500 hover:text-white transition-all"><i className="fas fa-times"></i></button>
          </div>

          <div className="space-y-3 bg-theme-panel/20 p-4 rounded-2xl border border-theme/50">
            <label className="text-[9px] font-black uppercase opacity-40 tracking-widest">Formato da Estampa</label>
            <div className="grid grid-cols-7 gap-2">
              {shapes.map(s => (
                <button key={s.id} onClick={() => s.id === 'custom' ? fileInputRef.current?.click() : onUpdate({ ...settings, shapeType: s.id })} 
                  className={`h-10 rounded-xl border flex items-center justify-center text-sm transition-all ${settings.shapeType === s.id ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-panel border-theme opacity-30 hover:opacity-100'}`}>
                  <i className={`fas ${s.icon}`}></i>
                </button>
              ))}
            </div>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/png" onChange={(e) => {
              if (e.target.files?.[0]) {
                const url = URL.createObjectURL(e.target.files[0]);
                onUpdate({ ...settings, shapeType: 'custom', customShapeUrl: url });
              }
            }} />
          </div>

          {/* ENGINE 1: GRID */}
          <div className="space-y-4 p-4 rounded-2xl bg-theme-panel/10 border border-theme/20">
            <div className="flex items-center justify-between">
              <h4 className="text-[10px] font-black uppercase tracking-widest text-theme-main">1. Grid Engine</h4>
              <button onClick={() => onUpdate({ ...settings, gridEnabled: !settings.gridEnabled })} className={`w-10 h-5 rounded-full relative transition-all ${settings.gridEnabled ? 'bg-theme-accent' : 'bg-theme-panel'}`}>
                 <div className={`absolute top-1 w-3 h-3 rounded-full bg-white transition-all ${settings.gridEnabled ? 'right-1' : 'left-1'}`}></div>
              </button>
            </div>
            <div className={`grid grid-cols-2 gap-4 ${!settings.gridEnabled && 'opacity-20 pointer-events-none'}`}>
               {[
                 { label: 'Tamanho', key: 'size', min: 2, max: 200 },
                 { label: 'Espaço X', key: 'spacingX', min: 0, max: 200 },
                 { label: 'Espaço Y', key: 'spacingY', min: 0, max: 200 },
                 { label: 'Giro Ind.', key: 'individualRotation', min: 0, max: 360 },
                 { label: 'Offset X', key: 'offsetX', min: -1000, max: 1000 },
                 { label: 'Offset Y', key: 'offsetY', min: -1000, max: 1000 },
               ].map(ctrl => (
                <div key={ctrl.key} className="space-y-1">
                  <div className="flex justify-between items-center cursor-ew-resize" onMouseDown={(e) => onDeltaStart(e, ctrl.key, (settings as any)[ctrl.key])}>
                    <label className="text-[8px] font-black uppercase opacity-40">{ctrl.label}</label>
                    <span className="text-[9px] font-mono font-bold text-theme-accent">{(settings as any)[ctrl.key]}</span>
                  </div>
                  <input type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]} onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })} className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent" />
                </div>
               ))}
            </div>
          </div>

          {/* ENGINE 2: SCATTER */}
          <div className="space-y-4 p-4 rounded-2xl bg-theme-panel/10 border border-theme/20">
            <div className="flex items-center justify-between">
              <h4 className="text-[10px] font-black uppercase tracking-widest text-theme-main">2. Scatter Engine</h4>
              <button onClick={() => onUpdate({ ...settings, scatterEnabled: !settings.scatterEnabled })} className={`w-10 h-5 rounded-full relative transition-all ${settings.scatterEnabled ? 'bg-theme-accent' : 'bg-theme-panel'}`}>
                 <div className={`absolute top-1 w-3 h-3 rounded-full bg-white transition-all ${settings.scatterEnabled ? 'right-1' : 'left-1'}`}></div>
              </button>
            </div>
            <div className={`grid grid-cols-2 gap-4 ${!settings.scatterEnabled && 'opacity-20 pointer-events-none'}`}>
               {[
                 { label: 'Tamanho', key: 'scatterSize', min: 2, max: 200 },
                 { label: 'Densidade', key: 'scatterDensity', min: 4, max: 100 },
                 { label: 'Ajuste Raio', key: 'scatterRadiusOffset', min: -500, max: 500 },
                 { label: 'Giro Ind.', key: 'scatterIndividualRotation', min: 0, max: 360 },
               ].map(ctrl => (
                <div key={ctrl.key} className="space-y-1">
                  <div className="flex justify-between items-center cursor-ew-resize" onMouseDown={(e) => onDeltaStart(e, ctrl.key, (settings as any)[ctrl.key])}>
                    <label className="text-[8px] font-black uppercase opacity-40">{ctrl.label}</label>
                    <span className="text-[9px] font-mono font-bold text-theme-accent">{(settings as any)[ctrl.key]}</span>
                  </div>
                  <input type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]} onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })} className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent" />
                </div>
               ))}
            </div>
          </div>

          <div className="flex gap-4 p-4 bg-theme-panel/5 border border-theme/20 rounded-2xl">
             <div className="flex-1 space-y-1">
               <label className="text-[8px] font-black uppercase opacity-40 block">Cor Estampa</label>
               <input type="color" value={settings.color} onChange={(e) => onUpdate({ ...settings, color: e.target.value })} className="w-full h-8 rounded-lg cursor-pointer bg-theme-panel border-none" />
             </div>
             <div className="flex-1 space-y-1">
               <label className="text-[8px] font-black uppercase opacity-40 block">Cor Fundo</label>
               <input type="color" value={settings.bgColor} onChange={(e) => onUpdate({ ...settings, bgColor: e.target.value })} className="w-full h-8 rounded-lg cursor-pointer bg-theme-panel border-none" />
             </div>
          </div>

          <button onClick={onClose} className="w-full py-4 rounded-2xl bg-theme-accent text-white font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Sincronizar Engines</button>
        </div>
      </div>
    </div>
  );
};

export default AdvancedBorderModal;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import SidebarAlphaEdge from '../components/SidebarAlphaEdge';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import AdvancedBorderModal from '../components/AdvancedBorderModal';
import { GridImage, AlphaEdgeSettings, AdvancedBorderSettings } from '../types';

const AlphaEdgeTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [customShapeImg, setCustomShapeImg] = useState<HTMLImageElement | null>(null);

  const [settings, setSettings] = useState<AlphaEdgeSettings>({
    thickness: 15,
    softness: 2,
    opacity: 100,
    color: '#ffffff',
    advanced: {
      enabled: false,
      gridEnabled: true,
      scatterEnabled: false,
      shapeType: 'circle',
      size: 15,
      spacingX: 10,
      spacingY: 10,
      color: '#ffffff',
      bgColor: '#000000',
      individualRotation: 0,
      globalRotation: 0,
      offsetX: 0,
      offsetY: 0,
      scatterSize: 20,
      scatterDensity: 40,
      scatterRadiusOffset: 0,
      scatterIndividualRotation: 0
    }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (settings.advanced?.customShapeUrl) {
      const img = new Image(); img.src = settings.advanced.customShapeUrl;
      img.onload = () => setCustomShapeImg(img);
    }
  }, [settings.advanced?.customShapeUrl]);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    if (type === 'custom' && customShapeImg) {
      ctx.drawImage(customShapeImg, -s, -s, size, size);
      return;
    }
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      ctx.moveTo(0, s * 0.6);
      ctx.bezierCurveTo(-s * 1.1, -s * 0.4, -s * 0.5, -s * 1.2, 0, -s * 0.4);
      ctx.bezierCurveTo(s * 0.5, -s * 1.2, s * 1.1, -s * 0.4, 0, s * 0.6);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const drawDualEngine = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    ctx.save();
    if (config.gridEnabled) {
      ctx.save();
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, w, h);
      ctx.translate(w / 2 + config.offsetX, h / 2 + config.offsetY);
      ctx.rotate((config.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = config.color;
      const stepX = config.size + config.spacingX;
      const stepY = config.size + config.spacingY;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save(); ctx.translate(x, y); ctx.rotate((config.individualRotation * Math.PI) / 180);
          drawShape(ctx, config.shapeType, config.size); ctx.restore();
        }
      }
      ctx.restore();
    } else {
      ctx.fillStyle = config.bgColor; ctx.fillRect(0, 0, w, h);
    }

    if (config.scatterEnabled) {
      ctx.save();
      ctx.fillStyle = config.color;
      const steps = config.scatterDensity;
      const baseRadius = Math.min(w, h) * 0.35;
      const radius = baseRadius + config.scatterRadiusOffset;
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2;
        const px = w / 2 + Math.cos(angle) * radius;
        const py = h / 2 + Math.sin(angle) * radius;
        ctx.save(); ctx.translate(px, py); ctx.rotate(angle + (config.scatterIndividualRotation * Math.PI) / 180);
        drawShape(ctx, config.shapeType, config.scatterSize); ctx.restore();
      }
      ctx.restore();
    }
    ctx.restore();
  };

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings) => {
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const safePadding = config.thickness + config.softness + 30;
    canvas.width = img.width + (safePadding * 2);
    canvas.height = img.height + (safePadding * 2);

    const silCanvas = document.createElement('canvas');
    silCanvas.width = canvas.width; silCanvas.height = canvas.height;
    const sCtx = silCanvas.getContext('2d');
    if (!sCtx) return;

    sCtx.save();
    sCtx.translate(safePadding, safePadding);
    sCtx.drawImage(img, 0, 0);
    sCtx.globalCompositeOperation = 'source-in';
    sCtx.fillStyle = '#ffffff';
    sCtx.fillRect(-safePadding, -safePadding, canvas.width, canvas.height);
    sCtx.restore();

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (config.thickness > 0) {
      const expansionCanvas = document.createElement('canvas');
      expansionCanvas.width = canvas.width; expansionCanvas.height = canvas.height;
      const eCtx = expansionCanvas.getContext('2d');
      if (eCtx) {
        const radius = config.thickness;
        eCtx.filter = `blur(${radius / 2.5}px)`; 
        for (let i = 0; i < 16; i++) {
          const angle = (i / 16) * Math.PI * 2;
          eCtx.drawImage(silCanvas, Math.cos(angle) * (radius/2), Math.sin(angle) * (radius/2));
        }
        eCtx.drawImage(silCanvas, 0, 0);
        const imgData = eCtx.getImageData(0, 0, canvas.width, canvas.height);
        const data = imgData.data;
        for (let i = 0; i < data.length; i += 4) if (data[i + 3] > 10) data[i + 3] = 255;
        eCtx.putImageData(imgData, 0, 0);

        // 1. LAYER DE GLOW (Borda da Borda)
        if (config.softness > 0) {
          ctx.save();
          ctx.globalAlpha = (config.opacity / 100) * 0.6;
          ctx.filter = `blur(${config.softness}px)`;
          ctx.drawImage(expansionCanvas, 0, 0);
          ctx.globalCompositeOperation = 'source-in';
          ctx.fillStyle = config.color;
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.restore();
        }

        // 2. LAYER DE ESTAMPA (Sharp - Cortada pela expansão nítida)
        ctx.save();
        ctx.globalAlpha = config.opacity / 100;
        const patternLayer = document.createElement('canvas');
        patternLayer.width = canvas.width; patternLayer.height = canvas.height;
        const pCtx = patternLayer.getContext('2d');
        if (pCtx) {
           if (config.advanced?.enabled) {
              drawDualEngine(pCtx, canvas.width, canvas.height, config.advanced);
           } else {
              pCtx.fillStyle = config.color;
              pCtx.fillRect(0, 0, canvas.width, canvas.height);
           }
           pCtx.globalCompositeOperation = 'destination-in';
           pCtx.drawImage(expansionCanvas, 0, 0);
           ctx.drawImage(patternLayer, 0, 0);
        }
        ctx.restore();
      }
    }

    ctx.save();
    ctx.translate(safePadding, safePadding);
    ctx.drawImage(img, 0, 0);
    ctx.restore();
  }, [customShapeImg]);

  useEffect(() => {
    const updatePreview = async () => {
      if (!previewCanvasRef.current || !images[selectedIdx]) return;
      const img = new Image();
      img.src = images[selectedIdx].previewUrl;
      img.onload = () => drawEdge(img, previewCanvasRef.current!, settings);
    };
    updatePreview();
  }, [selectedIdx, images, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = [];
    for (const file of files) {
      const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const i = new Image();
        i.onload = () => resolve(i);
        i.src = url;
      });
      newImgs.push({ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height, isActive: true });
    }
    setImages(prev => [...prev, ...newImgs]);
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i];
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl;
      });
      await drawEdge(img, canvas, settings);
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a'); link.download = `${item.file.name.split('.')[0]}_miau.png`; link.href = dataUrl; link.click();
      await new Promise(r => setTimeout(r, 400));
    }
    setIsProcessing(false);
  };

  const currentImg = images[selectedIdx];

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={setSettings}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onOpenAdvanced={() => setIsModalOpen(true)}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />
        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-lg"
                style={{ 
                  width: (currentImg.width + (settings.thickness + settings.softness + 30) * 2) * zoom,
                  height: (currentImg.height + (settings.thickness + settings.softness + 30) * 2) * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <canvas ref={previewCanvasRef} className="w-full h-full block" />
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Alpha Edge Pro</p>
            </div>
          )}
          {currentImg && (
            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-6 py-2 rounded-full shadow-2xl backdrop-blur-md z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-24 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[9px] font-mono opacity-40 w-8">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-4">
                <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(prev => prev - 1)} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10"><i className="fas fa-chevron-left text-[9px]"></i></button>
                <span className="text-[10px] font-mono font-black text-theme-accent min-w-[50px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(prev => prev + 1)} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10"><i className="fas fa-chevron-right text-[9px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <ImageList 
          images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} onToggleActive={(id) => setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img))} 
        />
      </aside>

      <AdvancedBorderModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}
        settings={settings.advanced!} onUpdate={(adv) => setSettings({ ...settings, advanced: adv })}
        baseImage={currentImg ? { url: currentImg.previewUrl, width: currentImg.width, height: currentImg.height } : null}
      />
      <input type="file" multiple accept="image/png, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default AlphaEdgeTool;

export interface GridImage {
  id: string;
  file: File;
  previewUrl: string;
  width: number;
  height: number;
  aspectRatio: number;
  isActive?: boolean;
  visible?: boolean;
  x?: number;
  y?: number;
  scale?: number;
  rotation?: number;
}

export interface GridSettings {
  canvasWidth: number;
  canvasHeight: number;
  columns: number;
  innerSpacing: number;
  outerMargin: number;
  backgroundColor: string;
  isTransparent: boolean;
  layoutMode: 'grid' | 'auto';
  itemScale: number;
  targetShape: 'square' | 'portrait' | 'landscape';
}

export interface AdvancedBorderSettings {
  enabled: boolean;
  gridEnabled: boolean;
  scatterEnabled: boolean;
  shapeType: 'circle' | 'square' | 'triangle' | 'x' | 'heart' | 'diamond' | 'custom';
  customShapeUrl?: string;
  size: number;
  spacingX: number;
  spacingY: number;
  color: string;
  bgColor: string;
  individualRotation: number;
  globalRotation: number;
  offsetX: number;
  offsetY: number;
  scatterSize: number;
  scatterDensity: number;
  scatterRadiusOffset: number;
  scatterIndividualRotation: number;
}

export interface AlphaEdgeSettings {
  thickness: number;
  softness: number;
  opacity: number;
  color: string;
  advanced?: AdvancedBorderSettings;
}

export interface FrameSettings {
  borderWidth: number;
  borderColor: string;
  borderRadius: number;
  padding: number;
  shadow: number;
  canvasWidth: number;
  canvasHeight: number;
  frameImageUrl?: string;
  frameImageName?: string;
}

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { AdvancedBorderSettings } from '../types';

interface AdvancedBorderModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: AdvancedBorderSettings;
  onUpdate: (s: AdvancedBorderSettings) => void;
  baseImage: { url: string, width: number, height: number } | null;
}

const AdvancedBorderModal: React.FC<AdvancedBorderModalProps> = ({ isOpen, onClose, settings, onUpdate, baseImage }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [guideImg, setGuideImg] = useState<HTMLImageElement | null>(null);
  const [customShapeImg, setCustomShapeImg] = useState<HTMLImageElement | null>(null);

  const [isDeltaDragging, setIsDeltaDragging] = useState<string | null>(null);
  const deltaRef = useRef({ startX: 0, initialValue: 0 });

  const previewScale = useMemo(() => {
    if (!baseImage) return 1;
    return 520 / Math.max(baseImage.width, baseImage.height);
  }, [baseImage]);

  const shapes: { id: AdvancedBorderSettings['shapeType'], icon: string }[] = [
    { id: 'circle', icon: 'fa-circle' },
    { id: 'square', icon: 'fa-square' },
    { id: 'triangle', icon: 'fa-caret-up' },
    { id: 'x', icon: 'fa-times' },
    { id: 'heart', icon: 'fa-heart' },
    { id: 'diamond', icon: 'fa-clone' },
    { id: 'custom', icon: 'fa-image' }
  ];

  useEffect(() => {
    if (baseImage?.url) {
      const img = new Image(); img.src = baseImage.url;
      img.onload = () => setGuideImg(img);
    }
  }, [baseImage?.url]);

  useEffect(() => {
    if (settings.customShapeUrl) {
      const img = new Image(); img.src = settings.customShapeUrl;
      img.onload = () => setCustomShapeImg(img);
    }
  }, [settings.customShapeUrl]);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    if (type === 'custom' && customShapeImg) {
      ctx.drawImage(customShapeImg, -s, -s, size, size);
      return;
    }
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      // Coração Perfeito (Gordinho)
      ctx.moveTo(0, s * 0.7);
      ctx.bezierCurveTo(-s * 1.5, -s * 0.5, -s * 0.7, -s * 1.5, 0, -s * 0.5);
      ctx.bezierCurveTo(s * 0.7, -s * 1.5, s * 1.5, -s * 0.5, 0, s * 0.7);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const renderPreview = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const w = 520, h = 520;
    canvas.width = w; canvas.height = h;
    const s = previewScale;
    ctx.clearRect(0, 0, w, h);

    if (settings.gridEnabled) {
      ctx.save();
      ctx.fillStyle = settings.bgColor;
      ctx.fillRect(0, 0, w, h);
      ctx.translate(w / 2 + (settings.offsetX * s), h / 2 + (settings.offsetY * s));
      ctx.rotate((settings.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = settings.color;
      const stepX = (settings.size + settings.spacingX) * s;
      const stepY = (settings.size + settings.spacingY) * s;
      const drawSize = settings.size * s;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save(); ctx.translate(x, y); ctx.rotate((settings.individualRotation * Math.PI) / 180);
          drawShape(ctx, settings.shapeType, drawSize); ctx.restore();
        }
      }
      ctx.restore();
    } else {
      ctx.fillStyle = settings.bgColor; ctx.fillRect(0, 0, w, h);
    }

    if (settings.scatterEnabled) {
      ctx.save();
      ctx.fillStyle = settings.color;
      const steps = settings.scatterDensity;
      const radius = (Math.min(w, h) * 0.35) + (settings.scatterRadiusOffset * s);
      const drawSize = settings.scatterSize * s;
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2;
        const px = w / 2 + Math.cos(angle) * radius;
        const py = h / 2 + Math.sin(angle) * radius;
        ctx.save(); ctx.translate(px, py); ctx.rotate(angle + (settings.scatterIndividualRotation * Math.PI) / 180);
        drawShape(ctx, settings.shapeType, drawSize); ctx.restore();
      }
      ctx.restore();
    }

    if (guideImg) {
      ctx.save(); ctx.globalAlpha = 0.4;
      const ratio = Math.min(350 / guideImg.width, 350 / guideImg.height);
      const dw = guideImg.width * ratio, dh = guideImg.height * ratio;
      ctx.drawImage(guideImg, (w - dw) / 2, (h - dh) / 2, dw, dh); ctx.restore();
    }
  };

  useEffect(() => { if (isOpen) renderPreview(); }, [isOpen, settings, guideImg, customShapeImg, previewScale]);

  const onDeltaStart = (e: React.MouseEvent, key: string, initial: number) => {
    e.preventDefault();
    setIsDeltaDragging(key);
    deltaRef.current = { startX: e.clientX, initialValue: initial };
    document.body.style.cursor = 'none';
  };

  useEffect(() => {
    if (!isDeltaDragging) return;
    const handleMove = (e: MouseEvent) => {
      const delta = e.clientX - deltaRef.current.startX;
      const newValue = deltaRef.current.initialValue + delta;
      onUpdate({ ...settings, [isDeltaDragging]: Math.round(newValue) });
    };
    const handleUp = () => {
      setIsDeltaDragging(null);
      document.body.style.cursor = 'default';
    };
    window.addEventListener('mousemove', handleMove);
    window.addEventListener('mouseup', handleUp);
    return () => { window.removeEventListener('mousemove', handleMove); window.removeEventListener('mouseup', handleUp); };
  }, [isDeltaDragging, settings]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 backdrop-blur-2xl bg-black/70 animate-in fade-in duration-300">
      <div className="bg-theme-side border border-theme w-full max-w-6xl rounded-[3.5rem] shadow-2xl flex overflow-hidden h-[90vh]">

        {/* VIEWPORT */}
        <div className="flex-1 bg-black/30 flex flex-col items-center justify-center relative p-10 border-r border-theme/30">
           <div className="absolute top-10 left-10 flex items-center gap-4">
              <div className="w-12 h-12 rounded-3xl bg-theme-accent flex items-center justify-center text-white shadow-xl rotate-6 animate-pulse">
                <i className="fas fa-brush"></i>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] font-black uppercase tracking-[0.4em] opacity-40">Design Studio</span>
                <span className="text-2xl font-black tracking-tighter uppercase">Pattern Engine v3</span>
              </div>
           </div>

           <div className="relative rounded-[3rem] overflow-hidden shadow-[0_0_100px_rgba(0,0,0,0.5)] border-8 border-white/5 bg-theme-panel/20 p-2">
              <canvas ref={canvasRef} className="block rounded-[2.5rem]" />
           </div>
        </div>

        {/* CONTROLS */}
        <div className="w-[480px] p-10 flex flex-col gap-8 overflow-y-auto bg-theme-side custom-scrollbar">
          <div className="flex justify-between items-center">
             <button 
                onClick={() => onUpdate({ ...settings, enabled: !settings.enabled })}
                className={`flex items-center gap-3 px-6 py-3 rounded-full font-black text-[11px] uppercase tracking-widest transition-all ${settings.enabled ? 'bg-theme-accent text-white shadow-lg' : 'bg-theme-panel border border-theme opacity-50'}`}
             >
                <i className={`fas ${settings.enabled ? 'fa-check-circle' : 'fa-power-off'}`}></i>
                {settings.enabled ? 'Estampa Ativada' : 'Ativar Estampa'}
             </button>
             <button onClick={onClose} className="w-10 h-10 rounded-full bg-theme-panel hover:bg-red-500 hover:text-white transition-all flex items-center justify-center"><i className="fas fa-times"></i></button>
          </div>

          <div className="space-y-4">
            <label className="text-[10px] font-black uppercase opacity-40 tracking-widest flex items-center justify-between">
               <span>Formas & Carimbos</span>
               {settings.shapeType === 'custom' && <span className="text-theme-accent">PNG Personalizado</span>}
            </label>
            <div className="grid grid-cols-7 gap-2">
              {shapes.map(s => (
                <button key={s.id} onClick={() => onUpdate({ ...settings, shapeType: s.id })} 
                  className={`h-12 rounded-2xl border flex items-center justify-center text-lg transition-all ${settings.shapeType === s.id ? 'bg-theme-accent text-white border-theme-accent shadow-lg scale-110 z-10' : 'bg-theme-panel border-theme opacity-30 hover:opacity-100'}`}>
                  <i className={`fas ${s.icon}`}></i>
                </button>
              ))}
            </div>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full py-4 rounded-2xl border border-dashed border-theme hover:border-theme-accent hover:bg-theme-accent/5 transition-all flex items-center justify-center gap-3 text-[10px] font-black uppercase tracking-widest opacity-60 hover:opacity-100"
            >
              <i className="fas fa-upload"></i> Importar PNG para Estampa
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/png" onChange={(e) => {
              if (e.target.files?.[0]) {
                const url = URL.createObjectURL(e.target.files[0]);
                onUpdate({ ...settings, shapeType: 'custom', customShapeUrl: url });
              }
            }} />
          </div>

          {/* ENGINE 1 */}
          <div className="p-6 rounded-[2rem] bg-theme-panel/10 border border-theme/20 space-y-6">
            <div className="flex items-center justify-between">
               <h4 className="text-[11px] font-black uppercase tracking-widest text-theme-main">1. Grid Engine</h4>
               <button onClick={() => onUpdate({ ...settings, gridEnabled: !settings.gridEnabled })} className={`w-12 h-6 rounded-full relative transition-all ${settings.gridEnabled ? 'bg-theme-accent' : 'bg-theme-panel border border-theme'}`}>
                  <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${settings.gridEnabled ? 'right-1' : 'left-1'}`}></div>
               </button>
            </div>
            <div className={`grid grid-cols-2 gap-x-8 gap-y-6 ${!settings.gridEnabled && 'opacity-20 pointer-events-none grayscale'}`}>
               {[
                 { label: 'Tamanho', key: 'size', min: 2, max: 200 },
                 { label: 'Espaço X', key: 'spacingX', min: 0, max: 200 },
                 { label: 'Espaço Y', key: 'spacingY', min: 0, max: 200 },
                 { label: 'Giro Unic.', key: 'individualRotation', min: 0, max: 360 },
                 { label: 'Offset X', key: 'offsetX', min: -1000, max: 1000 },
                 { label: 'Offset Y', key: 'offsetY', min: -1000, max: 1000 },
               ].map(ctrl => (
                <div key={ctrl.key} className="space-y-2">
                  <div className="flex justify-between items-center cursor-ew-resize group" onMouseDown={(e) => onDeltaStart(e, ctrl.key, (settings as any)[ctrl.key])}>
                    <label className="text-[9px] font-black uppercase opacity-40 group-hover:opacity-100 transition-opacity">{ctrl.label}</label>
                    <span className="text-[10px] font-mono font-black text-theme-accent bg-theme-accent/10 px-2 py-0.5 rounded">{(settings as any)[ctrl.key]}</span>
                  </div>
                  <input type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]} onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })} className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent" />
                </div>
               ))}
            </div>
          </div>

          {/* ENGINE 2 */}
          <div className="p-6 rounded-[2rem] bg-theme-panel/10 border border-theme/20 space-y-6">
            <div className="flex items-center justify-between">
               <h4 className="text-[11px] font-black uppercase tracking-widest text-theme-main">2. Scatter Engine</h4>
               <button onClick={() => onUpdate({ ...settings, scatterEnabled: !settings.scatterEnabled })} className={`w-12 h-6 rounded-full relative transition-all ${settings.scatterEnabled ? 'bg-theme-accent' : 'bg-theme-panel border border-theme'}`}>
                  <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${settings.scatterEnabled ? 'right-1' : 'left-1'}`}></div>
               </button>
            </div>
            <div className={`grid grid-cols-2 gap-x-8 gap-y-6 ${!settings.scatterEnabled && 'opacity-20 pointer-events-none grayscale'}`}>
               {[
                 { label: 'Tamanho', key: 'scatterSize', min: 2, max: 200 },
                 { label: 'Densidade', key: 'scatterDensity', min: 4, max: 100 },
                 { label: 'Raio Delta', key: 'scatterRadiusOffset', min: -500, max: 500 },
                 { label: 'Giro Unic.', key: 'scatterIndividualRotation', min: 0, max: 360 },
               ].map(ctrl => (
                <div key={ctrl.key} className="space-y-2">
                  <div className="flex justify-between items-center cursor-ew-resize group" onMouseDown={(e) => onDeltaStart(e, ctrl.key, (settings as any)[ctrl.key])}>
                    <label className="text-[9px] font-black uppercase opacity-40 group-hover:opacity-100 transition-opacity">{ctrl.label}</label>
                    <span className="text-[10px] font-mono font-black text-theme-accent bg-theme-accent/10 px-2 py-0.5 rounded">{(settings as any)[ctrl.key]}</span>
                  </div>
                  <input type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]} onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })} className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent" />
                </div>
               ))}
            </div>
          </div>

          <div className="flex gap-6 p-6 bg-theme-panel/10 border border-theme/20 rounded-[2rem]">
             <div className="flex-1 space-y-2">
               <label className="text-[9px] font-black uppercase opacity-40 block">Cor Pattern</label>
               <input type="color" value={settings.color} onChange={(e) => onUpdate({ ...settings, color: e.target.value })} className="w-full h-12 rounded-2xl cursor-pointer bg-theme-panel border-none p-1 shadow-inner" />
             </div>
             <div className="flex-1 space-y-2">
               <label className="text-[9px] font-black uppercase opacity-40 block">Cor Fundo</label>
               <input type="color" value={settings.bgColor} onChange={(e) => onUpdate({ ...settings, bgColor: e.target.value })} className="w-full h-12 rounded-2xl cursor-pointer bg-theme-panel border-none p-1 shadow-inner" />
             </div>
          </div>

          <button onClick={onClose} className="w-full py-6 rounded-[2.5rem] bg-theme-accent text-white font-black uppercase text-[12px] tracking-widest shadow-2xl active:scale-95 transition-all">Sincronizar Arte</button>
        </div>
      </div>
    </div>
  );
};

