                  <div className="flex justify-between items-center cursor-ew-resize group" onMouseDown={(e) => onDragStart(e, ctrl.key, (settings as any)[ctrl.key])}>
                    <label className="text-[9px] font-black uppercase opacity-40 group-hover:opacity-100 transition-opacity">{ctrl.label}</label>
                    <span className="text-[10px] font-mono font-black text-theme-accent">{(settings as any)[ctrl.key]}</span>
