          </div>

          <div className="flex gap-6 p-6 bg-theme-panel/10 border border-theme/20 rounded-[2.5rem]">
             <div className="flex-1 space-y-2">
               <label className="text-[9px] font-black uppercase opacity-40 block text-center">Cor Pattern</label>
               <input type="color" value={settings.color} onChange={(e) => onUpdate({ ...settings, color: e.target.value })} className="w-full h-12 rounded-2xl cursor-pointer bg-theme-panel border-none p-1" />
             </div>
             <div className="flex-1 space-y-2">
               <label className="text-[9px] font-black uppercase opacity-40 block text-center">Cor Fundo</label>
               <input type="color" value={settings.bgColor} onChange={(e) => onUpdate({ ...settings, bgColor: e.target.value })} className="w-full h-12 rounded-2xl cursor-pointer bg-theme-panel border-none p-1" />
             </div>
          </div>

          <button onClick={onClose} className="w-full py-6 rounded-[3rem] bg-theme-accent text-white font-black uppercase text-[12px] tracking-widest shadow-2xl active:scale-95 transition-all">Sincronizar Engines</button>
        </div>
