export default SidebarAlphaEdge;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import SidebarAlphaEdge from '../components/SidebarAlphaEdge';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import AdvancedBorderModal from '../components/AdvancedBorderModal';
import { GridImage, AlphaEdgeSettings, AdvancedBorderSettings } from '../types';

const AlphaEdgeTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [customShapeImg, setCustomShapeImg] = useState<HTMLImageElement | null>(null);

  const [settings, setSettings] = useState<AlphaEdgeSettings>({
    expansion: 20,
    feather: 10,
    borderScale: 100, 
    opacity: 100,
    color: '#ffffff',
    advanced: {
      enabled: false,
      gridEnabled: true,
      scatterEnabled: false,
      shapeType: 'heart',
      size: 15,
      spacingX: 10,
      spacingY: 10,
      color: '#ffffff',
      bgColor: '#ff0000',
      individualRotation: 0,
      globalRotation: 0,
      offsetX: 0,
      offsetY: 0,
      scatterSize: 20,
      scatterDensity: 40,
      scatterRadiusOffset: 0,
      scatterIndividualRotation: 0
    }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (settings.advanced?.customShapeUrl) {
      const img = new Image(); img.src = settings.advanced.customShapeUrl;
      img.onload = () => setCustomShapeImg(img);
    }
  }, [settings.advanced?.customShapeUrl]);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    if (type === 'custom' && customShapeImg) {
      ctx.drawImage(customShapeImg, -s, -s, size, size);
      return;
    }
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      ctx.moveTo(0, s * 0.7);
      ctx.bezierCurveTo(-s * 1.5, -s * 0.5, -s * 0.8, -s * 1.5, 0, -s * 0.6);
      ctx.bezierCurveTo(s * 0.8, -s * 1.5, s * 1.5, -s * 0.5, 0, s * 0.7);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const drawPatternBuffer = useCallback((ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    ctx.save();
    if (config.gridEnabled) {
      ctx.save();
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, w, h);
      ctx.translate(w / 2 + config.offsetX, h / 2 + config.offsetY);
      ctx.rotate((config.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = config.color;
      const stepX = config.size + config.spacingX;
      const stepY = config.size + config.spacingY;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save(); ctx.translate(x, y); ctx.rotate((config.individualRotation * Math.PI) / 180);
          drawShape(ctx, config.shapeType, config.size); ctx.restore();
        }
      }
      ctx.restore();
    } else {
      ctx.fillStyle = config.bgColor; ctx.fillRect(0, 0, w, h);
    }

    if (config.scatterEnabled) {
      ctx.save();
      ctx.fillStyle = config.color;
      const steps = config.scatterDensity;
      const radius = (Math.min(w, h) * 0.35) + config.scatterRadiusOffset;
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2;
        const px = w / 2 + Math.cos(angle) * radius;
        const py = h / 2 + Math.sin(angle) * radius;
        ctx.save(); ctx.translate(px, py); ctx.rotate(angle + (config.scatterIndividualRotation * Math.PI) / 180);
        drawShape(ctx, config.shapeType, config.scatterSize); ctx.restore();
      }
      ctx.restore();
    }
    ctx.restore();
  }, [customShapeImg]);

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings) => {
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    // Fator de Escala Extra (Zoom da Borda)
    const extraScale = config.borderScale / 100;

    // Valores Finais Aplicados
    const finalShift = config.expansion * extraScale;
    const finalFeather = config.feather * extraScale;

    // Ajuste de Canvas MILIMÉTRICO para remover espaços vazios
    // Usamos um pequeno buffer de 2px apenas para evitar cortes de antialiasing
    const padding = Math.ceil(finalShift + finalFeather) + 2;

    canvas.width = img.width + (padding * 2);
    canvas.height = img.height + (padding * 2);

    // 1. GERAR SILHUETA 100% SÓLIDA
    const silCanvas = document.createElement('canvas');
    silCanvas.width = canvas.width; silCanvas.height = canvas.height;
    const sCtx = silCanvas.getContext('2d');
    if (!sCtx) return;
    sCtx.translate(padding, padding);
    sCtx.drawImage(img, 0, 0);
    sCtx.globalCompositeOperation = 'source-in';
    sCtx.fillStyle = '#ffffff';
    sCtx.fillRect(-padding, -padding, canvas.width, canvas.height);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 2. EXPANSÃO SÓLIDA (SHIFT) - Aumentamos a densidade do loop para evitar "dispersão"
    const bodyCanvas = document.createElement('canvas');
    bodyCanvas.width = canvas.width; bodyCanvas.height = canvas.height;
    const bCtx = bodyCanvas.getContext('2d');
    if (bCtx) {
      if (finalShift > 0) {
        // Usamos 72 passos (5 graus cada) para garantir que em bordas grandes não existam furos
        const steps = 72;
        for (let i = 0; i < steps; i++) {
          const angle = (i / steps) * Math.PI * 2;
          bCtx.drawImage(silCanvas, Math.cos(angle) * finalShift, Math.sin(angle) * finalShift);
        }
      }
      bCtx.drawImage(silCanvas, 0, 0);
    }

    // 3. MÁSCARA COM SUAVIZAÇÃO (FEATHER)
    const maskCanvas = document.createElement('canvas');
    maskCanvas.width = canvas.width; maskCanvas.height = canvas.height;
    const mCtx = maskCanvas.getContext('2d');
    if (mCtx) {
      if (finalFeather > 0) {
        mCtx.filter = `blur(${finalFeather}px)`;
      }
      mCtx.drawImage(bodyCanvas, 0, 0);
    }

    // 4. RENDERIZAÇÃO FINAL DA BORDA (COR OU ESTAMPA)
    ctx.save();
    ctx.globalAlpha = config.opacity / 100;

    const contentLayer = document.createElement('canvas');
    contentLayer.width = canvas.width; contentLayer.height = canvas.height;
    const clCtx = contentLayer.getContext('2d');
    if (clCtx) {
      if (config.advanced?.enabled) {
        drawPatternBuffer(clCtx, canvas.width, canvas.height, config.advanced);
      } else {
        clCtx.fillStyle = config.color;
        clCtx.fillRect(0, 0, canvas.width, canvas.height);
      }
      // Aplica a máscara final
      clCtx.globalCompositeOperation = 'destination-in';
      clCtx.drawImage(maskCanvas, 0, 0);
      ctx.drawImage(contentLayer, 0, 0);
    }
    ctx.restore();

    // 5. IMAGEM ORIGINAL (NÍTIDA NO TOPO)
    ctx.save();
    ctx.translate(padding, padding);
    ctx.drawImage(img, 0, 0);
    ctx.restore();
  }, [customShapeImg, drawPatternBuffer]);

  useEffect(() => {
    const updatePreview = async () => {
      if (!previewCanvasRef.current || !images[selectedIdx]) return;
      const img = new Image();
      img.src = images[selectedIdx].previewUrl;
      img.onload = () => drawEdge(img, previewCanvasRef.current!, settings);
    };
    updatePreview();
  }, [selectedIdx, images, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = [];
    for (const file of files) {
      const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const i = new Image(); i.onload = () => resolve(i); i.src = url;
      });
      newImgs.push({ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height, isActive: true });
    }
    setImages(prev => [...prev, ...newImgs]);
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i];
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl;
      });
      await drawEdge(img, canvas, settings);
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a'); link.download = `${item.file.name.split('.')[0]}_miau.png`; link.href = dataUrl; link.click();
      await new Promise(r => setTimeout(r, 400));
    }
    setIsProcessing(false);
  };

  const currentImg = images[selectedIdx];
  const currentPadding = Math.ceil((settings.expansion + settings.feather) * (settings.borderScale/100)) + 2;

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={setSettings}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onOpenAdvanced={() => setIsModalOpen(true)}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />
        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-[2.5rem]"
                style={{ 
                  width: (currentImg.width + currentPadding * 2) * zoom,
                  height: (currentImg.height + currentPadding * 2) * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <canvas ref={previewCanvasRef} className="w-full h-full block" />
              </div>

              {/* INFO PANEL */}
              <div className="absolute bottom-10 left-10 flex flex-col items-start gap-4 animate-in fade-in slide-in-from-left-4 duration-700 pointer-events-none z-50">
                <div className="flex items-center gap-3 bg-theme-side/90 border border-theme/40 px-4 py-2 rounded-full shadow-2xl backdrop-blur-3xl">
                   <div className="flex flex-col items-start leading-none gap-0.5">
                      <span className="text-[6px] font-black uppercase opacity-30 tracking-widest">Resolução Final</span>
                      <span className="text-[10px] font-mono font-black text-theme-accent tracking-tighter">
                        {Math.round(currentImg.width + currentPadding * 2)}<span className="opacity-40 mx-0.5">×</span>{Math.round(currentImg.height + currentPadding * 2)}
                      </span>
                   </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Alpha Edge Studio</p>
            </div>
          )}
          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-4 pr-8 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-6">
                <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(prev => prev - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[10px]"></i></button>
                <span className="text-[11px] font-mono font-black text-theme-accent min-w-[70px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(prev => prev + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[10px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <ImageList 
          images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} onToggleActive={(id) => setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img))} 
        />
      </aside>

      <AdvancedBorderModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}
        settings={settings.advanced!} onUpdate={(adv) => setSettings({ ...settings, advanced: adv })}
        baseImage={currentImg ? { url: currentImg.previewUrl, width: currentImg.width, height: currentImg.height } : null}
      />
      <input type="file" multiple accept="image/png, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default AlphaEdgeTool;

export interface GridImage {
  id: string;
  file: File;
  previewUrl: string;
  width: number;
  height: number;
  aspectRatio: number;
  isActive?: boolean;
  visible?: boolean;
  x?: number;
  y?: number;
  scale?: number;
  rotation?: number;
}

export interface GridSettings {
  canvasWidth: number;
  canvasHeight: number;
  columns: number;
  innerSpacing: number;
  outerMargin: number;
  backgroundColor: string;
  isTransparent: boolean;
  layoutMode: 'grid' | 'auto';
  itemScale: number;
  targetShape: 'square' | 'portrait' | 'landscape';
}

export interface AdvancedBorderSettings {
  enabled: boolean;
  gridEnabled: boolean;
  scatterEnabled: boolean;
  shapeType: 'circle' | 'square' | 'triangle' | 'x' | 'heart' | 'diamond';
  size: number;
  spacingX: number;
  spacingY: number;
  color: string;
  bgColor: string;
  individualRotation: number;
  globalRotation: number;
  offsetX: number;
  offsetY: number;
  scatterSize: number;
  scatterDensity: number;
  scatterRadiusOffset: number;
  scatterIndividualRotation: number;
}

export interface AlphaEdgeSettings {
  thickness: number; // Shift
  softness: number;  // Feather
  borderScale: number; // Zoom Global
  opacity: number;
  color: string;
  advanced?: AdvancedBorderSettings;
}

export interface FrameSettings {
  borderWidth: number;
  borderColor: string;
  borderRadius: number;
  padding: number;
  shadow: number;
  canvasWidth: number;
  canvasHeight: number;
  frameImageUrl?: string;
  frameImageName?: string;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import SidebarAlphaEdge from '../components/SidebarAlphaEdge';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import AdvancedBorderModal from '../components/AdvancedBorderModal';
import { GridImage, AlphaEdgeSettings, AdvancedBorderSettings } from '../types';

const AlphaEdgeTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);

  const [settings, setSettings] = useState<AlphaEdgeSettings>({
    thickness: 20,
    softness: 5,
    borderScale: 100, // 100% = tamanho base
    opacity: 100,
    color: '#ffffff',
    advanced: {
      enabled: false,
      gridEnabled: true,
      scatterEnabled: false,
      shapeType: 'circle',
      size: 15,
      spacingX: 10,
      spacingY: 10,
      color: '#ffffff',
      bgColor: '#000000',
      individualRotation: 0,
      globalRotation: 0,
      offsetX: 0,
      offsetY: 0,
      scatterSize: 20,
      scatterDensity: 40,
      scatterRadiusOffset: 0,
      scatterIndividualRotation: 0
    }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'x') {
      ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s);
      ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return;
    } else if (type === 'heart') {
      ctx.moveTo(0, s * 0.7);
      ctx.bezierCurveTo(-s * 1.5, -s * 0.5, -s * 0.8, -s * 1.5, 0, -s * 0.6);
      ctx.bezierCurveTo(s * 0.8, -s * 1.5, s * 1.5, -s * 0.5, 0, s * 0.7);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const drawPattern = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    ctx.save();
    if (config.gridEnabled) {
      ctx.save();
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, w, h);
      ctx.translate(w / 2 + config.offsetX, h / 2 + config.offsetY);
      ctx.rotate((config.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = config.color;
      const stepX = config.size + config.spacingX;
      const stepY = config.size + config.spacingY;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save(); ctx.translate(x, y); ctx.rotate((config.individualRotation * Math.PI) / 180);
          drawShape(ctx, config.shapeType, config.size); ctx.restore();
        }
      }
      ctx.restore();
    } else {
      ctx.fillStyle = config.bgColor; ctx.fillRect(0, 0, w, h);
    }
    if (config.scatterEnabled) {
      ctx.save();
      ctx.fillStyle = config.color;
      const steps = config.scatterDensity;
      const radius = (Math.min(w, h) * 0.35) + config.scatterRadiusOffset;
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2;
        const px = w / 2 + Math.cos(angle) * radius;
        const py = h / 2 + Math.sin(angle) * radius;
        ctx.save(); ctx.translate(px, py); ctx.rotate(angle + (config.scatterIndividualRotation * Math.PI) / 180);
        drawShape(ctx, config.shapeType, config.scatterSize); ctx.restore();
      }
      ctx.restore();
    }
    ctx.restore();
  };

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings) => {
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    // Fator de escala extra
    const extraScale = config.borderScale / 100;
    const finalShift = config.thickness * extraScale;
    const finalFeather = config.softness * extraScale;

    // Padding inteligente: soma dos efeitos + pequena margem de segurança
    const padding = Math.ceil(finalShift + finalFeather) + 4;

    canvas.width = img.width + (padding * 2);
    canvas.height = img.height + (padding * 2);

    // 1. SILHUETA SÓLIDA
    const silCanvas = document.createElement('canvas');
    silCanvas.width = canvas.width; silCanvas.height = canvas.height;
    const sCtx = silCanvas.getContext('2d');
    if (!sCtx) return;
    sCtx.translate(padding, padding);
    sCtx.drawImage(img, 0, 0);
    sCtx.globalCompositeOperation = 'source-in';
    sCtx.fillStyle = '#ffffff';
    sCtx.fillRect(-padding, -padding, canvas.width, canvas.height);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 2. EXPANSÃO (SHIFT) - Alta densidade (72 passos) para ser 100% sólido
    const bodyCanvas = document.createElement('canvas');
    bodyCanvas.width = canvas.width; bodyCanvas.height = canvas.height;
    const bCtx = bodyCanvas.getContext('2d');
    if (bCtx) {
      if (finalShift > 0) {
        const steps = 72;
        for (let i = 0; i < steps; i++) {
          const angle = (i / steps) * Math.PI * 2;
          bCtx.drawImage(silCanvas, Math.cos(angle) * finalShift, Math.sin(angle) * finalShift);
        }
      }
      bCtx.drawImage(silCanvas, 0, 0);
    }

    // 3. MÁSCARA COM FEATHER
    const maskCanvas = document.createElement('canvas');
    maskCanvas.width = canvas.width; maskCanvas.height = canvas.height;
    const mCtx = maskCanvas.getContext('2d');
    if (mCtx) {
      if (finalFeather > 0) mCtx.filter = `blur(${finalFeather}px)`;
      mCtx.drawImage(bodyCanvas, 0, 0);
    }

    // 4. RENDERIZAÇÃO FINAL
    ctx.save();
    ctx.globalAlpha = config.opacity / 100;

    const contentLayer = document.createElement('canvas');
    contentLayer.width = canvas.width; contentLayer.height = canvas.height;
    const clCtx = contentLayer.getContext('2d');
    if (clCtx) {
      if (config.advanced?.enabled) {
        drawPattern(clCtx, canvas.width, canvas.height, config.advanced);
      } else {
        clCtx.fillStyle = config.color;
        clCtx.fillRect(0, 0, canvas.width, canvas.height);
      }
      clCtx.globalCompositeOperation = 'destination-in';
      clCtx.drawImage(maskCanvas, 0, 0);
      ctx.drawImage(contentLayer, 0, 0);
    }
    ctx.restore();

    // 5. IMAGEM ORIGINAL
    ctx.save();
    ctx.translate(padding, padding);
    ctx.drawImage(img, 0, 0);
    ctx.restore();
  }, []);

  useEffect(() => {
    const updatePreview = async () => {
      if (!previewCanvasRef.current || !images[selectedIdx]) return;
      const img = new Image();
      img.src = images[selectedIdx].previewUrl;
      img.onload = () => drawEdge(img, previewCanvasRef.current!, settings);
    };
    updatePreview();
  }, [selectedIdx, images, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = [];
    for (const file of files) {
      const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const i = new Image(); i.onload = () => resolve(i); i.src = url;
      });
      newImgs.push({ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height, isActive: true });
    }
    setImages(prev => [...prev, ...newImgs]);
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i];
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl;
      });
      await drawEdge(img, canvas, settings);
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a'); link.download = `${item.file.name.split('.')[0]}_miau.png`; link.href = dataUrl; link.click();
      await new Promise(r => setTimeout(r, 400));
    }
    setIsProcessing(false);
  };

  const currentImg = images[selectedIdx];
  const currentPadding = Math.ceil((settings.thickness + settings.softness) * (settings.borderScale / 100)) + 4;

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={setSettings}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onOpenAdvanced={() => setIsModalOpen(true)}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />
        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-[2.5rem]"
                style={{ 
                  width: (currentImg.width + currentPadding * 2) * zoom,
                  height: (currentImg.height + currentPadding * 2) * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <canvas ref={previewCanvasRef} className="w-full h-full block" />
              </div>

              <div className="absolute bottom-10 left-10 flex flex-col gap-1 pointer-events-none opacity-50">
                <span className="text-[7px] font-black uppercase tracking-[0.2em]">Output Info</span>
                <span className="text-[10px] font-mono font-black text-theme-accent">
                   {Math.round(currentImg.width + currentPadding * 2)}x{Math.round(currentImg.height + currentPadding * 2)}px
                </span>
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Alpha Edge Studio</p>
            </div>
          )}

          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-4 pr-8 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-6">
                <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(prev => prev - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[10px]"></i></button>
                <span className="text-[11px] font-mono font-black text-theme-accent min-w-[70px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(prev => prev + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[10px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <ImageList 
          images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} onToggleActive={(id) => setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img))} 
        />
      </aside>

      <AdvancedBorderModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}
        settings={settings.advanced!} onUpdate={(adv) => setSettings({ ...settings, advanced: adv })}
        baseImage={currentImg ? { url: currentImg.previewUrl, width: currentImg.width, height: currentImg.height } : null}
      />
      <input type="file" multiple accept="image/png, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default AlphaEdgeTool;

import React from 'react';
import { AlphaEdgeSettings } from '../types';

interface SidebarAlphaEdgeProps {
  settings: AlphaEdgeSettings;
  onSettingsChange: (s: AlphaEdgeSettings) => void;
  onAdd: () => void;
  onSave: () => void;
  isProcessing?: boolean;
  progress?: number;
  total?: number;
  exportOptions: {
    downloadIndividual: boolean;
    setDownloadIndividual: (v: boolean) => void;
    downloadZip: boolean;
    setDownloadZip: (v: boolean) => void;
  };
  onOpenAdvanced: () => void;
}

const SidebarAlphaEdge: React.FC<SidebarAlphaEdgeProps> = ({ 
  settings, onSettingsChange, onAdd, onSave, isProcessing, progress, total, exportOptions, onOpenAdvanced
}) => {
  const handleChange = (key: keyof AlphaEdgeSettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  return (
    <div className="p-5 space-y-6 h-full overflow-y-auto scrollbar-hide flex flex-col">
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Auto-Fit Engine</h3>
        <button onClick={onAdd} className="w-full py-4 rounded-xl font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase active:scale-95 transition-all">
          <i className="fas fa-wand-magic-sparkles"></i> Importar Lote
        </button>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-5">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Controle de Borda</h3>

        <div className="space-y-4">
          <div className="space-y-2">
            <div className="flex justify-between items-center px-1">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-tighter">Shift (Expansão)</label>
              <span className="text-[9px] font-black text-theme-accent">{settings.thickness}px</span>
            </div>
            <input type="range" min="0" max="250" value={settings.thickness} onChange={(e) => handleChange('thickness', parseInt(e.target.value))} className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent" />
          </div>

          <div className="space-y-2">
            <div className="flex justify-between items-center px-1">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-tighter">Feather (Suavizar)</label>
              <span className="text-[9px] font-black text-theme-accent">{settings.softness}px</span>
            </div>
            <input type="range" min="0" max="150" value={settings.softness} onChange={(e) => handleChange('softness', parseInt(e.target.value))} className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent" />
          </div>

          <div className="space-y-2 pt-2 border-t border-theme/10">
            <div className="flex justify-between items-center px-1">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-tighter text-theme-accent">Tamanho Extra (Zoom)</label>
              <span className="text-[9px] font-black text-theme-accent">{settings.borderScale}%</span>
            </div>
            <input type="range" min="10" max="400" value={settings.borderScale} onChange={(e) => handleChange('borderScale', parseInt(e.target.value))} className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent" />
          </div>

          <div className="space-y-2">
            <div className="flex justify-between items-center px-1">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-tighter">Opacidade</label>
              <span className="text-[9px] font-black text-theme-accent">{settings.opacity}%</span>
            </div>
            <input type="range" min="0" max="100" value={settings.opacity} onChange={(e) => handleChange('opacity', parseInt(e.target.value))} className="w-full h-1 bg-theme-panel rounded-lg appearance-none cursor-pointer accent-theme-accent" />
          </div>

          <div className="pt-2 border-t border-theme/20">
             <button onClick={onOpenAdvanced} className="w-full py-3 rounded-xl bg-theme-panel hover:bg-theme-accent/20 border border-theme hover:border-theme-accent transition-all flex items-center justify-center gap-3">
                <div className="w-4 h-4 rounded-full border border-theme shadow-inner" style={{ backgroundColor: settings.color }}></div>
                <span className="text-[9px] font-black uppercase tracking-widest">Estúdio de Estampas</span>
                <i className="fas fa-cog text-theme-accent text-[10px]"></i>
             </button>
          </div>
        </div>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Exportar</h3>
        <div className="grid grid-cols-1 gap-2">
          <button onClick={() => { exportOptions.setDownloadIndividual(true); exportOptions.setDownloadZip(false); }} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${exportOptions.downloadIndividual ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/30 border-theme opacity-60'}`}>
            <span className="text-[9px] font-black uppercase">Individual</span>
          </button>
          <button onClick={() => { exportOptions.setDownloadIndividual(false); exportOptions.setDownloadZip(true); }} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${exportOptions.downloadZip ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/30 border-theme opacity-60'}`}>
            <span className="text-[9px] font-black uppercase">Lote ZIP</span>
          </button>
        </div>
      </div>

      <div className="mt-auto pt-4">
        <button onClick={onSave} disabled={isProcessing || total === 0} className="w-full py-5 rounded-xl font-black text-[11px] bg-theme-accent text-theme-inv shadow-2xl flex items-center justify-center gap-2 uppercase disabled:opacity-50 active:scale-95 transition-all">
           {isProcessing ? <><i className="fas fa-spinner animate-spin"></i> {progress}/{total}</> : <><i className="fas fa-save"></i> Salvar Lote</>}
        </button>
      </div>
    </div>
  );
};

export default SidebarAlphaEdge;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import SidebarAlphaEdge from '../components/SidebarAlphaEdge';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import AdvancedBorderModal from '../components/AdvancedBorderModal';
import { GridImage, AlphaEdgeSettings, AdvancedBorderSettings } from '../types';

const AlphaEdgeTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);

  const [settings, setSettings] = useState<AlphaEdgeSettings>({
    thickness: 20, // Shift (Tamanho da silhueta base)
    softness: 5,   // Feather (Glow)
    borderScale: 100, // Zoom Global da Camada de Borda
    opacity: 100,
    color: '#ffffff',
    advanced: {
      enabled: false,
      gridEnabled: true,
      scatterEnabled: false,
      shapeType: 'circle',
      size: 15,
      spacingX: 10,
      spacingY: 10,
      color: '#ffffff',
      bgColor: '#000000',
      individualRotation: 0,
      globalRotation: 0,
      offsetX: 0,
      offsetY: 0,
      scatterSize: 20,
      scatterDensity: 40,
      scatterRadiusOffset: 0,
      scatterIndividualRotation: 0
    }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2;
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') {
      ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath();
    } else if (type === 'heart') {
      ctx.moveTo(0, s * 0.7);
      ctx.bezierCurveTo(-s * 1.5, -s * 0.5, -s * 0.8, -s * 1.5, 0, -s * 0.6);
      ctx.bezierCurveTo(s * 0.8, -s * 1.5, s * 1.5, -s * 0.5, 0, s * 0.7);
    } else if (type === 'diamond') {
      ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath();
    }
    ctx.fill();
  };

  const drawPattern = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    ctx.save();
    if (config.gridEnabled) {
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, w, h);
      ctx.translate(w / 2 + config.offsetX, h / 2 + config.offsetY);
      ctx.rotate((config.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = config.color;
      const stepX = config.size + config.spacingX;
      const stepY = config.size + config.spacingY;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save(); ctx.translate(x, y); ctx.rotate((config.individualRotation * Math.PI) / 180);
          drawShape(ctx, config.shapeType, config.size); ctx.restore();
        }
      }
    } else {
      ctx.fillStyle = config.bgColor; ctx.fillRect(0, 0, w, h);
    }
    ctx.restore();
  };

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings) => {
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const bScale = config.borderScale / 100;

    // O padding deve considerar o tamanho da borda após o escalonamento
    // Se bScale for 2.0 (200%), a borda dobra de tamanho
    const borderThickness = (config.thickness + config.softness);
    const scaledBorderThickness = borderThickness * bScale;

    // Padding dinâmico para evitar cortes na borda escalonada
    const padding = Math.ceil(Math.max(scaledBorderThickness, borderThickness)) + 10;

    canvas.width = img.width + (padding * 2);
    canvas.height = img.height + (padding * 2);
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;

    // --- 1. GERAR MÁSCARA DA BORDA (TAMANHO ORIGINAL) ---
    const maskCanvas = document.createElement('canvas');
    maskCanvas.width = canvas.width;
    maskCanvas.height = canvas.height;
    const mCtx = maskCanvas.getContext('2d');
    if (!mCtx) return;

    // Silhueta base
    const silCanvas = document.createElement('canvas');
    silCanvas.width = canvas.width; silCanvas.height = canvas.height;
    const sCtx = silCanvas.getContext('2d');
    if (sCtx) {
      sCtx.translate(padding, padding);
      sCtx.drawImage(img, 0, 0);
      sCtx.globalCompositeOperation = 'source-in';
      sCtx.fillStyle = '#ffffff';
      sCtx.fillRect(-padding, -padding, canvas.width, canvas.height);
    }

    // Aplica Shift (Expansão sólida)
    if (config.thickness > 0) {
      const steps = 72;
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2;
        mCtx.drawImage(silCanvas, Math.cos(angle) * config.thickness, Math.sin(angle) * config.thickness);
      }
    }
    mCtx.drawImage(silCanvas, 0, 0);

    // Aplica Feather (Suavização)
    if (config.softness > 0) {
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = canvas.width; tempCanvas.height = canvas.height;
      const tCtx = tempCanvas.getContext('2d');
      if (tCtx) {
        tCtx.filter = `blur(${config.softness}px)`;
        tCtx.drawImage(maskCanvas, 0, 0);
        mCtx.clearRect(0, 0, canvas.width, canvas.height);
        mCtx.drawImage(tempCanvas, 0, 0);
      }
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // --- 2. DESENHAR CAMADA DA BORDA COM ESCALONAMENTO (ZOOM) ---
    ctx.save();
    ctx.globalAlpha = config.opacity / 100;

    // Move para o centro para escalonar a partir dali
    ctx.translate(centerX, centerY);
    ctx.scale(bScale, bScale);
    ctx.translate(-centerX, -centerY);

    const borderContent = document.createElement('canvas');
    borderContent.width = canvas.width; borderContent.height = canvas.height;
    const bcCtx = borderContent.getContext('2d');
    if (bcCtx) {
      if (config.advanced?.enabled) {
        drawPattern(bcCtx, canvas.width, canvas.height, config.advanced);
      } else {
        bcCtx.fillStyle = config.color;
        bcCtx.fillRect(0, 0, canvas.width, canvas.height);
      }
      bcCtx.globalCompositeOperation = 'destination-in';
      bcCtx.drawImage(maskCanvas, 0, 0);
      ctx.drawImage(borderContent, 0, 0);
    }
    ctx.restore();

    // --- 3. DESENHAR IMAGEM ORIGINAL (SEMPRE 100% NO CENTRO) ---
    ctx.save();
    ctx.translate(padding, padding);
    ctx.drawImage(img, 0, 0);
    ctx.restore();
  }, []);

  useEffect(() => {
    const updatePreview = async () => {
      if (!previewCanvasRef.current || !images[selectedIdx]) return;
      const img = new Image();
      img.src = images[selectedIdx].previewUrl;
      img.onload = () => drawEdge(img, previewCanvasRef.current!, settings);
    };
    updatePreview();
  }, [selectedIdx, images, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = [];
    for (const file of files) {
      const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const i = new Image(); i.onload = () => resolve(i); i.src = url;
      });
      newImgs.push({ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height, isActive: true });
    }
    setImages(prev => [...prev, ...newImgs]);
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i];
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl;
      });
      await drawEdge(img, canvas, settings);
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a'); link.download = `${item.file.name.split('.')[0]}_miau.png`; link.href = dataUrl; link.click();
      await new Promise(r => setTimeout(r, 400));
    }
    setIsProcessing(false);
  };

  const currentImg = images[selectedIdx];
  const bScale = settings.borderScale / 100;
  const currentPadding = Math.ceil(Math.max((settings.thickness + settings.softness) * bScale, settings.thickness + settings.softness)) + 10;

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={setSettings}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onOpenAdvanced={() => setIsModalOpen(true)}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />
        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-[2.5rem]"
                style={{ 
                  width: (currentImg.width + currentPadding * 2) * zoom,
                  height: (currentImg.height + currentPadding * 2) * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <canvas ref={previewCanvasRef} className="w-full h-full block" />
              </div>

              <div className="absolute bottom-10 left-10 flex flex-col gap-1 pointer-events-none opacity-50">
                <span className="text-[7px] font-black uppercase tracking-[0.2em]">Resolucão de Saída</span>
                <span className="text-[10px] font-mono font-black text-theme-accent">
                   {Math.round(currentImg.width + currentPadding * 2)}x{Math.round(currentImg.height + currentPadding * 2)}px
                </span>
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Alpha Edge Studio</p>
            </div>
          )}

          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-4 pr-8 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-6">
                <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(prev => prev - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[10px]"></i></button>
                <span className="text-[11px] font-mono font-black text-theme-accent min-w-[70px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(prev => prev + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[10px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>

      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <ImageList 
          images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} onToggleActive={(id) => setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img))} 
        />
      </aside>

      <AdvancedBorderModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}
        settings={settings.advanced!} onUpdate={(adv) => setSettings({ ...settings, advanced: adv })}
        baseImage={currentImg ? { url: currentImg.previewUrl, width: currentImg.width, height: currentImg.height } : null}
      />
      <input type="file" multiple accept="image/png, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

