          <button onClick={() => { exportOptions.setDownloadIndividual(false); exportOptions.setDownloadZip(true); }} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${exportOptions.downloadZip ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/30 border-theme opacity-60'}`}>
