          <div className="p-6 border-b border-theme/20">
            <h3 className="text-[10px] font-black uppercase tracking-[0.3em] opacity-40 mb-1">Miau Patterns</h3>
            <h4 className="text-sm font-black uppercase text-theme-accent">Biblioteca</h4>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {presets.length === 0 ? (
              <div className="h-40 flex flex-col items-center justify-center text-center opacity-20 p-4">
                <i className="fas fa-layer-group text-2xl mb-2"></i>
                <p className="text-[9px] font-black uppercase">Nenhum padrão salvo</p>
              </div>
            ) : (
              presets.map(p => (
                <div 
                  key={p.id}
                  onClick={() => { onUpdate(p.settings); setSelectedPresetId(p.id); }}
                  className={`group flex items-center gap-3 p-2 rounded-2xl border transition-all cursor-pointer ${selectedPresetId === p.id ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/20 border-transparent hover:border-theme'}`}
                >
                  <PresetThumbnail settings={p.settings} />
                  <div className="flex-1 min-w-0">
                    <p className="text-[9px] font-black uppercase truncate text-theme-main">{p.name}</p>
                    <p className="text-[7px] opacity-40 uppercase">Design #{p.id.slice(0,4)}</p>
                  </div>
                  <button onClick={(e) => deletePreset(e, p.id)} className="opacity-0 group-hover:opacity-100 p-2 text-theme-muted hover:text-red-500 transition-all">
                    <i className="fas fa-trash-alt text-[10px]"></i>
                  </button>
                </div>
              ))
            )}
          </div>
        </aside>

        {/* PREVIEW CENTRAL */}
        <div className="flex-1 bg-black/5 flex flex-col items-center justify-center relative p-10 gap-6">
           <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-theme-accent flex items-center justify-center text-white shadow-lg rotate-3">
                <i className="fas fa-wand-magic-sparkles"></i>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-40">Editor Pro</span>
                <span className="text-xl font-black tracking-tighter uppercase">{selectedPresetId ? presets.find(p=>p.id===selectedPresetId)?.name : 'Novo Padrão'}</span>
              </div>
           </div>

           <div className="relative rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white/5 bg-theme-panel/20 p-2">
              <canvas ref={canvasRef} className="block rounded-[2rem] shadow-inner" />
           </div>

           <div className="flex gap-4 opacity-40 text-[9px] font-black uppercase tracking-widest bg-theme-panel/40 px-4 py-2 rounded-full border border-theme">
              <span>Sincronia Pixel Perfect</span>
           </div>
        </div>

        {/* CONTROLES (DIREITA) */}
        <div className="w-[400px] p-8 flex flex-col gap-6 overflow-y-auto bg-theme-side custom-scrollbar border-l border-theme/30">
          <div className="flex justify-between items-center mb-2">
             <button 
                onClick={handleSaveClick}
                className="flex-1 flex items-center justify-center gap-3 py-3.5 rounded-2xl bg-theme-accent text-white font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 transition-all"
             >
                <i className="fas fa-save"></i> {selectedPresetId ? 'Gerenciar Estilo' : 'Salvar Estilo'}
             </button>
             <button onClick={onClose} className="ml-4 w-12 h-12 rounded-2xl bg-theme-panel hover:bg-red-500 hover:text-white text-theme-main transition-all flex items-center justify-center shadow-lg"><i className="fas fa-times"></i></button>
          </div>

          <div className="space-y-6">
            <div className="space-y-3 bg-theme-panel/20 p-4 rounded-2xl border border-theme/50">
              <label className="text-[9px] font-black uppercase opacity-40 tracking-widest">Shape Base</label>
              <div className="grid grid-cols-6 gap-2">
