            ) : (
              presets.map(p => (
                <div key={p.id} onClick={() => { onUpdate(p.settings); setSelectedPresetId(p.id); }} className={`group flex items-center gap-3 p-2 rounded-2xl border transition-all cursor-pointer ${selectedPresetId === p.id ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/20 border-transparent hover:border-theme'}`}><PresetThumbnail settings={p.settings} /><div className="flex-1 min-w-0"><p className="text-[9px] font-black uppercase truncate text-theme-main">{p.name}</p><p className="text-[7px] opacity-40 uppercase">Design #{p.id.slice(0,4)}</p></div><button onClick={(e) => deletePreset(e, p.id)} className="opacity-0 group-hover:opacity-100 p-2 text-theme-muted hover:text-red-500 transition-all"><i className="fas fa-trash-alt text-[10px]"></i></button></div>
              ))
