               <div className="flex-1 space-y-2"><label className="text-[9px] font-black uppercase opacity-40 block text-center">Background</label><input type="color" value={settings.bgColor} onChange={(e) => onUpdate({ ...settings, bgColor: e.target.value })} className="w-full h-10 rounded-xl border border-theme p-1 bg-theme-panel cursor-pointer" /></div>
            </div>
          </div>
        </div>

        {isNamingOpen && (
          <div className="absolute inset-0 z-[210] flex items-center justify-center bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
            <div className="bg-theme-side border border-theme-accent w-full max-w-md rounded-[2.5rem] p-10 shadow-[0_0_100px_rgba(79,70,229,0.3)] flex flex-col items-center gap-6">
              <div className="w-16 h-16 rounded-3xl bg-theme-accent flex items-center justify-center text-white text-2xl shadow-xl animate-bounce"><i className="fas fa-bookmark"></i></div>
              <div className="text-center"><h3 className="text-xl font-black uppercase tracking-tighter text-theme-main">Nomear Padrão</h3><p className="text-[10px] opacity-40 uppercase tracking-widest mt-1">Sua biblioteca pessoal Miau</p></div>
              <input type="text" autoFocus value={newPresetName} onChange={(e) => setNewPresetName(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleFinalSave(false)} className="w-full bg-theme-panel border border-theme px-6 py-4 rounded-2xl outline-none focus:border-theme-accent text-sm font-bold transition-all text-center" placeholder="Ex: Minha Borda Estrelada" />
              <div className="w-full flex flex-col gap-3">{selectedPresetId ? (<div className="grid grid-cols-2 gap-3 w-full"><button onClick={() => handleFinalSave(true)} className="py-4 rounded-2xl bg-theme-accent text-white font-black uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all">Atualizar Atual</button><button onClick={() => handleFinalSave(false)} className="py-4 rounded-2xl bg-theme-panel border border-theme text-theme-main font-black uppercase text-[10px] tracking-widest active:scale-95 transition-all">Novo Registro</button></div>) : (<button onClick={() => handleFinalSave(false)} className="w-full py-4 rounded-2xl bg-theme-accent text-white font-black uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all">Salvar na Biblioteca</button>)}<button onClick={() => setIsNamingOpen(false)} className="w-full py-3 rounded-2xl text-[9px] font-black uppercase opacity-30 hover:opacity-100 transition-all">Cancelar</button></div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdvancedBorderModal;

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { AdvancedBorderSettings, PatternPreset } from '../types';

interface AdvancedBorderModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: AdvancedBorderSettings;
  onUpdate: (s: AdvancedBorderSettings) => void;
  baseImage: { url: string, width: number, height: number } | null;
}

const PresetThumbnail: React.FC<{ settings: AdvancedBorderSettings }> = ({ settings }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const size = 64; canvas.width = size; canvas.height = size;
    const s = size / 520; ctx.clearRect(0, 0, size, size); ctx.fillStyle = settings.bgColor; ctx.fillRect(0, 0, size, size);
    const drawShape = (c: CanvasRenderingContext2D, type: string, sz: number) => {
      const h = sz / 2; c.beginPath();
      if (type === 'circle') c.arc(0, 0, h, 0, Math.PI * 2);
      else if (type === 'square') c.rect(-h, -h, sz, sz);
      else if (type === 'triangle') { c.moveTo(0, -h); c.lineTo(h, h); c.lineTo(-h, h); c.closePath(); }
      else if (type === 'x') { c.moveTo(-h, -h); c.lineTo(h, h); c.moveTo(h, -h); c.lineTo(-h, h); c.lineWidth = sz / 4; c.strokeStyle = c.fillStyle; c.stroke(); return; }
      else if (type === 'heart') { 
        const hr = sz * 0.4; c.moveTo(0, hr); 
        c.bezierCurveTo(-sz * 0.7, -sz * 0.1, -sz * 0.5, -sz * 0.9, 0, -sz * 0.4);
        c.bezierCurveTo(sz * 0.5, -sz * 0.9, sz * 0.7, -sz * 0.1, 0, hr);
      }
      else if (type === 'diamond') { c.moveTo(0, -h); c.lineTo(h, 0); c.lineTo(0, h); c.lineTo(-h, 0); c.closePath(); }
      c.fill();
    };
    if (settings.gridEnabled) {
      ctx.save(); ctx.translate(size / 2 + (settings.offsetX * s), size / 2 + (settings.offsetY * s)); ctx.rotate((settings.globalRotation * Math.PI) / 180); ctx.translate(-size / 2, -size / 2); ctx.fillStyle = settings.color;
      const stepX = (settings.size + settings.spacingX) * s; const stepY = (settings.size + settings.spacingY) * s; const dSize = settings.size * s;
      for (let x = -size; x < size * 2; x += stepX) { for (let y = -size; y < size * 2; y += stepY) { ctx.save(); ctx.translate(x, y); ctx.rotate((settings.individualRotation * Math.PI) / 180); drawShape(ctx, settings.shapeType, dSize); ctx.restore(); } }
      ctx.restore();
    }
  }, [settings]);
  return <canvas ref={canvasRef} className="w-10 h-10 rounded-lg shadow-inner bg-black/20 border border-white/10" />;
};

const AdvancedBorderModal: React.FC<AdvancedBorderModalProps> = ({ isOpen, onClose, settings, onUpdate, baseImage }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [guideImg, setGuideImg] = useState<HTMLImageElement | null>(null);
  const [presets, setPresets] = useState<PatternPreset[]>([]);
  const [selectedPresetId, setSelectedPresetId] = useState<string | null>(null);
  const [isNamingOpen, setIsNamingOpen] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('miau_pattern_presets');
    if (saved) setPresets(JSON.parse(saved));
  }, []);

  const savePresets = (newPresets: PatternPreset[]) => { setPresets(newPresets); localStorage.setItem('miau_pattern_presets', JSON.stringify(newPresets)); };

  const previewScale = useMemo(() => { if (!baseImage) return 1; return 520 / Math.max(baseImage.width, baseImage.height); }, [baseImage]);
  const shapes: { id: AdvancedBorderSettings['shapeType'], icon: string }[] = [
    { id: 'circle', icon: 'fa-circle' }, { id: 'square', icon: 'fa-square' }, { id: 'triangle', icon: 'fa-caret-up' },
    { id: 'x', icon: 'fa-times' }, { id: 'heart', icon: 'fa-heart' }, { id: 'diamond', icon: 'fa-clone' }
  ];

  useEffect(() => { if (baseImage?.url) { const img = new Image(); img.src = baseImage.url; img.onload = () => setGuideImg(img); } }, [baseImage?.url]);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    const s = size / 2; ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') { ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath(); }
    else if (type === 'x') { ctx.moveTo(-s, -s); ctx.lineTo(s, s); ctx.moveTo(s, -s); ctx.lineTo(-s, s); ctx.lineWidth = size / 4; ctx.strokeStyle = ctx.fillStyle; ctx.stroke(); return; }
    else if (type === 'heart') {
      const hr = size * 0.4; ctx.moveTo(0, hr);
      ctx.bezierCurveTo(-size * 0.7, -size * 0.1, -size * 0.5, -size * 0.9, 0, -size * 0.4);
      ctx.bezierCurveTo(size * 0.5, -size * 0.9, size * 0.7, -size * 0.1, 0, hr);
    } else if (type === 'diamond') { ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath(); }
    ctx.fill();
  };

  const renderPreview = () => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return;
    const w = 520, h = 520; canvas.width = w; canvas.height = h; const s = previewScale; ctx.clearRect(0, 0, w, h);
    if (settings.gridEnabled) {
      ctx.save(); ctx.fillStyle = settings.bgColor; ctx.fillRect(0, 0, w, h); ctx.translate(w / 2 + (settings.offsetX * s), h / 2 + (settings.offsetY * s)); ctx.rotate((settings.globalRotation * Math.PI) / 180); ctx.translate(-w / 2, -h / 2); ctx.fillStyle = settings.color;
      const stepX = (settings.size + settings.spacingX) * s; const stepY = (settings.size + settings.spacingY) * s; const drawSize = settings.size * s;
      for (let x = -w; x < w * 2; x += stepX) { for (let y = -h; y < h * 2; y += stepY) { ctx.save(); ctx.translate(x, y); ctx.rotate((settings.individualRotation * Math.PI) / 180); drawShape(ctx, settings.shapeType, drawSize); ctx.restore(); } }
      ctx.restore();
    } else { ctx.fillStyle = settings.bgColor; ctx.fillRect(0, 0, w, h); }
    if (settings.scatterEnabled) {
      ctx.save(); ctx.fillStyle = settings.color; const steps = settings.scatterDensity; const radius = (Math.min(w, h) * 0.35) + (settings.scatterRadiusOffset * s); const drawSize = settings.scatterSize * s;
      for (let i = 0; i < steps; i++) { const angle = (i / steps) * Math.PI * 2; ctx.save(); ctx.translate(w / 2 + Math.cos(angle) * radius, h / 2 + Math.sin(angle) * radius); ctx.rotate(angle + (settings.scatterIndividualRotation * Math.PI) / 180); drawShape(ctx, settings.shapeType, drawSize); ctx.restore(); }
      ctx.restore();
    }
    if (guideImg) { ctx.save(); ctx.globalAlpha = 0.4; const ratio = Math.min(350 / guideImg.width, 350 / guideImg.height); const dw = guideImg.width * ratio, dh = guideImg.height * ratio; ctx.drawImage(guideImg, (w - dw) / 2, (h - dh) / 2, dw, dh); ctx.restore(); }
  };
  useEffect(() => { if (isOpen) renderPreview(); }, [isOpen, settings, guideImg, previewScale]);

  const handleSaveClick = () => { if (selectedPresetId) { setIsNamingOpen(true); const current = presets.find(p => p.id === selectedPresetId); setNewPresetName(current?.name || ''); } else { setIsNamingOpen(true); setNewPresetName(`Pattern ${presets.length + 1}`); } };
  const handleFinalSave = (overwrite: boolean) => { if (overwrite && selectedPresetId) { const updated = presets.map(p => p.id === selectedPresetId ? { ...p, settings, name: newPresetName } : p); savePresets(updated); } else { const newPreset: PatternPreset = { id: uuidv4(), name: newPresetName, settings: { ...settings }, createdAt: Date.now() }; savePresets([newPreset, ...presets]); setSelectedPresetId(newPreset.id); } setIsNamingOpen(false); };
  const deletePreset = (e: React.MouseEvent, id: string) => { e.stopPropagation(); savePresets(presets.filter(p => p.id !== id)); if (selectedPresetId === id) setSelectedPresetId(null); };

  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 backdrop-blur-xl bg-black/60 animate-in fade-in duration-300">
      <div className="bg-theme-side border border-theme w-full max-w-7xl rounded-[3rem] shadow-2xl flex overflow-hidden h-[90vh] relative">

        {/* BIBLIOTECA LATERAL (ESQUERDA) */}
        <aside className="w-64 border-r border-theme/30 flex flex-col bg-black/10">
          <div className="p-6 border-b border-theme/20">
            <h3 className="text-[10px] font-black uppercase tracking-[0.3em] opacity-40 mb-1">Miau Patterns</h3>
            <h4 className="text-sm font-black uppercase text-theme-accent">Biblioteca</h4>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {presets.length === 0 ? (
              <div className="h-40 flex flex-col items-center justify-center text-center opacity-20 p-4"><i className="fas fa-layer-group text-2xl mb-2"></i><p className="text-[9px] font-black uppercase">Nenhum padrão salvo</p></div>
            ) : (
              presets.map(p => (
                <div key={p.id} onClick={() => { onUpdate(p.settings); setSelectedPresetId(p.id); }} className={`group flex items-center gap-3 p-2 rounded-2xl border transition-all cursor-pointer ${selectedPresetId === p.id ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/20 border-transparent hover:border-theme'}`}><PresetThumbnail settings={p.settings} /><div className="flex-1 min-w-0"><p className="text-[9px] font-black uppercase truncate text-theme-main">{p.name}</p><p className="text-[7px] opacity-40 uppercase">Design #{p.id.slice(0,4)}</p></div><button onClick={(e) => deletePreset(e, p.id)} className="opacity-0 group-hover:opacity-100 p-2 text-theme-muted hover:text-red-500 transition-all"><i className="fas fa-trash-alt text-[10px]"></i></button></div>
              ))
            )}
          </div>

          {/* BOTÃO SALVAR NA BASE DA BIBLIOTECA */}
          <div className="p-4 border-t border-theme/20 bg-theme-panel/10">
             <button 
                onClick={handleSaveClick} 
                className="w-full py-3.5 rounded-2xl bg-theme-accent text-white font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 hover:bg-theme-accent/90 transition-all flex items-center justify-center gap-2"
             >
                <i className="fas fa-bookmark"></i>
                {selectedPresetId ? 'Atualizar Estampa' : 'Salvar Estampa'}
             </button>
          </div>
        </aside>

        {/* ÁREA CENTRAL */}
        <div className="flex-1 bg-black/5 flex flex-col items-center justify-center relative p-10 gap-6">
           <div className="absolute top-8 left-8 flex items-center gap-3"><div className="w-10 h-10 rounded-2xl bg-theme-accent flex items-center justify-center text-white shadow-lg rotate-3"><i className="fas fa-wand-magic-sparkles"></i></div><div className="flex flex-col"><span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-40">Editor Pro</span><span className="text-xl font-black tracking-tighter uppercase">{selectedPresetId ? presets.find(p=>p.id===selectedPresetId)?.name : 'Novo Padrão'}</span></div></div>
           <div className="relative rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white/5 bg-theme-panel/20 p-2"><canvas ref={canvasRef} className="block rounded-[2rem] shadow-inner" /></div>
        </div>

        {/* CONTROLES (DIREITA) */}
        <div className="w-[400px] p-8 flex flex-col gap-6 overflow-y-auto bg-theme-side custom-scrollbar border-l border-theme/30">
          <div className="flex justify-between items-center mb-2">
            <button 
              onClick={() => onUpdate({ ...settings, enabled: !settings.enabled })}
              className={`flex-1 flex items-center justify-center gap-3 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 transition-all ${settings.enabled ? 'bg-green-500 text-white' : 'bg-theme-accent text-white'}`}
            >
              <i className={`fas ${settings.enabled ? 'fa-check-circle' : 'fa-power-off'}`}></i>
              {settings.enabled ? 'Estampa Ativa na Borda' : 'Aplicar Estampa na Borda'}
            </button>

            <button onClick={onClose} className="ml-4 w-12 h-12 rounded-2xl bg-theme-panel hover:bg-red-500 hover:text-white text-theme-main transition-all flex items-center justify-center shadow-lg"><i className="fas fa-times"></i></button>
          </div>

          <div className="space-y-6">
            {/* STATUS MASTER */}
            <div className={`p-4 rounded-2xl border transition-all flex items-center justify-between ${settings.enabled ? 'bg-green-500/10 border-green-500/50' : 'bg-theme-panel/20 border-theme'}`}>
               <div className="flex flex-col">
                 <span className="text-[8px] font-black uppercase opacity-40">Status Master</span>
                 <span className={`text-[10px] font-black uppercase ${settings.enabled ? 'text-green-500' : 'opacity-20'}`}>{settings.enabled ? 'Renderizando' : 'Desativado'}</span>
               </div>
               <button onClick={() => onUpdate({ ...settings, enabled: !settings.enabled })} className={`w-12 h-6 rounded-full relative transition-all ${settings.enabled ? 'bg-green-500' : 'bg-theme-panel'}`}>
                 <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.enabled ? 'right-1' : 'left-1'}`}></div>
               </button>
            </div>

            <div className="space-y-3 bg-theme-panel/20 p-4 rounded-2xl border border-theme/50">
              <label className="text-[9px] font-black uppercase opacity-40 tracking-widest">Shape Base</label>
              <div className="grid grid-cols-6 gap-2">{shapes.map(s => (<button key={s.id} onClick={() => onUpdate({ ...settings, shapeType: s.id })} className={`h-10 rounded-xl border flex items-center justify-center text-md transition-all ${settings.shapeType === s.id ? 'bg-theme-accent text-white border-theme-accent shadow-lg scale-105' : 'bg-theme-panel border-theme opacity-30 hover:opacity-100 hover:bg-theme-panel/50'}`}><i className={`fas ${s.icon}`}></i></button>))}</div>
            </div>

            <div className="space-y-4">
              <div className="flex justify-between items-center border-b border-theme/20 pb-2">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-theme-accent">Grid Engine</h4>
                <button onClick={() => onUpdate({ ...settings, gridEnabled: !settings.gridEnabled })} className={`w-8 h-4 rounded-full relative transition-all ${settings.gridEnabled ? 'bg-theme-accent' : 'bg-theme-panel'}`}><div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-all ${settings.gridEnabled ? 'right-0.5' : 'left-0.5'}`}></div></button>
              </div>
              <div className={`grid grid-cols-2 gap-x-4 gap-y-4 transition-all ${!settings.gridEnabled ? 'opacity-20 pointer-events-none grayscale' : ''}`}>
                 {[
                   { label: 'Size', key: 'size', min: 2, max: 200 },
                   { label: 'Spacing X', key: 'spacingX', min: 0, max: 200 },
                   { label: 'Spacing Y', key: 'spacingY', min: 0, max: 200 },
                   { label: 'Rotate Shape', key: 'individualRotation', min: 0, max: 360 },
                   { label: 'Giro Global', key: 'globalRotation', min: 0, max: 360 },
                   { label: 'Offset X', key: 'offsetX', min: -1000, max: 1000 },
                   { label: 'Offset Y', key: 'offsetY', min: -1000, max: 1000 },
                 ].map(ctrl => (
                  <div key={ctrl.key} className="space-y-1"><div className="flex justify-between items-center px-1"><label className="text-[8px] font-black uppercase opacity-40">{ctrl.label}</label><span className="text-[8px] font-mono font-bold text-theme-accent">{(settings as any)[ctrl.key]}</span></div><input type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]} onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })} className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent" /></div>
                 ))}
              </div>
            </div>

            <div className="space-y-4 pt-4 border-t border-theme/20">
              <div className="flex justify-between items-center border-b border-theme/20 pb-2">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-theme-accent">Scatter Engine</h4>
                <button onClick={() => onUpdate({ ...settings, scatterEnabled: !settings.scatterEnabled })} className={`w-8 h-4 rounded-full relative transition-all ${settings.scatterEnabled ? 'bg-theme-accent' : 'bg-theme-panel'}`}><div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-all ${settings.scatterEnabled ? 'right-0.5' : 'left-0.5'}`}></div></button>
              </div>
              <div className={`grid grid-cols-2 gap-x-4 gap-y-4 transition-all ${!settings.scatterEnabled ? 'opacity-20 pointer-events-none grayscale' : ''}`}>
                 {[
                   { label: 'Scatter Size', key: 'scatterSize', min: 5, max: 200 },
                   { label: 'Density', key: 'scatterDensity', min: 4, max: 100 },
                   { label: 'Radius', key: 'scatterRadiusOffset', min: -500, max: 500 },
                 ].map(ctrl => (
                  <div key={ctrl.key} className="space-y-1"><div className="flex justify-between items-center px-1"><label className="text-[8px] font-black uppercase opacity-40">{ctrl.label}</label><span className="text-[8px] font-mono font-bold text-theme-accent">{(settings as any)[ctrl.key]}</span></div><input type="range" min={ctrl.min} max={ctrl.max} value={(settings as any)[ctrl.key]} onChange={(e) => onUpdate({ ...settings, [ctrl.key]: parseInt(e.target.value) })} className="w-full h-1 bg-theme-panel rounded-full appearance-none accent-theme-accent" /></div>
                 ))}
              </div>
            </div>

            <div className="flex gap-4 pt-4 border-t border-theme/20">
               <div className="flex-1 space-y-2"><label className="text-[9px] font-black uppercase opacity-40 block text-center">Shapes</label><input type="color" value={settings.color} onChange={(e) => onUpdate({ ...settings, color: e.target.value })} className="w-full h-10 rounded-xl border border-theme p-1 bg-theme-panel cursor-pointer" /></div>
               <div className="flex-1 space-y-2"><label className="text-[9px] font-black uppercase opacity-40 block text-center">Background</label><input type="color" value={settings.bgColor} onChange={(e) => onUpdate({ ...settings, bgColor: e.target.value })} className="w-full h-10 rounded-xl border border-theme p-1 bg-theme-panel cursor-pointer" /></div>
            </div>
