import React, { useRef, useState, useEffect } from 'react';

interface MiauSliderProps {
  label: string;
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  unit?: string;
  step?: number;
  icon?: string;
}

const MiauSlider: React.FC<MiauSliderProps> = ({ label, value, min, max, onChange, unit = '', step = 1, icon }) => {
  const [isDragging, setIsDragging] = useState(false);
  const sliderRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef({ lastX: 0, startValue: 0 });

  const handlePointerDown = (e: React.PointerEvent) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    setIsDragging(true);
    dragRef.current = { lastX: e.clientX, startValue: value };

    // Feedback visual global
    document.body.style.cursor = 'ew-resize';
    const style = document.createElement('style');
    style.id = 'miau-slider-active';
    style.innerHTML = '*{ cursor: ew-resize !important; user-select: none !important; }';
    document.head.appendChild(style);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDragging) return;

    const deltaX = e.clientX - dragRef.current.lastX;
    dragRef.current.lastX = e.clientX;

    // Sensibilidade baseada no range
    const range = max - min;
    const sensitivity = range > 100 ? 0.5 : 0.1;
    let newValue = value + (deltaX * sensitivity);

    // Snap para o step
    newValue = Math.round(newValue / step) * step;
    newValue = Math.max(min, Math.min(max, newValue));

    if (newValue !== value) {
      onChange(newValue);
    }
  };

  const handlePointerUp = () => {
    setIsDragging(false);
    document.body.style.cursor = '';
    document.getElementById('miau-slider-active')?.remove();
  };

  // Porcentagem para o preenchimento visual
  const percentage = ((value - min) / (max - min)) * 100;

  return (
    <div className="group space-y-1.5 w-full">
      <div className="flex justify-between items-center px-1">
        <label className="text-[8px] font-black uppercase opacity-40 tracking-wider group-hover:opacity-100 group-hover:text-theme-accent transition-all">
          {label}
        </label>
        <span className="text-[9px] font-mono font-black text-theme-accent bg-theme-accent/5 px-2 py-0.5 rounded-md border border-theme-accent/10">
          {value}{unit}
        </span>
      </div>

      <div 
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
        className={`relative h-9 bg-theme-panel/30 border rounded-xl cursor-ew-resize transition-all flex items-center px-3 gap-3 overflow-hidden ${isDragging ? 'border-theme-accent ring-2 ring-theme-accent/15 shadow-lg bg-theme-accent/5' : 'border-theme hover:border-theme-accent/40'}`}
      >
        {icon && <i className={`fas ${icon} text-[10px] ${isDragging ? 'text-theme-accent' : 'opacity-20'}`}></i>}

        <div className="flex-1 h-1 bg-theme/10 rounded-full relative overflow-hidden">
          <div 
            className={`absolute inset-y-0 left-0 bg-theme-accent transition-all duration-75 shadow-[0_0_10px_rgba(79,70,229,0.3)] ${isDragging ? 'opacity-100' : 'opacity-60'}`}
            style={{ width: `${percentage}%` }}
          />
        </div>

        {/* Marcadores de graduação sutis */}
        <div className="absolute inset-x-0 bottom-0 h-0.5 flex justify-between px-1 opacity-10">
          {[...Array(10)].map((_, i) => (
            <div key={i} className="w-[1px] h-full bg-white" />
          ))}
        </div>
      </div>
    </div>
  );
};

