// Helper de Desenho unificado para patinha fofa
const drawCatPawInternal = (ctx: CanvasRenderingContext2D, size: number) => {
  const s = size / 2;
  ctx.beginPath();
  ctx.moveTo(-s * 0.7, s * 0.2);
  ctx.bezierCurveTo(-s * 0.8, -s * 0.4, s * 0.8, -s * 0.4, s * 0.7, s * 0.2);
  ctx.bezierCurveTo(s * 0.6, s * 0.7, -s * 0.6, s * 0.7, -s * 0.7, s * 0.2);
  ctx.fill();
  const toeY = -s * 0.4;
  const toeRadius = s * 0.22;
  ctx.beginPath(); ctx.arc(-s * 0.55, -s * 0.1, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(-s * 0.2, toeY - s * 0.15, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(s * 0.2, toeY - s * 0.15, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(s * 0.55, -s * 0.1, toeRadius, 0, Math.PI * 2); ctx.fill();
};

