              <div className="text-center"><h3 className="text-xl font-black uppercase tracking-tighter text-theme-main">Nomear Padrão</h3><p className="text-[10px] opacity-40 uppercase tracking-widest mt-1">Sua biblioteca pessoal Miau</p></div>
              <input type="text" autoFocus value={newPresetName} onChange={(e) => setNewPresetName(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleFinalSave(false)} className="w-full bg-theme-panel border border-theme px-6 py-4 rounded-2xl outline-none focus:border-theme-accent text-sm font-bold transition-all text-center" placeholder="Ex: Minha Borda Estrelada" />
              <div className="w-full flex flex-col gap-3">{selectedPresetId ? (<div className="grid grid-cols-2 gap-3 w-full"><button onClick={() => handleFinalSave(true)} className="py-4 rounded-2xl bg-theme-accent text-white font-black uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all">Atualizar Atual</button><button onClick={() => handleFinalSave(false)} className="py-4 rounded-2xl bg-theme-panel border border-theme text-theme-main font-black uppercase text-[10px] tracking-widest active:scale-95 transition-all">Novo Registro</button></div>) : (<button onClick={() => handleFinalSave(false)} className="w-full py-4 rounded-2xl bg-theme-accent text-white font-black uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all">Salvar na Biblioteca</button>)}<button onClick={() => setIsNamingOpen(false)} className="w-full py-3 rounded-2xl text-[9px] font-black uppercase opacity-30 hover:opacity-100 transition-all">Cancelar</button></div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdvancedBorderModal;

import React, { useRef, useState, useEffect } from 'react';

interface MiauSliderProps {
  label: string;
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  unit?: string;
  step?: number;
  icon?: string;
}

const MiauSlider: React.FC<MiauSliderProps> = ({ label, value, min, max, onChange, unit = '', step = 1, icon }) => {
  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef({ lastX: 0, startValue: 0, accumulatedDelta: 0 });

  const handlePointerDown = (e: React.PointerEvent) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    setIsDragging(true);
    dragRef.current = { 
      lastX: e.clientX, 
      startValue: value,
      accumulatedDelta: 0
    };

    // Esconde o cursor globalmente e aplica o estilo de arrasto
    const style = document.createElement('style');
    style.id = 'miau-dragging-cursor';
    style.innerHTML = '*{ cursor: none !important; user-select: none !important; }';
    document.head.appendChild(style);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDragging) return;

    // Usamos movementX para o efeito "Pac-Man" (delta infinito independente da posição do cursor)
    const deltaX = e.movementX;

    // Sensibilidade baseada no range do slider
    const range = max - min;
    const sensitivity = range > 100 ? 0.4 : 0.05;

    // Acumula o movimento para precisão em valores decimais/pequenos
    dragRef.current.accumulatedDelta += deltaX * sensitivity;

    const change = Math.trunc(dragRef.current.accumulatedDelta);
    if (change !== 0) {
      let newValue = value + change;
      // Snap para o step e limites
      newValue = Math.round(newValue / step) * step;
      newValue = Math.max(min, Math.min(max, newValue));

      if (newValue !== value) {
        onChange(newValue);
        dragRef.current.accumulatedDelta -= change;
      }
    }
  };

  const handlePointerUp = () => {
    setIsDragging(false);
    document.getElementById('miau-dragging-cursor')?.remove();
  };

  const percentage = ((value - min) / (max - min)) * 100;

  return (
    <div className="group space-y-1.5 w-full">
      <div className="flex justify-between items-center px-1">
        <label className={`text-[8px] font-black uppercase tracking-wider transition-all ${isDragging ? 'text-theme-accent opacity-100' : 'opacity-40 group-hover:opacity-70'}`}>
          {label}
        </label>
        <span className={`text-[9px] font-mono font-black px-2 py-0.5 rounded-md border transition-all ${isDragging ? 'bg-theme-accent text-white border-theme-accent shadow-[0_0_10px_rgba(79,70,229,0.4)]' : 'text-theme-accent bg-theme-accent/5 border-theme-accent/10'}`}>
          {value}{unit}
        </span>
      </div>

      <div 
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
        className={`relative h-9 bg-theme-panel/30 border rounded-xl cursor-ew-resize transition-all flex items-center px-3 gap-3 overflow-hidden 
          ${isDragging ? 'border-theme-accent ring-2 ring-theme-accent/30 shadow-[0_0_15px_rgba(79,70,229,0.2)] bg-theme-accent/10' : 'border-theme hover:border-theme-accent/40'}`}
      >
        {icon && <i className={`fas ${icon} text-[10px] transition-all ${isDragging ? 'text-theme-accent scale-110' : 'opacity-20'}`}></i>}

        <div className="flex-1 h-1 bg-theme/10 rounded-full relative overflow-hidden">
          <div 
            className={`absolute inset-y-0 left-0 bg-theme-accent transition-all duration-75 ${isDragging ? 'opacity-100 shadow-[0_0_8px_rgba(255,255,255,0.8)]' : 'opacity-60'}`}
            style={{ width: `${percentage}%` }}
          />
        </div>

        {/* Marcadores de graduação sutis */}
        <div className="absolute inset-x-0 bottom-0 h-0.5 flex justify-between px-1 opacity-10">
          {[...Array(10)].map((_, i) => (
            <div key={i} className="w-[1px] h-full bg-white" />
          ))}
        </div>
      </div>
    </div>
  );
};

