import React, { useState, useRef, useCallback, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import Sidebar from '../components/Sidebar';
import GridPreview from '../components/GridPreview';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage, GridSettings } from '../types';

const GridTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [settings, setSettings] = useState<GridSettings>({
    canvasWidth: 2048,
    canvasHeight: 2048,
    columns: 3,
    innerSpacing: 20,
    outerMargin: 40,
    backgroundColor: '#0f172a',
    isTransparent: false,
    layoutMode: 'grid',
    itemScale: 0,
    targetShape: 'square'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  const processFiles = async (files: File[]) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    const filteredFiles = files.filter(file => validTypes.includes(file.type));
    const newImages: GridImage[] = [];

    for (const file of filteredFiles) {
      try {
        const url = URL.createObjectURL(file);
        const img = await new Promise<HTMLImageElement>((resolve, reject) => {
          const i = new Image();
          i.onload = () => resolve(i);
          i.onerror = reject;
          i.src = url;
        });

        newImages.push({
          id: uuidv4(),
          file,
          previewUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height,
          isActive: true,
          visible: true
        });
      } catch (err) {
        console.error("Erro ao processar imagem:", file.name);
      }
    }

    if (newImages.length > 0) {
      setImages(prev => [...prev, ...newImages]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      let filesArray = Array.from(e.target.files) as File[];
      processFiles(filesArray);
    }
    if (e.target) e.target.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => {
      const target = prev.find(img => img.id === id);
      if (target) URL.revokeObjectURL(target.previewUrl);
      return prev.filter(img => img.id !== id);
    });
  };

  const toggleActive = (id: string) => {
    setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img));
  };

  const updateActiveCount = (count: number) => {
    setImages(prev => prev.map((img, idx) => ({
      ...img,
      isActive: idx < count
    })));
  };

  const moveImage = (index: number, direction: 'up' | 'down') => {
    const newImages = [...images];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex >= 0 && targetIndex < newImages.length) {
      [newImages[index], newImages[targetIndex]] = [newImages[targetIndex], newImages[index]];
      setImages(newImages);
    }
  };

  const handleExport = async () => {
    const canvas = document.querySelector('canvas') as HTMLCanvasElement;
    if (!canvas) return;
    const fileName = `grid_miau_${Date.now()}.png`;
    const dataUrl = canvas.toDataURL('image/png', 1.0);

    if (downloadIndividual) {
      const link = document.createElement('a');
      link.download = fileName; link.href = dataUrl; link.click();
    }
    if (downloadZip) {
      const zip = new JSZip();
      zip.file(fileName, dataUrl.split(',')[1], { base64: true });
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `grid_pack_miau_${Date.now()}.zip`; link.click();
    }
  };

  const clearAll = useCallback(() => {
    images.forEach(img => { if (img.previewUrl) URL.revokeObjectURL(img.previewUrl); });
    setImages([]); setOffset({ x: 0, y: 0 }); setZoom(0.4);
  }, [images]);

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 flex-shrink-0 border-r overflow-y-auto bg-theme-side border-theme custom-scrollbar">
        <Sidebar 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddFile={() => fileInputRef.current?.click()}
          onAddFolder={() => folderInputRef.current?.click()}
          images={images}
          onUpdateActiveCount={updateActiveCount}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onExport={handleExport}
        />
      </aside>

      <section className="flex-1 overflow-hidden relative flex flex-col">
        <Header itemCount={images.length} onClear={clearAll} />

        <div className="flex-1 relative flex flex-col items-center justify-center bg-black/5 overflow-hidden">
          <div className="flex-1 w-full h-full cursor-grab active:cursor-grabbing">
            <GridPreview 
              images={images} 
              settings={settings} 
              zoom={zoom} 
              offset={offset}
              onOffsetChange={setOffset}
            />
          </div>

          {/* PAINEL DE INFO FLUTUANTE */}
          {images.length > 0 && (
            <div className="absolute bottom-10 left-10 flex flex-col items-start gap-4 animate-in fade-in slide-in-from-left-4 duration-700 pointer-events-none z-50">
              <div className="flex items-center gap-4 bg-theme-side/90 border border-theme/40 px-6 py-3 rounded-full shadow-2xl backdrop-blur-3xl">
                <div className="flex flex-col items-start leading-none gap-1.5">
                  <span className="text-[7px] font-black uppercase opacity-30 tracking-[0.2em]">GRID ENGINE</span>
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${settings.layoutMode === 'auto' ? 'bg-theme-accent animate-pulse shadow-[0_0_8px_rgba(79,70,229,0.8)]' : 'bg-theme-muted'}`}></div>
                    <span className="text-[10px] font-mono font-bold opacity-60">
                      {settings.layoutMode === 'auto' ? 'Auto-Flow active' : 'Manual Placement'}
                    </span>
                  </div>
                </div>

                <div className="w-[1px] h-8 bg-theme/20"></div>

                <div className="flex flex-col items-start leading-none gap-1">
                  <span className="text-[7px] font-black uppercase text-theme-accent tracking-widest">Master Resolution</span>
                  <span className="text-[12px] font-mono font-black text-theme-accent tracking-tighter">
                    {Math.round(settings.canvasWidth)}<span className="opacity-30 mx-1">×</span>{settings.layoutMode === 'auto' ? 'Dynamic' : settings.canvasHeight}
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* VIEW CONTROLLER GLASS */}
          <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-8 bg-theme-side/90 border border-theme/40 py-2.5 px-8 rounded-full shadow-2xl backdrop-blur-xl z-50">
            <div className="flex items-center gap-4 pr-8 border-r border-theme/30">
              <i className="fas fa-search text-[10px] opacity-30"></i>
              <input type="range" min="0.05" max="2" step="0.01" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-48 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
              <span className="text-[10px] font-mono opacity-40 w-12 text-center">{Math.round(zoom * 100)}%</span>
            </div>
            <button onClick={() => { setOffset({ x: 0, y: 0 }); setZoom(0.4); }} className="w-9 h-9 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main transition-all group active:scale-90" title="Reset Viewport">
              <i className="fas fa-undo-alt text-[10px] opacity-40 group-hover:opacity-100 group-hover:rotate-[-45deg] transition-all"></i>
            </button>
          </div>
        </div>
      </section>

      <aside className="w-80 flex-shrink-0 border-l overflow-hidden flex flex-col bg-theme-side border-theme">
        <div className="p-4 border-b font-black text-[10px] uppercase tracking-[0.2em] flex justify-between items-center text-theme-muted bg-black/5">
          <span>Item Manager</span>
          <i className="fas fa-layer-group opacity-30"></i>
        </div>
        <ImageList 
          images={images} 
          onRemove={removeImage} 
          onMove={moveImage}
          onToggleActive={toggleActive}
        />
      </aside>

      <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
      <input type="file" {...({ webkitdirectory: "" } as any)} className="hidden" ref={folderInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default GridTool;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { GridImage, GridSettings } from '../types';

interface GridPreviewProps {
  images: GridImage[];
  settings: GridSettings;
  zoom?: number;
  offset: { x: number, y: number };
  onOffsetChange: (offset: { x: number, y: number }) => void;
}

const GridPreview: React.FC<GridPreviewProps> = ({ 
  images, 
  settings, 
  zoom = 0.4,
  offset,
  onOffsetChange
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const imageCache = useRef<Map<string, HTMLImageElement>>(new Map());
  const [currentCanvasHeight, setCurrentCanvasHeight] = useState(settings.canvasHeight);
  const [calculatedCols, setCalculatedCols] = useState(settings.columns);
  const [isDragging, setIsDragging] = useState(false);

  const activeImages = images.filter(img => img.isActive);

  useEffect(() => {
    const loadImages = async () => {
      const promises = activeImages.map(img => {
        if (imageCache.current.has(img.id)) return Promise.resolve();
        return new Promise<void>((resolve) => {
          const i = new Image();
          i.onload = () => {
            imageCache.current.set(img.id, i);
            resolve();
          };
          i.src = img.previewUrl;
        });
      });
      await Promise.all(promises);
      drawGrid();
    };
    loadImages();
  }, [images]);

  const drawGrid = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const isAuto = settings.layoutMode === 'auto';
    const margin = settings.outerMargin;
    const spacing = settings.innerSpacing;
    const scaleFactor = 1 + ((settings.itemScale || 0) / 100);

    let cols = settings.columns;

    if (isAuto && activeImages.length > 0) {
      let targetRatio = 1;
      if (settings.targetShape === 'portrait') targetRatio = 0.65;
      if (settings.targetShape === 'landscape') targetRatio = 1.6;
      const avgItemRatio = activeImages.reduce((acc, img) => acc + img.aspectRatio, 0) / activeImages.length;
      cols = Math.max(1, Math.round(Math.sqrt((targetRatio * activeImages.length) / avgItemRatio)));
      if (calculatedCols !== cols) setCalculatedCols(cols);
    }

    let finalCanvasWidth = settings.canvasWidth;
    let finalCanvasHeight = settings.canvasHeight;

    if (isAuto && activeImages.length > 0) {
      const baseCellWidth = (settings.canvasWidth - (2 * margin) - ((cols - 1) * spacing)) / cols;
      const cellWidth = baseCellWidth * scaleFactor;
      const cellHeight = cellWidth;
      const rows = Math.ceil(activeImages.length / cols);
      finalCanvasHeight = (rows * cellHeight) + (2 * margin) + ((rows - 1) * spacing);
      finalCanvasWidth = (cols * cellWidth) + (2 * margin) + ((cols - 1) * spacing);
      if (currentCanvasHeight !== finalCanvasHeight) setCurrentCanvasHeight(finalCanvasHeight);
    }

    canvas.width = finalCanvasWidth;
    canvas.height = finalCanvasHeight;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // FUNDO REAL NO CANVAS (Apenas se não for transparente)
    if (!settings.isTransparent) {
      ctx.fillStyle = settings.backgroundColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    if (activeImages.length === 0) return;

    const actualCellWidth = (canvas.width - (2 * margin) - ((cols - 1) * spacing)) / cols;
    const rows = Math.ceil(activeImages.length / cols);
    const actualCellHeight = (canvas.height - (2 * margin) - ((rows - 1) * spacing)) / rows;

    activeImages.forEach((imgObj, index) => {
      const img = imageCache.current.get(imgObj.id);
      if (!img) return;
      const col = index % cols;
      const row = Math.floor(index / cols);

      const x = margin + (col * (actualCellWidth + spacing));
      const y = margin + (row * (actualCellHeight + spacing));

      let drawW = actualCellWidth;
      let drawH = actualCellWidth / imgObj.aspectRatio;

      if (drawH > actualCellHeight) {
        drawH = actualCellHeight;
        drawW = actualCellHeight * imgObj.aspectRatio;
      }

      ctx.drawImage(img, x + (actualCellWidth - drawW) / 2, y + (actualCellHeight - drawH) / 2, drawW, drawH);
    });
  }, [activeImages, settings, currentCanvasHeight, calculatedCols]);

  useEffect(() => {
    drawGrid();
  }, [drawGrid, settings]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    containerRef.current?.setPointerCapture(1);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    onOffsetChange({ x: offset.x + e.movementX, y: offset.y + e.movementY });
  };

  const handleMouseUp = () => setIsDragging(false);

  const canvasWidth = canvasRef.current?.width || settings.canvasWidth;
  const canvasHeight = canvasRef.current?.height || settings.canvasHeight;

  return (
    <div 
      ref={containerRef}
      className="w-full h-full flex items-center justify-center relative select-none overflow-hidden"
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div 
        className="relative shadow-[0_40px_100px_rgba(0,0,0,0.5)] border-4 border-white/5 transition-all duration-300 rounded-[2.5rem] overflow-hidden"
        style={{
          width: canvasWidth * zoom,
          height: canvasHeight * zoom,
          transform: `translate(${offset.x}px, ${offset.y}px)`,
          // O FUNDO DO VIEWER REFLETE A COR DO TEMA OU A TRANSPARÊNCIA
          backgroundColor: settings.isTransparent ? 'transparent' : settings.backgroundColor,
          backgroundImage: settings.isTransparent ? 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)' : 'none',
          backgroundSize: '20px 20px'
        }}
      >
        <canvas ref={canvasRef} className="w-full h-full block pointer-events-none" />
      </div>
    </div>
  );
};

export default GridPreview;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarAlphaEdge from '../components/SidebarAlphaEdge';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import AdvancedBorderModal from '../components/AdvancedBorderModal';
import { GridImage, AlphaEdgeSettings, AdvancedBorderSettings } from '../types';

const DEFAULT_SETTINGS: AlphaEdgeSettings = {
  thickness: 20,
  softness: 5,
  borderScale: 100,
  opacity: 100,
  color: '#ffffff',
  advanced: {
    enabled: false,
    gridEnabled: true,
    scatterEnabled: false,
    shapeType: 'circle',
    size: 15,
    spacingX: 10,
    spacingY: 10,
    color: '#ffffff',
    backgroundType: 'solid',
    bgColor: '#000000',
    gradientAngle: 0,
    gradientStops: [
      { id: '1', color: '#1e293b', offset: 0 },
      { id: '2', color: '#4f46e5', offset: 1 }
    ],
    individualRotation: 0,
    globalRotation: 0,
    offsetX: 0,
    offsetY: 0,
    scatterSize: 20,
    scatterDensity: 40,
    scatterRadiusOffset: 0,
    scatterIndividualRotation: 0
  }
};

// Helper para desenhar a Patinha Miau 2.0 (Classic Bean)
const drawCatPawClassic = (ctx: CanvasRenderingContext2D, size: number) => {
  const s = size / 2;
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(0, s * 0.2, s * 0.65, s * 0.5, 0, 0, Math.PI * 2);
  ctx.fill();
  const toeRadius = s * 0.22;
  ctx.beginPath(); ctx.arc(-s * 0.5, -s * 0.25, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(-s * 0.18, -s * 0.5, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(s * 0.18, -s * 0.5, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(s * 0.5, -s * 0.25, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
};

const AlphaEdgeTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [autoSave, setAutoSave] = useState(true);
  const customShapeImgs = useRef<Map<string, HTMLImageElement>>(new Map());

  const [batchSettings, setBatchSettings] = useState<Record<string, AlphaEdgeSettings>>({});
  const [settings, setSettings] = useState<AlphaEdgeSettings>(DEFAULT_SETTINGS);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  const currentImg = images[selectedIdx];

  useEffect(() => {
    const urlsToLoad = new Set<string>();
    if (settings.advanced?.shapeType === 'custom' && settings.advanced?.customShapeUrl) {
      urlsToLoad.add(settings.advanced.customShapeUrl);
    }
    // Fix: Explicitly type 's' as AlphaEdgeSettings to prevent 'unknown' property access errors.
    Object.values(batchSettings).forEach((s: AlphaEdgeSettings) => {
      if (s.advanced?.shapeType === 'custom' && s.advanced?.customShapeUrl) {
        urlsToLoad.add(s.advanced.customShapeUrl);
      }
    });

    urlsToLoad.forEach(url => {
      if (!customShapeImgs.current.has(url)) {
        const img = new Image();
        img.src = url;
        img.onload = () => {
          customShapeImgs.current.set(url, img);
          if (settings.advanced?.customShapeUrl === url && currentImg) {
             const previewImg = new Image();
             previewImg.src = currentImg.previewUrl;
             previewImg.onload = () => drawEdge(previewImg, previewCanvasRef.current!, settings);
          }
        };
      }
    });
  }, [settings, batchSettings, currentImg]);

  const handleSettingsChange = (newSettings: AlphaEdgeSettings) => {
    setSettings(newSettings);
    if (autoSave && currentImg) {
      setBatchSettings(prev => ({ ...prev, [currentImg.id]: newSettings }));
    }
  };

  const applyToAll = () => {
    const newBatch: Record<string, AlphaEdgeSettings> = {};
    images.forEach(img => { newBatch[img.id] = { ...settings }; });
    setBatchSettings(newBatch);
  };

  const navigateTo = (newIdx: number) => {
    const nextImg = images[newIdx];
    if (nextImg) {
      if (batchSettings[nextImg.id]) {
        setSettings(batchSettings[nextImg.id]);
      } else if (autoSave) {
        setBatchSettings(prev => ({ ...prev, [nextImg.id]: settings }));
      }
      setSelectedIdx(newIdx);
    }
  };

  const getScaledPadding = useCallback((imgW: number, imgH: number, s: AlphaEdgeSettings) => {
    const scale = s.borderScale / 100;
    const effectiveBorder = s.thickness + (s.softness * 2.5);
    const maxHalf = Math.max(imgW, imgH) / 2;
    const radialPadding = (maxHalf + effectiveBorder) * scale - maxHalf;
    return Math.ceil(Math.max(20, radialPadding)); 
  }, []);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number, customUrl?: string) => {
    if (type === 'none') return;
    const s = size / 2;
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') { ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath(); }
    else if (type === 'heart') {
      const h = size * 0.4; ctx.moveTo(0, h);
      ctx.bezierCurveTo(-size * 0.7, -size * 0.1, -size * 0.5, -size * 0.9, 0, -size * 0.4);
      ctx.bezierCurveTo(size * 0.5, -size * 0.9, size * 0.7, -size * 0.1, 0, h);
    } else if (type === 'diamond') { ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath(); }
    else if (type === 'pata') { drawCatPawClassic(ctx, size); return; }
    else if (type === 'custom' && customUrl && customShapeImgs.current.has(customUrl)) {
      ctx.drawImage(customShapeImgs.current.get(customUrl)!, -s, -s, size, size);
      return;
    }
    ctx.fill();
  };

  const applyBackground = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    if (config.backgroundType === 'solid') {
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, w, h);
    } else {
      const angle = (config.gradientAngle * Math.PI) / 180;
      const x1 = w/2 - Math.cos(angle) * w/2;
      const y1 = h/2 - Math.sin(angle) * h/2;
      const x2 = w/2 + Math.cos(angle) * w/2;
      const y2 = h/2 + Math.sin(angle) * h/2;
      const grad = ctx.createLinearGradient(x1, y1, x2, y2);
      config.gradientStops.forEach(stop => grad.addColorStop(Math.max(0, Math.min(1, stop.offset)), stop.color));
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, w, h);
    }
  };

  const drawPattern = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    ctx.save();
    applyBackground(ctx, w, h, config);
    if (config.gridEnabled && config.shapeType !== 'none') {
      ctx.translate(w / 2 + config.offsetX, h / 2 + config.offsetY);
      ctx.rotate((config.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = config.color;
      const stepX = config.size + config.spacingX;
      const stepY = config.size + config.spacingY;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save(); ctx.translate(x, y); ctx.rotate((config.individualRotation * Math.PI) / 180);
          drawShape(ctx, config.shapeType, config.size, config.customShapeUrl); ctx.restore();
        }
      }
    }
    ctx.restore();
  };

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings) => {
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;
    const bScale = config.borderScale / 100;
    const finalPadding = getScaledPadding(img.width, img.height, config);
    canvas.width = img.width + (finalPadding * 2); canvas.height = img.height + (finalPadding * 2);
    const centerX = canvas.width / 2; const centerY = canvas.height / 2;
    const unitPadding = config.thickness + (config.softness * 2.5) + 30;
    const unitCanvas = document.createElement('canvas');
    unitCanvas.width = img.width + (unitPadding * 2); unitCanvas.height = img.height + (unitPadding * 2);
    const uCtx = unitCanvas.getContext('2d');
    if (!uCtx) return;
    const silCanvas = document.createElement('canvas');
    silCanvas.width = unitCanvas.width; silCanvas.height = unitCanvas.height;
    const sCtx = silCanvas.getContext('2d');
    if (sCtx) {
      sCtx.translate(unitPadding, unitPadding); sCtx.drawImage(img, 0, 0);
      sCtx.globalCompositeOperation = 'source-in'; sCtx.fillStyle = '#ffffff';
      sCtx.fillRect(-unitPadding, -unitPadding, unitCanvas.width, unitCanvas.height);
    }
    const maskCanvas = document.createElement('canvas');
    maskCanvas.width = unitCanvas.width; maskCanvas.height = unitCanvas.height;
    const mCtx = maskCanvas.getContext('2d');
    if (mCtx) {
      if (config.thickness > 0) {
        const steps = 72;
        for (let i = 0; i < steps; i++) {
          const angle = (i / steps) * Math.PI * 2;
          mCtx.drawImage(silCanvas, Math.cos(angle) * config.thickness, Math.sin(angle) * config.thickness);
        }
      }
      mCtx.drawImage(silCanvas, 0, 0);
      if (config.softness > 0) {
        const temp = document.createElement('canvas');
        temp.width = unitCanvas.width; temp.height = unitCanvas.height;
        const tCtx = temp.getContext('2d');
        if (tCtx) { tCtx.filter = `blur(${config.softness}px)`; tCtx.drawImage(maskCanvas, 0, 0); mCtx.clearRect(0, 0, maskCanvas.width, maskCanvas.height); mCtx.drawImage(temp, 0, 0); }
      }
    }
    uCtx.save();
    if (config.advanced?.enabled) drawPattern(uCtx, unitCanvas.width, unitCanvas.height, config.advanced);
    else { uCtx.fillStyle = config.color; uCtx.fillRect(0, 0, unitCanvas.width, unitCanvas.height); }
    uCtx.globalCompositeOperation = 'destination-in'; uCtx.drawImage(maskCanvas, 0, 0); uCtx.restore();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save(); ctx.globalAlpha = config.opacity / 100; ctx.translate(centerX, centerY); ctx.scale(bScale, bScale); ctx.drawImage(unitCanvas, -unitCanvas.width / 2, -unitCanvas.height / 2); ctx.restore();
    ctx.save(); ctx.translate(centerX - img.width / 2, centerY - img.height / 2); ctx.drawImage(img, 0, 0); ctx.restore();
  }, [getScaledPadding]);

  useEffect(() => {
    const updatePreview = async () => {
      if (!previewCanvasRef.current || !currentImg) return;
      const img = new Image(); img.src = currentImg.previewUrl;
      img.onload = () => drawEdge(img, previewCanvasRef.current!, settings);
    };
    updatePreview();
  }, [selectedIdx, currentImg, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = []; const newBatchStates: Record<string, AlphaEdgeSettings> = {};
    for (const file of files) {
      const id = uuidv4(); const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => { const i = new Image(); i.onload = () => resolve(i); i.src = url; });
      newImgs.push({ id, file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height, isActive: true });
      newBatchStates[id] = { ...settings };
    }
    setImages(prev => [...prev, ...newImgs]);
    setBatchSettings(prev => ({ ...prev, ...newBatchStates }));
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    const zip = downloadZip ? new JSZip() : null;
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i]; const currentConfig = batchSettings[item.id] || settings;
      const img = await new Promise<HTMLImageElement>((resolve) => { const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl; });
      await drawEdge(img, canvas, currentConfig);
      const dataUrl = canvas.toDataURL('image/png');
      const fileName = `${item.file.name.split('.')[0]}_miau.png`;
      if (downloadIndividual) {
        const link = document.createElement('a'); link.download = fileName; link.href = dataUrl; link.click();
        await new Promise(r => setTimeout(r, 400));
      }
      if (zip) zip.file(fileName, dataUrl.split(',')[1], { base64: true });
    }
    if (zip) {
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a'); link.href = URL.createObjectURL(content); link.download = `alpha_edge_batch_${Date.now()}.zip`; link.click();
    }
    setIsProcessing(false);
  };

  const handleExportGrid = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const cols = Math.ceil(Math.sqrt(images.length));
    const rows = Math.ceil(images.length / cols);
    const itemBuffers: HTMLCanvasElement[] = [];
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i]; const currentConfig = batchSettings[item.id] || settings;
      const img = await new Promise<HTMLImageElement>((resolve) => { const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl; });
      const bCanvas = document.createElement('canvas');
      await drawEdge(img, bCanvas, currentConfig);
      itemBuffers.push(bCanvas);
    }
    const maxW = Math.max(...itemBuffers.map(b => b.width));
    const maxH = Math.max(...itemBuffers.map(b => b.height));
    const spacing = 40;
    const masterCanvas = document.createElement('canvas');
    masterCanvas.width = (maxW * cols) + (spacing * (cols + 1));
    masterCanvas.height = (maxH * rows) + (spacing * (rows + 1));
    const mCtx = masterCanvas.getContext('2d');
    if (!mCtx) return;
    itemBuffers.forEach((buf, idx) => {
      const col = idx % cols; const row = Math.floor(idx / cols);
      const x = spacing + col * (maxW + spacing) + (maxW - buf.width) / 2;
      const y = spacing + row * (maxH + spacing) + (maxH - buf.height) / 2;
      mCtx.drawImage(buf, x, y);
    });
    const link = document.createElement('a'); link.download = `alpha_grid_miau_${Date.now()}.png`; link.href = masterCanvas.toDataURL('image/png'); link.click();
    setIsProcessing(false);
  };

  const currentPadding = currentImg ? getScaledPadding(currentImg.width, currentImg.height, settings) : 0;

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={handleSettingsChange}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onOpenAdvanced={() => setIsModalOpen(true)}
          autoSave={autoSave} onAutoSaveChange={setAutoSave}
          onApplyToAll={applyToAll}
          onExportGrid={handleExportGrid}
        />
      </aside>
      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => { setImages([]); setBatchSettings({}); }} />
        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-[2.5rem]"
                style={{ 
                  width: (currentImg.width + currentPadding * 2) * zoom,
                  height: (currentImg.height + currentPadding * 2) * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <canvas ref={previewCanvasRef} className="w-full h-full block" />
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Alpha Edge Studio</p>
            </div>
          )}
          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-6">
                <button disabled={selectedIdx === 0} onClick={() => navigateTo(selectedIdx - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[10px]"></i></button>
                <span className="text-[11px] font-mono font-black text-theme-accent min-w-[70px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => navigateTo(selectedIdx + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[10px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>
      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <ImageList images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} onToggleActive={(id) => setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img))} />
      </aside>
      <input type="file" multiple accept="image/png, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
      <AdvancedBorderModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} settings={settings.advanced!} onUpdate={(adv) => handleSettingsChange({ ...settings, advanced: adv })} baseImage={currentImg ? { url: currentImg.previewUrl, width: currentImg.width, height: currentImg.height } : null} />
    </div>
  );
};

export default AlphaEdgeTool;

import React from 'react';
import { GridSettings, GridImage } from '../types';
import MiauSlider from './MiauSlider';

interface SidebarProps {
  settings: GridSettings;
  onSettingsChange: (settings: GridSettings) => void;
  onAddFile: () => void;
  onAddFolder: () => void;
  images: GridImage[];
  onUpdateActiveCount: (count: number) => void;
  exportOptions: {
    downloadIndividual: boolean;
    setDownloadIndividual: (v: boolean) => void;
    downloadZip: boolean;
    setDownloadZip: (v: boolean) => void;
  };
  onExport: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ settings, onSettingsChange, onAddFile, onAddFolder, images, onUpdateActiveCount, exportOptions, onExport }) => {
  const handleChange = (key: keyof GridSettings, value: any) => { 
    onSettingsChange({ ...settings, [key]: value }); 
  };

  // Função para atualizar cor e transparência juntas, evitando o bug de reset
  const handleBackgroundChange = (color: string, transparent: boolean) => {
    onSettingsChange({
      ...settings,
      backgroundColor: color,
      isTransparent: transparent
    });
  };

  const activeCount = images.filter(img => img.isActive).length;
  const isAuto = settings.layoutMode === 'auto';

  return (
    <div className="p-5 space-y-6 h-full overflow-y-auto scrollbar-hide flex flex-col">
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Entrada de Mídia</h3>
        <div className="space-y-2">
          <button onClick={onAddFile} className="w-full flex items-center justify-center gap-2 py-3.5 px-4 rounded-xl font-black text-[10px] transition-all active:scale-95 shadow-lg hover:opacity-90 relative group overflow-hidden uppercase bg-theme-accent text-theme-inv">
            <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
            <i className="fas fa-plus-circle z-10"></i> <span className="z-10">Adicionar Fotos</span>
          </button>
          <button onClick={onAddFolder} className="w-full flex items-center justify-center gap-2 py-2.5 px-4 rounded-lg font-bold text-[9px] border transition-all active:scale-95 shadow-sm hover:bg-black/10 relative group overflow-hidden uppercase border-theme bg-theme-panel text-theme-main">
            <i className="fas fa-folder z-10"></i> <span className="z-10">Pasta Completa</span>
          </button>
        </div>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <div className="flex items-center justify-between border-b border-theme pb-2">
          <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Organização</h3>
          {isAuto && <i className="fas fa-robot text-theme-accent text-[10px]"></i>}
        </div>
        <div className="flex p-1 bg-theme-panel/50 rounded-xl border border-theme">
          <button onClick={() => handleChange('layoutMode', 'grid')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${!isAuto ? 'bg-theme-accent text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}>Manual</button>
          <button onClick={() => handleChange('layoutMode', 'auto')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${isAuto ? 'bg-theme-accent text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}>Auto-Flow</button>
        </div>
        {isAuto && (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
            <MiauSlider label="Itens na Grid" min={1} max={images.length || 1} value={activeCount} onChange={onUpdateActiveCount} icon="fa-layer-group" />
            <div className="space-y-2">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide px-1">Formato do Conjunto</label>
              <div className="grid grid-cols-3 gap-1.5">
                {[{ id: 'square', label: '1:1', icon: 'fa-square' }, { id: 'portrait', label: '3:4', icon: 'fa-columns' }, { id: 'landscape', label: '4:3', icon: 'fa-grip-horizontal' }].map(shape => (
                  <button key={shape.id} onClick={() => handleChange('targetShape', shape.id)} className={`flex flex-col items-center justify-center gap-1.5 py-3 rounded-xl border transition-all ${settings.targetShape === shape.id ? 'bg-theme-accent border-theme-accent text-white shadow-lg' : 'bg-theme-panel/50 border-theme opacity-50 hover:opacity-100'}`}>
                    <i className={`fas ${shape.icon} text-[10px]`}></i>
                    <span className="text-[7px] font-black uppercase">{shape.label}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-5">
