const SidebarAlphaEdge: React.FC<SidebarAlphaEdgeProps> = ({ 
  settings, onSettingsChange, onAdd, onSave, isProcessing, progress, total, exportOptions, onOpenAdvanced, autoSave, onAutoSaveChange, onApplyToAll, onExportGrid
}) => {
  const handleChange = (key: keyof AlphaEdgeSettings, value: any) => {
