import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import Header from '../components/Header';
import { GridImage, AISettings } from '../types';

const PRE_PROMPTS = {
  'remove-bg': 'Remova o fundo desta imagem de forma extremamente precisa, deixando apenas o objeto ou pessoa principal em um fundo transparente ou branco puro. Mantenha os detalhes dos cabelos e bordas finas.',
  'enhance': 'Melhore a nitidez, o contraste e a clareza desta imagem. Realce os detalhes sem criar artefatos artificiais. Torne a imagem profissional e limpa.',
  'denoise': 'Remova o ruído e a granulação desta imagem digital, preservando as texturas naturais e a nitidez dos objetos principais.',
  'restore': 'Restaure esta imagem, corrigindo cores desbotadas e melhorando a definição geral para que pareça nova.'
};

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [aiSettings, setAiSettings] = useState<AISettings>({
    action: 'enhance',
    prompt: PRE_PROMPTS['enhance'],
    strength: 50,
    refineShift: 0,
    refineFeather: 2,
    quality: 'fast'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const currentImg = images[selectedIdx];

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files);
    const newImgs: GridImage[] = [];
    for (const file of files) {
      const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => {
        const i = new Image();
        i.onload = () => resolve(i);
        i.src = url;
      });
      newImgs.push({
        id: uuidv4(),
        file,
        previewUrl: url,
        width: img.width,
        height: img.height,
        aspectRatio: img.width / img.height
      });
    }
    setImages(prev => [...prev, ...newImgs]);
  };

  const processWithAI = async () => {
    if (!currentImg) return;
    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const model = aiSettings.quality === 'high' ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(currentImg.file);
      });
      const base64Data = await base64Promise;

      const response = await ai.models.generateContent({
        model: model,
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType: currentImg.file.type } },
            { text: aiSettings.prompt }
          ]
        }
      });

      let newImageUrl = '';
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          newImageUrl = `data:image/png;base64,${part.inlineData.data}`;
          break;
        }
      }

      if (newImageUrl) {
        // Criar nova versão da imagem
        const fetchRes = await fetch(newImageUrl);
        const blob = await fetchRes.blob();
        const newFile = new File([blob], `miau_ai_${currentImg.file.name}`, { type: 'image/png' });
        const finalUrl = URL.createObjectURL(newFile);

        setImages(prev => prev.map((img, i) => i === selectedIdx ? {
          ...img,
          file: newFile,
          previewUrl: finalUrl
        } : img));
      }
    } catch (error) {
      console.error("Erro no processamento IA:", error);
      alert("Houve um erro ao processar com a IA. Verifique sua conexão ou tente novamente.");
    } finally {
      setIsProcessing(false);
    }
  };

  const applyRefinements = useCallback(() => {
    if (!canvasRef.current || !currentImg) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.src = currentImg.previewUrl;
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;

      // Aqui aplicamos a lógica de refinamento de bordas local (Shift/Feather)
      // Para fins de preview rápido, desenhamos a imagem
      // Em uma implementação real completa, processaríamos o Alpha Channel aqui
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      if (aiSettings.refineFeather > 0) {
        ctx.filter = `blur(${aiSettings.refineFeather}px)`;
      }

      ctx.drawImage(img, 0, 0);
      ctx.filter = 'none';
    };
  }, [currentImg, aiSettings.refineFeather, aiSettings.refineShift]);

  useEffect(() => {
    applyRefinements();
  }, [applyRefinements]);

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={(s) => {
            const newS = { ...s };
            if (s.action !== aiSettings.action) {
              newS.prompt = PRE_PROMPTS[s.action];
            }
            setAiSettings(newS);
          }}
          onAdd={() => fileInputRef.current?.click()}
          onProcess={processWithAI}
          isProcessing={isProcessing}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-[2.5rem]"
                style={{ 
                  width: currentImg.width * zoom,
                  height: currentImg.height * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <canvas ref={canvasRef} className="w-full h-full block" />
                {isProcessing && (
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-md flex flex-col items-center justify-center text-white z-50">
                    <div className="w-16 h-16 border-4 border-theme-accent border-t-transparent rounded-full animate-spin mb-4"></div>
                    <p className="text-[10px] font-black uppercase tracking-widest animate-pulse">Consultando o Gemini...</p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-brain text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Miau AI Lab</p>
            </div>
          )}

          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-6">
                <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(selectedIdx - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[10px]"></i></button>
                <span className="text-[11px] font-mono font-black text-theme-accent min-w-[70px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(selectedIdx + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[10px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>

      <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default AILabTool;

