interface SidebarAILabProps {
  settings: AISettings;
  onSettingsChange: (s: AISettings) => void;
  onAdd: () => void;
  onProcess: () => void;
  isProcessing: boolean;
}

const SidebarAILab: React.FC<SidebarAILabProps> = ({ settings, onSettingsChange, onAdd, onProcess, isProcessing }) => {
  const handleChange = (key: keyof AISettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  const actions: { id: AISettings['action'], label: string, icon: string, color: string, btnText: string }[] = [
    { id: 'remove-bg', label: 'Magic Cutout', icon: 'fa-scissors', color: 'bg-orange-500', btnText: 'Iniciar Recorte Neural' },
    { id: 'enhance', label: 'Pro Detailer', icon: 'fa-magic', color: 'bg-blue-500', btnText: 'Otimizar Detalhes' },
    { id: 'denoise', label: 'Grain Killer', icon: 'fa-eye-slash', color: 'bg-indigo-500', btnText: 'Limpar Granulação' },
    { id: 'restore', label: 'Time Machine', icon: 'fa-history', color: 'bg-purple-500', btnText: 'Restaurar Original' }
  ];

  const currentAction = actions.find(a => a.id === settings.action);

  const renderRefinements = () => {
    switch (settings.action) {
      case 'remove-bg':
        return (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
