            <MiauSlider label="Shift Edge (Expansão)" min={-50} max={50} value={settings.refineShift} onChange={(v) => handleChange('refineShift', v)} icon="fa-arrows-alt" />
            <MiauSlider label="Suavização (Smooth)" min={0} max={100} value={settings.smoothness} onChange={(v) => handleChange('smoothness', v)} icon="fa-wave-square" />
            <MiauSlider label="Borda Feather" min={0} max={20} value={settings.refineFeather} onChange={(v) => handleChange('refineFeather', v)} icon="fa-feather-alt" />
          </div>
        );
      case 'enhance':
        return (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
            <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Controle de Nitidez</h3>
            <MiauSlider label="Intensidade IA" min={1} max={100} value={settings.strength} onChange={(v) => handleChange('strength', v)} icon="fa-bolt" />
            <MiauSlider label="Clareza Neural" min={0} max={100} value={settings.smoothness} onChange={(v) => handleChange('smoothness', v)} icon="fa-sun" />
          </div>
        );
      case 'denoise':
        return (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
            <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Redução de Ruído</h3>
            <MiauSlider label="Força do Filtro" min={1} max={100} value={settings.strength} onChange={(v) => handleChange('strength', v)} icon="fa-shield-halved" />
            <MiauSlider label="Preservar Textura" min={0} max={100} value={settings.smoothness} onChange={(v) => handleChange('smoothness', v)} icon="fa-fingerprint" />
          </div>
        );
      case 'restore':
        return (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
            <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Parâmetros de Restauro</h3>
            <MiauSlider label="Fidelidade de Cor" min={0} max={100} value={settings.strength} onChange={(v) => handleChange('strength', v)} icon="fa-palette" />
            <MiauSlider label="Recuperação Pro" min={0} max={100} value={settings.smoothness} onChange={(v) => handleChange('smoothness', v)} icon="fa-sparkles" />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="p-5 space-y-6 h-full flex flex-col overflow-y-auto custom-scrollbar">
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Neural Hub</h3>
        <button onClick={onAdd} className="w-full py-4 rounded-xl font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase active:scale-95 transition-all">
          <i className="fas fa-cloud-upload-alt"></i> Upload de Origem
        </button>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Seleção de Módulo IA</h3>
        <div className="grid grid-cols-2 gap-2">
