            <button
              key={act.id}
              onClick={() => handleChange('action', act.id)}
              className={`flex flex-col items-center gap-2 p-3 rounded-xl border transition-all text-center ${settings.action === act.id ? 'bg-theme-accent/20 border-theme-accent ring-1 ring-theme-accent/30 shadow-lg' : 'bg-theme-panel/30 border-theme opacity-40 hover:opacity-100'}`}
            >
