          <div className="flex gap-1">
            <button onClick={() => handleChange('quality', 'fast')} className={`px-2 py-0.5 rounded text-[7px] font-black uppercase ${settings.quality === 'fast' ? 'bg-theme-accent text-white' : 'bg-theme-panel opacity-40'}`}>Lite</button>
            <button onClick={() => handleChange('quality', 'high')} className={`px-2 py-0.5 rounded text-[7px] font-black uppercase ${settings.quality === 'high' ? 'bg-theme-accent text-white' : 'bg-theme-panel opacity-40'}`}>Pro</button>
