      <div className="mt-auto pt-4">
        <button 
          onClick={onProcess}
          disabled={isProcessing}
          className="w-full py-5 rounded-xl font-black text-[11px] bg-theme-accent text-theme-inv shadow-2xl flex items-center justify-center gap-2 uppercase disabled:opacity-50 active:scale-95 transition-all group overflow-hidden relative"
