          {isProcessing ? <><i className="fas fa-spinner animate-spin"></i> Sincronizando...</> : <><i className={`fas ${currentAction?.icon}`}></i> {currentAction?.btnText}</>}
        </button>
      </div>
    </div>
  );
};

