}

const SidebarAILab: React.FC<SidebarAILabProps> = ({ settings, onSettingsChange, onAdd, onProcess, isProcessing, onAction }) => {
  const handleChange = (key: keyof AISettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  const tools: { id: AISettings['currentTool'], label: string, icon: string }[] = [
    { id: 'move', label: 'Mover', icon: 'fa-mouse-pointer' },
    { id: 'lasso', label: 'Laço', icon: 'fa-bezier-curve' },
    { id: 'brush', label: 'Pincel', icon: 'fa-paint-brush' },
    { id: 'eraser', label: 'Borracha', icon: 'fa-eraser' }
  ];

  return (
    <div className="p-5 space-y-6 h-full flex flex-col overflow-y-auto custom-scrollbar">
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Laboratório</h3>
        <button onClick={onAdd} className="w-full py-4 rounded-xl font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase active:scale-95 transition-all">
          <i className="fas fa-file-import"></i> Nova Imagem
        </button>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Toolbox Master</h3>
        <div className="grid grid-cols-2 gap-1 p-1 bg-black/20 rounded-xl border border-theme">
          {tools.map(tool => (
            <button
              key={tool.id}
              onClick={() => handleChange('currentTool', tool.id)}
              className={`flex items-center justify-center gap-2 py-3 rounded-lg transition-all ${settings.currentTool === tool.id ? 'bg-theme-accent text-white shadow-lg' : 'opacity-30 hover:opacity-100 text-theme-main'}`}
            >
              <i className={`fas ${tool.icon} text-[10px]`}></i>
              <span className="text-[8px] font-black uppercase">{tool.label}</span>
            </button>
          ))}
        </div>

        {(settings.currentTool === 'brush' || settings.currentTool === 'eraser') && (
          <div className="space-y-4 pt-2 animate-in fade-in zoom-in duration-300">
            <MiauSlider label="Tamanho Pincel" min={1} max={300} value={settings.brushSize} onChange={(v) => handleChange('brushSize', v)} icon="fa-circle" />
            <MiauSlider label="Fluxo / Flow" min={1} max={100} value={settings.brushOpacity} onChange={(v) => handleChange('brushOpacity', v)} unit="%" icon="fa-tint" />
          </div>
        )}

        {settings.currentTool === 'lasso' && (
          <div className="space-y-2 pt-2 animate-in fade-in zoom-in duration-300">
            <p className="text-[7px] text-theme-accent font-black uppercase opacity-60 px-1">Dica: Clique para adicionar pontos. Clique no primeiro ponto para fechar.</p>
            <div className="grid grid-cols-2 gap-2">
               <button onClick={() => onAction('crop')} className="py-2.5 rounded-lg bg-theme-panel border border-theme text-[8px] font-black uppercase hover:bg-theme-accent hover:text-white transition-all">Recortar</button>
               <button onClick={() => onAction('invert')} className="py-2.5 rounded-lg bg-theme-panel border border-theme text-[8px] font-black uppercase hover:bg-theme-accent hover:text-white transition-all">Inverter</button>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Ações Rápidas</h3>
        <div className="space-y-2">
           <button onClick={() => onAction('clear-mask')} className="w-full py-3 rounded-xl bg-theme-panel border border-theme text-[9px] font-black uppercase opacity-60 hover:opacity-100 transition-all flex items-center justify-center gap-2">
             <i className="fas fa-trash-restore"></i> Resetar Máscara
           </button>
           <button onClick={onProcess} disabled={isProcessing} className="w-full py-4 rounded-xl bg-theme-accent text-white text-[10px] font-black uppercase shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all">
             <i className="fas fa-magic"></i> {isProcessing ? 'Calculando...' : 'IA Auto-Cutout'}
           </button>
        </div>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Refino de Borda</h3>
        <div className="space-y-4">
          <MiauSlider label="Shift Edge" min={-100} max={100} value={settings.refineShift} onChange={(v) => handleChange('refineShift', v)} icon="fa-compress-arrows-alt" />
          <MiauSlider label="Suavizar (Blur)" min={0} max={100} value={settings.refineFeather} onChange={(v) => handleChange('refineFeather', v)} icon="fa-feather" />
        </div>
      </div>

      <div className="mt-auto pt-4">
        <button className="w-full py-5 rounded-xl font-black text-[11px] bg-white text-black shadow-2xl flex items-center justify-center gap-2 uppercase active:scale-95 transition-all">
          <i className="fas fa-download"></i> Exportar Final
        </button>
      </div>
    </div>
  );
};

export default SidebarAILab;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import Header from '../components/Header';
import { GridImage, AISettings } from '../types';

interface Point { x: number; y: number; }

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [isDrawing, setIsDrawing] = useState(false);
  const [lassoPoints, setLassoPoints] = useState<Point[]>([]);

  const [aiSettings, setAiSettings] = useState<AISettings>({
    action: 'remove-bg',
    currentTool: 'move',
    brushSize: 40,
    brushOpacity: 100,
    strength: 50,
    refineShift: 0,
    refineFeather: 0,
    smoothness: 0,
    quality: 'fast'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const maskCanvasRef = useRef<HTMLCanvasElement>(null);
  const imageRef = useRef<HTMLImageElement | null>(null);

  const currentImg = images[selectedIdx];

  // Inicia ou reseta a máscara ao trocar de imagem
  useEffect(() => {
    if (currentImg && maskCanvasRef.current) {
      const img = new Image();
      img.src = currentImg.previewUrl;
      img.onload = () => {
        imageRef.current = img;
        const canvas = maskCanvasRef.current!;
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        if (ctx) {
          ctx.fillStyle = 'white';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          drawFinal();
        }
      };
    }
  }, [currentImg]);

  const drawFinal = useCallback(() => {
    if (!canvasRef.current || !maskCanvasRef.current || !imageRef.current) return;
    const mainCanvas = canvasRef.current;
    const maskCanvas = maskCanvasRef.current;
    const img = imageRef.current;
    const ctx = mainCanvas.getContext('2d');
    if (!ctx) return;

    mainCanvas.width = img.width;
    mainCanvas.height = img.height;
    ctx.clearRect(0, 0, mainCanvas.width, mainCanvas.height);

    // Filtro de Feather (via CSS blur no preview)
    if (aiSettings.refineFeather > 0) {
      ctx.filter = `blur(${aiSettings.refineFeather / 10}px)`;
    }

    // Composição Master: Máscara -> Imagem Original
    ctx.drawImage(maskCanvas, 0, 0);
    ctx.globalCompositeOperation = 'source-in';

    // Simulação visual de Shift Edge através de pequena escala
    const shiftScale = 1 + (aiSettings.refineShift / 1000);
    const sw = img.width * shiftScale;
    const sh = img.height * shiftScale;
    ctx.drawImage(img, (img.width - sw)/2, (img.height - sh)/2, sw, sh);

    ctx.globalCompositeOperation = 'source-over';
    ctx.filter = 'none';

    // Se estiver no laço, desenha os pontos e linhas guias
    if (aiSettings.currentTool === 'lasso' && lassoPoints.length > 0) {
       drawLassoPreview(ctx);
    }
  }, [aiSettings.refineFeather, aiSettings.refineShift, aiSettings.currentTool, lassoPoints]);

  const drawLassoPreview = (ctx: CanvasRenderingContext2D) => {
    ctx.beginPath();
    ctx.strokeStyle = '#4f46e5';
    ctx.lineWidth = 2 / zoom;
    ctx.setLineDash([5 / zoom, 5 / zoom]);
    ctx.moveTo(lassoPoints[0].x, lassoPoints[0].y);
    lassoPoints.forEach((p, i) => i > 0 && ctx.lineTo(p.x, p.y));
    ctx.stroke();
    ctx.setLineDash([]);

    // Pontos
    lassoPoints.forEach(p => {
       ctx.fillStyle = '#ffffff';
       ctx.beginPath();
       ctx.arc(p.x, p.y, 4 / zoom, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();
    });
  };

  const handleCanvasInteraction = (e: React.MouseEvent) => {
    if (!currentImg || !maskCanvasRef.current) return;
    const canvas = maskCanvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (canvas.width / rect.width);
    const y = (e.clientY - rect.top) * (canvas.height / rect.height);

    if (aiSettings.currentTool === 'lasso') {
      if (e.type === 'mousedown') {
        // Verifica se clicou perto do primeiro ponto para fechar
        if (lassoPoints.length > 2) {
          const d = Math.sqrt(Math.pow(x - lassoPoints[0].x, 2) + Math.pow(y - lassoPoints[0].y, 2));
          if (d < 15 / zoom) {
            closeLasso();
            return;
          }
        }
        setLassoPoints(prev => [...prev, { x, y }]);
      }
    } else if (aiSettings.currentTool === 'brush' || aiSettings.currentTool === 'eraser') {
      if (e.type === 'mousedown') setIsDrawing(true);
      if (isDrawing || e.type === 'mousedown') paintMask(x, y);
    }
  };

  const paintMask = (x: number, y: number) => {
    const canvas = maskCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!ctx) return;

    ctx.lineWidth = aiSettings.brushSize;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.globalAlpha = aiSettings.brushOpacity / 100;

    if (aiSettings.currentTool === 'brush') {
       ctx.strokeStyle = 'white';
       ctx.globalCompositeOperation = 'source-over';
    } else {
       ctx.strokeStyle = 'black';
       ctx.globalCompositeOperation = 'destination-out';
    }

    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y);
    drawFinal();
  };

  const closeLasso = () => {
    const canvas = maskCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!ctx || lassoPoints.length < 3) return;

    // Pedimos confirmação visual ou automática
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(lassoPoints[0].x, lassoPoints[0].y);
    lassoPoints.forEach(p => ctx.lineTo(p.x, p.y));
    ctx.closePath();

    // Criamos o recorte na máscara
    // Por padrão, o laço aqui "seleciona" o que fica visível
    ctx.fillStyle = 'white';
    ctx.globalCompositeOperation = 'destination-in';
    ctx.fill();
    ctx.restore();

    setLassoPoints([]);
    drawFinal();
  };

  const handleSidebarAction = (action: 'crop' | 'clear-mask' | 'invert') => {
    if (!maskCanvasRef.current) return;
    const canvas = maskCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    switch (action) {
      case 'clear-mask':
        ctx.fillStyle = 'white';
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        break;
      case 'invert':
        // Lógica de inversão de pixels (Alpha)
        const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        for (let i = 0; i < imgData.data.length; i += 4) {
          imgData.data[i + 3] = 255 - imgData.data[i + 3];
        }
        ctx.putImageData(imgData, 0, 0);
        break;
      case 'crop':
        if (lassoPoints.length > 2) closeLasso();
        break;
    }
    drawFinal();
  };

  const processWithAI = async () => {
    if (!currentImg) return;
    setIsProcessing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(currentImg.file);
      });
      const base64Data = await base64Promise;

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType: currentImg.file.type } },
            { text: "Remova o fundo desta imagem e retorne apenas o objeto principal em transparência." }
          ]
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const aiImg = new Image();
            aiImg.src = `data:image/png;base64,${part.inlineData.data}`;
            aiImg.onload = () => {
               const ctx = maskCanvasRef.current?.getContext('2d');
               if (ctx) {
                  ctx.clearRect(0, 0, canvasRef.current!.width, canvasRef.current!.height);
                  ctx.drawImage(aiImg, 0, 0);
                  drawFinal();
               }
            };
            break;
          }
        }
      }
    } catch (e) { console.error(e); } finally { setIsProcessing(false); }
  };

  useEffect(() => { drawFinal(); }, [drawFinal]);

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={setAiSettings}
          onAdd={() => fileInputRef.current?.click()}
          onProcess={processWithAI}
          isProcessing={isProcessing}
          onAction={handleSidebarAction}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className={`relative shadow-2xl border border-theme bg-theme-panel overflow-hidden rounded-[2.5rem] ${aiSettings.currentTool === 'move' ? 'cursor-grab' : 'cursor-crosshair'}`}
                style={{ 
                  width: currentImg.width * zoom,
                  height: currentImg.height * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
                onMouseDown={handleCanvasInteraction}
                onMouseMove={handleCanvasInteraction}
                onMouseUp={() => { setIsDrawing(false); maskCanvasRef.current?.getContext('2d')?.beginPath(); }}
              >
                <canvas ref={canvasRef} className="w-full h-full block" />
                <canvas ref={maskCanvasRef} className="hidden" />
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-brain text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Miau AI Lab</p>
            </div>
          )}

          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-6">
                <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(selectedIdx - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[10px]"></i></button>
                <span className="text-[11px] font-mono font-black text-theme-accent min-w-[70px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(selectedIdx + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[10px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>

      <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={async (e) => {
        if (!e.target.files) return;
        const file = e.target.files[0];
        const url = URL.createObjectURL(file);
        const img = new Image();
        img.onload = () => {
          setImages(prev => [...prev, { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height }]);
        };
        img.src = url;
      }} />
    </div>
  );
};

export default AILabTool;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import Header from '../components/Header';
import { GridImage, AISettings } from '../types';

interface Point { x: number; y: number; }

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [isDrawing, setIsDrawing] = useState(false);
  const [lassoPoints, setLassoPoints] = useState<Point[]>([]);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });
  const [dashOffset, setDashOffset] = useState(0);

  const [aiSettings, setAiSettings] = useState<AISettings>({
    action: 'remove-bg',
    currentTool: 'move',
    brushSize: 60,
    brushOpacity: 100,
    strength: 50,
    refineShift: 0,
    refineFeather: 2,
    smoothness: 10,
    quality: 'fast'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const maskCanvasRef = useRef<HTMLCanvasElement>(null);
  const uiCanvasRef = useRef<HTMLCanvasElement>(null);
  const imageRef = useRef<HTMLImageElement | null>(null);
  const lastPointRef = useRef<Point | null>(null);

  const currentImg = images[selectedIdx];

  // Animação das "Marching Ants"
  useEffect(() => {
    if (aiSettings.currentTool !== 'lasso') return;
    const interval = setInterval(() => {
      setDashOffset(prev => (prev + 0.5) % 10);
    }, 30);
    return () => clearInterval(interval);
  }, [aiSettings.currentTool]);

  // Inicializa a máscara
  useEffect(() => {
    if (currentImg && maskCanvasRef.current) {
      const img = new Image();
      img.src = currentImg.previewUrl;
      img.onload = () => {
        imageRef.current = img;
        const mCanvas = maskCanvasRef.current!;
        mCanvas.width = img.width;
        mCanvas.height = img.height;
        const mCtx = mCanvas.getContext('2d', { willReadFrequently: true });
        if (mCtx) {
          mCtx.fillStyle = 'white';
          mCtx.fillRect(0, 0, mCanvas.width, mCanvas.height);
          drawFinal();
        }
      };
    }
  }, [currentImg]);

  const drawUI = useCallback(() => {
    if (!uiCanvasRef.current || !imageRef.current) return;
    const canvas = uiCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = imageRef.current;
    canvas.width = img.width;
    canvas.height = img.height;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 1. Desenhar Cursor do Pincel
    if (aiSettings.currentTool === 'brush' || aiSettings.currentTool === 'eraser') {
      ctx.beginPath();
      ctx.strokeStyle = aiSettings.currentTool === 'brush' ? 'rgba(79, 70, 229, 0.8)' : 'rgba(239, 68, 68, 0.8)';
      ctx.lineWidth = 2 / zoom;
      ctx.arc(mousePos.x, mousePos.y, aiSettings.brushSize / 2, 0, Math.PI * 2);
      ctx.stroke();
      // Centro
      ctx.beginPath();
      ctx.fillStyle = ctx.strokeStyle;
      ctx.arc(mousePos.x, mousePos.y, 2 / zoom, 0, Math.PI * 2);
      ctx.fill();
    }

    // 2. Desenhar Laço
    if (lassoPoints.length > 0) {
      ctx.beginPath();
      ctx.strokeStyle = '#4f46e5';
      ctx.lineWidth = 2 / zoom;
      ctx.setLineDash([5 / zoom, 5 / zoom]);
      ctx.lineDashOffset = -dashOffset;
      ctx.moveTo(lassoPoints[0].x, lassoPoints[0].y);
      lassoPoints.forEach((p, i) => i > 0 && ctx.lineTo(p.x, p.y));

      // Linha elástica para o mouse se não for fechar
      if (aiSettings.currentTool === 'lasso') {
        ctx.lineTo(mousePos.x, mousePos.y);
      }

      ctx.stroke();
      ctx.setLineDash([]);

      // Pontos do laço
      lassoPoints.forEach((p, i) => {
        ctx.fillStyle = i === 0 ? '#4f46e5' : '#ffffff';
        ctx.strokeStyle = '#4f46e5';
        ctx.beginPath();
        ctx.arc(p.x, p.y, (i === 0 ? 6 : 4) / zoom, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      });
    }
  }, [mousePos, lassoPoints, aiSettings.currentTool, aiSettings.brushSize, zoom, dashOffset]);

  const drawFinal = useCallback(() => {
    if (!canvasRef.current || !maskCanvasRef.current || !imageRef.current) return;
    const mainCanvas = canvasRef.current;
    const maskCanvas = maskCanvasRef.current;
    const img = imageRef.current;
    const ctx = mainCanvas.getContext('2d');
    if (!ctx) return;

    mainCanvas.width = img.width;
    mainCanvas.height = img.height;
    ctx.clearRect(0, 0, mainCanvas.width, mainCanvas.height);

    // Filtro de Borda Suave
    if (aiSettings.refineFeather > 0) {
      ctx.filter = `blur(${aiSettings.refineFeather}px)`;
    }

    // Composição: Máscara -> Imagem
    ctx.drawImage(maskCanvas, 0, 0);
    ctx.globalCompositeOperation = 'source-in';

    // Shift Edge (Simulação por escala da imagem sob a máscara fixa)
    const shift = 1 + (aiSettings.refineShift / 500);
    const sw = img.width * shift;
    const sh = img.height * shift;
    ctx.drawImage(img, (img.width - sw)/2, (img.height - sh)/2, sw, sh);

    ctx.globalCompositeOperation = 'source-over';
    ctx.filter = 'none';

    drawUI();
  }, [aiSettings.refineFeather, aiSettings.refineShift, drawUI]);

  const handleInteraction = (e: React.MouseEvent) => {
    if (!currentImg || !maskCanvasRef.current) return;
    const canvas = maskCanvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (canvas.width / rect.width);
    const y = (e.clientY - rect.top) * (canvas.height / rect.height);

    setMousePos({ x, y });

    if (aiSettings.currentTool === 'lasso') {
      if (e.type === 'mousedown') {
        if (lassoPoints.length > 2) {
          const d = Math.sqrt(Math.pow(x - lassoPoints[0].x, 2) + Math.pow(y - lassoPoints[0].y, 2));
          if (d < 20 / zoom) {
            applyLassoSelection();
            return;
          }
        }
        setLassoPoints(prev => [...prev, { x, y }]);
      }
    } else if (aiSettings.currentTool === 'brush' || aiSettings.currentTool === 'eraser') {
      if (e.type === 'mousedown') {
        setIsDrawing(true);
        lastPointRef.current = { x, y };
      }
      if (isDrawing || e.type === 'mousedown') {
        paintOnMask(x, y);
      }
    }

    drawUI();
  };

  const paintOnMask = (x: number, y: number) => {
    const canvas = maskCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!ctx || !lastPointRef.current) return;

    ctx.save();
    ctx.lineWidth = aiSettings.brushSize;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (aiSettings.currentTool === 'brush') {
      ctx.strokeStyle = 'white';
      ctx.globalCompositeOperation = 'source-over';
    } else {
      ctx.strokeStyle = 'black';
      ctx.globalCompositeOperation = 'destination-out';
    }

    // Desenha linha suave do ponto anterior ao atual
    ctx.beginPath();
    ctx.moveTo(lastPointRef.current.x, lastPointRef.current.y);
    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.restore();

    lastPointRef.current = { x, y };
    drawFinal();
  };

  const applyLassoSelection = () => {
    const canvas = maskCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!ctx || lassoPoints.length < 3) return;

    ctx.save();
    ctx.beginPath();
    ctx.moveTo(lassoPoints[0].x, lassoPoints[0].y);
    lassoPoints.forEach(p => ctx.lineTo(p.x, p.y));
    ctx.closePath();

    // O laço por padrão "limpa" o resto
    ctx.fillStyle = 'white';
    ctx.globalCompositeOperation = 'destination-in';
    ctx.fill();
    ctx.restore();

    setLassoPoints([]);
    drawFinal();
  };

  const handleAction = (action: 'crop' | 'clear-mask' | 'invert') => {
    if (!maskCanvasRef.current) return;
    const ctx = maskCanvasRef.current.getContext('2d');
    if (!ctx) return;

    if (action === 'clear-mask') {
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = 'white';
      ctx.fillRect(0, 0, maskCanvasRef.current.width, maskCanvasRef.current.height);
    } else if (action === 'invert') {
      const imgData = ctx.getImageData(0, 0, ctx.canvas.width, ctx.canvas.height);
      for (let i = 0; i < imgData.data.length; i += 4) {
        imgData.data[i + 3] = 255 - imgData.data[i + 3];
      }
      ctx.putImageData(imgData, 0, 0);
    } else if (action === 'crop') {
      applyLassoSelection();
    }
    drawFinal();
  };

  useEffect(() => { drawFinal(); }, [drawFinal, dashOffset]);

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={setAiSettings}
          onAdd={() => fileInputRef.current?.click()}
          onProcess={() => {/* Logic for AI Auto-Cutout */}}
          isProcessing={isProcessing}
          onAction={handleAction}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => setImages([])} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className={`relative shadow-2xl border border-theme bg-theme-panel overflow-hidden rounded-[2.5rem] ${aiSettings.currentTool === 'move' ? 'cursor-grab' : 'cursor-none'}`}
                style={{ 
                  width: currentImg.width * zoom,
                  height: currentImg.height * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
                onMouseDown={handleInteraction}
                onMouseMove={handleInteraction}
                onMouseUp={() => setIsDrawing(false)}
                onMouseLeave={() => setIsDrawing(false)}
              >
                {/* Layer 1: Resultado Final Composto */}
                <canvas ref={canvasRef} className="absolute inset-0 w-full h-full block" />

                {/* Layer 2: Máscara Invisível (Buffer) */}
                <canvas ref={maskCanvasRef} className="hidden" />

                {/* Layer 3: UI Overlay (Cursor, Gizmos) */}
                <canvas ref={uiCanvasRef} className="absolute inset-0 w-full h-full block pointer-events-none" />
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-magic text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Miau Mask Studio</p>
            </div>
          )}

          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-6">
                <button disabled={selectedIdx === 0} onClick={() => setSelectedIdx(selectedIdx - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[10px]"></i></button>
                <span className="text-[11px] font-mono font-black text-theme-accent min-w-[70px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => setSelectedIdx(selectedIdx + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[10px]"></i></button>
              </div>
