import React from 'react';
import { AISettings } from '../types';
import MiauSlider from './MiauSlider';

interface SidebarAILabProps {
  settings: AISettings;
  onSettingsChange: (s: AISettings) => void;
  onAdd: () => void;
  onProcess: (mode: AISettings['mode']) => void;
  onSave: () => void;
