export default SidebarAILab;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import Header from '../components/Header';
import { GridImage, AISettings } from '../types';

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [compareSplit, setCompareSplit] = useState(50);
  const [isComparing, setIsComparing] = useState(true);
  const [enhancedUrl, setEnhancedUrl] = useState<string | null>(null);
  const [highPassUrl, setHighPassUrl] = useState<string | null>(null);
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  const [aiSettings, setAiSettings] = useState<AISettings>({
    mode: 'enhance',
    sharpness: 0,
    noiseReduction: 0,
    brightness: 100,
    contrast: 100,
    aiIntensity: 70,
    edgeSmoothness: 2,
    smartSharpen: false,
    highPassRadius: 1.5
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentImg = images[selectedIdx];

  useEffect(() => {
    setEnhancedUrl(null);
    setHighPassUrl(null);
  }, [selectedIdx]);

  const generateHighPass = useCallback(async () => {
    if (!currentImg || !aiSettings.smartSharpen) {
      setHighPassUrl(null);
      return;
    }

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = enhancedUrl || currentImg.previewUrl;

    img.onload = () => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return;

      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);

      const blurCanvas = document.createElement('canvas');
      blurCanvas.width = canvas.width;
      blurCanvas.height = canvas.height;
      const bCtx = blurCanvas.getContext('2d');
      if (bCtx) {
        bCtx.filter = `blur(${aiSettings.highPassRadius}px) grayscale(100%)`;
        bCtx.drawImage(img, 0, 0);
      }

      const originalData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const blurredData = bCtx?.getImageData(0, 0, canvas.width, canvas.height);

      if (blurredData) {
        for (let i = 0; i < originalData.data.length; i += 4) {
          originalData.data[i] = 128 + (originalData.data[i] - blurredData.data[i]);
          originalData.data[i+1] = 128 + (originalData.data[i+1] - blurredData.data[i+1]);
          originalData.data[i+2] = 128 + (originalData.data[i+2] - blurredData.data[i+2]);
        }
        ctx.putImageData(originalData, 0, 0);
      }

      setHighPassUrl(canvas.toDataURL('image/png'));
    };
  }, [currentImg, enhancedUrl, aiSettings.smartSharpen, aiSettings.highPassRadius]);

  useEffect(() => {
    generateHighPass();
  }, [generateHighPass]);

  const processWithAI = async (mode: AISettings['mode']) => {
    if (!currentImg) return;
    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = mode === 'enhance' 
        ? `Professional image enhancement: improve clarity, colors and overall quality. Do NOT add, remove or reconstruct any objects or structural elements. Maintain 100% fidelity to the original shapes and content. Intensity: ${aiSettings.aiIntensity}%`
        : `Denoise this image: remove digital noise and compression artifacts while keeping edges sharp. Maintain maximum realism. Intensity: ${aiSettings.aiIntensity}%`;

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(currentImg.file);
      });
      const base64Data = await base64Promise;

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType: currentImg.file.type } },
            { text: prompt }
          ]
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            setEnhancedUrl(`data:image/png;base64,${part.inlineData.data}`);
            break;
          }
        }
      }
    } catch (error) {
      console.error("Erro AI Enhancer:", error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!currentImg) return;

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = enhancedUrl || currentImg.previewUrl;

    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      ctx.filter = getFilterString();
      ctx.drawImage(img, 0, 0);

      if (aiSettings.smartSharpen && highPassUrl) {
        const hpImg = new Image();
        hpImg.onload = () => {
          ctx.globalCompositeOperation = 'overlay';
          ctx.drawImage(hpImg, 0, 0);
          const link = document.createElement('a');
          link.download = `miau_enhanced_${Date.now()}.png`;
          link.href = canvas.toDataURL('image/png', 1.0);
          link.click();
        };
        hpImg.src = highPassUrl;
      } else {
        const link = document.createElement('a');
        link.download = `miau_enhanced_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png', 1.0);
        link.click();
      }
    };
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      // Limpa projeto anterior ao carregar novo para evitar confusão no Lab
      setImages([{ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height }]);
      setSelectedIdx(0);
      setEnhancedUrl(null);
      setHighPassUrl(null);
    };
    img.src = url;

    // CORREÇÃO CRÍTICA: Reseta o valor do input para permitir carregar o mesmo arquivo novamente
    e.target.value = '';
  };

  const triggerUpload = () => {
    if (images.length > 0) {
      setShowConfirmModal(true);
    } else {
      fileInputRef.current?.click();
    }
  };

  const getFilterString = () => {
    const sharpen = aiSettings.sharpness > 0 
      ? `contrast(${100 + aiSettings.sharpness/2}%) brightness(${100 - aiSettings.sharpness/20}%)` 
      : '';
    const blur = aiSettings.noiseReduction > 0 ? `blur(${aiSettings.noiseReduction/20}px)` : '';
    return `brightness(${aiSettings.brightness}%) contrast(${aiSettings.contrast}%) ${sharpen} ${blur}`;
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={setAiSettings}
          onAdd={triggerUpload}
          onProcess={processWithAI}
          onSave={handleDownload}
          isProcessing={isProcessing}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => { setImages([]); setEnhancedUrl(null); }} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden rounded-[2.5rem] group"
                style={{ 
                  width: currentImg.width * zoom,
                  height: currentImg.height * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <img 
                  src={currentImg.previewUrl} 
                  className="absolute inset-0 w-full h-full object-cover" 
                  alt="original"
                />

                <div 
                  className="absolute inset-0 w-full h-full overflow-hidden"
                  style={{ 
                    clipPath: isComparing ? `inset(0 0 0 ${compareSplit}%)` : 'none'
                  }}
                >
                  <img 
                    src={enhancedUrl || currentImg.previewUrl} 
                    className="absolute inset-0 w-full h-full object-cover"
                    style={{ filter: getFilterString() }} 
                    alt="enhanced"
                  />
                  {aiSettings.smartSharpen && highPassUrl && (
                    <img 
                      src={highPassUrl} 
                      className="absolute inset-0 w-full h-full object-cover"
                      style={{ mixBlendMode: 'overlay' }} 
                      alt="high-pass"
                    />
                  )}
                </div>

                {isComparing && (
                  <>
                    <div 
                      className="absolute top-0 bottom-0 w-0.5 bg-theme-accent z-10 shadow-[0_0_15px_rgba(79,70,229,0.8)] pointer-events-none"
                      style={{ left: `${compareSplit}%` }}
                    >
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-theme-accent text-white flex items-center justify-center text-[10px] shadow-2xl">
                        <i className="fas fa-arrows-alt-h"></i>
                      </div>
                    </div>
                    <input 
                      type="range" min="0" max="100" value={compareSplit} 
                      onChange={(e) => setCompareSplit(parseInt(e.target.value))}
                      className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-20"
                    />
                  </>
                )}

                {isComparing && (
                  <>
                    <div className="absolute top-6 left-6 px-3 py-1 bg-black/40 backdrop-blur-md rounded-lg text-[8px] font-black uppercase text-white/60 tracking-widest z-30">Antes</div>
                    <div className="absolute top-6 right-6 px-3 py-1 bg-theme-accent/80 backdrop-blur-md rounded-lg text-[8px] font-black uppercase text-white tracking-widest z-30">Depois</div>
                  </>
                )}

                {isProcessing && (
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-xl flex flex-col items-center justify-center text-white z-50 animate-in fade-in duration-500">
                    <div className="w-16 h-16 border-4 border-theme-accent border-t-transparent rounded-full animate-spin mb-6"></div>
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">Sincronia Neural...</p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Miau AI Enhancer</p>
            </div>
          )}

          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-32 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <button 
                onClick={() => setIsComparing(!isComparing)}
                className={`flex items-center gap-2 px-4 py-1.5 rounded-full text-[9px] font-black uppercase transition-all ${isComparing ? 'bg-theme-accent text-white shadow-lg' : 'bg-theme-panel/50 opacity-40 hover:opacity-100'}`}
              >
                <i className="fas fa-columns"></i>
                <span>{isComparing ? 'Ver Final' : 'Comparar'}</span>
              </button>
            </div>
          )}
        </div>
      </section>

      {/* POPUP DE CONFIRMAÇÃO DE CARREGAMENTO */}
      {showConfirmModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 backdrop-blur-xl bg-black/40 animate-in fade-in duration-300">
          <div className="max-w-md w-full bg-theme-side border border-theme rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden text-center">
            <div className="w-16 h-16 rounded-3xl bg-theme-accent flex items-center justify-center text-white text-2xl shadow-xl mx-auto mb-6">
              <i className="fas fa-exclamation-triangle"></i>
            </div>
            <h3 className="text-xl font-black uppercase tracking-tighter text-theme-main mb-2">Substituir Edição?</h3>
            <p className="text-[10px] opacity-50 uppercase tracking-widest mb-8 leading-relaxed px-4">Você já tem uma imagem sendo editada. Deseja salvar o resultado atual antes de carregar uma nova?</p>

            <div className="flex flex-col gap-3">
              <button 
                onClick={() => { handleDownload(); setShowConfirmModal(false); setTimeout(() => fileInputRef.current?.click(), 100); }} 
                className="w-full py-4 rounded-2xl bg-theme-accent text-white font-black uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                <i className="fas fa-download"></i> Salvar e Carregar Nova
              </button>
              <button 
                onClick={() => { setShowConfirmModal(false); setTimeout(() => fileInputRef.current?.click(), 100); }} 
                className="w-full py-4 rounded-2xl bg-theme-panel border border-theme text-theme-main font-black uppercase text-[10px] tracking-widest active:scale-95 transition-all"
              >
                Apenas Substituir
              </button>
              <button 
                onClick={() => setShowConfirmModal(false)} 
                className="w-full py-3 rounded-2xl text-[9px] font-black uppercase opacity-30 hover:opacity-100 transition-all"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      <input 
        type="file" 
        accept="image/*" 
        className="hidden" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
      />
    </div>
  );
};

export default AILabTool;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import Sidebar from '../components/Sidebar';
import GridPreview from '../components/GridPreview';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage, GridSettings } from '../types';

const GridTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [settings, setSettings] = useState<GridSettings>({
    canvasWidth: 2048,
    canvasHeight: 2048,
    columns: 3,
    innerSpacing: 20,
    outerMargin: 40,
    backgroundColor: '#0f172a',
    isTransparent: false,
    layoutMode: 'grid',
    itemScale: 0,
    targetShape: 'square'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  const processFiles = async (files: File[]) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    const filteredFiles = files.filter(file => validTypes.includes(file.type));
    const newImages: GridImage[] = [];

    for (const file of filteredFiles) {
      try {
        const url = URL.createObjectURL(file);
        const img = await new Promise<HTMLImageElement>((resolve, reject) => {
          const i = new Image();
          i.onload = () => resolve(i);
          i.onerror = reject;
          i.src = url;
        });

        newImages.push({
          id: uuidv4(),
          file,
          previewUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height,
          isActive: true,
          visible: true
        });
      } catch (err) {
        console.error("Erro ao processar imagem:", file.name);
      }
    }

    if (newImages.length > 0) {
      setImages(prev => [...prev, ...newImages]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      let filesArray = Array.from(e.target.files) as File[];
      processFiles(filesArray);
    }
    // RESET CRÍTICO
    if (e.target) e.target.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => {
      const target = prev.find(img => img.id === id);
      if (target) URL.revokeObjectURL(target.previewUrl);
      return prev.filter(img => img.id !== id);
    });
  };

  const toggleActive = (id: string) => {
    setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img));
  };

  const updateActiveCount = (count: number) => {
    setImages(prev => prev.map((img, idx) => ({
      ...img,
      isActive: idx < count
    })));
  };

  const moveImage = (index: number, direction: 'up' | 'down') => {
    const newImages = [...images];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex >= 0 && targetIndex < newImages.length) {
      [newImages[index], newImages[targetIndex]] = [newImages[targetIndex], newImages[index]];
      setImages(newImages);
    }
  };

  const handleExport = async () => {
    const canvas = document.querySelector('canvas') as HTMLCanvasElement;
    if (!canvas) return;
    const fileName = `grid_miau_${Date.now()}.png`;
    const dataUrl = canvas.toDataURL('image/png', 1.0);

    if (downloadIndividual) {
      const link = document.createElement('a');
      link.download = fileName; link.href = dataUrl; link.click();
    }
    if (downloadZip) {
      const zip = new JSZip();
      zip.file(fileName, dataUrl.split(',')[1], { base64: true });
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `grid_pack_miau_${Date.now()}.zip`; link.click();
    }
  };

  const clearAll = useCallback(() => {
    images.forEach(img => { if (img.previewUrl) URL.revokeObjectURL(img.previewUrl); });
    setImages([]); setOffset({ x: 0, y: 0 }); setZoom(0.4);
  }, [images]);

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 flex-shrink-0 border-r overflow-y-auto bg-theme-side border-theme custom-scrollbar">
