const DEFAULT_SETTINGS: AlphaEdgeSettings = {
  thickness: 20,
  softness: 5,
  borderScale: 100,
  opacity: 100,
  color: '#ffffff',
  boundaryMode: 'silhouette',
  geometricShape: 'circle',
  shapeOffsetX: 0,
  shapeOffsetY: 0,
  advanced: {
    enabled: false,
    gridEnabled: true,
    scatterEnabled: false,
    shapeType: 'circle',
    size: 15,
    spacingX: 10,
    spacingY: 10,
    color: '#ffffff',
    backgroundType: 'solid',
    bgColor: '#000000',
    gradientAngle: 0,
    gradientStops: [
      { id: '1', color: '#1e293b', offset: 0 },
      { id: '2', color: '#4f46e5', offset: 1 }
    ],
    individualRotation: 0,
