};

const drawStar = (ctx: CanvasRenderingContext2D, size: number) => {
  const spikes = 5;
  const outerRadius = size / 2;
  const innerRadius = size / 4;
  let rot = (Math.PI / 2) * 3;
  let x = 0;
  let y = 0;
  const step = Math.PI / spikes;

  ctx.beginPath();
  ctx.moveTo(0, -outerRadius);
  for (let i = 0; i < spikes; i++) {
    x = Math.cos(rot) * outerRadius;
    y = Math.sin(rot) * outerRadius;
    ctx.lineTo(x, y);
    rot += step;

    x = Math.cos(rot) * innerRadius;
    y = Math.sin(rot) * innerRadius;
    ctx.lineTo(x, y);
    rot += step;
  }
  ctx.lineTo(0, -outerRadius);
  ctx.closePath();
};

const drawCatPawClassic = (ctx: CanvasRenderingContext2D, size: number) => {
  const s = size / 2;
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(0, s * 0.2, s * 0.65, s * 0.5, 0, 0, Math.PI * 2);
  ctx.fill();
  const toeRadius = s * 0.22;
  ctx.beginPath(); ctx.arc(-s * 0.5, -s * 0.25, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(-s * 0.18, -s * 0.5, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(s * 0.18, -s * 0.5, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(s * 0.5, -s * 0.25, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
};

const AlphaEdgeTool: React.FC<AlphaEdgeToolProps> = ({ globalPreviewQuality = 'fast' }) => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [autoSave, setAutoSave] = useState(true);
  const customShapeImgs = useRef<Map<string, HTMLImageElement>>(new Map());

  const [batchSettings, setBatchSettings] = useState<Record<string, AlphaEdgeSettings>>({});
  const [settings, setSettings] = useState<AlphaEdgeSettings>(DEFAULT_SETTINGS);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  const currentImg = images[selectedIdx];

  useEffect(() => {
    const urlsToLoad = new Set<string>();
    if (settings.advanced?.shapeType === 'custom' && settings.advanced?.customShapeUrl) {
      urlsToLoad.add(settings.advanced.customShapeUrl);
    }
    Object.values(batchSettings).forEach((s: AlphaEdgeSettings) => {
      if (s.advanced?.shapeType === 'custom' && s.advanced?.customShapeUrl) {
        urlsToLoad.add(s.advanced.customShapeUrl);
      }
    });

    urlsToLoad.forEach(url => {
      if (!customShapeImgs.current.has(url)) {
        const img = new Image();
        img.src = url;
        img.onload = () => {
          customShapeImgs.current.set(url, img);
          if (settings.advanced?.customShapeUrl === url && currentImg) {
             const previewImg = new Image();
             previewImg.src = currentImg.previewUrl;
             previewImg.onload = () => drawEdge(previewImg, previewCanvasRef.current!, settings, false);
          }
        };
      }
    });
  }, [settings, batchSettings, currentImg]);

  const handleSettingsChange = (newSettings: AlphaEdgeSettings) => {
    setSettings(newSettings);
    if (autoSave && currentImg) {
      setBatchSettings(prev => ({ ...prev, [currentImg.id]: newSettings }));
    }
  };

  const applyToAll = () => {
    const newBatch: Record<string, AlphaEdgeSettings> = {};
    images.forEach(img => { newBatch[img.id] = { ...settings }; });
    setBatchSettings(newBatch);
  };

  const navigateTo = (newIdx: number) => {
    const nextImg = images[newIdx];
    if (nextImg) {
      if (batchSettings[nextImg.id]) {
        setSettings(batchSettings[nextImg.id]);
      } else if (autoSave) {
        setBatchSettings(prev => ({ ...prev, [nextImg.id]: settings }));
      }
      setSelectedIdx(newIdx);
    }
  };

  const getScaledPadding = useCallback((imgW: number, imgH: number, s: AlphaEdgeSettings) => {
    const scale = s.borderScale / 100;
    const effectiveBorder = s.thickness + (s.softness * 2.5);
    const offsetX = Math.abs(s.shapeOffsetX);
    const offsetY = Math.abs(s.shapeOffsetY);
    const paddingBase = (effectiveBorder + Math.max(offsetX, offsetY) + 80) * scale;
    return Math.ceil(Math.max(100, paddingBase)); 
  }, []);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number, customUrl?: string) => {
    if (type === 'none') return;
    const s = size / 2;
    ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') { ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath(); }
    else if (type === 'heart') {
      const h = size * 0.4; ctx.moveTo(0, h);
      ctx.bezierCurveTo(-size * 0.7, -size * 0.1, -size * 0.5, -size * 0.9, 0, -size * 0.4);
      ctx.bezierCurveTo(size * 0.5, -size * 0.9, size * 0.7, -size * 0.1, 0, h);
    } else if (type === 'diamond') { ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath(); }
    else if (type === 'star') { drawStar(ctx, size); }
    else if (type === 'pata') { drawCatPawClassic(ctx, size); return; }
    else if (type === 'custom' && customUrl && customShapeImgs.current.has(customUrl)) {
      ctx.drawImage(customShapeImgs.current.get(customUrl)!, -s, -s, size, size);
      return;
    }
    ctx.fill();
  };

  const applyBackground = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    if (config.backgroundType === 'solid') {
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, w, h);
    } else {
      const angle = (config.gradientAngle * Math.PI) / 180;
      const x1 = w/2 - Math.cos(angle) * w/2;
      const y1 = h/2 - Math.sin(angle) * h/2;
      const x2 = w/2 + Math.cos(angle) * w/2;
      const y2 = h/2 + Math.sin(angle) * h/2;
      const grad = ctx.createLinearGradient(x1, y1, x2, y2);
      config.gradientStops.forEach(stop => grad.addColorStop(Math.max(0, Math.min(1, stop.offset)), stop.color));
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, w, h);
    }
  };

  const drawPattern = (ctx: CanvasRenderingContext2D, w: number, h: number, config: AdvancedBorderSettings) => {
    ctx.save();
    applyBackground(ctx, w, h, config);
    if (config.gridEnabled && config.shapeType !== 'none') {
      ctx.translate(w / 2 + config.offsetX, h / 2 + config.offsetY);
      ctx.rotate((config.globalRotation * Math.PI) / 180);
      ctx.translate(-w / 2, -h / 2);
      ctx.fillStyle = config.color;
      const stepX = config.size + config.spacingX;
      const stepY = config.size + config.spacingY;
      for (let x = -w; x < w * 2; x += stepX) {
        for (let y = -h; y < h * 2; y += stepY) {
          ctx.save(); ctx.translate(x, y); ctx.rotate((config.individualRotation * Math.PI) / 180);
          drawShape(ctx, config.shapeType, config.size, config.customShapeUrl); ctx.restore();
        }
      }
    }
    ctx.restore();
  };

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings, isExport: boolean) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const bScale = config.borderScale / 100;
    const finalPadding = getScaledPadding(img.width, img.height, config);
    canvas.width = img.width + (finalPadding * 2); canvas.height = img.height + (finalPadding * 2);
    const centerX = canvas.width / 2; const centerY = canvas.height / 2;

    const unitPadding = Math.max(img.width, img.height) + 150;
    const unitCanvas = document.createElement('canvas');
    unitCanvas.width = unitPadding * 2; unitCanvas.height = unitPadding * 2;
    const uCtx = unitCanvas.getContext('2d');
    if (!uCtx) return;

    const silCanvas = document.createElement('canvas');
    silCanvas.width = unitCanvas.width; silCanvas.height = unitCanvas.height;
    const sCtx = silCanvas.getContext('2d');
    if (sCtx) {
      sCtx.translate(silCanvas.width / 2, silCanvas.height / 2);
      if (config.boundaryMode === 'silhouette') {
        sCtx.drawImage(img, -img.width/2, -img.height/2);
        sCtx.globalCompositeOperation = 'source-in'; sCtx.fillStyle = '#ffffff';
        sCtx.fillRect(-silCanvas.width/2, -silCanvas.height/2, silCanvas.width, silCanvas.height);
      } else {
        const baseSize = Math.max(img.width, img.height);
        sCtx.fillStyle = '#ffffff';
        drawShape(sCtx, config.geometricShape, baseSize);
      }
    }

    const maskCanvas = document.createElement('canvas');
    maskCanvas.width = unitCanvas.width; maskCanvas.height = unitCanvas.height;
    const mCtx = maskCanvas.getContext('2d');
    if (mCtx) {
      const totalGrowth = config.thickness;
      mCtx.drawImage(silCanvas, 0, 0);

      if (totalGrowth > 0) {
        if (isExport) {
          for (let r = 1; r <= totalGrowth; r += 1) {
            const samples = Math.max(16, Math.round(r * 3));
            for (let i = 0; i < samples; i++) {
              const angle = (i / samples) * Math.PI * 2;
              mCtx.drawImage(silCanvas, Math.cos(angle) * r, Math.sin(angle) * r);
            }
          }
        } else {
          const quality = globalPreviewQuality;
          let layers = 2;
          let samplesPerLayer = 12;

          switch (quality) {
            case 'fast': layers = 2; samplesPerLayer = 12; break;
            case 'moderate': layers = 3; samplesPerLayer = 16; break;
            case 'medium': layers = 4; samplesPerLayer = 20; break;
            case 'high': layers = 6; samplesPerLayer = 24; break;
            case 'ultra': layers = 10; samplesPerLayer = 32; break;
          }

          for (let l = 1; l <= layers; l++) {
            const r = (totalGrowth / layers) * l;
            for (let i = 0; i < samplesPerLayer; i++) {
              const angle = (i / samplesPerLayer) * Math.PI * 2;
              mCtx.drawImage(silCanvas, Math.cos(angle) * r, Math.sin(angle) * r);
            }
          }
        }
      }

      if (config.softness > 0) {
        const temp = document.createElement('canvas');
        temp.width = unitCanvas.width; temp.height = unitCanvas.height;
        const tCtx = temp.getContext('2d');
        if (tCtx) {
          tCtx.filter = `blur(${config.softness}px)`;
          tCtx.drawImage(maskCanvas, 0, 0);
          mCtx.clearRect(0, 0, maskCanvas.width, maskCanvas.height);
          mCtx.drawImage(temp, 0, 0);
        }
      }
    }

    const glowVisualCanvas = document.createElement('canvas');
    glowVisualCanvas.width = unitCanvas.width; glowVisualCanvas.height = unitCanvas.height;
    const gvCtx = glowVisualCanvas.getContext('2d');
    if (gvCtx) {
      gvCtx.save();
      if (config.advanced?.enabled) drawPattern(gvCtx, unitCanvas.width, unitCanvas.height, config.advanced);
      else { gvCtx.fillStyle = config.color; gvCtx.fillRect(0, 0, unitCanvas.width, unitCanvas.height); }
      gvCtx.globalCompositeOperation = 'destination-in';
      gvCtx.drawImage(maskCanvas, 0, 0); 
      gvCtx.restore();
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const sX = config.shapeOffsetX; const sY = config.shapeOffsetY;

    ctx.save(); 
    ctx.globalAlpha = config.opacity / 100; 
    ctx.translate(centerX + sX * bScale, centerY + sY * bScale); 
    ctx.scale(bScale, bScale); 
    ctx.drawImage(glowVisualCanvas, -glowVisualCanvas.width / 2, -glowVisualCanvas.height / 2); 
    ctx.restore();

    ctx.save(); 
    ctx.translate(centerX - img.width/2, centerY - img.height/2);
    ctx.drawImage(img, 0, 0); 
    ctx.restore();
  }, [getScaledPadding, globalPreviewQuality]);

  useEffect(() => {
    let animId: number;
    const updatePreview = async () => {
      if (!previewCanvasRef.current || !currentImg) return;

      animId = requestAnimationFrame(() => {
        const img = new Image(); img.src = currentImg.previewUrl;
        img.onload = () => drawEdge(img, previewCanvasRef.current!, settings, false);
      });
    };
    updatePreview();
    return () => cancelAnimationFrame(animId);
  }, [selectedIdx, currentImg, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = []; const newBatchStates: Record<string, AlphaEdgeSettings> = {};
    for (const file of files) {
      const id = uuidv4(); const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => { const i = new Image(); i.onload = () => resolve(i); i.src = url; });
      newImgs.push({ id, file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height, isActive: true });
      newBatchStates[id] = { ...settings };
    }
    setImages(prev => [...prev, ...newImgs]);
    setBatchSettings(prev => ({ ...prev, ...newBatchStates }));

    // RESET CRÍTICO
    if (e.target) e.target.value = '';
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    const zip = downloadZip ? new JSZip() : null;
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i]; const currentConfig = batchSettings[item.id] || settings;
      const img = await new Promise<HTMLImageElement>((resolve) => { const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl; });
      await drawEdge(img, canvas, currentConfig, true);
      const dataUrl = canvas.toDataURL('image/png');
      const fileName = `${item.file.name.split('.')[0]}_miau.png`;
      if (downloadIndividual) {
        const link = document.createElement('a'); link.download = fileName; link.href = dataUrl; link.click();
        await new Promise(r => setTimeout(r, 400));
      }
      if (zip) zip.file(fileName, dataUrl.split(',')[1], { base64: true });
    }
    if (zip) {
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a'); link.href = URL.createObjectURL(content); link.download = `borde_maker_batch_${Date.now()}.zip`; link.click();
    }
    setIsProcessing(false);
  };

  const handleExportGrid = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const cols = Math.ceil(Math.sqrt(images.length));
    const rows = Math.ceil(images.length / cols);
    const itemBuffers: HTMLCanvasElement[] = [];
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i]; const currentConfig = batchSettings[item.id] || settings;
      const img = await new Promise<HTMLImageElement>((resolve) => { const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl; });
      const bCanvas = document.createElement('canvas');
      await drawEdge(img, bCanvas, currentConfig, true);
      itemBuffers.push(bCanvas);
    }
    const maxW = Math.max(...itemBuffers.map(b => b.width));
    const maxH = Math.max(...itemBuffers.map(b => b.height));
    const spacing = 40;
    const masterCanvas = document.createElement('canvas');
    masterCanvas.width = (maxW * cols) + (spacing * (cols + 1));
    masterCanvas.height = (maxH * rows) + (spacing * (rows + 1));
    const mCtx = masterCanvas.getContext('2d');
    if (!mCtx) return;
    itemBuffers.forEach((buf, idx) => {
      const col = idx % cols; const row = Math.floor(idx / cols);
      const x = spacing + col * (maxW + spacing) + (maxW - buf.width) / 2;
      const y = spacing + row * (maxH + spacing) + (maxH - buf.height) / 2;
      mCtx.drawImage(buf, x, y);
    });
    const link = document.createElement('a'); link.download = `borde_grid_miau_${Date.now()}.png`; link.href = masterCanvas.toDataURL('image/png'); link.click();
    setIsProcessing(false);
  };

  const currentPadding = currentImg ? getScaledPadding(currentImg.width, currentImg.height, settings) : 0;

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={handleSettingsChange}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onOpenAdvanced={() => setIsModalOpen(true)}
          autoSave={autoSave} onAutoSaveChange={setAutoSave}
          onApplyToAll={applyToAll}
          onExportGrid={handleExportGrid}
        />
      </aside>
      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => { setImages([]); setBatchSettings({}); }} />
        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-[2.5rem]"
                style={{ 
                  width: (currentImg.width + currentPadding * 2) * zoom,
                  height: (currentImg.height + currentPadding * 2) * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <canvas ref={previewCanvasRef} className="w-full h-full block" />
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Borde Maker Studio</p>
            </div>
          )}
          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <div className="flex items-center gap-6">
                <button disabled={selectedIdx === 0} onClick={() => navigateTo(selectedIdx - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[10px]"></i></button>
                <span className="text-[11px] font-mono font-black text-theme-accent min-w-[70px] text-center">{selectedIdx + 1} / {images.length}</span>
                <button disabled={selectedIdx >= images.length - 1} onClick={() => navigateTo(selectedIdx + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[10px]"></i></button>
              </div>
            </div>
          )}
        </div>
      </section>
      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <ImageList images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} onToggleActive={(id) => setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img))} />
      </aside>
      <input type="file" multiple accept="image/png, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
      <AdvancedBorderModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} settings={settings.advanced!} onUpdate={(adv) => handleSettingsChange({ ...settings, advanced: adv })} baseImage={currentImg ? { url: currentImg.previewUrl, width: currentImg.width, height: currentImg.height } : null} />
    </div>
  );
};

