export type ToolType = 'grid' | 'framing' | 'resizer' | 'alpha-edge' | 'ai-lab';
export type ThemeType = 'dark' | 'light' | 'pastel' | 'midnight';

export interface GridImage {
  id: string;
  file: File;
  previewUrl: string;
  width: number;
  height: number;
  aspectRatio: number;
  isActive?: boolean;
  visible?: boolean;
  x?: number;
  y?: number;
  scale?: number;
  rotation?: number;
}

// Interface for Grid Tool settings
export interface GridSettings {
  canvasWidth: number;
  canvasHeight: number;
  columns: number;
  innerSpacing: number;
  outerMargin: number;
  backgroundColor: string;
  isTransparent: boolean;
  layoutMode: 'grid' | 'auto';
  itemScale: number;
  targetShape: 'square' | 'portrait' | 'landscape';
}

export interface AISettings {
  mode: 'enhance' | 'denoise' | 'restore';
  sharpness: number;
  noiseReduction: number;
  brightness: number;
  contrast: number;
  aiIntensity: number;
  edgeSmoothness: number;
  // Configurações de Nitidez Inteligente
  smartSharpen: boolean;
  highPassRadius: number;
  // Sistema de Dupla Frequência
  isAdvancedSharpen: boolean;
  highFreqRadius: number;
  highFreqOpacity: number;
  lowFreqRadius: number;
  lowFreqOpacity: number;
}

export type PreviewQuality = 'fast' | 'moderate' | 'medium' | 'high' | 'ultra';

export interface AlphaEdgeSettings {
  thickness: number;
  softness: number;
  borderScale: number;
  opacity: number;
  color: string;
  boundaryMode: 'silhouette' | 'geometric';
  geometricShape: 'circle' | 'square' | 'heart' | 'diamond' | 'star';
  shapeOffsetX: number;
  shapeOffsetY: number;
  previewQuality?: PreviewQuality;
  advanced?: AdvancedBorderSettings;
}

export interface FrameSettings {
  borderWidth: number;
  borderColor: string;
  borderRadius: number;
  padding: number;
  shadow: number;
  canvasWidth: number;
  canvasHeight: number;
  frameImageUrl?: string;
  frameImageName?: string;
}

export interface AdvancedBorderSettings {
  enabled: boolean;
  gridEnabled: boolean;
  scatterEnabled: boolean;
  shapeType: 'circle' | 'square' | 'triangle' | 'x' | 'heart' | 'diamond' | 'none' | 'pata' | 'custom' | 'star';
  customShapeUrl?: string;
  size: number;
  spacingX: number;
  spacingY: number;
  color: string;
  backgroundType: 'solid' | 'gradient';
  bgColor: string;
  gradientAngle: number;
  gradientStops: GradientStop[];
  individualRotation: number;
  globalRotation: number;
  offsetX: number;
  offsetY: number;
  scatterSize: number;
  scatterDensity: number;
  scatterRadiusOffset: number;
  scatterIndividualRotation: number;
}

export interface PatternPreset {
  id: string;
  name: string;
  settings: AdvancedBorderSettings;
  createdAt: number;
}

export interface GradientStop {
  id: string;
  color: string;
  offset: number;
}

