import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import Header from '../components/Header';
import { GridImage, AISettings } from '../types';

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [compareSplit, setCompareSplit] = useState(50);
  const [isComparing, setIsComparing] = useState(true);
  const [enhancedUrl, setEnhancedUrl] = useState<string | null>(null);

  // Camadas de High Pass
  const [highPassUrl, setHighPassUrl] = useState<string | null>(null);
  const [highPassUrlFine, setHighPassUrlFine] = useState<string | null>(null);
  const [highPassUrlLarge, setHighPassUrlLarge] = useState<string | null>(null);

  const [showConfirmModal, setShowConfirmModal] = useState(false);

  const [aiSettings, setAiSettings] = useState<AISettings>({
    mode: 'enhance',
    sharpness: 0,
    noiseReduction: 0,
    brightness: 100,
    contrast: 100,
    aiIntensity: 70,
    edgeSmoothness: 2,
    smartSharpen: false,
    highPassRadius: 1.5,
    // Sistema Avançado
    isAdvancedSharpen: false,
    highFreqRadius: 1.2,
    highFreqOpacity: 100,
    lowFreqRadius: 8.0,
    lowFreqOpacity: 50
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentImg = images[selectedIdx];

  useEffect(() => {
    setEnhancedUrl(null);
    setHighPassUrl(null);
    setHighPassUrlFine(null);
    setHighPassUrlLarge(null);
  }, [selectedIdx]);

  // Função genérica para gerar uma camada de High Pass
  const generateSingleHighPass = async (imgSrc: string, radius: number): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = imgSrc;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        if (!ctx) return resolve('');

        canvas.width = img.width;
        canvas.height = img.height;
        ctx.drawImage(img, 0, 0);

        const blurCanvas = document.createElement('canvas');
        blurCanvas.width = canvas.width;
        blurCanvas.height = canvas.height;
        const bCtx = blurCanvas.getContext('2d');
        if (bCtx) {
          bCtx.filter = `blur(${radius}px) grayscale(100%)`;
          bCtx.drawImage(img, 0, 0);
        }

        const originalData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const blurredData = bCtx?.getImageData(0, 0, canvas.width, canvas.height);

        if (blurredData) {
          for (let i = 0; i < originalData.data.length; i += 4) {
            originalData.data[i] = 128 + (originalData.data[i] - blurredData.data[i]);
            originalData.data[i+1] = 128 + (originalData.data[i+1] - blurredData.data[i+1]);
            originalData.data[i+2] = 128 + (originalData.data[i+2] - blurredData.data[i+2]);
          }
          ctx.putImageData(originalData, 0, 0);
        }
        resolve(canvas.toDataURL('image/png'));
      };
    });
  };

  const updateHighPassLayers = useCallback(async () => {
    if (!currentImg || !aiSettings.smartSharpen) {
      setHighPassUrl(null);
      setHighPassUrlFine(null);
      setHighPassUrlLarge(null);
      return;
    }

    const source = enhancedUrl || currentImg.previewUrl;

    if (aiSettings.isAdvancedSharpen) {
      // Gera as duas camadas separadamente
      const fine = await generateSingleHighPass(source, aiSettings.highFreqRadius);
      const large = await generateSingleHighPass(source, aiSettings.lowFreqRadius);
      setHighPassUrlFine(fine);
      setHighPassUrlLarge(large);
      setHighPassUrl(null);
    } else {
      // Gera apenas a camada padrão
      const standard = await generateSingleHighPass(source, aiSettings.highPassRadius);
      setHighPassUrl(standard);
      setHighPassUrlFine(null);
      setHighPassUrlLarge(null);
    }
  }, [currentImg, enhancedUrl, aiSettings.smartSharpen, aiSettings.isAdvancedSharpen, aiSettings.highPassRadius, aiSettings.highFreqRadius, aiSettings.lowFreqRadius]);

  useEffect(() => {
    updateHighPassLayers();
  }, [updateHighPassLayers]);

  const processWithAI = async (mode: AISettings['mode']) => {
    if (!currentImg) return;
    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = mode === 'enhance' 
        ? `Professional image enhancement: improve clarity, colors and overall quality. Do NOT add, remove or reconstruct any objects or structural elements. Maintain 100% fidelity to the original shapes and content. Intensity: ${aiSettings.aiIntensity}%`
        : `Denoise this image: remove digital noise and compression artifacts while keeping edges sharp. Maintain maximum realism. Intensity: ${aiSettings.aiIntensity}%`;

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(currentImg.file);
      });
      const base64Data = await base64Promise;

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType: currentImg.file.type } },
            { text: prompt }
          ]
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            setEnhancedUrl(`data:image/png;base64,${part.inlineData.data}`);
            break;
          }
        }
      }
    } catch (error) {
      console.error("Erro AI Enhancer:", error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!currentImg) return;

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = enhancedUrl || currentImg.previewUrl;

    img.onload = async () => {
      canvas.width = img.width;
      canvas.height = img.height;
      ctx.filter = getFilterString();
      ctx.drawImage(img, 0, 0);

      if (aiSettings.smartSharpen) {
        ctx.globalCompositeOperation = 'overlay';

        if (aiSettings.isAdvancedSharpen) {
          // Bake da camada de Alta Frequência
          if (highPassUrlFine) {
            const hpFine = new Image();
            await new Promise(r => {
              hpFine.onload = () => {
                ctx.globalAlpha = aiSettings.highFreqOpacity / 100;
                ctx.drawImage(hpFine, 0, 0);
                r(null);
              };
              hpFine.src = highPassUrlFine;
            });
          }
          // Bake da camada de Baixa Frequência
          if (highPassUrlLarge) {
            const hpLarge = new Image();
            await new Promise(r => {
              hpLarge.onload = () => {
                ctx.globalAlpha = aiSettings.lowFreqOpacity / 100;
                ctx.drawImage(hpLarge, 0, 0);
                r(null);
              };
              hpLarge.src = highPassUrlLarge;
            });
          }
        } else if (highPassUrl) {
          // Bake padrão
          const hpStd = new Image();
          await new Promise(r => {
            hpStd.onload = () => {
              ctx.globalAlpha = 1.0;
              ctx.drawImage(hpStd, 0, 0);
              r(null);
            };
            hpStd.src = highPassUrl;
          });
        }
      }

      const link = document.createElement('a');
      link.download = `miau_lab_${Date.now()}.png`;
      link.href = canvas.toDataURL('image/png', 1.0);
      link.click();
    };
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      setImages([{ id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height }]);
      setSelectedIdx(0);
      setEnhancedUrl(null);
    };
    img.src = url;
    e.target.value = '';
  };

  const triggerUpload = () => {
    if (images.length > 0) setShowConfirmModal(true);
    else fileInputRef.current?.click();
  };

  const getFilterString = () => {
    const sharpen = aiSettings.sharpness > 0 
      ? `contrast(${100 + aiSettings.sharpness/2}%) brightness(${100 - aiSettings.sharpness/20}%)` 
      : '';
    const blur = aiSettings.noiseReduction > 0 ? `blur(${aiSettings.noiseReduction/20}px)` : '';
    return `brightness(${aiSettings.brightness}%) contrast(${aiSettings.contrast}%) ${sharpen} ${blur}`;
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={setAiSettings}
          onAdd={triggerUpload}
          onProcess={processWithAI}
          onSave={handleDownload}
          isProcessing={isProcessing}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => { setImages([]); setEnhancedUrl(null); }} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden rounded-[2.5rem] group"
                style={{ 
                  width: currentImg.width * zoom,
                  height: currentImg.height * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <img src={currentImg.previewUrl} className="absolute inset-0 w-full h-full object-cover" alt="original" />

                <div 
                  className="absolute inset-0 w-full h-full overflow-hidden"
                  style={{ clipPath: isComparing ? `inset(0 0 0 ${compareSplit}%)` : 'none' }}
                >
                  <img src={enhancedUrl || currentImg.previewUrl} className="absolute inset-0 w-full h-full object-cover" style={{ filter: getFilterString() }} alt="enhanced" />

                  {/* Camadas de High Pass */}
                  {aiSettings.smartSharpen && (
                    <>
                      {/* Camada Padrão */}
                      {!aiSettings.isAdvancedSharpen && highPassUrl && (
                        <img src={highPassUrl} className="absolute inset-0 w-full h-full object-cover" style={{ mixBlendMode: 'overlay' }} alt="hp-std" />
                      )}

                      {/* Camadas Avançadas */}
                      {aiSettings.isAdvancedSharpen && (
                        <>
                          {highPassUrlFine && (
                            <img 
                              src={highPassUrlFine} 
                              className="absolute inset-0 w-full h-full object-cover" 
                              style={{ mixBlendMode: 'overlay', opacity: aiSettings.highFreqOpacity / 100 }} 
                              alt="hp-fine" 
                            />
                          )}
                          {highPassUrlLarge && (
                            <img 
                              src={highPassUrlLarge} 
                              className="absolute inset-0 w-full h-full object-cover" 
                              style={{ mixBlendMode: 'overlay', opacity: aiSettings.lowFreqOpacity / 100 }} 
                              alt="hp-large" 
                            />
                          )}
                        </>
                      )}
                    </>
                  )}
                </div>

                {isComparing && (
                  <>
                    <div className="absolute top-0 bottom-0 w-0.5 bg-theme-accent z-10 shadow-[0_0_15px_rgba(79,70,229,0.8)] pointer-events-none" style={{ left: `${compareSplit}%` }}>
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-theme-accent text-white flex items-center justify-center text-[10px] shadow-2xl"><i className="fas fa-arrows-alt-h"></i></div>
                    </div>
                    <input type="range" min="0" max="100" value={compareSplit} onChange={(e) => setCompareSplit(parseInt(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-20" />
                    <div className="absolute top-6 left-6 px-3 py-1 bg-black/40 backdrop-blur-md rounded-lg text-[8px] font-black uppercase text-white/60 tracking-widest z-30">Antes</div>
                    <div className="absolute top-6 right-6 px-3 py-1 bg-theme-accent/80 backdrop-blur-md rounded-lg text-[8px] font-black uppercase text-white tracking-widest z-30">Depois</div>
                  </>
                )}

                {isProcessing && (
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-xl flex flex-col items-center justify-center text-white z-50 animate-in fade-in duration-500">
                    <div className="w-16 h-16 border-4 border-theme-accent border-t-transparent rounded-full animate-spin mb-6"></div>
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">Sincronia Neural...</p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Miau AI Enhancer</p>
            </div>
          )}

          {currentImg && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-32 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <button onClick={() => setIsComparing(!isComparing)} className={`flex items-center gap-2 px-4 py-1.5 rounded-full text-[9px] font-black uppercase transition-all ${isComparing ? 'bg-theme-accent text-white shadow-lg' : 'bg-theme-panel/50 opacity-40 hover:opacity-100'}`}><i className="fas fa-columns"></i><span>{isComparing ? 'Ver Final' : 'Comparar'}</span></button>
            </div>
          )}
        </div>
      </section>

      {showConfirmModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 backdrop-blur-xl bg-black/40 animate-in fade-in duration-300">
          <div className="max-w-md w-full bg-theme-side border border-theme rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden text-center">
            <div className="w-16 h-16 rounded-3xl bg-theme-accent flex items-center justify-center text-white text-2xl shadow-xl mx-auto mb-6"><i className="fas fa-exclamation-triangle"></i></div>
            <h3 className="text-xl font-black uppercase tracking-tighter text-theme-main mb-2">Substituir Edição?</h3>
            <p className="text-[10px] opacity-50 uppercase tracking-widest mb-8 leading-relaxed px-4">Deseja salvar o resultado atual antes de carregar uma nova imagem?</p>
            <div className="flex flex-col gap-3">
              <button onClick={() => { handleDownload(); setShowConfirmModal(false); setTimeout(() => fileInputRef.current?.click(), 100); }} className="w-full py-4 rounded-2xl bg-theme-accent text-white font-black uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2"><i className="fas fa-download"></i> Salvar e Carregar Nova</button>
              <button onClick={() => { setShowConfirmModal(false); setTimeout(() => fileInputRef.current?.click(), 100); }} className="w-full py-4 rounded-2xl bg-theme-panel border border-theme text-theme-main font-black uppercase text-[10px] tracking-widest active:scale-95 transition-all">Apenas Substituir</button>
              <button onClick={() => setShowConfirmModal(false)} className="w-full py-3 rounded-2xl text-[9px] font-black uppercase opacity-30 hover:opacity-100 transition-all">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      <input type="file" accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default AILabTool;

export type ToolType = 'grid' | 'framing' | 'resizer' | 'alpha-edge' | 'ai-lab';
export type ThemeType = 'dark' | 'light' | 'pastel' | 'midnight';

export interface GridImage {
  id: string;
  file: File;
  previewUrl: string;
  width: number;
  height: number;
  aspectRatio: number;
  isActive?: boolean;
  visible?: boolean;
  x?: number;
  y?: number;
  scale?: number;
  rotation?: number;
}

export interface HistoryState {
  id: string;
  url: string;
  label: string;
  timestamp: number;
  settingsSnapshot: AISettings;
}

export interface GridSettings {
  canvasWidth: number;
  canvasHeight: number;
  columns: number;
  innerSpacing: number;
  outerMargin: number;
  backgroundColor: string;
  isTransparent: boolean;
  layoutMode: 'grid' | 'auto';
  itemScale: number;
  targetShape: 'square' | 'portrait' | 'landscape';
}

export interface AISettings {
  mode: 'enhance' | 'denoise' | 'restore';
  sharpness: number;
  noiseReduction: number;
  brightness: number;
  contrast: number;
  aiIntensity: number;
  edgeSmoothness: number;
  smartSharpen: boolean;
  highPassRadius: number;
  isAdvancedSharpen: boolean;
  highFreqRadius: number;
  highFreqOpacity: number;
  lowFreqRadius: number;
  lowFreqOpacity: number;
}

export type PreviewQuality = 'fast' | 'moderate' | 'medium' | 'high' | 'ultra';

export interface AlphaEdgeSettings {
  thickness: number;
  softness: number;
  borderScale: number;
  opacity: number;
  color: string;
  boundaryMode: 'silhouette' | 'geometric';
  geometricShape: 'circle' | 'square' | 'heart' | 'diamond' | 'star';
  shapeOffsetX: number;
  shapeOffsetY: number;
  previewQuality?: PreviewQuality;
  advanced?: AdvancedBorderSettings;
}

export interface FrameSettings {
  borderWidth: number;
  borderColor: string;
  borderRadius: number;
  padding: number;
  shadow: number;
  canvasWidth: number;
  canvasHeight: number;
  frameImageUrl?: string;
  frameImageName?: string;
}

export interface AdvancedBorderSettings {
  enabled: boolean;
  gridEnabled: boolean;
  scatterEnabled: boolean;
  shapeType: 'circle' | 'square' | 'triangle' | 'x' | 'heart' | 'diamond' | 'none' | 'pata' | 'custom' | 'star';
  customShapeUrl?: string;
  size: number;
  spacingX: number;
  spacingY: number;
  color: string;
  backgroundType: 'solid' | 'gradient';
  bgColor: string;
  gradientAngle: number;
  gradientStops: GradientStop[];
  individualRotation: number;
  globalRotation: number;
  offsetX: number;
  offsetY: number;
  scatterSize: number;
  scatterDensity: number;
  scatterRadiusOffset: number;
  scatterIndividualRotation: number;
}

export interface PatternPreset {
  id: string;
  name: string;
  settings: AdvancedBorderSettings;
  createdAt: number;
}

export interface GradientStop {
  id: string;
  color: string;
  offset: number;
}

import React from 'react';
import { HistoryState } from '../types';

interface HistorySidebarProps {
  history: HistoryState[];
  currentIndex: number;
  onRestore: (index: number) => void;
  isOpen: boolean;
  onToggle: () => void;
}

const HistorySidebar: React.FC<HistorySidebarProps> = ({ history, currentIndex, onRestore, isOpen, onToggle }) => {
  return (
    <aside 
      className={`border-l border-theme bg-theme-side transition-all duration-500 overflow-hidden flex flex-col relative ${isOpen ? 'w-64' : 'w-0'}`}
    >
      <div className="min-w-[256px] h-full flex flex-col">
        <div className="p-4 border-b border-theme/30 bg-black/10 flex items-center justify-between">
          <span className="text-[10px] font-black uppercase tracking-[0.2em] text-theme-accent">Camadas / Histórico</span>
          <i className="fas fa-layer-group opacity-30 text-xs"></i>
        </div>

        <div className="flex-1 overflow-y-auto p-3 space-y-3 custom-scrollbar">
          {history.length === 0 ? (
            <div className="h-40 flex flex-col items-center justify-center text-center opacity-20 p-4">
              <i className="fas fa-history text-2xl mb-2"></i>
              <p className="text-[9px] font-black uppercase">Sem histórico</p>
            </div>
          ) : (
            history.map((state, idx) => (
              <button 
                key={state.id}
                onClick={() => onRestore(idx)}
                className={`w-full group relative flex flex-col gap-2 p-2 rounded-2xl border transition-all text-left overflow-hidden ${currentIndex === idx ? 'border-theme-accent bg-theme-accent/5 ring-1 ring-theme-accent/20' : 'border-transparent bg-theme-panel/20 hover:border-theme'}`}
              >
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-lg bg-black/20 border border-theme overflow-hidden flex-shrink-0">
                    <img src={state.url} className="w-full h-full object-cover" alt="history-step" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className={`text-[9px] font-black uppercase truncate ${currentIndex === idx ? 'text-theme-accent' : 'opacity-60'}`}>
                      {state.label}
                    </p>
                    <p className="text-[7px] opacity-30 uppercase font-mono">
                      {new Date(state.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                    </p>
                  </div>
                </div>
                {currentIndex === idx && (
                  <div className="absolute right-2 top-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-theme-accent shadow-[0_0_8px_rgba(79,70,229,0.8)]"></div>
                  </div>
                )}
              </button>
            )).reverse() // Mostra as mais recentes no topo
          )}
        </div>
      </div>
    </aside>
  );
};

export default HistorySidebar;

import React, { useState } from 'react';
import { AISettings } from '../types';
import MiauSlider from './MiauSlider';

interface SidebarAILabProps {
  settings: AISettings;
  onSettingsChange: (s: AISettings) => void;
  onAdd: () => void;
  onProcess: (mode: AISettings['mode']) => void;
  onSave: () => void;
  onBakeManual: () => void;
  isProcessing: boolean;
  hasManualChanges: boolean;
}

const SidebarAILab: React.FC<SidebarAILabProps> = ({ settings, onSettingsChange, onAdd, onProcess, onSave, onBakeManual, isProcessing, hasManualChanges }) => {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);

  const handleChange = (key: keyof AISettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  return (
    <div className="p-5 space-y-6 h-full flex flex-col overflow-y-auto custom-scrollbar">
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Fonte</h3>
        <button onClick={onAdd} className="w-full py-4 rounded-xl font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase active:scale-95 transition-all">
          <i className="fas fa-cloud-upload-alt"></i> Carregar Foto
        </button>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-5">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Aperfeiçoamento Real-Time</h3>
        <div className="space-y-4">
          <div className="bg-black/10 p-4 rounded-2xl border border-theme/30 space-y-4">
            <div className="flex items-center justify-between mb-1">
              <span className="text-[9px] font-black uppercase tracking-widest text-theme-accent">Smart Sharpen</span>
              <button 
                onClick={() => handleChange('smartSharpen', !settings.smartSharpen)}
                className={`w-8 h-4 rounded-full relative transition-all ${settings.smartSharpen ? 'bg-theme-accent' : 'bg-theme-panel'}`}
              >
                <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-all ${settings.smartSharpen ? 'right-0.5' : 'left-0.5'}`}></div>
              </button>
            </div>

            <div className={`space-y-4 transition-all ${!settings.smartSharpen ? 'opacity-20 pointer-events-none grayscale' : ''}`}>
              {!settings.isAdvancedSharpen && (
                <MiauSlider label="Frequência (Raio)" min={0.1} max={10} step={0.1} value={settings.highPassRadius} onChange={(v) => handleChange('highPassRadius', v)} icon="fa-wave-square" />
              )}

              <div className="space-y-3">
                <button 
                  onClick={() => {
                    const nextState = !isAdvancedOpen;
                    setIsAdvancedOpen(nextState);
                    handleChange('isAdvancedSharpen', nextState);
                  }}
                  className="w-full flex items-center justify-between group py-1"
                >
                  <div className="flex items-center gap-2">
                    <span className="text-[8px] font-black uppercase tracking-[0.2em] opacity-40 group-hover:opacity-100 transition-opacity">Advanced</span>
                    <div className="h-[1px] w-8 bg-theme/20 group-hover:bg-theme-accent/40 transition-all"></div>
                  </div>
                  <i className={`fas ${isAdvancedOpen ? 'fa-caret-down' : 'fa-caret-right'} text-[10px] text-theme-accent transition-transform`}></i>
                </button>

                {isAdvancedOpen && (
                  <div className="space-y-6 pt-2 animate-in slide-in-from-top-2 duration-300">
                    <div className="space-y-4 p-3 bg-black/20 rounded-xl border border-theme/30">
                      <p className="text-[7px] font-black uppercase opacity-30 tracking-widest text-center border-b border-theme/10 pb-1 mb-2">Camada: Alta Frequência</p>
                      <MiauSlider label="Raio (Detalhes)" min={0.1} max={5} step={0.1} value={settings.highFreqRadius} onChange={(v) => handleChange('highFreqRadius', v)} icon="fa-microchip" />
                      <MiauSlider label="Opacidade Alta" min={0} max={100} value={settings.highFreqOpacity} onChange={(v) => handleChange('highFreqOpacity', v)} unit="%" icon="fa-tint" />
                    </div>

                    <div className="space-y-4 p-3 bg-black/20 rounded-xl border border-theme/30">
                      <p className="text-[7px] font-black uppercase opacity-30 tracking-widest text-center border-b border-theme/10 pb-1 mb-2">Camada: Baixa Frequência</p>
                      <MiauSlider label="Raio (Volumes)" min={5} max={20} step={0.5} value={settings.lowFreqRadius} onChange={(v) => handleChange('lowFreqRadius', v)} icon="fa-mountain" />
                      <MiauSlider label="Opacidade Baixa" min={0} max={100} value={settings.lowFreqOpacity} onChange={(v) => handleChange('lowFreqOpacity', v)} unit="%" icon="fa-tint" />
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          <MiauSlider label="Nitidez Geral" min={0} max={100} value={settings.sharpness} onChange={(v) => handleChange('sharpness', v)} icon="fa-magic" />
          <MiauSlider label="Redução de Ruído" min={0} max={100} value={settings.noiseReduction} onChange={(v) => handleChange('noiseReduction', v)} icon="fa-broom" />
          <MiauSlider label="Contraste" min={50} max={200} value={settings.contrast} onChange={(v) => handleChange('contrast', v)} unit="%" icon="fa-adjust" />
          <MiauSlider label="Brilho" min={50} max={150} value={settings.brightness} onChange={(v) => handleChange('brightness', v)} unit="%" icon="fa-sun" />
        </div>

        {/* NOVO BOTÃO DE APLICAR AJUSTES */}
        <div className="pt-2">
          <button 
            onClick={onBakeManual}
            disabled={!hasManualChanges || isProcessing}
            className={`w-full py-3.5 rounded-xl font-black text-[9px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all active:scale-95 shadow-lg border ${hasManualChanges ? 'bg-white text-black border-white hover:bg-theme-panel' : 'opacity-30 border-theme bg-theme-panel pointer-events-none'}`}
          >
            <i className="fas fa-check-circle"></i> Aplicar Melhorias
          </button>
          <p className="text-[7px] opacity-30 uppercase mt-2 text-center tracking-tighter italic">Consolida ajustes manuais em uma nova camada</p>
        </div>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Módulos Neurais (IA)</h3>
        <div className="grid grid-cols-1 gap-2">
           <button 
             onClick={() => onProcess('enhance')} 
             disabled={isProcessing}
             className="w-full flex items-center justify-between p-3 rounded-xl border border-theme bg-theme-panel/30 hover:border-theme-accent transition-all group"
           >
             <div className="flex items-center gap-3">
                <i className="fas fa-sparkles text-theme-accent group-hover:scale-125 transition-transform"></i>
                <div className="text-left">
                   <p className="text-[9px] font-black uppercase">Enhanced com IA</p>
                   <p className="text-[7px] opacity-40 uppercase">Nitidez Realista</p>
                </div>
             </div>
             <i className="fas fa-chevron-right text-[8px] opacity-20"></i>
           </button>

           <button 
             onClick={() => onProcess('denoise')} 
             disabled={isProcessing}
             className="w-full flex items-center justify-between p-3 rounded-xl border border-theme bg-theme-panel/30 hover:border-theme-accent transition-all group"
           >
             <div className="flex items-center gap-3">
                <i className="fas fa-broom text-theme-accent group-hover:scale-125 transition-transform"></i>
                <div className="text-left">
                   <p className="text-[9px] font-black uppercase">Deep Clean</p>
                   <p className="text-[7px] opacity-40 uppercase">Remoção de Ruído IA</p>
                </div>
             </div>
             <i className="fas fa-chevron-right text-[8px] opacity-20"></i>
           </button>
        </div>

        <MiauSlider label="Intensidade IA" min={10} max={100} value={settings.aiIntensity} onChange={(v) => handleChange('aiIntensity', v)} unit="%" icon="fa-brain" />
      </div>

      <div className="mt-auto pt-4 flex flex-col gap-2">
        <button 
          onClick={onSave}
          className="w-full py-5 rounded-xl font-black text-[11px] bg-theme-accent text-theme-inv shadow-2xl flex items-center justify-center gap-2 uppercase active:scale-95 hover:opacity-90 transition-all"
        >
          <i className="fas fa-download"></i> Salvar Resultado Final
        </button>
      </div>
    </div>
  );
};

export default SidebarAILab;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import HistorySidebar from '../components/HistorySidebar';
import Header from '../components/Header';
import { GridImage, AISettings, HistoryState } from '../types';

const INITIAL_SETTINGS: AISettings = {
  mode: 'enhance',
  sharpness: 0,
  noiseReduction: 0,
  brightness: 100,
  contrast: 100,
  aiIntensity: 70,
  edgeSmoothness: 2,
  smartSharpen: false,
  highPassRadius: 1.5,
  isAdvancedSharpen: false,
  highFreqRadius: 1.2,
  highFreqOpacity: 100,
  lowFreqRadius: 8.0,
  lowFreqOpacity: 50
};

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [currentHistoryIdx, setCurrentHistoryIdx] = useState(-1);
  const [isHistoryOpen, setIsHistoryOpen] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [compareSplit, setCompareSplit] = useState(50);
  const [isComparing, setIsComparing] = useState(true);

  // Imagem base (que pode ser alterada pelo Bake) e a imagem processada por IA
  const [baseImageLayer, setBaseImageLayer] = useState<string | null>(null);
  const [aiEnhancedLayer, setAiEnhancedLayer] = useState<string | null>(null);

  // Camadas de High Pass
  const [highPassUrl, setHighPassUrl] = useState<string | null>(null);
  const [highPassUrlFine, setHighPassUrlFine] = useState<string | null>(null);
  const [highPassUrlLarge, setHighPassUrlLarge] = useState<string | null>(null);

  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [aiSettings, setAiSettings] = useState<AISettings>(INITIAL_SETTINGS);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentImg = images[0]; // No AI Lab trabalhamos com uma por vez

  // Verifica se há alterações manuais pendentes para habilitar o botão de Aplicar
  const hasManualChanges = useMemo(() => {
    return aiSettings.sharpness !== 0 || 
           aiSettings.noiseReduction !== 0 || 
           aiSettings.brightness !== 100 || 
           aiSettings.contrast !== 100 || 
           aiSettings.smartSharpen === true;
  }, [aiSettings]);

  // Limpa tudo ao mudar de ferramenta ou resetar
  const handleClear = useCallback(() => {
    setImages([]);
    setHistory([]);
    setCurrentHistoryIdx(-1);
    setBaseImageLayer(null);
    setAiEnhancedLayer(null);
    setHighPassUrl(null);
    setHighPassUrlFine(null);
    setHighPassUrlLarge(null);
    setAiSettings(INITIAL_SETTINGS);
  }, []);

  // Adiciona ao histórico
  const addToHistory = (url: string, label: string) => {
    const newState: HistoryState = {
      id: uuidv4(),
      url,
      label,
      timestamp: Date.now(),
      settingsSnapshot: { ...aiSettings }
    };
    const newHistory = [...history.slice(0, currentHistoryIdx + 1), newState];
    setHistory(newHistory);
    setCurrentHistoryIdx(newHistory.length - 1);
  };

  // Restaura um estado do histórico
  const handleRestoreHistory = (idx: number) => {
    const state = history[idx];
    if (!state) return;
    setCurrentHistoryIdx(idx);
    setBaseImageLayer(state.url);
    setAiEnhancedLayer(null); // Reseta preview de IA ao voltar
    setAiSettings(state.settingsSnapshot);
  };

  // Consolida as alterações em uma nova camada (Bake)
  const bakeManualChanges = async () => {
    if (!baseImageLayer) return;
    setIsProcessing(true);

    try {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = baseImageLayer;

      await new Promise((resolve) => {
        img.onload = async () => {
          canvas.width = img.width;
          canvas.height = img.height;
          ctx.filter = getFilterString();
          ctx.drawImage(img, 0, 0);

          if (aiSettings.smartSharpen) {
            ctx.globalCompositeOperation = 'overlay';
            if (aiSettings.isAdvancedSharpen) {
              if (highPassUrlFine) {
                const hp = await loadImage(highPassUrlFine);
                ctx.globalAlpha = aiSettings.highFreqOpacity / 100;
                ctx.drawImage(hp, 0, 0);
              }
              if (highPassUrlLarge) {
                const hp = await loadImage(highPassUrlLarge);
                ctx.globalAlpha = aiSettings.lowFreqOpacity / 100;
                ctx.drawImage(hp, 0, 0);
              }
            } else if (highPassUrl) {
              const hp = await loadImage(highPassUrl);
              ctx.globalAlpha = 1.0;
              ctx.drawImage(hp, 0, 0);
            }
          }
          resolve(null);
        };
      });

      const bakedUrl = canvas.toDataURL('image/png', 1.0);
      setBaseImageLayer(bakedUrl);
      setAiSettings(prev => ({ ...prev, ...INITIAL_SETTINGS, aiIntensity: prev.aiIntensity })); // Reseta sliders manuais
      addToHistory(bakedUrl, "Melhoria Manual");
    } catch (e) {
      console.error("Erro ao consolidar:", e);
    } finally {
      setIsProcessing(false);
    }
  };

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.src = src;
    });
  };

  const generateSingleHighPass = async (imgSrc: string, radius: number): Promise<string> => {
    const img = await loadImage(imgSrc);
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return '';

    canvas.width = img.width;
    canvas.height = img.height;
    ctx.drawImage(img, 0, 0);

    const blurCanvas = document.createElement('canvas');
    blurCanvas.width = canvas.width;
    blurCanvas.height = canvas.height;
    const bCtx = blurCanvas.getContext('2d');
    if (bCtx) {
      bCtx.filter = `blur(${radius}px) grayscale(100%)`;
      bCtx.drawImage(img, 0, 0);
    }

    const originalData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const blurredData = bCtx?.getImageData(0, 0, canvas.width, canvas.height);

    if (blurredData) {
      for (let i = 0; i < originalData.data.length; i += 4) {
        originalData.data[i] = 128 + (originalData.data[i] - blurredData.data[i]);
        originalData.data[i+1] = 128 + (originalData.data[i+1] - blurredData.data[i+1]);
        originalData.data[i+2] = 128 + (originalData.data[i+2] - blurredData.data[i+2]);
      }
      ctx.putImageData(originalData, 0, 0);
    }
    return canvas.toDataURL('image/png');
  };

  const updateHighPassLayers = useCallback(async () => {
    if (!baseImageLayer || !aiSettings.smartSharpen) {
      setHighPassUrl(null);
      setHighPassUrlFine(null);
      setHighPassUrlLarge(null);
      return;
    }

    const source = aiEnhancedLayer || baseImageLayer;

    if (aiSettings.isAdvancedSharpen) {
      const fine = await generateSingleHighPass(source, aiSettings.highFreqRadius);
      const large = await generateSingleHighPass(source, aiSettings.lowFreqRadius);
      setHighPassUrlFine(fine);
      setHighPassUrlLarge(large);
      setHighPassUrl(null);
    } else {
      const standard = await generateSingleHighPass(source, aiSettings.highPassRadius);
      setHighPassUrl(standard);
      setHighPassUrlFine(null);
      setHighPassUrlLarge(null);
    }
  }, [baseImageLayer, aiEnhancedLayer, aiSettings.smartSharpen, aiSettings.isAdvancedSharpen, aiSettings.highPassRadius, aiSettings.highFreqRadius, aiSettings.lowFreqRadius]);

  useEffect(() => {
    updateHighPassLayers();
  }, [updateHighPassLayers]);

  const processWithAI = async (mode: AISettings['mode']) => {
    if (!baseImageLayer) return;
    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = mode === 'enhance' 
        ? `Professional enhancement: realistic sharpness and detail improvement. Maintain 100% fidelity. Intensity: ${aiSettings.aiIntensity}%`
        : `Denoise: clean digital artifacts while keeping edges sharp. Realistic results only. Intensity: ${aiSettings.aiIntensity}%`;

      // Importante: Pegamos a baseImageLayer ATUAL (pode já estar bakery-ada)
      const base64Data = baseImageLayer.split(',')[1];

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType: 'image/png' } },
            { text: prompt }
          ]
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const resultUrl = `data:image/png;base64,${part.inlineData.data}`;
            setAiEnhancedLayer(resultUrl);
            setBaseImageLayer(resultUrl); // Torna a imagem de IA a nova base
            setAiEnhancedLayer(null); // Limpa o "overlay" pois ela já virou a base
            addToHistory(resultUrl, mode === 'enhance' ? "AI Enhanced" : "AI Deep Clean");
            break;
          }
        }
      }
    } catch (error) {
      console.error("Erro AI:", error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!baseImageLayer) return;
    bakeManualChanges().then(() => {
      // Re-busca a imagem após o bake para salvar o estado final absoluto
      const link = document.createElement('a');
      link.download = `miau_lab_final_${Date.now()}.png`;
      link.href = baseImageLayer;
      link.click();
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const gridImg = { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height };
      setImages([gridImg]);
      setBaseImageLayer(url);
      setAiEnhancedLayer(null);
      setHistory([]); // Limpa histórico anterior
      addToHistory(url, "Original");
    };
    img.src = url;
    e.target.value = '';
  };

  const getFilterString = () => {
    const sharpen = aiSettings.sharpness > 0 
      ? `contrast(${100 + aiSettings.sharpness/2}%) brightness(${100 - aiSettings.sharpness/20}%)` 
      : '';
    const blur = aiSettings.noiseReduction > 0 ? `blur(${aiSettings.noiseReduction/20}px)` : '';
    return `brightness(${aiSettings.brightness}%) contrast(${aiSettings.contrast}%) ${sharpen} ${blur}`;
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main relative">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={setAiSettings}
          onAdd={() => (images.length > 0 ? setShowConfirmModal(true) : fileInputRef.current?.click())}
          onProcess={processWithAI}
          onBakeManual={bakeManualChanges}
          onSave={handleDownload}
          isProcessing={isProcessing}
          hasManualChanges={hasManualChanges}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={handleClear} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {baseImageLayer ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden rounded-[2.5rem] group"
                style={{ 
                  width: currentImg.width * zoom,
                  height: currentImg.height * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                {/* Imagem Original de Comparação (Sempre o primeiro estado do histórico) */}
                <img src={history[0]?.url || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" alt="original" />

                <div 
                  className="absolute inset-0 w-full h-full overflow-hidden"
                  style={{ clipPath: isComparing ? `inset(0 0 0 ${compareSplit}%)` : 'none' }}
                >
                  <img src={aiEnhancedLayer || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" style={{ filter: getFilterString() }} alt="enhanced" />

                  {aiSettings.smartSharpen && (
                    <>
                      {!aiSettings.isAdvancedSharpen && highPassUrl && (
                        <img src={highPassUrl} className="absolute inset-0 w-full h-full object-cover" style={{ mixBlendMode: 'overlay' }} alt="hp-std" />
                      )}
                      {aiSettings.isAdvancedSharpen && (
                        <>
                          {highPassUrlFine && (
                            <img src={highPassUrlFine} className="absolute inset-0 w-full h-full object-cover" style={{ mixBlendMode: 'overlay', opacity: aiSettings.highFreqOpacity / 100 }} alt="hp-fine" />
                          )}
                          {highPassUrlLarge && (
                            <img src={highPassUrlLarge} className="absolute inset-0 w-full h-full object-cover" style={{ mixBlendMode: 'overlay', opacity: aiSettings.lowFreqOpacity / 100 }} alt="hp-large" />
                          )}
                        </>
                      )}
                    </>
                  )}
                </div>

                {isComparing && (
                  <>
                    <div className="absolute top-0 bottom-0 w-0.5 bg-theme-accent z-10 shadow-[0_0_15px_rgba(79,70,229,0.8)] pointer-events-none" style={{ left: `${compareSplit}%` }}>
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-theme-accent text-white flex items-center justify-center text-[10px] shadow-2xl"><i className="fas fa-arrows-alt-h"></i></div>
                    </div>
                    <input type="range" min="0" max="100" value={compareSplit} onChange={(e) => setCompareSplit(parseInt(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-20" />
                    <div className="absolute top-6 left-6 px-3 py-1 bg-black/40 backdrop-blur-md rounded-lg text-[8px] font-black uppercase text-white/60 tracking-widest z-30">Original</div>
                    <div className="absolute top-6 right-6 px-3 py-1 bg-theme-accent/80 backdrop-blur-md rounded-lg text-[8px] font-black uppercase text-white tracking-widest z-30">Current Layer</div>
                  </>
                )}

                {isProcessing && (
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-xl flex flex-col items-center justify-center text-white z-50 animate-in fade-in duration-500">
                    <div className="w-16 h-16 border-4 border-theme-accent border-t-transparent rounded-full animate-spin mb-6"></div>
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">Sincronia Neural...</p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Miau AI Lab</p>
            </div>
          )}

          {baseImageLayer && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-32 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <button onClick={() => setIsComparing(!isComparing)} className={`flex items-center gap-2 px-4 py-1.5 rounded-full text-[9px] font-black uppercase transition-all ${isComparing ? 'bg-theme-accent text-white shadow-lg' : 'bg-theme-panel/50 opacity-40 hover:opacity-100'}`}><i className="fas fa-columns"></i><span>{isComparing ? 'Ver Atual' : 'Comparar'}</span></button>
            </div>
          )}
        </div>
      </section>

      {/* SIDEBAR DE HISTÓRICO À DIREITA */}
      <HistorySidebar 
        history={history} 
        currentIndex={currentHistoryIdx} 
        onRestore={handleRestoreHistory} 
        isOpen={isHistoryOpen}
        onToggle={() => setIsHistoryOpen(!isHistoryOpen)}
      />

      {/* BOTÃO FLUTUANTE PARA TOGGLE DO HISTÓRICO */}
      <button 
        onClick={() => setIsHistoryOpen(!isHistoryOpen)}
        className={`absolute top-1/2 -translate-y-1/2 z-50 w-6 h-20 bg-theme-panel border border-theme flex items-center justify-center rounded-l-xl hover:bg-theme-accent transition-all group ${isHistoryOpen ? 'right-64' : 'right-0'}`}
      >
        <i className={`fas ${isHistoryOpen ? 'fa-chevron-right' : 'fa-history'} text-[10px] group-hover:scale-125`}></i>
      </button>

      {showConfirmModal && (
