        <i className={`fas ${isOpen ? 'fa-chevron-right' : 'fa-history'} text-[10px] transition-transform duration-500 ${isOpen ? 'rotate-0' : 'rotate-12 group-hover:rotate-0'} group-hover:scale-125`}></i>
