import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import HistorySidebar from '../components/HistorySidebar';
import Header from '../components/Header';
import { GridImage, AISettings, HistoryState } from '../types';

const INITIAL_SETTINGS: AISettings = {
  mode: 'enhance',
  sharpness: 0,
  noiseReduction: 0,
  brightness: 100,
  contrast: 100,
  aiIntensity: 70,
  edgeSmoothness: 2,
  smartSharpen: false,
  highPassRadius: 1.5,
  isAdvancedSharpen: false,
  highFreqRadius: 1.2,
  highFreqOpacity: 100,
  lowFreqRadius: 8.0,
  lowFreqOpacity: 50
};

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [currentHistoryIdx, setCurrentHistoryIdx] = useState(-1);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [compareSplit, setCompareSplit] = useState(50);
  const [isComparing, setIsComparing] = useState(true);

  const [baseImageLayer, setBaseImageLayer] = useState<string | null>(null);
  const [aiEnhancedLayer, setAiEnhancedLayer] = useState<string | null>(null);

  const [highPassUrl, setHighPassUrl] = useState<string | null>(null);
  const [highPassUrlFine, setHighPassUrlFine] = useState<string | null>(null);
  const [highPassUrlLarge, setHighPassUrlLarge] = useState<string | null>(null);

  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [aiSettings, setAiSettings] = useState<AISettings>(INITIAL_SETTINGS);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentImg = images[0];

  const hasManualChanges = useMemo(() => {
    return aiSettings.sharpness !== 0 || 
           aiSettings.noiseReduction !== 0 || 
           aiSettings.brightness !== 100 || 
           aiSettings.contrast !== 100 || 
           aiSettings.smartSharpen === true;
  }, [aiSettings]);

  const handleClear = useCallback(() => {
    images.forEach(img => URL.revokeObjectURL(img.previewUrl));
    setImages([]);
    setHistory([]);
    setCurrentHistoryIdx(-1);
    setBaseImageLayer(null);
    setAiEnhancedLayer(null);
    setHighPassUrl(null);
    setHighPassUrlFine(null);
    setHighPassUrlLarge(null);
    setAiSettings(INITIAL_SETTINGS);
  }, [images]);

  const addToHistory = (url: string, label: string) => {
    const newState: HistoryState = {
      id: uuidv4(),
      url,
      label,
      timestamp: Date.now(),
      settingsSnapshot: { ...aiSettings }
    };
    const newHistory = [...history.slice(0, currentHistoryIdx + 1), newState];
    setHistory(newHistory);
    setCurrentHistoryIdx(newHistory.length - 1);
  };

  const handleRestoreHistory = (idx: number) => {
    const state = history[idx];
    if (!state) return;
    setCurrentHistoryIdx(idx);
    setBaseImageLayer(state.url);
    setAiEnhancedLayer(null);
    setAiSettings(state.settingsSnapshot);
  };

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error(`Erro ao carregar recurso visual.`));
      img.src = src;
    });
  };

  const bakeManualChanges = async () => {
    if (!baseImageLayer) return;
    setIsProcessing(true);

    try {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const mainImg = await loadImage(baseImageLayer);
      canvas.width = mainImg.width;
      canvas.height = mainImg.height;

      ctx.filter = getFilterString();
      ctx.drawImage(mainImg, 0, 0);
      ctx.filter = 'none';

      if (aiSettings.smartSharpen) {
        ctx.globalCompositeOperation = 'overlay';

        if (aiSettings.isAdvancedSharpen) {
          if (highPassUrlFine) {
            const hpFine = await loadImage(highPassUrlFine);
            ctx.globalAlpha = aiSettings.highFreqOpacity / 100;
            ctx.drawImage(hpFine, 0, 0);
          }
          if (highPassUrlLarge) {
            const hpLarge = await loadImage(highPassUrlLarge);
            ctx.globalAlpha = aiSettings.lowFreqOpacity / 100;
            ctx.drawImage(hpLarge, 0, 0);
          }
        } else if (highPassUrl) {
          const hpStd = await loadImage(highPassUrl);
          ctx.globalAlpha = 1.0;
          ctx.drawImage(hpStd, 0, 0);
        }

        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1.0;
      }

      const bakedUrl = canvas.toDataURL('image/png', 1.0);

      if (baseImageLayer.startsWith('blob:')) URL.revokeObjectURL(baseImageLayer);

      setBaseImageLayer(bakedUrl);
      setAiEnhancedLayer(null);

      setAiSettings(prev => ({ 
        ...prev, 
        sharpness: 0,
        noiseReduction: 0,
        brightness: 100,
        contrast: 100,
        smartSharpen: false 
      }));

      addToHistory(bakedUrl, "Consolidação Manual");
    } catch (e) {
      console.error("Erro no processamento de camadas:", e);
    } finally {
      setIsProcessing(false);
    }
  };

  const generateSingleHighPass = async (imgSrc: string, radius: number): Promise<string> => {
    try {
      const img = await loadImage(imgSrc);
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return '';

      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);

      const blurCanvas = document.createElement('canvas');
      blurCanvas.width = canvas.width;
      blurCanvas.height = canvas.height;
      const bCtx = blurCanvas.getContext('2d');
      if (bCtx) {
        bCtx.filter = `blur(${radius}px) grayscale(100%)`;
        bCtx.drawImage(img, 0, 0);
      }

      const originalData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const blurredData = bCtx?.getImageData(0, 0, canvas.width, canvas.height);

      if (blurredData) {
        for (let i = 0; i < originalData.data.length; i += 4) {
          originalData.data[i] = 128 + (originalData.data[i] - blurredData.data[i]);
          originalData.data[i+1] = 128 + (originalData.data[i+1] - blurredData.data[i+1]);
          originalData.data[i+2] = 128 + (originalData.data[i+2] - blurredData.data[i+2]);
        }
        ctx.putImageData(originalData, 0, 0);
      }
      return canvas.toDataURL('image/png');
    } catch (e) {
      return '';
    }
  };

  const updateHighPassLayers = useCallback(async () => {
    if (!baseImageLayer || !aiSettings.smartSharpen) {
      setHighPassUrl(null);
      setHighPassUrlFine(null);
      setHighPassUrlLarge(null);
      return;
    }

    const source = aiEnhancedLayer || baseImageLayer;

    if (aiSettings.isAdvancedSharpen) {
      const [fine, large] = await Promise.all([
        generateSingleHighPass(source, aiSettings.highFreqRadius),
        generateSingleHighPass(source, aiSettings.lowFreqRadius)
      ]);
      setHighPassUrlFine(fine);
      setHighPassUrlLarge(large);
      setHighPassUrl(null);
    } else {
      const standard = await generateSingleHighPass(source, aiSettings.highPassRadius);
      setHighPassUrl(standard);
      setHighPassUrlFine(null);
      setHighPassUrlLarge(null);
    }
  }, [baseImageLayer, aiEnhancedLayer, aiSettings.smartSharpen, aiSettings.isAdvancedSharpen, aiSettings.highPassRadius, aiSettings.highFreqRadius, aiSettings.lowFreqRadius]);

  useEffect(() => {
    const timer = setTimeout(() => {
      updateHighPassLayers();
    }, 150);
    return () => clearTimeout(timer);
  }, [updateHighPassLayers]);

  const processWithAI = async (mode: AISettings['mode']) => {
    if (!baseImageLayer) return;
    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = mode === 'enhance' 
        ? `Enhance details and sharpness. Realistic results only. Keep colors natural.`
        : `Remove digital noise and artifacts. Clean the image but preserve textures.`;

      const base64Data = baseImageLayer.split(',')[1];

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType: 'image/png' } },
            { text: prompt }
          ]
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const resultUrl = `data:image/png;base64,${part.inlineData.data}`;
            setBaseImageLayer(resultUrl);
            setAiEnhancedLayer(null);
            addToHistory(resultUrl, mode === 'enhance' ? "AI High Detail" : "AI Clean Mask");
            break;
          }
        }
      }
    } catch (error) {
      console.error("AI Error:", error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!baseImageLayer) return;
    bakeManualChanges().then(() => {
      const finalName = aiSettings.exportFilename?.trim() 
        ? `${aiSettings.exportFilename.trim()}.png`
        : `miau_lab_export_${Date.now()}.png`;

      const link = document.createElement('a');
      link.download = finalName;
      link.href = baseImageLayer;
      link.click();
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const gridImg = { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height };
      setImages([gridImg]);
      setBaseImageLayer(url);
      setAiEnhancedLayer(null);
      setHistory([]);
      addToHistory(url, "Imagem Original");
    };
    img.src = url;
    e.target.value = '';
  };

  const getFilterString = () => {
    const sharpenVal = aiSettings.sharpness;
    const sharpen = sharpenVal > 0 
      ? `contrast(${100 + sharpenVal/2.5}%) brightness(${100 - sharpenVal/25}%) saturate(${100 + sharpenVal/10}%)` 
      : '';
    const blur = aiSettings.noiseReduction > 0 ? `blur(${aiSettings.noiseReduction/30}px)` : '';
    return `brightness(${aiSettings.brightness}%) contrast(${aiSettings.contrast}%) ${sharpen} ${blur}`;
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main relative">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={setAiSettings}
          onAdd={() => (images.length > 0 ? setShowConfirmModal(true) : fileInputRef.current?.click())}
          onProcess={processWithAI}
          onBakeManual={bakeManualChanges}
          onSave={handleDownload}
          isProcessing={isProcessing}
          hasManualChanges={hasManualChanges}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={handleClear} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {baseImageLayer ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden rounded-[2.5rem] group"
                style={{ 
                  width: currentImg.width * zoom,
                  height: currentImg.height * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <img src={history[0]?.url || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" alt="original" />

                <div 
                  className="absolute inset-0 w-full h-full overflow-hidden"
                  style={{ clipPath: isComparing ? `inset(0 0 0 ${compareSplit}%)` : 'none' }}
                >
                  <img src={aiEnhancedLayer || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" style={{ filter: getFilterString() }} alt="enhanced" />

                  {aiSettings.smartSharpen && (
                    <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ mixBlendMode: 'overlay' }}>
                      {!aiSettings.isAdvancedSharpen && highPassUrl && (
                        <img src={highPassUrl} className="absolute inset-0 w-full h-full object-cover" alt="hp-std" />
                      )}
                      {aiSettings.isAdvancedSharpen && (
                        <>
                          {highPassUrlFine && (
                            <img src={highPassUrlFine} className="absolute inset-0 w-full h-full object-cover" style={{ opacity: aiSettings.highFreqOpacity / 100 }} alt="hp-fine" />
                          )}
                          {highPassUrlLarge && (
                            <img src={highPassUrlLarge} className="absolute inset-0 w-full h-full object-cover" style={{ opacity: aiSettings.lowFreqOpacity / 100 }} alt="hp-large" />
                          )}
                        </>
                      )}
                    </div>
                  )}
                </div>

                {isComparing && (
                  <>
                    <div className="absolute top-0 bottom-0 w-0.5 bg-theme-accent z-10 shadow-[0_0_20px_rgba(79,70,229,1)] pointer-events-none" style={{ left: `${compareSplit}%` }}>
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-theme-accent text-white flex items-center justify-center text-[10px] shadow-2xl border border-white/20"><i className="fas fa-arrows-alt-h"></i></div>
                    </div>
                    <input type="range" min="0" max="100" value={compareSplit} onChange={(e) => setCompareSplit(parseInt(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-20" />
                  </>
                )}

                {isProcessing && (
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-xl flex flex-col items-center justify-center text-white z-50 animate-in fade-in duration-300">
                    <div className="w-12 h-12 border-4 border-theme-accent border-t-transparent rounded-full animate-spin mb-4"></div>
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">Sincronia Visual...</p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Miau AI Lab</p>
            </div>
          )}

          {baseImageLayer && (
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-32 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[10px] font-mono opacity-40 w-10">{Math.round(zoom * 100)}%</span>
              </div>
              <button onClick={() => setIsComparing(!isComparing)} className={`flex items-center gap-2 px-4 py-1.5 rounded-full text-[9px] font-black uppercase transition-all ${isComparing ? 'bg-theme-accent text-white shadow-lg' : 'bg-theme-panel/50 opacity-40 hover:opacity-100'}`}><i className="fas fa-columns"></i><span>{isComparing ? 'Ver Atual' : 'Comparar'}</span></button>
            </div>
          )}
        </div>
      </section>

      <HistorySidebar 
        history={history} 
        currentIndex={currentHistoryIdx} 
        onRestore={handleRestoreHistory} 
        isOpen={isHistoryOpen}
        onToggle={() => setIsHistoryOpen(!isHistoryOpen)}
      />

      <input type="file" accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

