        {!settings.frameImageUrl ? (
          <div className="space-y-4">
            <MiauSlider label="Espessura Borda" min={0} max={200} value={settings.borderWidth} onChange={(v) => handleChange('borderWidth', v)} icon="fa-border-style" />
