          <div className="p-3 bg-theme-accent/5 rounded-lg border border-theme-accent/20 flex gap-3 items-center"><i className="fas fa-check-circle text-theme-accent text-xs"></i><div className="flex-1 min-w-0"><p className="text-[9px] font-black uppercase text-theme-accent">Moldura Ativa</p></div><button onClick={() => handleChange('frameImageUrl', undefined)} className="text-red-500 p-1"><i className="fas fa-trash-alt text-[10px]"></i></button></div>
        )}
