      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-1 text-theme-accent">Nomenclatura do Lote</h3>
        <div className="space-y-3">
          <div className="space-y-1">
            <label className="text-[8px] font-black uppercase opacity-40 ml-1">Prefixo Global</label>
            <div className="flex gap-2">
              <input 
                type="text" 
                placeholder="Ex: final_"
                value={settings.exportPrefix || ''}
                onChange={(e) => handleChange('exportPrefix', e.target.value)}
                className="flex-1 bg-theme-panel border border-theme rounded-xl p-2.5 text-[10px] outline-none font-bold focus:border-theme-accent transition-colors"
              />
              <button 
                onClick={onApplyPrefixToAll}
                className="px-3 rounded-xl bg-theme-accent/10 border border-theme-accent/20 text-theme-accent hover:bg-theme-accent hover:text-white transition-all text-[10px]"
                title="Aplicar prefixo a todos"
              >
                <i className="fas fa-clone"></i>
              </button>
            </div>
          </div>
          <div className="space-y-1">
            <label className="text-[8px] font-black uppercase opacity-40 ml-1">Renomear Selecionado</label>
            <input 
              type="text" 
              placeholder="Vazio p/ manter original"
              value={settings.exportFilename || ''}
              onChange={(e) => handleChange('exportFilename', e.target.value)}
              className="w-full bg-theme-panel border border-theme rounded-xl p-2.5 text-[10px] outline-none font-bold focus:border-theme-accent transition-colors"
