interface AlphaEdgeToolProps {
  globalPreviewQuality?: PreviewQuality;
}

const DEFAULT_SETTINGS: AlphaEdgeSettings = {
  thickness: 20,
  softness: 5,
  borderScale: 100,
  opacity: 100,
  color: '#ffffff',
  boundaryMode: 'silhouette',
  geometricShape: 'circle',
  shapeOffsetX: 0,
  shapeOffsetY: 0,
  advanced: {
