import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GridImage, FrameSettings } from '../types';

interface InteractiveEditorProps {
  mainImage: (GridImage & { x: number, y: number, scale: number, rotation: number }) | null;
  loteImages: GridImage[];
  frameSettings: FrameSettings;
  onUpdateImage: (id: string, updates: Partial<GridImage>) => void;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  zoom?: number;
}

const InteractiveEditor: React.FC<InteractiveEditorProps> = ({ 
  mainImage,
  loteImages, 
  frameSettings, 
  onUpdateImage,
  selectedId,
  onSelect,
  zoom = 0.4
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragInfo = useRef({
    startX: 0,
    startY: 0,
    initialPosX: 0,
    initialPosY: 0,
    id: '',
    animationFrameId: 0
  });

  const handleMouseDown = (e: React.MouseEvent, id: string, x: number, y: number) => {
    e.stopPropagation();
    onSelect(id);
    setIsDragging(true);

    dragInfo.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialPosX: x,
      initialPosY: y,
      id: id,
      animationFrameId: 0
    };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging || !selectedId) return;

    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }

    dragInfo.current.animationFrameId = requestAnimationFrame(() => {
      const dx = e.clientX - dragInfo.current.startX;
      const dy = e.clientY - dragInfo.current.startY;

      onUpdateImage(dragInfo.current.id, {
        x: dragInfo.current.initialPosX + (dx / zoom),
        y: dragInfo.current.initialPosY + (dy / zoom)
      });
    });
  }, [isDragging, selectedId, zoom, onUpdateImage]);

  const handleMouseUp = useCallback(() => {
    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }
    setIsDragging(false);
  }, []);

  const handleWheel = useCallback((e: WheelEvent) => {
    if (!selectedId) return;
    e.preventDefault();

    const element = selectedId === 'main' 
      ? mainImage 
      : loteImages.find(img => img.id === selectedId);

    if (element) {
      const delta = e.deltaY > 0 ? -0.02 : 0.02;
      const currentScale = (element as any).scale || 1;
      const newScale = Math.max(0.01, Math.min(10, currentScale + delta));
      onUpdateImage(selectedId, { scale: newScale });
    }
  }, [selectedId, mainImage, loteImages, onUpdateImage]);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove, { passive: true });
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  useEffect(() => {
    const container = containerRef.current;
    if (container) {
      container.addEventListener('wheel', handleWheel, { passive: false });
    }
    return () => {
      if (container) container.removeEventListener('wheel', handleWheel);
    };
  }, [handleWheel]);

  const SelectionOverlay = ({ isActive }: { isActive: boolean }) => (
    isActive ? (
      <div className="absolute inset-[-2px] border-2 border-dashed border-theme-accent rounded-none shadow-[0_0_15px_rgba(79,70,229,0.3)] z-50 pointer-events-none">
      </div>
    ) : null
  );

  return (
    <div 
      ref={containerRef}
      className="relative shadow-2xl border border-white/10 bg-theme-panel transition-[width,height] duration-300 ease-out"
      style={{ 
        width: frameSettings.canvasWidth * zoom, 
        height: frameSettings.canvasHeight * zoom,
        minWidth: frameSettings.canvasWidth * zoom,
        minHeight: frameSettings.canvasHeight * zoom,
        backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)',
        backgroundSize: '20px 20px',
      }}
      onMouseDown={() => onSelect(null)}
    >
      {/* CAMADA DE LIMBO: Escurece tudo o que vaza para fora do canvas principal */}
      <div className="absolute inset-[-5000px] pointer-events-none z-[55] bg-black/40" style={{ clipPath: 'polygon(0% 0%, 0% 100%, 100% 100%, 100% 0%, 0% 0%, 5000px 5000px, calc(100% - 5000px) 5000px, calc(100% - 5000px) calc(100% - 5000px), 5000px calc(100% - 5000px), 5000px 5000px)' }}></div>

      {/* Guia Visual do Perímetro Exato */}
      <div className="absolute inset-0 border border-theme-accent/40 border-dashed pointer-events-none z-[60]"></div>

      {mainImage && mainImage.visible !== false && (
        <div
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === 'main' ? 'z-30 opacity-100' : 'z-10 opacity-70'}`}
          style={{
            left: mainImage.x * zoom,
            top: mainImage.y * zoom,
            width: (mainImage.width * mainImage.scale) * zoom,
            transform: `rotate(${mainImage.rotation}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, 'main', mainImage.x, mainImage.y)}
        >
          <img src={mainImage.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === 'main'} />
        </div>
      )}

      {loteImages.map((img) => img.visible !== false && (
        <div
          key={img.id}
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === img.id ? 'z-40 opacity-100' : 'z-20 opacity-70'}`}
          style={{
            left: (img.x || 0) * zoom,
            top: (img.y || 0) * zoom,
            width: (img.width * (img.scale || 1)) * zoom,
            transform: `rotate(${img.rotation || 0}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, img.id, img.x || 0, img.y || 0)}
        >
          <img src={img.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === img.id} />
        </div>
      ))}

      <div 
        className="absolute inset-0 pointer-events-none z-[100] transition-all duration-300"
        style={{
          border: frameSettings.frameImageUrl ? 'none' : `${frameSettings.borderWidth * zoom}px solid ${frameSettings.borderColor}`,
          borderRadius: `${frameSettings.borderRadius * zoom}px`,
          boxShadow: `inset 0 0 ${frameSettings.shadow * zoom}px rgba(0,0,0,0.2)`
        }}
      >
        {frameSettings.frameImageUrl && (
          <img src={frameSettings.frameImageUrl} className="w-full h-full object-fill" />
        )}
      </div>
    </div>
  );
};

export default InteractiveEditor;

class MiauAudioEngine {
  private ctx: AudioContext | null = null;
  private sliderOscillator: OscillatorNode | null = null;
  private sliderGain: GainNode | null = null;
  private lowPassFilter: BiquadFilterNode | null = null;

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  // Som de clique "Plulli"
  public playPlop() {
    this.init();
    if (!this.ctx) return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    // Sweep de frequência: começa em 600 e cai para 100 rápido
    osc.frequency.setValueAtTime(600, this.ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(100, this.ctx.currentTime + 0.1);

    gain.gain.setValueAtTime(0.3, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.15);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start();
    osc.stop(this.ctx.currentTime + 0.15);
  }

  // Inicia o som do slider
  public startSliderHum() {
    this.init();
    if (!this.ctx || this.sliderOscillator) return;

    this.sliderOscillator = this.ctx.createOscillator();
    this.sliderGain = this.ctx.createGain();
    this.lowPassFilter = this.ctx.createBiquadFilter();

    this.sliderOscillator.type = 'sine';
    this.lowPassFilter.type = 'lowpass';
    this.lowPassFilter.frequency.value = 1200; // Corta agudos chatos

    this.sliderGain.gain.setValueAtTime(0, this.ctx.currentTime);
    this.sliderGain.gain.linearRampToValueAtTime(0.15, this.ctx.currentTime + 0.05);

    this.sliderOscillator.connect(this.lowPassFilter);
    this.lowPassFilter.connect(this.sliderGain);
    this.sliderGain.connect(this.ctx.destination);

    this.sliderOscillator.start();
  }

  // Atualiza a frequência baseada no valor do slider
  public updateSliderFreq(value: number, min: number, max: number) {
    if (!this.ctx || !this.sliderOscillator) return;

    // Mapeia o valor do slider (min-max) para uma frequência fofinha (200Hz - 600Hz)
    const percent = (value - min) / (max - min);
    const freq = 220 + (percent * 380);

    this.sliderOscillator.frequency.setTargetAtTime(freq, this.ctx.currentTime, 0.03);
  }

  // Para o som do slider com um fade-out suave
  public stopSliderHum() {
    if (!this.ctx || !this.sliderGain || !this.sliderOscillator) return;

    const currentGain = this.sliderGain;
    const currentOsc = this.sliderOscillator;

    currentGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.05);

    setTimeout(() => {
      currentOsc.stop();
      currentOsc.disconnect();
      currentGain.disconnect();
    }, 100);

    this.sliderOscillator = null;
    this.sliderGain = null;
  }
}

export const miauAudio = new MiauAudioEngine();

