import React, { useRef, useState, useEffect } from 'react';
import { miauAudio } from '../utils/audio';

interface MiauSliderProps {
  label: string;
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  unit?: string;
  step?: number;
  icon?: string;
}

const MiauSlider: React.FC<MiauSliderProps> = ({ label, value, min, max, onChange, unit = '', step = 1, icon }) => {
  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef({ lastX: 0, startValue: 0, accumulatedDelta: 0 });

  const handlePointerDown = (e: React.PointerEvent) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    setIsDragging(true);

    // Inicia o som do slider
    miauAudio.startSliderHum();
    miauAudio.updateSliderFreq(value, min, max);

    dragRef.current = { 
      lastX: e.clientX, 
      startValue: value,
      accumulatedDelta: 0
    };

    const style = document.createElement('style');
    style.id = 'miau-dragging-cursor';
    style.innerHTML = '*{ cursor: none !important; user-select: none !important; }';
    document.head.appendChild(style);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDragging) return;

    const deltaX = e.movementX;
    const range = max - min;
    const sensitivity = range > 100 ? 0.4 : 0.05;

    dragRef.current.accumulatedDelta += deltaX * sensitivity;

    const change = Math.trunc(dragRef.current.accumulatedDelta);
    if (change !== 0) {
      let newValue = value + change;
      newValue = Math.round(newValue / step) * step;
      newValue = Math.max(min, Math.min(max, newValue));

      if (newValue !== value) {
        onChange(newValue);
        // Atualiza a frequência sonora dinamicamente
        miauAudio.updateSliderFreq(newValue, min, max);
        dragRef.current.accumulatedDelta -= change;
      }
    }
  };

  const handlePointerUp = () => {
    setIsDragging(false);
    // Para o som do slider
    miauAudio.stopSliderHum();
    document.getElementById('miau-dragging-cursor')?.remove();
  };

  const percentage = ((value - min) / (max - min)) * 100;

  // Formatação para evitar o bug de decimais infinitos (Ex: 4.000000001)
