class MiauAudioEngine {
  private sounds: Record<string, HTMLAudioElement> = {};
  private audioPath = 'audio/'; // Caminho padrão para seus arquivos

  constructor() {
    // Pré-carregamento básico (opcional, ajuda na latência)
    if (typeof window !== 'undefined') {
      this.loadSound('btClick', ['Btclick.wav', 'Btclick.mp3']);
      this.loadSound('mouseClick', ['Click.wav', 'Click.mp3']);
    }
  }

  private async loadSound(key: string, filenames: string[]) {
    for (const filename of filenames) {
      const audio = new Audio(`${this.audioPath}${filename}`);
      audio.preload = 'auto';

      // Tenta carregar o arquivo
      try {
        await new Promise((resolve, reject) => {
          audio.oncanplaythrough = resolve;
          audio.onerror = reject;
          // Timeout de segurança para não travar
          setTimeout(reject, 2000);
        });
        this.sounds[key] = audio;
        break; // Carregou com sucesso, pula o próximo formato
      } catch (e) {
        continue; // Tenta o próximo formato (ex: se .wav falhou, tenta .mp3)
      }
    }
  }

  private play(key: string) {
    const audio = this.sounds[key];
    if (audio) {
      // Reinicia o áudio caso já esteja tocando (permite cliques rápidos)
      audio.currentTime = 0;
      audio.play().catch(() => {
        // Silencioso se o browser bloquear (precisa de interação inicial)
      });
    } else {
      // Fallback: Se o arquivo sumiu, a gente faz um bip fofinho por segurança
      this.playFallbackBeep(key === 'btClick' ? 600 : 400);
    }
  }

  // Toca o som de botão (Btclick.wav)
  public playBtClick() {
    this.play('btClick');
  }

  // Toca o som de clique genérico (Click.wav)
  public playMouseClick() {
    this.play('mouseClick');
  }

  // Fallback sintético caso os arquivos não existam no servidor
  private playFallbackBeep(freq: number) {
    try {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.1);
    } catch (e) { /* AudioContext fails before interaction */ }
  }
}

