            {!isKeyActive && <div className="absolute top-1 right-1 w-2 h-2 bg-amber-500 rounded-full animate-pulse border-2 border-theme-side"></div>}
            {isKeyActive && <div className="absolute top-1 right-1 w-2 h-2 bg-green-500 rounded-full border-2 border-theme-side"></div>}
