              {/* SEÇÃO DE ACESSO IA (ESTILIZADA) */}
              <div className="px-5 py-5 mb-2 border-b bg-black/10 rounded-t-[1.8rem]" style={{ borderColor: 'var(--border)' }}>
                <div className="flex justify-between items-center mb-4">
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black uppercase tracking-widest opacity-40" style={{ color: 'var(--text-main)' }}>Sistema de Acesso</span>
                    <span className="text-[11px] font-black tracking-tighter text-theme-main">{miauID || 'Sessão Offline'}</span>
                  </div>
                  {isKeyActive ? (
                    <div className="flex items-center gap-2 bg-green-500 text-white px-3 py-1 rounded-full shadow-[0_0_15px_rgba(34,197,94,0.4)] animate-pulse">
                      <i className="fas fa-check-circle text-[10px]"></i>
                      <span className="text-[8px] font-black uppercase">Validado</span>
                    </div>
