                <button 
                  onClick={handleOpenKeySelector}
                  className={`w-full py-4 rounded-2xl flex items-center justify-center gap-3 border transition-all active:scale-95 group relative overflow-hidden ${isKeyActive ? 'bg-theme-panel border-theme text-theme-main' : 'bg-theme-accent text-white border-theme-accent shadow-xl'}`}
                >
                  <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                  <i className={`fas ${isKeyActive ? 'fa-sync-alt' : 'fa-key'} text-[12px] transition-transform group-hover:rotate-12`}></i>
                  <span className="text-[10px] font-black uppercase tracking-[0.2em]">
                    {isKeyActive ? 'Trocar Chave Miau' : 'Vincular Chave Miau'}
                  </span>
                </button>

                <p className="mt-3 text-[7px] text-center opacity-30 leading-relaxed uppercase tracking-widest font-bold">
                  Sua chave é salva localmente e<br/>usada apenas para conectar ao Gemini.
                </p>
              </div>

              <div className="p-3 space-y-4">
                <div className="space-y-2">
                  <span className="text-[9px] font-black uppercase tracking-widest block opacity-40 px-2" style={{ color: 'var(--text-main)' }}>Visual do Studio</span>
                  <div className="grid grid-cols-2 gap-1.5">
                    {themes.map((t) => (
                      <button key={t.id} onClick={() => onThemeChange(t.id as ThemeType)} className={`flex items-center gap-2 px-3 py-2.5 rounded-xl text-[9px] font-bold transition-all border ${currentTheme === t.id ? 'bg-theme-accent/20 border-theme-accent text-theme-accent' : 'bg-theme-panel/50 border-transparent hover:border-theme text-theme-main opacity-60'}`}>
                        <div className="w-2.5 h-2.5 rounded-full border border-black/10" style={{ backgroundColor: t.color }}></div>
                        <span className="truncate">{t.label.split(' ')[0]}</span>
                      </button>
                    ))}
