                </div>

                <div className="space-y-2">
                  <span className="text-[9px] font-black uppercase tracking-widest block opacity-40 px-2" style={{ color: 'var(--text-main)' }}>Motor de Preview</span>
                  <div className="flex flex-wrap gap-1.5">
                    {qualities.map((q) => (
                      <button 
                        key={q.id} 
                        onClick={() => onQualityChange(q.id)} 
                        className={`flex-1 min-w-[30%] py-2 rounded-xl text-[8px] font-black uppercase transition-all border ${previewQuality === q.id ? 'bg-theme-accent border-theme-accent text-white shadow-md' : 'bg-theme-panel/50 border-theme opacity-40 hover:opacity-100 text-theme-main'}`}
                      >
                        {q.label}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="pt-2 border-t" style={{ borderColor: 'var(--border)' }}>
                  <button onClick={() => { onShowAbout(); setShowSettings(false); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest text-theme-muted hover:text-theme-accent hover:bg-theme-accent/5 transition-all">
                    <i className="fas fa-paw text-[11px]"></i>
                    <span>Sobre o Projeto</span>
                  </button>
                </div>
              </div>
