import React, { useState, useRef, useEffect } from 'react';
import { ToolType, ThemeType, PreviewQuality } from '../types';

interface TopNavProps {
  activeTool: ToolType;
  onToolChange: (tool: ToolType) => void;
  currentTheme: ThemeType;
  onThemeChange: (theme: ThemeType) => void;
  previewQuality: PreviewQuality;
  onQualityChange: (q: PreviewQuality) => void;
  onShowAbout: () => void;
}

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    aistudio?: AIStudio;
  }
}

const TopNav: React.FC<TopNavProps> = ({ activeTool, onToolChange, currentTheme, onThemeChange, previewQuality, onQualityChange, onShowAbout }) => {
  const [showSettings, setShowSettings] = useState(false);
  const [isKeyActive, setIsKeyActive] = useState(false);
  const [miauID, setMiauID] = useState<string | null>(null);
  const [manualKey, setManualKey] = useState(localStorage.getItem('miau_manual_key') || '');
  const settingsRef = useRef<HTMLDivElement>(null);

  const tools = [
    { id: 'grid', label: 'Grid Maker', icon: 'fa-th-large' },
    { id: 'framing', label: 'Bulk Framing', icon: 'fa-crop-alt' },
    { id: 'alpha-edge', label: 'Borde Maker', icon: 'fa-wand-magic-sparkles' },
    { id: 'ai-lab', label: 'AI Lab', icon: 'fa-brain' },
  ];

  const themes = [
    { id: 'dark', label: 'Dark Edition', color: '#020617', icon: 'fa-moon' },
    { id: 'light', label: 'Clean Light', color: '#f8fafc', icon: 'fa-sun' },
    { id: 'pastel', label: 'Sweet Pastel', color: '#fff1f2', icon: 'fa-heart' },
    { id: 'midnight', label: 'Midnight Purple', color: '#0c0a09', icon: 'fa-vial' },
  ];

  const qualities: { id: PreviewQuality, label: string }[] = [
    { id: 'fast', label: 'Turbo' },
    { id: 'moderate', label: 'Leve' },
    { id: 'medium', label: 'Médio' },
    { id: 'high', label: 'Alto' },
    { id: 'ultra', label: 'Ultra' }
  ];

  const checkApiKey = async () => {
    try {
      if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setIsKeyActive(hasKey || manualKey.length > 10);

        if (hasKey && process.env.API_KEY) {
          const key = process.env.API_KEY;
          setMiauID(`MIAU-${key.substring(0, 4)}...${key.substring(key.length - 4)}`);
        } else if (manualKey.length > 10) {
          setMiauID(`MANUAL-${manualKey.substring(0, 4)}...${manualKey.substring(manualKey.length - 4)}`);
        } else {
          setMiauID(null);
        }
      } else {
        // Fallback para localhost/offline
        setIsKeyActive(manualKey.length > 10);
        if (manualKey.length > 10) {
          setMiauID(`LOCAL-${manualKey.substring(0, 4)}...${manualKey.substring(manualKey.length - 4)}`);
        }
      }
    } catch (e) {
      setIsKeyActive(manualKey.length > 10);
    }
  };

  useEffect(() => {
    checkApiKey();
  }, [manualKey]);

  useEffect(() => {
    if (showSettings) checkApiKey();
  }, [showSettings]);

  const handleOpenKeySelector = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setIsKeyActive(true);
      checkApiKey();
    }
  };

  const handlePasteKey = async () => {
    try {
      const text = await navigator.clipboard.readText();
      if (text && text.trim().length > 10) {
        setManualKey(text.trim());
        localStorage.setItem('miau_manual_key', text.trim());
        // Se estiver no localhost, a gente tenta injetar no env simulado
        if (!process.env.API_KEY) {
           (process.env as any).API_KEY = text.trim();
        }
        setIsKeyActive(true);
      }
    } catch (err) {
      alert("Não consegui acessar sua área de transferência. Tente colar com Ctrl+V!");
    }
  };

  const handleManualKeyChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value.trim();
    setManualKey(val);
    localStorage.setItem('miau_manual_key', val);
    if (!process.env.API_KEY) {
      (process.env as any).API_KEY = val;
    }
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (settingsRef.current && !settingsRef.current.contains(event.target as Node)) {
        setShowSettings(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <nav className="h-12 border-b flex items-center justify-between px-6 z-50 shadow-sm relative backdrop-blur-md" 
         style={{ backgroundColor: 'var(--bg-side)', borderColor: 'var(--border)' }}>

      <div className="flex-1 flex items-center gap-3">
        <div className="logo-support h-8">
           <div className="flex items-center gap-2">
             <i className="fas fa-paw text-[10px] text-white/90"></i>
             <span className="miau-text text-xl tracking-tighter select-none leading-none pt-0.5">Miau</span>
           </div>
        </div>
        <span className="font-black text-[10px] tracking-[0.3em] uppercase opacity-40 pt-1" style={{ color: 'var(--text-main)' }}>Tools</span>
      </div>

      <div className="flex-none">
        <div className="flex items-center gap-1 p-1 rounded-full border shadow-inner backdrop-blur-2xl bg-black/10 transition-all duration-500"
             style={{ borderColor: 'var(--border)' }}>
          {tools.map((tool) => (
            <button
              key={tool.id}
              onClick={() => onToolChange(tool.id as ToolType)}
              className={`flex items-center gap-2.5 px-4 py-1.5 rounded-full text-[10px] font-black transition-all duration-300 whitespace-nowrap uppercase tracking-wider relative group overflow-hidden`}
              style={{
                backgroundColor: activeTool === tool.id ? 'var(--accent)' : 'transparent',
                color: activeTool === tool.id ? 'var(--text-inv)' : 'var(--text-muted)',
                boxShadow: activeTool === tool.id ? '0 4px 12px rgba(79, 70, 229, 0.3)' : 'none'
              }}
            >
              {activeTool !== tool.id && (
                <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
              )}
              <i className={`fas ${tool.icon} text-[9px] z-10 transition-transform duration-300 ${activeTool === tool.id ? 'scale-110' : 'opacity-40 group-hover:opacity-100'}`}></i>
              <span className="z-10">{tool.label}</span>
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 flex justify-end">
        <div className="relative" ref={settingsRef}>
          <button onClick={() => setShowSettings(!showSettings)} className="w-9 h-9 flex items-center justify-center transition-all hover:bg-black/10 rounded-full border border-transparent hover:border-theme active:scale-90 relative" style={{ color: showSettings ? 'var(--accent)' : 'var(--text-muted)' }}>
            <i className={`fas ${showSettings ? 'fa-times' : 'fa-cog'} text-sm`}></i>
            {!isKeyActive && <div className="absolute top-1 right-1 w-2.5 h-2.5 bg-amber-500 rounded-full animate-pulse border-2 border-theme-side shadow-[0_0_8px_rgba(245,158,11,0.6)]"></div>}
            {isKeyActive && <div className="absolute top-1 right-1 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-theme-side"></div>}
          </button>
          {showSettings && (
            <div className="absolute right-0 mt-3 w-80 rounded-[2.5rem] border shadow-2xl p-2 z-[100] animate-in fade-in zoom-in slide-in-from-top-2 duration-200 overflow-hidden backdrop-blur-2xl" style={{ backgroundColor: 'var(--bg-side)', borderColor: 'var(--border)' }}>

              <div className="px-5 py-6 mb-2 border-b bg-black/10 rounded-t-[2.3rem]" style={{ borderColor: 'var(--border)' }}>
                <div className="flex justify-between items-center mb-5">
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black uppercase tracking-widest opacity-40" style={{ color: 'var(--text-main)' }}>Chave de Acesso</span>
                    <span className="text-[11px] font-black tracking-tighter text-theme-main">{miauID || 'Aguardando Vínculo...'}</span>
                  </div>
                  {isKeyActive ? (
                    <div className="flex items-center gap-2 bg-green-500 text-white px-3 py-1 rounded-full shadow-[0_0_15px_rgba(34,197,94,0.4)]">
                      <i className="fas fa-paw text-[9px]"></i>
                      <span className="text-[8px] font-black uppercase tracking-wider">Ativa</span>
                    </div>
                  ) : (
                    <div className="flex items-center gap-2 bg-amber-500/10 text-amber-500 px-3 py-1 rounded-full border border-amber-500/20">
                      <i className="fas fa-key text-[9px] animate-bounce"></i>
                      <span className="text-[8px] font-black uppercase tracking-wider">Configurar</span>
                    </div>
                  )}
                </div>

                {/* INTERFACE DE ENTRADA MANUAL E COLAR */}
                <div className="space-y-3">
                  <div className="relative group">
                    <input 
                      type="password"
                      placeholder="Cole sua chave aqui..."
                      value={manualKey}
                      onChange={handleManualKeyChange}
                      className="w-full bg-black/20 border border-theme rounded-xl py-3 pl-4 pr-12 text-[10px] font-mono outline-none focus:border-theme-accent focus:ring-1 focus:ring-theme-accent/30 transition-all"
                    />
                    <button 
                      onClick={handlePasteKey}
                      title="Colar da Área de Transferência"
                      className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center rounded-lg bg-theme-accent/10 hover:bg-theme-accent text-theme-accent hover:text-white transition-all active:scale-90"
                    >
                      <i className="fas fa-paste text-[10px]"></i>
                    </button>
                  </div>

                  {window.aistudio && (
                    <button 
                      onClick={handleOpenKeySelector}
                      className="w-full py-2.5 rounded-xl flex items-center justify-center gap-2 border border-theme-accent/20 bg-theme-accent/5 text-theme-accent text-[9px] font-black uppercase tracking-widest hover:bg-theme-accent/10 transition-all"
                    >
                      <i className="fas fa-external-link-alt"></i>
                      Usar Painel do Google
                    </button>
                  )}
                </div>

                <div className="mt-4 p-4 bg-theme-accent/5 rounded-2xl border border-theme-accent/10 space-y-2">
                  <p className="text-[8px] opacity-70 leading-relaxed font-bold uppercase tracking-wider">
                    <i className="fas fa-magic text-theme-accent mr-1"></i> 
                    Se não conseguir digitar, clique no botão <span className="text-theme-accent">Prancheta</span> acima para colar o que você copiou!
                  </p>
                </div>
              </div>

              <div className="p-4 space-y-5">
                <div className="space-y-3">
                  <span className="text-[9px] font-black uppercase tracking-widest block opacity-40 px-2" style={{ color: 'var(--text-main)' }}>Ambiente Visual</span>
                  <div className="grid grid-cols-2 gap-2">
                    {themes.map((t) => (
                      <button key={t.id} onClick={() => onThemeChange(t.id as ThemeType)} className={`flex items-center gap-3 px-3 py-3 rounded-2xl text-[9px] font-black transition-all border ${currentTheme === t.id ? 'bg-theme-accent/20 border-theme-accent text-theme-accent' : 'bg-theme-panel/50 border-transparent hover:border-theme text-theme-main opacity-50'}`}>
                        <div className="w-2.5 h-2.5 rounded-full border border-black/10 shadow-sm" style={{ backgroundColor: t.color }}></div>
                        <span className="truncate uppercase tracking-tighter">{t.label.split(' ')[0]}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-3">
                  <span className="text-[9px] font-black uppercase tracking-widest block opacity-40 px-2" style={{ color: 'var(--text-main)' }}>Qualidade de Render</span>
                  <div className="flex flex-wrap gap-2">
                    {qualities.map((q) => (
                      <button 
                        key={q.id} 
                        onClick={() => onQualityChange(q.id)} 
                        className={`flex-1 min-w-[30%] py-2.5 rounded-xl text-[8px] font-black uppercase transition-all border ${previewQuality === q.id ? 'bg-theme-accent border-theme-accent text-white shadow-lg' : 'bg-theme-panel/50 border-theme opacity-30 hover:opacity-100 text-theme-main'}`}
                      >
                        {q.label}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="pt-3 border-t border-white/5">
                  <button onClick={() => { onShowAbout(); setShowSettings(false); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest text-theme-muted hover:text-theme-accent hover:bg-theme-accent/5 transition-all">
                    <i className="fas fa-paw text-[11px]"></i>
                    <span>Créditos MiauTools</span>
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </nav>
  );
};

export default TopNav;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import HistorySidebar from '../components/HistorySidebar';
import Header from '../components/Header';
import { GridImage, AISettings, HistoryState } from '../types';

const INITIAL_SETTINGS: AISettings = {
  mode: 'enhance',
  sharpness: 0,
  noiseReduction: 0,
  brightness: 100,
  contrast: 100,
  aiIntensity: 70,
  edgeSmoothness: 2,
  smartSharpen: false,
  highPassRadius: 1.5,
  isAdvancedSharpen: false,
  highFreqRadius: 1.2,
  highFreqOpacity: 100,
  lowFreqRadius: 8.0,
  lowFreqOpacity: 50
};

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [currentHistoryIdx, setCurrentHistoryIdx] = useState(-1);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [compareSplit, setCompareSplit] = useState(50);
  const [isComparing, setIsComparing] = useState(true);

  const [baseImageLayer, setBaseImageLayer] = useState<string | null>(null);
  const [aiEnhancedLayer, setAiEnhancedLayer] = useState<string | null>(null);

  const [highPassUrl, setHighPassUrl] = useState<string | null>(null);
  const [highPassUrlFine, setHighPassUrlFine] = useState<string | null>(null);
  const [highPassUrlLarge, setHighPassUrlLarge] = useState<string | null>(null);

  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [aiSettings, setAiSettings] = useState<AISettings>(INITIAL_SETTINGS);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentImg = images[0];

  const hasManualChanges = useMemo(() => {
    return aiSettings.sharpness !== 0 || 
           aiSettings.noiseReduction !== 0 || 
           aiSettings.brightness !== 100 || 
           aiSettings.contrast !== 100 || 
           aiSettings.smartSharpen === true;
  }, [aiSettings]);

  const handleClear = useCallback(() => {
    images.forEach(img => URL.revokeObjectURL(img.previewUrl));
    setImages([]);
    setHistory([]);
    setCurrentHistoryIdx(-1);
    setBaseImageLayer(null);
    setAiEnhancedLayer(null);
    setHighPassUrl(null);
    setHighPassUrlFine(null);
    setHighPassUrlLarge(null);
    setAiSettings(INITIAL_SETTINGS);
  }, [images]);

  const addToHistory = (url: string, label: string) => {
    const newState: HistoryState = {
      id: uuidv4(),
      url,
      label,
      timestamp: Date.now(),
      settingsSnapshot: { ...aiSettings }
    };
    const newHistory = [...history.slice(0, currentHistoryIdx + 1), newState];
    setHistory(newHistory);
    setCurrentHistoryIdx(newHistory.length - 1);
  };

  const handleRestoreHistory = (idx: number) => {
    const state = history[idx];
    if (!state) return;
    setCurrentHistoryIdx(idx);
    setBaseImageLayer(state.url);
    setAiEnhancedLayer(null);
    setAiSettings(state.settingsSnapshot);
  };

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error(`Erro ao carregar recurso visual.`));
      img.src = src;
    });
  };

  const bakeManualChanges = async () => {
    if (!baseImageLayer) return;
    setIsProcessing(true);

    try {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const mainImg = await loadImage(baseImageLayer);
      canvas.width = mainImg.width;
      canvas.height = mainImg.height;

      ctx.filter = getFilterString();
      ctx.drawImage(mainImg, 0, 0);
      ctx.filter = 'none';

      if (aiSettings.smartSharpen) {
        ctx.globalCompositeOperation = 'overlay';

        if (aiSettings.isAdvancedSharpen) {
          if (highPassUrlFine) {
            const hpFine = await loadImage(highPassUrlFine);
            ctx.globalAlpha = aiSettings.highFreqOpacity / 100;
            ctx.drawImage(hpFine, 0, 0);
          }
          if (highPassUrlLarge) {
            const hpLarge = await loadImage(highPassUrlLarge);
            ctx.globalAlpha = aiSettings.lowFreqOpacity / 100;
            ctx.drawImage(hpLarge, 0, 0);
          }
        } else if (highPassUrl) {
          const hpStd = await loadImage(highPassUrl);
          ctx.globalAlpha = 1.0;
          ctx.drawImage(hpStd, 0, 0);
        }

        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1.0;
      }

      const bakedUrl = canvas.toDataURL('image/png', 1.0);

      if (baseImageLayer.startsWith('blob:')) URL.revokeObjectURL(baseImageLayer);

      setBaseImageLayer(bakedUrl);
      setAiEnhancedLayer(null);

      setAiSettings(prev => ({ 
        ...prev, 
        sharpness: 0,
        noiseReduction: 0,
        brightness: 100,
        contrast: 100,
        smartSharpen: false 
      }));

      addToHistory(bakedUrl, "Consolidação Manual");
    } catch (e) {
      console.error("Erro no processamento de camadas:", e);
    } finally {
      setIsProcessing(false);
    }
  };

  const generateSingleHighPass = async (imgSrc: string, radius: number): Promise<string> => {
    try {
      const img = await loadImage(imgSrc);
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return '';

      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);

      const blurCanvas = document.createElement('canvas');
      blurCanvas.width = canvas.width;
      blurCanvas.height = canvas.height;
      const bCtx = blurCanvas.getContext('2d');
      if (bCtx) {
        bCtx.filter = `blur(${radius}px) grayscale(100%)`;
        bCtx.drawImage(img, 0, 0);
      }

      const originalData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const blurredData = bCtx?.getImageData(0, 0, canvas.width, canvas.height);

      if (blurredData) {
        for (let i = 0; i < originalData.data.length; i += 4) {
          originalData.data[i] = 128 + (originalData.data[i] - blurredData.data[i]);
          originalData.data[i+1] = 128 + (originalData.data[i+1] - blurredData.data[i+1]);
          originalData.data[i+2] = 128 + (originalData.data[i+2] - blurredData.data[i+2]);
        }
        ctx.putImageData(originalData, 0, 0);
      }
      return canvas.toDataURL('image/png');
    } catch (e) {
      return '';
    }
  };

  const updateHighPassLayers = useCallback(async () => {
    if (!baseImageLayer || !aiSettings.smartSharpen) {
      setHighPassUrl(null);
      setHighPassUrlFine(null);
      setHighPassUrlLarge(null);
      return;
    }

    const source = aiEnhancedLayer || baseImageLayer;

    if (aiSettings.isAdvancedSharpen) {
      const [fine, large] = await Promise.all([
        generateSingleHighPass(source, aiSettings.highFreqRadius),
        generateSingleHighPass(source, aiSettings.lowFreqRadius)
      ]);
      setHighPassUrlFine(fine);
      setHighPassUrlLarge(large);
      setHighPassUrl(null);
    } else {
      const standard = await generateSingleHighPass(source, aiSettings.highPassRadius);
      setHighPassUrl(standard);
      setHighPassUrlFine(null);
      setHighPassUrlLarge(null);
    }
  }, [baseImageLayer, aiEnhancedLayer, aiSettings.smartSharpen, aiSettings.isAdvancedSharpen, aiSettings.highPassRadius, aiSettings.highFreqRadius, aiSettings.lowFreqRadius]);

  useEffect(() => {
    const timer = setTimeout(() => {
      updateHighPassLayers();
    }, 150);
    return () => clearTimeout(timer);
  }, [updateHighPassLayers]);

  const processWithAI = async (mode: AISettings['mode']) => {
    if (!baseImageLayer) return;

    // Fallback: Tenta pegar do LocalStorage se process.env estiver vazio (cenário Localhost)
    const effectiveApiKey = process.env.API_KEY || localStorage.getItem('miau_manual_key');

    if (!effectiveApiKey) {
      alert("Chave Miau não encontrada! Use o ícone de engrenagem para colar sua API Key.");
      return;
    }

    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: effectiveApiKey });
      const prompt = mode === 'enhance' 
        ? `Enhance details and sharpness. Realistic results only. Keep colors natural.`
        : `Remove digital noise and artifacts. Clean the image but preserve textures.`;

      const base64Data = baseImageLayer.split(',')[1];

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType: 'image/png' } },
            { text: prompt }
          ]
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const resultUrl = `data:image/png;base64,${part.inlineData.data}`;
            setBaseImageLayer(resultUrl);
            setAiEnhancedLayer(null);
            addToHistory(resultUrl, mode === 'enhance' ? "AI High Detail" : "AI Clean Mask");
            break;
          }
        }
      }
    } catch (error) {
      console.error("AI Error:", error);
      alert("Erro na IA! Verifique sua chave ou conexão.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!baseImageLayer) return;
    bakeManualChanges().then(() => {
      const customName = aiSettings.exportFilename?.trim();
      const fileName = `${customName || `miau_lab_export_${Date.now()}`}.png`;
      const link = document.createElement('a');
      link.download = fileName;
      link.href = baseImageLayer;
      link.click();
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const gridImg = { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height };
      setImages([gridImg]);
      setBaseImageLayer(url);
      setAiEnhancedLayer(null);
      setHistory([]);
      addToHistory(url, "Imagem Original");
    };
    img.src = url;
    e.target.value = '';
  };

  const getFilterString = () => {
    const sharpenVal = aiSettings.sharpness;
    const sharpen = sharpenVal > 0 
      ? `contrast(${100 + sharpenVal/2.5}%) brightness(${100 - sharpenVal/25}%) saturate(${100 + sharpenVal/10}%)` 
      : '';
    const blur = aiSettings.noiseReduction > 0 ? `blur(${aiSettings.noiseReduction/30}px)` : '';
    return `brightness(${aiSettings.brightness}%) contrast(${aiSettings.contrast}%) ${sharpen} ${blur}`;
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main relative">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={setAiSettings}
          onAdd={() => (images.length > 0 ? setShowConfirmModal(true) : fileInputRef.current?.click())}
          onProcess={processWithAI}
          onBakeManual={bakeManualChanges}
          onSave={handleDownload}
          isProcessing={isProcessing}
          hasManualChanges={hasManualChanges}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={handleClear} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {baseImageLayer ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden rounded-none group"
                style={{ 
                  width: currentImg.width * zoom,
                  height: currentImg.height * zoom,
                  backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)',
                  backgroundSize: '16px 16px'
                }}
              >
                <img src={history[0]?.url || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" alt="original" />
                <div 
                  className="absolute inset-0 w-full h-full overflow-hidden"
                  style={{ clipPath: isComparing ? `inset(0 0 0 ${compareSplit}%)` : 'none' }}
                >
                  <img src={aiEnhancedLayer || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" style={{ filter: getFilterString() }} alt="enhanced" />
                  {aiSettings.smartSharpen && (
                    <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ mixBlendMode: 'overlay' }}>
                      {!aiSettings.isAdvancedSharpen && highPassUrl && (
                        <img src={highPassUrl} className="absolute inset-0 w-full h-full object-cover" alt="hp-std" />
                      )}
                      {aiSettings.isAdvancedSharpen && (
                        <>
                          {highPassUrlFine && (
                            <img src={highPassUrlFine} className="absolute inset-0 w-full h-full object-cover" style={{ opacity: aiSettings.highFreqOpacity / 100 }} alt="hp-fine" />
                          )}
                          {highPassUrlLarge && (
                            <img src={highPassUrlLarge} className="absolute inset-0 w-full h-full object-cover" style={{ opacity: aiSettings.lowFreqOpacity / 100 }} alt="hp-large" />
                          )}
                        </>
                      )}
                    </div>
                  )}
                </div>
                {isComparing && (
                  <>
                    <div className="absolute top-0 bottom-0 w-0.5 bg-theme-accent z-10 shadow-[0_0_20px_rgba(79,70,229,1)] pointer-events-none" style={{ left: `${compareSplit}%` }}>
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-theme-accent text-white flex items-center justify-center text-[10px] shadow-2xl border border-white/20"><i className="fas fa-arrows-alt-h"></i></div>
                    </div>
                    <input type="range" min="0" max="100" value={compareSplit} onChange={(e) => setCompareSplit(parseInt(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-20" />
                  </>
                )}
                {isProcessing && (
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-xl flex flex-col items-center justify-center text-white z-50 animate-in fade-in duration-300">
                    <div className="w-12 h-12 border-4 border-theme-accent border-t-transparent rounded-full animate-spin mb-4"></div>
