import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import HistorySidebar from '../components/HistorySidebar';
import Header from '../components/Header';
import { GridImage, AISettings, HistoryState } from '../types';

const INITIAL_SETTINGS: AISettings = {
  mode: 'enhance',
  sharpness: 0,
  noiseReduction: 0,
  brightness: 100,
  contrast: 100,
  aiIntensity: 70,
  edgeSmoothness: 2,
  smartSharpen: false,
  highPassRadius: 1.5,
  isAdvancedSharpen: false,
  highFreqRadius: 1.2,
  highFreqOpacity: 100,
  lowFreqRadius: 8.0,
  lowFreqOpacity: 50
};

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [currentHistoryIdx, setCurrentHistoryIdx] = useState(-1);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [compareSplit, setCompareSplit] = useState(50);
  const [isComparing, setIsComparing] = useState(true);
  const [hasApiKey, setHasApiKey] = useState<boolean>(false);

  const [baseImageLayer, setBaseImageLayer] = useState<string | null>(null);
  const [aiEnhancedLayer, setAiEnhancedLayer] = useState<string | null>(null);

  const [highPassUrl, setHighPassUrl] = useState<string | null>(null);
  const [highPassUrlFine, setHighPassUrlFine] = useState<string | null>(null);
  const [highPassUrlLarge, setHighPassUrlLarge] = useState<string | null>(null);

  const [aiSettings, setAiSettings] = useState<AISettings>(INITIAL_SETTINGS);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentImg = images[0];

  // Verifica se a chave está configurada no ambiente
  useEffect(() => {
    const checkKey = async () => {
      try {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      } catch (e) {
        setHasApiKey(false);
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    try {
      await window.aistudio.openSelectKey();
      // Assume sucesso imediato para evitar race conditions do sistema
      setHasApiKey(true);
    } catch (e) {
      console.error("Erro ao abrir seletor:", e);
    }
  };

  const hasManualChanges = useMemo(() => {
    return aiSettings.sharpness !== 0 || 
           aiSettings.noiseReduction !== 0 || 
           aiSettings.brightness !== 100 || 
           aiSettings.contrast !== 100 || 
           aiSettings.smartSharpen === true;
  }, [aiSettings]);

  const handleClear = useCallback(() => {
    images.forEach(img => URL.revokeObjectURL(img.previewUrl));
    setImages([]);
    setHistory([]);
    setCurrentHistoryIdx(-1);
    setBaseImageLayer(null);
    setAiEnhancedLayer(null);
    setHighPassUrl(null);
    setHighPassUrlFine(null);
    setHighPassUrlLarge(null);
    setAiSettings(INITIAL_SETTINGS);
  }, [images]);

  const addToHistory = (url: string, label: string) => {
    const newState: HistoryState = {
      id: uuidv4(),
      url,
      label,
      timestamp: Date.now(),
      settingsSnapshot: { ...aiSettings }
    };
    const newHistory = [...history.slice(0, currentHistoryIdx + 1), newState];
    setHistory(newHistory);
    setCurrentHistoryIdx(newHistory.length - 1);
  };

  const handleRestoreHistory = (idx: number) => {
    const state = history[idx];
    if (!state) return;
    setCurrentHistoryIdx(idx);
    setBaseImageLayer(state.url);
    setAiEnhancedLayer(null);
    setAiSettings(state.settingsSnapshot);
  };

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error(`Erro ao carregar recurso visual.`));
      img.src = src;
    });
  };

  const bakeManualChanges = async () => {
    if (!baseImageLayer) return;
    setIsProcessing(true);

    try {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const mainImg = await loadImage(baseImageLayer);
      canvas.width = mainImg.width;
      canvas.height = mainImg.height;

      ctx.filter = getFilterString();
      ctx.drawImage(mainImg, 0, 0);
      ctx.filter = 'none';

      if (aiSettings.smartSharpen) {
        ctx.globalCompositeOperation = 'overlay';

        if (aiSettings.isAdvancedSharpen) {
          if (highPassUrlFine) {
            const hpFine = await loadImage(highPassUrlFine);
            ctx.globalAlpha = aiSettings.highFreqOpacity / 100;
            ctx.drawImage(hpFine, 0, 0);
          }
          if (highPassUrlLarge) {
            const hpLarge = await loadImage(highPassUrlLarge);
            ctx.globalAlpha = aiSettings.lowFreqOpacity / 100;
            ctx.drawImage(hpLarge, 0, 0);
          }
        } else if (highPassUrl) {
          const hpStd = await loadImage(highPassUrl);
          ctx.globalAlpha = 1.0;
          ctx.drawImage(hpStd, 0, 0);
        }

        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1.0;
      }

      const bakedUrl = canvas.toDataURL('image/png', 1.0);
      if (baseImageLayer.startsWith('blob:')) URL.revokeObjectURL(baseImageLayer);
      setBaseImageLayer(bakedUrl);
      setAiEnhancedLayer(null);
      setAiSettings(prev => ({ 
        ...prev, 
        sharpness: 0,
        noiseReduction: 0,
        brightness: 100,
        contrast: 100,
        smartSharpen: false 
      }));
      addToHistory(bakedUrl, "Consolidação Manual");
    } catch (e) {
      console.error("Erro no processamento:", e);
    } finally {
      setIsProcessing(false);
    }
  };

  const processWithAI = async (mode: AISettings['mode']) => {
    if (!baseImageLayer) return;
    if (!hasApiKey) {
      handleOpenKeySelector();
      return;
    }

    setIsProcessing(true);

    try {
      // Cria instância nova a cada chamada para garantir o uso da chave mais recente
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const intensity = aiSettings.aiIntensity;

      let intensityContext = "";
      if (intensity <= 20) intensityContext = "STRICT PRESERVATION: Change almost nothing. Focus only on clarity.";
      else if (intensity <= 60) intensityContext = "MODERATE ENHANCEMENT: Clean artifacts and sharpen edges.";
      else intensityContext = "MAXIMUM NEURAL RECONSTRUCTION: Deeply enhance quality and reimagining details.";

      const prompt = mode === 'enhance' 
        ? `TASK: High-quality image enhancement. INSTRUCTIONS: ${intensityContext} Target: Clarity and texture restoration.`
        : `TASK: Image denoising. INSTRUCTIONS: ${intensityContext} Target: Artifact removal and clean surfaces.`;

      const base64Data = baseImageLayer.split(',')[1];

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview', // Upgrade para Gemini 3 Pro
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType: 'image/png' } },
            { text: prompt }
          ]
        },
        config: {
          imageConfig: { aspectRatio: "1:1", imageSize: "1K" }
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const resultUrl = `data:image/png;base64,${part.inlineData.data}`;
            setBaseImageLayer(resultUrl);
            setAiEnhancedLayer(null);
            addToHistory(resultUrl, mode === 'enhance' ? "AI Pro Enhanced" : "AI Pro Cleaned");
            setIsProcessing(false);
            return;
          }
        }
      }
      throw new Error("Resposta inesperada da IA.");
    } catch (error: any) {
      console.error("Miau AI Error:", error);
      if (error.message?.includes("Requested entity was not found")) {
        setHasApiKey(false);
        alert("Sua chave API parece inválida ou expirou. Por favor, conecte novamente.");
      } else {
        alert(`Miau Lab erro: ${error.message || 'Erro neural desconhecido.'}`);
      }
    } finally {
      setIsProcessing(false);
    }
  };

  const getFilterString = () => {
    const sharpenVal = aiSettings.sharpness;
    const sharpen = sharpenVal > 0 
      ? `contrast(${100 + sharpenVal/2.5}%) brightness(${100 - sharpenVal/25}%) saturate(${100 + sharpenVal/10}%)` 
      : '';
    const blur = aiSettings.noiseReduction > 0 ? `blur(${aiSettings.noiseReduction/30}px)` : '';
    return `brightness(${aiSettings.brightness}%) contrast(${aiSettings.contrast}%) ${sharpen} ${blur}`;
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main relative">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={setAiSettings}
          onAdd={() => fileInputRef.current?.click()}
          onProcess={processWithAI}
          onBakeManual={bakeManualChanges}
          onSave={() => {}} // Download handle
          isProcessing={isProcessing}
          hasManualChanges={hasManualChanges}
          hasKey={hasApiKey}
          onConfigKey={handleOpenKeySelector}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={handleClear} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {!hasApiKey && baseImageLayer && (
            <div className="absolute inset-0 z-[60] bg-black/80 backdrop-blur-md flex flex-col items-center justify-center text-center p-10 animate-in fade-in duration-500">
               <div className="w-20 h-20 rounded-3xl bg-theme-accent flex items-center justify-center text-white text-3xl mb-6 shadow-2xl animate-pulse">
                 <i className="fas fa-plug"></i>
               </div>
               <h2 className="text-xl font-black uppercase tracking-tighter mb-2">Cérebro Desconectado</h2>
               <p className="text-[10px] opacity-40 uppercase tracking-widest max-w-xs mb-8">Para usar os recursos Pro da IA, você precisa selecionar sua chave API paga.</p>
               <button onClick={handleOpenKeySelector} className="px-8 py-4 rounded-2xl bg-theme-accent text-white font-black text-[11px] uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-xl">Conectar Cérebro Neural</button>
               <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="mt-6 text-[8px] opacity-30 hover:opacity-100 uppercase tracking-widest underline decoration-theme-accent">Ver documentação de faturamento</a>
            </div>
          )}

          {baseImageLayer ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden rounded-none group"
                style={{ width: currentImg.width * zoom, height: currentImg.height * zoom }}
              >
                <img src={history[0]?.url || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" alt="original" />
                <div 
                  className="absolute inset-0 w-full h-full overflow-hidden"
                  style={{ clipPath: isComparing ? `inset(0 0 0 ${compareSplit}%)` : 'none' }}
                >
                  <img src={aiEnhancedLayer || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" style={{ filter: getFilterString() }} alt="enhanced" />
                </div>
                {isComparing && (
                  <>
                    <div className="absolute top-0 bottom-0 w-0.5 bg-theme-accent z-10" style={{ left: `${compareSplit}%` }} />
                    <input type="range" min="0" max="100" value={compareSplit} onChange={(e) => setCompareSplit(parseInt(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-20" />
                  </>
                )}
                {isProcessing && (
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-xl flex flex-col items-center justify-center text-white z-50">
                    <div className="w-12 h-12 border-4 border-theme-accent border-t-transparent rounded-full animate-spin mb-4 shadow-[0_0_40px_rgba(79,70,229,0.6)]"></div>
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">Neural Upgrade Pro...</p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Miau AI Lab</p>
            </div>
          )}
        </div>
      </section>
      <HistorySidebar history={history} currentIndex={currentHistoryIdx} onRestore={handleRestoreHistory} isOpen={isHistoryOpen} onToggle={() => setIsHistoryOpen(!isHistoryOpen)} />
      <input type="file" accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default AILabTool;

import React, { useState } from 'react';
import { AISettings } from '../types';
import MiauSlider from './MiauSlider';

interface SidebarAILabProps {
  settings: AISettings;
  onSettingsChange: (s: AISettings) => void;
  onAdd: () => void;
  onProcess: (mode: AISettings['mode']) => void;
  onSave: () => void;
  onBakeManual: () => void;
  isProcessing: boolean;
  hasManualChanges: boolean;
  hasKey?: boolean;
  onConfigKey?: () => void;
}

const SidebarAILab: React.FC<SidebarAILabProps> = ({ 
  settings, onSettingsChange, onAdd, onProcess, onSave, onBakeManual, isProcessing, hasManualChanges, hasKey, onConfigKey 
}) => {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);

  const handleChange = (key: keyof AISettings, value: any) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  return (
    <div className="p-5 space-y-6 h-full flex flex-col overflow-y-auto custom-scrollbar">
      {/* Indicador de Status de Conexão */}
      <div className="flex items-center justify-between px-2">
        <div className="flex items-center gap-2">
           <div className={`w-1.5 h-1.5 rounded-full ${hasKey ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 'bg-red-500'}`}></div>
           <span className="text-[8px] font-black uppercase tracking-widest opacity-40">{hasKey ? 'IA Conectada' : 'IA Offline'}</span>
        </div>
        <button onClick={onConfigKey} className="text-[8px] font-black uppercase text-theme-accent hover:underline">Configurar Chave</button>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Fonte do Projeto</h3>
        <button onClick={onAdd} className="w-full py-4 rounded-xl font-black text-[10px] bg-theme-accent text-theme-inv shadow-lg flex items-center justify-center gap-2 uppercase active:scale-95 transition-all">
          <i className="fas fa-cloud-upload-alt"></i> Carregar Nova Foto
        </button>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-5">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Melhorias Visuais (Filtros)</h3>
        <div className="space-y-4">
          <div className="bg-black/10 p-4 rounded-2xl border border-theme/30 space-y-4">
            <div className="flex items-center justify-between mb-1">
              <span className="text-[9px] font-black uppercase tracking-widest text-theme-accent">Smart Sharpen</span>
              <button 
                onClick={() => handleChange('smartSharpen', !settings.smartSharpen)}
                className={`w-8 h-4 rounded-full relative transition-all ${settings.smartSharpen ? 'bg-theme-accent' : 'bg-theme-panel'}`}
              >
                <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-all ${settings.smartSharpen ? 'right-0.5' : 'left-0.5'}`}></div>
              </button>
            </div>

            <div className={`space-y-4 transition-all ${!settings.smartSharpen ? 'opacity-20 pointer-events-none grayscale' : ''}`}>
              {!settings.isAdvancedSharpen && (
                <MiauSlider label="Raio de Nitidez" min={0.1} max={10} step={0.1} value={settings.highPassRadius} onChange={(v) => handleChange('highPassRadius', v)} icon="fa-wave-square" />
              )}
              <div className="space-y-3">
                <button onClick={() => { setIsAdvancedOpen(!isAdvancedOpen); handleChange('isAdvancedSharpen', !isAdvancedOpen); }} className="w-full flex items-center justify-between group py-1">
                  <div className="flex items-center gap-2"><span className="text-[8px] font-black uppercase tracking-[0.2em] opacity-40 group-hover:opacity-100 transition-opacity">Modo Expert</span><div className="h-[1px] w-8 bg-theme/20 group-hover:bg-theme-accent/40 transition-all"></div></div>
                  <i className={`fas ${isAdvancedOpen ? 'fa-caret-down' : 'fa-caret-right'} text-[10px] text-theme-accent transition-transform`}></i>
                </button>
                {isAdvancedOpen && (
                  <div className="space-y-6 pt-2 animate-in slide-in-from-top-2 duration-300">
                    <div className="space-y-4 p-3 bg-black/20 rounded-xl border border-theme/30">
                      <MiauSlider label="Micro Detalhes" min={0.1} max={5} step={0.1} value={settings.highFreqRadius} onChange={(v) => handleChange('highFreqRadius', v)} icon="fa-microchip" />
                      <MiauSlider label="Peso Fino" min={0} max={100} value={settings.highFreqOpacity} onChange={(v) => handleChange('highFreqOpacity', v)} unit="%" icon="fa-tint" />
                    </div>
                    <div className="space-y-4 p-3 bg-black/20 rounded-xl border border-theme/30">
                      <MiauSlider label="Volume Geral" min={5} max={20} step={0.5} value={settings.lowFreqRadius} onChange={(v) => handleChange('lowFreqRadius', v)} icon="fa-mountain" />
                      <MiauSlider label="Peso Grosso" min={0} max={100} value={settings.lowFreqOpacity} onChange={(v) => handleChange('lowFreqOpacity', v)} unit="%" icon="fa-tint" />
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
          <MiauSlider label="Nitidez de Borda" min={0} max={100} value={settings.sharpness} onChange={(v) => handleChange('sharpness', v)} icon="fa-magic" />
          <MiauSlider label="Limpeza (Denoise)" min={0} max={100} value={settings.noiseReduction} onChange={(v) => handleChange('noiseReduction', v)} icon="fa-broom" />
          <MiauSlider label="Contraste" min={50} max={200} value={settings.contrast} onChange={(v) => handleChange('contrast', v)} unit="%" icon="fa-adjust" />
          <MiauSlider label="Brilho" min={50} max={150} value={settings.brightness} onChange={(v) => handleChange('brightness', v)} unit="%" icon="fa-sun" />
        </div>
        <div className="pt-2">
          <button onClick={onBakeManual} disabled={!hasManualChanges || isProcessing} className={`w-full py-3.5 rounded-xl font-black text-[9px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all active:scale-95 shadow-lg border ${hasManualChanges ? 'bg-white text-black border-white hover:bg-theme-panel' : 'opacity-30 border-theme bg-theme-panel pointer-events-none'}`}><i className="fas fa-check-circle"></i> Aplicar Ajustes</button>
        </div>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-accent/5 space-y-4 shadow-[inset_0_0_20px_rgba(79,70,229,0.05)]">
        <div className="flex items-center justify-between border-b border-theme pb-2">
          <h3 className="text-[10px] font-black uppercase tracking-widest text-theme-accent">Módulos Neurais Pro</h3>
          <span className="text-[7px] bg-theme-accent text-white px-1.5 py-0.5 rounded font-black">ULTRA-Q</span>
        </div>

        <div className="pb-2 space-y-4">
           <MiauSlider 
            label="Peso da IA (Intensidade)" 
            min={0} 
            max={100} 
            value={settings.aiIntensity} 
            onChange={(v) => handleChange('aiIntensity', v)} 
            unit="%" 
            icon="fa-brain" 
          />

          <div className="flex flex-col gap-2">
            <button 
              onClick={() => onProcess('enhance')} 
              disabled={isProcessing} 
              className={`w-full flex items-center justify-between p-4 rounded-xl border border-theme transition-all group shadow-lg active:scale-95 ${!hasKey ? 'grayscale opacity-50' : 'bg-theme-accent text-white hover:brightness-110'}`}
            >
              <div className="flex items-center gap-3">
                <i className="fas fa-sparkles group-hover:rotate-12 transition-transform"></i>
                <div className="text-left">
                  <p className="text-[10px] font-black uppercase tracking-widest">Enhanced Pro</p>
                  <p className="text-[7px] opacity-70 uppercase">Gemini 3 Visual Engine</p>
                </div>
              </div>
              <i className="fas fa-arrow-right text-[10px] opacity-40"></i>
            </button>
          </div>
        </div>
      </div>

      <div className="mt-auto pt-4 space-y-4">
        <button onClick={onSave} className="w-full py-5 rounded-xl font-black text-[11px] bg-theme-accent text-theme-inv shadow-2xl flex items-center justify-center gap-2 uppercase active:scale-95 transition-all"><i className="fas fa-download"></i> Salvar Resultado</button>
      </div>
    </div>
  );
};

export default SidebarAILab;

