```xml
<changes>
  <change>
    <file>tools/AILabTool.tsx</file>
    <description>Add missing handleFileChange function and ensure API usage follows guidelines.</description>
    <content><![CDATA[
import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google-ai/generativelanguage';

import { useHistory } from './hooks/useHistory';
import { useUploadImage } from './hooks/useUploadImage';
import { useAPIKey } from './hooks/useAPIKey';
import { GridImage } from '../types/gridImage';

const AILabTool = () => {
    const [hasApiKey, setHasApiKey] = useState<boolean>(false);
    const [baseImageLayer, setBaseImageLayer] = useState<string | null>(null);
    const [prompt, setPrompt] = useState<string>('');
    const [images, setImages] = useState<GridImage[]>([]);
    const [currentImg, setCurrentImg] = useState<GridImage | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const { apiKey, isLoading, error } = useAPIKey();
    const { history, addToHistory, undo, redo, canUndo, canRedo } = useHistory();
    const { uploadImage } = useUploadImage();
    const [isGenerating, setIsGenerating] = useState(false);

    useEffect(() => {
        setHasApiKey(!!apiKey);
    }, [apiKey]);

    const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (e: ProgressEvent<FileReader>) => {
            const previewUrl = e.target?.result as string;
            const img = new Image();

            img.onload = () => {
                const newImg: GridImage = {
                    file,
                    previewUrl,
                    width: img.width,
                    height: img.height,
                    aspectRatio: img.width / img.height,
                    isVisible: true,
                };

                setImages(prevImages => [...prevImages, newImg]);
                setCurrentImg(newImg);
                setBaseImageLayer(previewUrl);

                addToHistory({
                    type: 'image',
                    data: {
                        image: newImg,
                        action: 'add'
                    }
                });
                if (fileInputRef.current) {
                    fileInputRef.current.value = '';
                }
            };
            img.src = previewUrl;
        };
        reader.readAsDataURL(file);
    };

    const processWithAI = async () => {
        if (!apiKey || !currentImg || isGenerating) {
            return;
        }

        setIsGenerating(true);
        const { previewUrl } = currentImg;
        if (!previewUrl) {
            setIsGenerating(false);
            return;
        }

        const base64Data = await uploadImage(previewUrl);

        try {
            const genAI = new GoogleGenAI(apiKey); // Moved here to ensure key is current
            const model = genAI.getGenerativeModel({ model: 'gemini-1.5-pro-001' });

            const result = await model.generateContent({
                contents: [
                    {
                        parts: [
                            { inlineData: { data: base64Data, mimeType: 'image/png' } },
                            { text: prompt }
                        ]
                    }
                ],
                config: {
                    imageConfig: { aspectRatio: "1:1", imageSize: "1K" }
                }
            });

            console.log("Response: ", result);
            setIsGenerating(false);
            // Handle the response and update the UI accordingly
        } catch (error) {
            console.error('Error generating content:', error);
            // Handle errors
            setIsGenerating(false);
        }
