        console.warn("Gemini 3 Pro falhou, tentando fallback Flash...", innerError);

        // Fallback para 2.5 Flash (Mais provável de funcionar com chaves padrão)
        const fallbackResponse: GenerateContentResponse = await ai.models.generateContent({
          model: 'gemini-2.5-flash-image',
