const App: React.FC = () => {
  const [activeTool, setActiveTool] = useState<ToolType>('ai-lab');
  const [theme, setTheme] = useState<ThemeType>('midnight');
  const [previewQuality, setPreviewQuality] = useState<PreviewQuality>('fast');
  const [showAbout, setShowAbout] = useState(false);

  // Estado para persistência de pasta local (FileSystemHandle)
  const [frameDirHandle, setFrameDirHandle] = useState<any>(null);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);

  useEffect(() => {
    const handleGlobalClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const isButton = 
        target.tagName === 'BUTTON' || 
        target.tagName === 'INPUT' || 
        target.tagName === 'A' ||
        target.closest('button') ||
        window.getComputedStyle(target).cursor === 'pointer';

      if (isButton) {
        miauAudio.playBtClick();
      } else {
        miauAudio.playMouseClick();
      }
    };

    window.addEventListener('mousedown', handleGlobalClick);
    return () => window.removeEventListener('mousedown', handleGlobalClick);
  }, []);

  const renderTool = () => {
    switch (activeTool) {
      case 'grid':
        return <GridTool />;
      case 'resizer':
        return <ResizerTool />;
      case 'framing':
        return <FramingTool cacheDirHandle={frameDirHandle} />;
