  return (
    <div className="flex flex-col h-screen overflow-hidden transition-colors duration-300 relative bg-theme-main text-theme-main">
      <TopNav 
        activeTool={activeTool} 
        onToolChange={setActiveTool} 
        currentTheme={theme}
