import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GridImage, FrameSettings } from '../types';

interface InteractiveEditorProps {
  mainImage: (GridImage & { x: number, y: number, scale: number, rotation: number }) | null;
  loteImages: GridImage[];
  frameSettings: FrameSettings;
  onUpdateImage: (id: string, updates: Partial<GridImage>) => void;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  zoom?: number;
}

const InteractiveEditor: React.FC<InteractiveEditorProps> = ({ 
  mainImage,
  loteImages, 
  frameSettings, 
  onUpdateImage,
  selectedId,
  onSelect,
  zoom = 0.4
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragInfo = useRef({
    startX: 0,
    startY: 0,
    initialPosX: 0,
    initialPosY: 0,
    id: '',
    animationFrameId: 0
  });

  const handleMouseDown = (e: React.MouseEvent, id: string, x: number, y: number) => {
    e.stopPropagation();
    onSelect(id);
    setIsDragging(true);

    dragInfo.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialPosX: x,
      initialPosY: y,
      id: id,
      animationFrameId: 0
    };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging || !selectedId) return;

    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }

    dragInfo.current.animationFrameId = requestAnimationFrame(() => {
      const dx = e.clientX - dragInfo.current.startX;
      const dy = e.clientY - dragInfo.current.startY;

      onUpdateImage(dragInfo.current.id, {
        x: dragInfo.current.initialPosX + (dx / zoom),
        y: dragInfo.current.initialPosY + (dy / zoom)
      });
    });
  }, [isDragging, selectedId, zoom, onUpdateImage]);

  const handleMouseUp = useCallback(() => {
    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }
    setIsDragging(false);
  }, []);

  const handleWheel = useCallback((e: WheelEvent) => {
    if (!selectedId) return;
    e.preventDefault();

    const element = selectedId === 'main' 
      ? mainImage 
      : loteImages.find(img => img.id === selectedId);

    if (element) {
      const delta = e.deltaY > 0 ? -0.02 : 0.02;
      const currentScale = (element as any).scale || 1;
      const newScale = Math.max(0.01, Math.min(10, currentScale + delta));
      onUpdateImage(selectedId, { scale: newScale });
    }
  }, [selectedId, mainImage, loteImages, onUpdateImage]);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove, { passive: true });
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  useEffect(() => {
    const container = containerRef.current;
    if (container) {
      container.addEventListener('wheel', handleWheel, { passive: false });
    }
    return () => {
      if (container) container.removeEventListener('wheel', handleWheel);
    };
  }, [handleWheel]);

  const SelectionOverlay = ({ isActive }: { isActive: boolean }) => (
    isActive ? (
      <div className="absolute inset-[-2px] border-2 border-dashed border-theme-accent rounded-none shadow-[0_0_15px_rgba(79,70,229,0.3)] z-50 pointer-events-none">
      </div>
    ) : null
  );

  return (
    <div 
      ref={containerRef}
      className="relative shadow-2xl border border-white/10 bg-theme-panel transition-[width,height] duration-300 ease-out"
      style={{ 
        width: frameSettings.canvasWidth * zoom, 
        height: frameSettings.canvasHeight * zoom,
        minWidth: frameSettings.canvasWidth * zoom,
        minHeight: frameSettings.canvasHeight * zoom,
        backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)',
        backgroundSize: '20px 20px',
      }}
      onMouseDown={() => onSelect(null)}
    >
      {/* CAMADA DE LIMBO: Aumentada opacidade para bg-black/85 para melhor visibilidade */}
      <div className="absolute inset-[-5000px] pointer-events-none z-[55] bg-black/85" style={{ clipPath: 'polygon(0% 0%, 0% 100%, 100% 100%, 100% 0%, 0% 0%, 5000px 5000px, calc(100% - 5000px) 5000px, calc(100% - 5000px) calc(100% - 5000px), 5000px calc(100% - 5000px), 5000px 5000px)' }}></div>

      {/* Guia Visual do Perímetro Exato */}
      <div className="absolute inset-0 border border-theme-accent/40 border-dashed pointer-events-none z-[60]"></div>

      {mainImage && mainImage.visible !== false && (
        <div
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === 'main' ? 'z-30 opacity-100' : 'z-10 opacity-70'}`}
          style={{
            left: mainImage.x * zoom,
            top: mainImage.y * zoom,
            width: (mainImage.width * mainImage.scale) * zoom,
            transform: `rotate(${mainImage.rotation}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, 'main', mainImage.x, mainImage.y)}
        >
          <img src={mainImage.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === 'main'} />
        </div>
      )}

      {loteImages.map((img) => img.visible !== false && (
        <div
          key={img.id}
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === img.id ? 'z-40 opacity-100' : 'z-20 opacity-70'}`}
          style={{
            left: (img.x || 0) * zoom,
            top: (img.y || 0) * zoom,
            width: (img.width * (img.scale || 1)) * zoom,
            transform: `rotate(${img.rotation || 0}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, img.id, img.x || 0, img.y || 0)}
        >
          <img src={img.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === img.id} />
        </div>
      ))}

      {/* MOLDURA: Ajustada para z-[45] para ficar abaixo da UI mas acima das fotos */}
      <div 
        className="absolute inset-0 pointer-events-none z-[45] transition-all duration-300"
        style={{
          border: frameSettings.frameImageUrl ? 'none' : `${frameSettings.borderWidth * zoom}px solid ${frameSettings.borderColor}`,
          borderRadius: `${frameSettings.borderRadius * zoom}px`,
          boxShadow: `inset 0 0 ${frameSettings.shadow * zoom}px rgba(0,0,0,0.2)`
        }}
      >
        {frameSettings.frameImageUrl && (
          <img src={frameSettings.frameImageUrl} className="w-full h-full object-fill" />
        )}
      </div>
    </div>
  );
};

export default InteractiveEditor;

import React from 'react';
import { GridSettings, GridImage } from '../types';
import MiauSlider from './MiauSlider';

interface SidebarProps {
  settings: GridSettings;
  onSettingsChange: (settings: GridSettings) => void;
  onAddFile: () => void;
  onAddFolder: () => void;
  images: GridImage[];
  onUpdateActiveCount: (count: number) => void;
  exportOptions: {
    downloadIndividual: boolean;
    setDownloadIndividual: (v: boolean) => void;
    downloadZip: boolean;
    setDownloadZip: (v: boolean) => void;
  };
  onExport: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ settings, onSettingsChange, onAddFile, onAddFolder, images, onUpdateActiveCount, exportOptions, onExport }) => {
  const handleChange = (key: keyof GridSettings, value: any) => { 
    onSettingsChange({ ...settings, [key]: value }); 
  };

  const handleBackgroundChange = (color: string, transparent: boolean) => {
    onSettingsChange({
      ...settings,
      backgroundColor: color,
      isTransparent: transparent
    });
  };

  const selectExportMode = (mode: 'individual' | 'zip') => {
    if (mode === 'individual') {
      exportOptions.setDownloadIndividual(true);
      exportOptions.setDownloadZip(false);
    } else {
      exportOptions.setDownloadIndividual(false);
      exportOptions.setDownloadZip(true);
    }
  };

  const activeCount = images.filter(img => img.isActive).length;
  const isAuto = settings.layoutMode === 'auto';

  return (
    <div className="p-5 space-y-6 h-full overflow-y-auto scrollbar-hide flex flex-col">
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Entrada de Mídia</h3>
        <div className="space-y-2">
          <button onClick={onAddFile} className="w-full flex items-center justify-center gap-2 py-3.5 px-4 rounded-xl font-black text-[10px] transition-all active:scale-95 shadow-lg hover:opacity-90 relative group overflow-hidden uppercase bg-theme-accent text-theme-inv">
            <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
            <i className="fas fa-plus-circle z-10"></i> <span className="z-10">Adicionar Fotos</span>
          </button>
          <button onClick={onAddFolder} className="w-full flex items-center justify-center gap-2 py-2.5 px-4 rounded-lg font-bold text-[9px] border transition-all active:scale-95 shadow-sm hover:bg-black/10 relative group overflow-hidden uppercase border-theme bg-theme-panel text-theme-main">
            <i className="fas fa-folder z-10"></i> <span className="z-10">Pasta Completa</span>
          </button>
        </div>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <div className="flex items-center justify-between border-b border-theme pb-2">
          <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Organização</h3>
          {isAuto && <i className="fas fa-robot text-theme-accent text-[10px]"></i>}
        </div>
        <div className="flex p-1 bg-theme-panel/50 rounded-xl border border-theme">
          <button onClick={() => handleChange('layoutMode', 'grid')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${!isAuto ? 'bg-theme-accent text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}>Manual</button>
          <button onClick={() => handleChange('layoutMode', 'auto')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${isAuto ? 'bg-theme-accent text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}>Auto-Flow</button>
        </div>
        {isAuto && (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
            <MiauSlider label="Itens na Grid" min={1} max={images.length || 1} value={activeCount} onChange={onUpdateActiveCount} icon="fa-layer-group" />
            <div className="space-y-2">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide px-1">Formato do Conjunto</label>
              <div className="grid grid-cols-3 gap-1.5">
                {[{ id: 'square', label: '1:1', icon: 'fa-square' }, { id: 'portrait', label: '3:4', icon: 'fa-columns' }, { id: 'landscape', label: '4:3', icon: 'fa-grip-horizontal' }].map(shape => (
                  <button key={shape.id} onClick={() => handleChange('targetShape', shape.id)} className={`flex flex-col items-center justify-center gap-1.5 py-3 rounded-xl border transition-all ${settings.targetShape === shape.id ? 'bg-theme-accent border-theme-accent text-white shadow-lg' : 'bg-theme-panel/50 border-theme opacity-50 hover:opacity-100'}`}>
                    <i className={`fas ${shape.icon} text-[10px]`}></i>
                    <span className="text-[7px] font-black uppercase">{shape.label}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-5">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Dimensões & Escala</h3>
        <div className={`grid grid-cols-2 gap-3 transition-all ${isAuto ? 'opacity-30 pointer-events-none grayscale' : ''}`}>
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase block">Largura</label>
            <input type="number" value={settings.canvasWidth} onChange={(e) => handleChange('canvasWidth', parseInt(e.target.value) || 0)} className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none font-mono" />
          </div>
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase block">Altura</label>
            <input type="number" value={settings.canvasHeight} onChange={(e) => handleChange('canvasHeight', parseInt(e.target.value) || 0)} className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none font-mono" />
          </div>
        </div>
        <div className="space-y-4">
          <MiauSlider label="Zoom Elementos" min={-50} max={50} value={settings.itemScale || 0} onChange={(v) => handleChange('itemScale', v)} unit="%" icon="fa-search-plus" />
          {!isAuto && <MiauSlider label="Colunas" min={1} max={12} value={settings.columns} onChange={(v) => handleChange('columns', v)} icon="fa-grip-vertical" />}
          <MiauSlider label="Espaçamento" min={0} max={200} value={settings.innerSpacing} onChange={(v) => handleChange('innerSpacing', v)} icon="fa-th" />
          <MiauSlider label="Margem Externa" min={0} max={200} value={settings.outerMargin} onChange={(v) => handleChange('outerMargin', v)} icon="fa-border-outer" />
        </div>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Estética do Fundo</h3>
        <div className="flex items-center gap-2">
          <button 
            onClick={() => handleBackgroundChange(settings.backgroundColor, !settings.isTransparent)} 
            className={`flex-1 flex items-center justify-center gap-2 py-3 px-3 rounded-xl border text-[9px] font-black transition-all ${settings.isTransparent ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-panel border-theme opacity-60'}`}
          >
            <i className={`fas ${settings.isTransparent ? 'fa-check-circle' : 'fa-circle-notch'}`}></i>
            <span>Transparência</span>
          </button>

          <div className="relative group">
            <input 
              type="color" 
              value={settings.backgroundColor} 
              onChange={(e) => handleBackgroundChange(e.target.value, false)} 
              className={`w-12 h-12 rounded-xl cursor-pointer border p-1 bg-theme-panel transition-all ${settings.isTransparent ? 'border-theme opacity-20' : 'border-theme-accent shadow-[0_0_15px_rgba(79,70,229,0.2)]'}`} 
            />
            {!settings.isTransparent && <div className="absolute -top-1 -right-1 w-3 h-3 bg-theme-accent rounded-full border-2 border-theme-side"></div>}
          </div>
        </div>
      </div>

      <div className="mt-auto pt-4 space-y-4">
        <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
          <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Opções de Exportação</h3>

          <div className="space-y-1 mb-3">
            <label className="text-[8px] font-black uppercase opacity-40 ml-1">Nome do Arquivo</label>
            <input 
              type="text" 
              placeholder="Ex: grid_final"
              value={settings.exportFilename || ''}
              onChange={(e) => handleChange('exportFilename', e.target.value)}
              className="w-full bg-theme-panel border border-theme rounded-xl p-2.5 text-[10px] outline-none font-bold focus:border-theme-accent transition-colors"
            />
          </div>

          <div className="grid grid-cols-1 gap-2">
            <button onClick={() => selectExportMode('individual')} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${exportOptions.downloadIndividual ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/30 border-theme opacity-60'}`}>
              <div className={`w-3 h-3 rounded-full border flex items-center justify-center ${exportOptions.downloadIndividual ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
                {exportOptions.downloadIndividual && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in"></div>}
              </div>
              <span className="text-[9px] font-black uppercase">Arquivo Solto (.PNG)</span>
            </button>
            <button onClick={() => selectExportMode('zip')} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${exportOptions.downloadZip ? 'bg-theme-accent/10 border-theme-accent' : 'bg-theme-panel/30 border-theme opacity-60'}`}>
              <div className={`w-3 h-3 rounded-full border flex items-center justify-center ${exportOptions.downloadZip ? 'border-theme-accent bg-theme-accent' : 'border-theme'}`}>
                {exportOptions.downloadZip && <div className="w-1.5 h-1.5 rounded-full bg-white animate-in zoom-in"></div>}
              </div>
              <span className="text-[9px] font-black uppercase">Salvar Zipado (.ZIP)</span>
            </button>
          </div>
        </div>

        <button disabled={images.length === 0} onClick={onExport} className="w-full flex items-center justify-center gap-3 py-4 px-4 rounded-xl font-black text-[11px] transition-all active:scale-95 shadow-2xl disabled:opacity-30 uppercase tracking-widest bg-theme-accent text-theme-inv relative group overflow-hidden">
          <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <i className="fas fa-file-export z-10"></i> <span className="z-10">Exportar Resultado</span>
        </button>
      </div>
    </div>
  );
};

