              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-2xl bg-theme-accent flex items-center justify-center text-white shadow-lg"><i className="fas fa-images"></i></div>
                <div>
                  <h3 className="text-xl font-black uppercase tracking-tighter">Molduras da Pasta Cache</h3>
