import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { FramingPreset, FrameSettings, GridImage } from '../types';

interface FramingPresetModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentSettings: FrameSettings;
  currentExtraLayers: GridImage[];
  onLoadPreset: (preset: FramingPreset) => void;
}

const FramingPresetModal: React.FC<FramingPresetModalProps> = ({ isOpen, onClose, currentSettings, currentExtraLayers, onLoadPreset }) => {
  const [presets, setPresets] = useState<FramingPreset[]>([]);
  const [isNaming, setIsNaming] = useState(false);
  const [presetName, setPresetName] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('miau_framing_presets');
    if (saved) setPresets(JSON.parse(saved));
  }, []);

  const saveToLocalStorage = (newPresets: FramingPreset[]) => {
    setPresets(newPresets);
    localStorage.setItem('miau_framing_presets', JSON.stringify(newPresets));
  };

  const fileToDataUrl = (file: File | string): Promise<string> => {
    return new Promise((resolve, reject) => {
      if (typeof file === 'string') {
        // Se já for uma URL (blob ou externa), tenta buscar e converter
        fetch(file)
          .then(r => r.blob())
          .then(blob => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result as string);
            reader.readAsDataURL(blob);
          })
          .catch(reject);
      } else {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(file);
      }
    });
  };

  const handleSavePreset = async () => {
    if (!presetName.trim()) return;

    try {
      const extraLayersData = await Promise.all(currentExtraLayers.map(async l => ({
        id: uuidv4(),
        dataUrl: await fileToDataUrl(l.file || l.previewUrl),
        width: l.width,
        height: l.height,
        aspectRatio: l.aspectRatio,
        x: l.x || 0,
        y: l.y || 0,
        scale: l.scale || 1,
        rotation: l.rotation || 0,
        name: l.file?.name || 'extra_layer'
      })));

      let frameImageDataUrl = undefined;
      if (currentSettings.frameImageUrl) {
        frameImageDataUrl = await fileToDataUrl(currentSettings.frameImageUrl);
      }

      const newPreset: FramingPreset = {
        id: uuidv4(),
        name: presetName,
        timestamp: Date.now(),
        settings: { ...currentSettings, frameImageUrl: undefined }, // Não salvamos o blob URL volátil
        extraLayers: extraLayersData,
        frameImageDataUrl
      };

      saveToLocalStorage([newPreset, ...presets]);
      setIsNaming(false);
      setPresetName('');
    } catch (err) {
      console.error('Erro ao salvar preset:', err);
      alert('Houve um erro ao processar as imagens do preset. Certifique-se de que os arquivos extras ainda estão disponíveis.');
    }
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    saveToLocalStorage(presets.filter(p => p.id !== id));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-8 bg-black/60 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="w-full max-w-4xl bg-theme-side border border-theme rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden h-[80vh]">
        <div className="p-8 border-b border-theme flex items-center justify-between bg-black/10">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-2xl bg-theme-accent flex items-center justify-center text-white shadow-lg"><i className="fas fa-bookmark"></i></div>
            <div>
              <h3 className="text-xl font-black uppercase tracking-tighter">Biblioteca de Estilos</h3>
              <p className="text-[10px] opacity-40 uppercase tracking-widest">Salve resoluções, molduras e elementos extras</p>
            </div>
          </div>
          <div className="flex gap-3">
            <button 
              onClick={() => setIsNaming(true)} 
              className="px-6 py-2.5 rounded-xl bg-theme-accent text-white text-[10px] font-black uppercase tracking-widest transition-all shadow-lg active:scale-95 flex items-center gap-2"
            >
              <i className="fas fa-plus"></i> Novo Preset
            </button>
            <button onClick={onClose} className="w-10 h-10 flex items-center justify-center rounded-xl bg-theme-panel text-theme-muted hover:text-red-500 transition-all"><i className="fas fa-times"></i></button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8 grid grid-cols-3 gap-6 custom-scrollbar">
          {presets.length === 0 ? (
            <div className="col-span-3 flex flex-col items-center justify-center text-center opacity-20 py-20">
              <i className="fas fa-folder-open text-6xl mb-4"></i>
              <p className="text-sm font-black uppercase">Nenhum preset salvo ainda</p>
            </div>
          ) : (
            presets.map(p => (
              <div 
                key={p.id} 
                onClick={() => onLoadPreset(p)} 
                className="group relative cursor-pointer bg-theme-panel/30 border border-theme rounded-3xl p-5 hover:border-theme-accent transition-all flex flex-col gap-4 active:scale-95"
              >
                <div className="flex justify-between items-start">
                  <div className="space-y-1">
                    <p className="text-[10px] font-black uppercase text-theme-accent tracking-widest">Design</p>
                    <h4 className="text-sm font-black truncate max-w-[150px] uppercase tracking-tighter">{p.name}</h4>
                  </div>
                  <button 
                    onClick={(e) => handleDelete(e, p.id)} 
                    className="w-8 h-8 rounded-lg bg-red-500/10 text-red-500 opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500 hover:text-white"
                  >
                    <i className="fas fa-trash-alt text-[10px]"></i>
                  </button>
                </div>

                <div className="grid grid-cols-2 gap-2">
                  <div className="p-2 rounded-xl bg-black/20 border border-white/5 text-center">
                    <p className="text-[7px] font-black uppercase opacity-30">Extras</p>
                    <p className="text-[11px] font-black font-mono">{p.extraLayers.length}</p>
                  </div>
                  <div className="p-2 rounded-xl bg-black/20 border border-white/5 text-center">
                    <p className="text-[7px] font-black uppercase opacity-30">Resolução</p>
                    <p className="text-[9px] font-black font-mono">{p.settings.canvasWidth}x{p.settings.canvasHeight}</p>
                  </div>
                </div>

                <div className="flex items-center gap-2 pt-2 border-t border-theme/30 opacity-40 group-hover:opacity-100 transition-all">
                  <i className={`fas ${p.frameImageDataUrl || p.settings.frameImageUrl ? 'fa-border-all' : 'fa-border-none'} text-[10px]`}></i>
                  <span className="text-[8px] font-black uppercase tracking-widest">{p.frameImageDataUrl ? 'Moldura de Imagem' : 'Bordas Dinâmicas'}</span>
                </div>
              </div>
            ))
          )}
        </div>

        {isNaming && (
          <div className="absolute inset-0 z-[110] flex items-center justify-center bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
            <div className="bg-theme-side border border-theme-accent w-full max-w-md rounded-[2.5rem] p-10 shadow-[0_0_100px_rgba(79,70,229,0.3)] flex flex-col items-center gap-6">
              <div className="w-16 h-16 rounded-3xl bg-theme-accent flex items-center justify-center text-white text-2xl shadow-xl animate-bounce"><i className="fas fa-bookmark"></i></div>
              <div className="text-center">
                <h3 className="text-xl font-black uppercase tracking-tighter text-theme-main">Salvar Preset</h3>
                <p className="text-[10px] opacity-40 uppercase tracking-widest mt-1">Defina um nome para este estilo</p>
              </div>
              <input 
                type="text" 
                autoFocus 
                value={presetName} 
                onChange={(e) => setPresetName(e.target.value)} 
                onKeyDown={(e) => e.key === 'Enter' && handleSavePreset()} 
                className="w-full bg-theme-panel border border-theme px-6 py-4 rounded-2xl outline-none focus:border-theme-accent text-sm font-bold transition-all text-center" 
                placeholder="Ex: Minimalista Red" 
              />
              <div className="w-full flex flex-col gap-3">
                <button 
                  onClick={handleSavePreset} 
                  className="w-full py-4 rounded-2xl bg-theme-accent text-white font-black uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all"
                >
                  Confirmar Registro
                </button>
                <button onClick={() => setIsNaming(false)} className="w-full py-3 rounded-2xl text-[9px] font-black uppercase opacity-30 hover:opacity-100 transition-all">Cancelar</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default FramingPresetModal;

import React, { useState, useRef, useMemo, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarFraming from '../components/SidebarFraming';
import InteractiveEditor from '../components/InteractiveEditor';
import FramingPresetModal from '../components/FramingPresetModal';
import Header from '../components/Header';
import { GridImage, FrameSettings, FramingPreset } from '../types';

interface BatchItemState { x: number; y: number; scale: number; rotation: number; exportPrefix?: string; exportFilename?: string; }

interface FramingToolProps {
  cacheDirHandle?: any;
  isSettingsOpen?: boolean;
}

const FramingTool: React.FC<FramingToolProps> = ({ cacheDirHandle, isSettingsOpen = false }) => {
  const [mainBatch, setMainBatch] = useState<GridImage[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [batchStates, setBatchStates] = useState<Record<string, BatchItemState>>({});
  const [autoSave, setAutoSave] = useState(true);
  const [extraLayers, setExtraLayers] = useState<GridImage[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [zoom, setZoom] = useState(0.4); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [settings, setSettings] = useState<FrameSettings>({ borderWidth: 20, borderColor: '#ffffff', borderRadius: 0, padding: 0, shadow: 10, canvasWidth: 1080, canvasHeight: 1080 });

  const [showPresets, setShowPresets] = useState(false);
  const [showCachePicker, setShowCachePicker] = useState(false);
  const [cacheFiles, setCacheFiles] = useState<{name: string, handle: any, url: string}[]>([]);

  const [isScaling, setIsScaling] = useState(false);
  const scaleDragRef = useRef({ lastX: 0, currentScale: 1 });

  const mainFileInputRef = useRef<HTMLInputElement>(null);
  const extraFileInputRef = useRef<HTMLInputElement>(null);
  const frameInputRef = useRef<HTMLInputElement>(null);

  const currentMainImage = mainBatch[currentIndex];

  const currentTransform = useMemo(() => {
    if (!currentMainImage) return null;
    return batchStates[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 };
  }, [currentMainImage, batchStates, settings.canvasWidth, settings.canvasHeight]);

  useEffect(() => {
    if (currentMainImage && batchStates[currentMainImage.id]) {
      const state = batchStates[currentMainImage.id];
      setSettings(prev => ({ 
        ...prev, 
        exportPrefix: state.exportPrefix || '', 
        exportFilename: state.exportFilename || '' 
      }));
    }
  }, [currentIndex, currentMainImage]);

  const updateSettings = (newSettings: FrameSettings) => {
    setSettings(newSettings);
    if (currentMainImage) {
      setBatchStates(prev => ({
        ...prev,
        [currentMainImage.id]: {
          ...(prev[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 }),
          exportPrefix: newSettings.exportPrefix,
          exportFilename: newSettings.exportFilename
        }
      }));
    }
  };

  const applyPrefixToAll = () => {
    const prefix = settings.exportPrefix || '';
    setBatchStates(prev => {
      const newState = { ...prev };
      mainBatch.forEach(img => {
        newState[img.id] = { 
          ...(newState[img.id] || { x: (settings.canvasWidth / 2) - (img.width * 0.1), y: (settings.canvasHeight / 2) - (img.height * 0.1), scale: 0.2, rotation: 0 }), 
          exportPrefix: prefix 
        };
      });
      return newState;
    });
  };

  const selectedElement = useMemo(() => {
    if (selectedId === 'main') return { ...currentMainImage, ...currentTransform };
    return extraLayers.find(img => img.id === selectedId);
  }, [selectedId, currentMainImage, currentTransform, extraLayers]);

  const updateTransform = useCallback((id: string, updates: Partial<BatchItemState | GridImage>) => {
    if (id === 'main' && currentMainImage) {
      setBatchStates(prev => ({ 
        ...prev, 
        [currentMainImage.id]: { 
          ...(prev[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 }), 
          ...updates as any 
        } 
      }));
    } else {
      setExtraLayers(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
    }
  }, [currentMainImage, settings]);

  const onScaleMouseDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!selectedId || !selectedElement) return;
    const target = e.currentTarget;
    target.setPointerCapture(e.pointerId);
    setIsScaling(true);
    scaleDragRef.current = { lastX: e.clientX, currentScale: selectedElement.scale || 1 };
    document.body.style.userSelect = 'none';
  };

  useEffect(() => {
    if (!isScaling) return;
    const handleMouseMove = (e: MouseEvent) => {
      const deltaX = e.clientX - scaleDragRef.current.lastX;
      scaleDragRef.current.lastX = e.clientX;
      const sensitivity = 0.0035; 
      const newScale = Math.max(0.01, Math.min(10, scaleDragRef.current.currentScale + (deltaX * sensitivity)));
      scaleDragRef.current.currentScale = newScale;
      updateTransform(selectedId!, { scale: newScale });
    };
    const handleMouseUp = () => {
      setIsScaling(false);
      document.body.style.userSelect = '';
    };
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isScaling, selectedId, updateTransform]);

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image(); img.crossOrigin = "anonymous";
      img.onload = () => resolve(img); img.onerror = () => reject(new Error("Erro"));
      img.src = url;
    });
  };

  const handleLoadPreset = async (preset: FramingPreset) => {
    try {
      setIsProcessing(true);

      // 1. Converter Base64 de volta para Blobs/URLs
      const dataUrlToBlob = (dataUrl: string) => fetch(dataUrl).then(r => r.blob());

      const restoredExtraLayers = await Promise.all(preset.extraLayers.map(async l => {
        const blob = await dataUrlToBlob(l.dataUrl);
        const file = new File([blob], l.name, { type: blob.type });
        const url = URL.createObjectURL(file);
        return {
          id: uuidv4(),
          file,
          previewUrl: url,
          width: l.width,
          height: l.height,
          aspectRatio: l.aspectRatio,
          x: l.x,
          y: l.y,
          scale: l.scale,
          rotation: l.rotation,
          visible: true
        };
      }));

      let restoredFrameUrl = undefined;
      let restoredFrameName = preset.settings.frameImageName;
      if (preset.frameImageDataUrl) {
        const blob = await dataUrlToBlob(preset.frameImageDataUrl);
        const file = new File([blob], restoredFrameName || 'frame.png', { type: blob.type });
        restoredFrameUrl = URL.createObjectURL(file);
      }

      // 2. Aplicar estados
      setSettings({
        ...preset.settings,
        frameImageUrl: restoredFrameUrl,
        frameImageName: restoredFrameName
      });
      setExtraLayers(restoredExtraLayers);
      setShowPresets(false);
    } catch (err) {
      console.error('Erro ao carregar preset:', err);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAddFrameClick = async () => {
    if (!cacheDirHandle) {
      frameInputRef.current?.click();
      return;
    }
    try {
      const moldurasDir = await cacheDirHandle.getDirectoryHandle('molduras', { create: true });
      const files: any[] = [];
      for await (const entry of moldurasDir.values()) {
        if (entry.kind === 'file' && (entry.name.endsWith('.png') || entry.name.endsWith('.jpg') || entry.name.endsWith('.webp'))) {
          const file = await entry.getFile();
          files.push({ name: entry.name, handle: entry, url: URL.createObjectURL(file) });
        }
      }
      setCacheFiles(files);
      setShowCachePicker(true);
    } catch (err) {
      console.error('Erro ao ler pasta de molduras:', err);
      frameInputRef.current?.click();
    }
  };

  const selectCacheFrame = async (fileData: any) => {
    const file = await fileData.handle.getFile();
    const url = fileData.url;
    const img = new Image();
    img.onload = () => {
      setSettings(prev => ({ ...prev, frameImageUrl: url, frameImageName: file.name, canvasWidth: img.width, canvasHeight: img.height }));
      setShowCachePicker(false);
    };
    img.src = url;
  };

  const handleProcessAll = async () => {
    if (mainBatch.length === 0) return;
    setIsProcessing(true); setProcessProgress(0);
    const canvas = document.createElement('canvas');
    canvas.width = settings.canvasWidth; canvas.height = settings.canvasHeight;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;
    const zip = downloadZip ? new JSZip() : null;
    try {
      const extraImgs = await Promise.all(extraLayers.map(l => loadImage(l.previewUrl)));
      let frameImg: HTMLImageElement | null = null;
      if (settings.frameImageUrl) frameImg = await loadImage(settings.frameImageUrl);
      for (let i = 0; i < mainBatch.length; i++) {
        setProcessProgress(i + 1);
        const item = mainBatch[i]; 
        const state = batchStates[item.id] || { x: (settings.canvasWidth / 2) - (item.width * 0.1), y: (settings.canvasHeight / 2) - (item.height * 0.1), scale: 0.2, rotation: 0 };
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const mainImgObj = await loadImage(item.previewUrl);
        ctx.save();
        const drawW = item.width * state.scale, drawH = item.height * state.scale;
        ctx.translate(state.x + drawW / 2, state.y + drawH / 2); ctx.rotate((state.rotation * Math.PI) / 180);
        ctx.drawImage(mainImgObj, -drawW / 2, -drawH / 2, drawW, drawH); ctx.restore();
        extraLayers.forEach((layer, idx) => {
          if (layer.visible === false) return;
          ctx.save(); const lW = layer.width * (layer.scale || 1), lH = layer.height * (layer.scale || 1);
          ctx.translate((layer.x || 0) + lW / 2, (layer.y || 0) + lH / 2); ctx.rotate(((layer.rotation || 0) * Math.PI) / 180);
          ctx.drawImage(extraImgs[idx], -lW / 2, -lH / 2, lW, lH); ctx.restore();
        });
        if (frameImg) ctx.drawImage(frameImg, 0, 0, canvas.width, canvas.height);
        else {
          ctx.strokeStyle = settings.borderColor; ctx.lineWidth = settings.borderWidth;
          ctx.strokeRect(settings.borderWidth / 2, settings.borderWidth / 2, canvas.width - settings.borderWidth, canvas.height - settings.borderWidth);
        }
        const dataUrl = canvas.toDataURL('image/png', 1.0);
        const prefix = state.exportPrefix || '';
        const baseName = state.exportFilename?.trim() || item.file.name.replace(/\.[^/.]+$/, "");
        const fileName = `${prefix}${baseName}.png`;
        if (downloadIndividual) {
          const link = document.createElement('a'); link.download = fileName; link.href = dataUrl;
          document.body.appendChild(link); link.click(); document.body.removeChild(link);
          await new Promise(r => setTimeout(r, 400));
        }
        if (zip) zip.file(fileName, dataUrl.split(',')[1], { base64: true });
      }
      if (zip) {
        const zipBlob = await zip.generateAsync({ type: "blob" });
        const link = document.createElement('a'); link.href = URL.createObjectURL(zipBlob);
        link.download = `miau_tools_batch_${Date.now()}.zip`; link.click();
      }
    } finally { setIsProcessing(false); setProcessProgress(0); }
  };

  const handleMainFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const newItems = await Promise.all(files.map(async file => {
        const url = URL.createObjectURL(file);
        const img = await loadImage(url);
        return { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height, isActive: true };
      }));
      setMainBatch(prev => [...prev, ...newItems]);
    }
  };

  const handleExtraFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const newLayers = await Promise.all(files.map(async file => {
        const url = URL.createObjectURL(file);
        const img = await loadImage(url);
        return { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height, x: 0, y: 0, scale: 0.2, rotation: 0, visible: true };
      }));
      setExtraLayers(prev => [...prev, ...newLayers]);
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto">
        <SidebarFraming 
          settings={settings} onSettingsChange={updateSettings} 
          onAddLote={() => mainFileInputRef.current?.click()} 
          onAddExtras={() => extraFileInputRef.current?.click()} 
          onAddFrame={handleAddFrameClick} 
          onOpenPresets={() => setShowPresets(true)}
          autoSave={autoSave} onAutoSaveChange={setAutoSave} onProcessAll={handleProcessAll} 
          isProcessing={isProcessing} progress={processProgress} total={mainBatch.length} 
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onApplyPrefixToAll={applyPrefixToAll}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden bg-theme-main relative">
        <Header itemCount={mainBatch.length + extraLayers.length} onClear={() => {setMainBatch([]); setExtraLayers([]); setBatchStates({});}} />
        <div className={`h-14 border-b flex items-center px-6 gap-8 backdrop-blur-xl transition-all duration-300 ${isSettingsOpen ? 'z-0 opacity-20 pointer-events-none' : 'z-[60] opacity-100'} ${selectedId ? 'bg-theme-accent/15 border-theme-accent/40' : 'bg-theme-side/50 border-theme'}`}>
          <div className={`flex items-center gap-8 transition-all duration-500 ${!selectedElement ? 'opacity-5 grayscale pointer-events-none translate-y-2' : 'opacity-100 translate-y-0'}`}>
            <div className="flex flex-col gap-1">
              <span className={`text-[7px] font-black uppercase tracking-[0.2em] transition-colors ${selectedId ? 'text-theme-accent' : 'opacity-40'}`}>Scale Precision</span>
              <div onPointerDown={onScaleMouseDown} className={`flex items-center gap-3 bg-theme-panel/40 border px-4 py-1.5 rounded-lg cursor-ew-resize transition-all group ${isScaling ? 'border-theme-accent ring-2 ring-theme-accent/20 bg-theme-accent/5' : 'border-theme hover:border-theme-accent/50'}`}>
                <i className={`fas fa-expand-alt text-[9px] ${isScaling ? 'text-theme-accent scale-125' : 'opacity-30'} transition-all`}></i>
                <div className="w-24 h-1 bg-theme/20 rounded-full relative overflow-hidden">
                  <div className="absolute inset-y-0 left-0 bg-theme-accent transition-all duration-100" style={{ width: `${Math.min(100, (selectedElement?.scale || 1) * 20)}%` }}></div>
                </div>
                <span className="text-[10px] font-mono text-theme-accent font-black w-10 text-right">{Math.round((selectedElement?.scale || 1) * 100)}%</span>
              </div>
            </div>
            <div className={`h-8 w-[1px] transition-colors ${selectedId ? 'bg-theme-accent/30' : 'bg-theme/50'}`}></div>
            <div className="flex flex-col gap-1">
              <span className={`text-[7px] font-black uppercase tracking-[0.2em] transition-colors ${selectedId ? 'text-theme-accent' : 'opacity-40'}`}>Rotation</span>
              <div className="flex gap-1.5 bg-theme-panel/40 p-1 rounded-lg border border-theme">
                <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) - 15 })} className="w-7 h-7 flex items-center justify-center rounded hover:bg-theme-accent/20 transition-all active:scale-90"><i className="fas fa-undo text-[9px]"></i></button>
                <div className="w-10 flex items-center justify-center text-[10px] font-mono font-black opacity-60">{(selectedElement?.rotation || 0)}°</div>
                <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) + 15 })} className="w-7 h-7 flex items-center justify-center rounded hover:bg-theme-accent/20 transition-all active:scale-90"><i className="fas fa-redo text-[9px]"></i></button>
              </div>
            </div>
          </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-8 overflow-hidden relative">
          <InteractiveEditor loteImages={extraLayers} mainImage={currentMainImage ? { ...currentMainImage, ...currentTransform! } : null} frameSettings={settings} selectedId={selectedId} onSelect={setSelectedId} onUpdateImage={updateTransform} zoom={zoom} hideLimbo={isSettingsOpen} />
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme/40 py-1.5 px-6 rounded-full shadow-2xl backdrop-blur-md z-[70]">
            <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
              <i className="fas fa-search text-[10px] opacity-20"></i>
              <input type="range" min="0.05" max="2" step="0.01" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
            </div>
            <div className="flex items-center gap-4">
              <button disabled={currentIndex === 0} onClick={() => { setCurrentIndex(prev => prev - 1); setSelectedId('main'); }} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[9px]"></i></button>
              <span className="text-[10px] font-mono font-black text-theme-accent min-w-[60px] text-center">{mainBatch.length > 0 ? `${currentIndex + 1} / ${mainBatch.length}` : '0 / 0'}</span>
              <button disabled={currentIndex >= mainBatch.length - 1} onClick={() => { setCurrentIndex(prev => prev + 1); setSelectedId('main'); }} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[9px]"></i></button>
            </div>
          </div>
        </div>
      </section>

      {showCachePicker && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-8 bg-black/60 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="w-full max-w-4xl bg-theme-side border border-theme rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden h-[80vh]">
            <div className="p-8 border-b border-theme flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-2xl bg-theme-accent flex items-center justify-center text-white shadow-lg"><i className="fas fa-images"></i></div>
                <div><h3 className="text-xl font-black uppercase tracking-tighter">Molduras da Pasta Cache</h3><p className="text-[10px] opacity-40 uppercase tracking-widest">Localizadas em: /molduras</p></div>
              </div>
              <div className="flex gap-2">
                <button onClick={() => frameInputRef.current?.click()} className="px-6 py-2.5 rounded-xl border border-theme hover:bg-theme-accent/10 text-[10px] font-black uppercase tracking-widest transition-all">Outra Pasta...</button>
                <button onClick={() => setShowCachePicker(false)} className="w-10 h-10 flex items-center justify-center rounded-xl bg-theme-panel text-theme-muted hover:text-red-500 transition-all"><i className="fas fa-times"></i></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-8 grid grid-cols-4 gap-6 custom-scrollbar">
              {cacheFiles.length === 0 ? (<div className="col-span-4 flex flex-col items-center justify-center text-center opacity-20 py-20"><i className="fas fa-folder-open text-6xl mb-4"></i><p className="text-sm font-black uppercase">Pasta de molduras vazia</p></div>) : 
              (cacheFiles.map(f => (<div key={f.name} onClick={() => selectCacheFrame(f)} className="group cursor-pointer space-y-3"><div className="aspect-square rounded-2xl border-2 border-transparent group-hover:border-theme-accent bg-theme-panel overflow-hidden transition-all shadow-lg group-active:scale-95"><img src={f.url} className="w-full h-full object-cover" /></div><p className="text-[10px] font-black uppercase tracking-tight text-center truncate group-hover:text-theme-accent transition-colors">{f.name}</p></div>)))}
            </div>
          </div>
        </div>
      )}

      <FramingPresetModal 
        isOpen={showPresets} 
        onClose={() => setShowPresets(false)} 
        currentSettings={settings} 
        currentExtraLayers={extraLayers} 
        onLoadPreset={handleLoadPreset} 
      />

      <input type="file" multiple accept="image/*" className="hidden" ref={mainFileInputRef} onChange={handleMainFileChange} />
      <input type="file" multiple accept="image/*" className="hidden" ref={extraFileInputRef} onChange={handleExtraFileChange} />
      <input type="file" accept="image/png" className="hidden" ref={frameInputRef} onChange={(e) => {
        if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0]; const url = URL.createObjectURL(file);
          const img = new Image(); img.onload = () => {
            setSettings(prev => ({ ...prev, frameImageUrl: url, frameImageName: file.name, canvasWidth: img.width, canvasHeight: img.height }));
            setShowCachePicker(false);
          };
          img.src = url;
        }
      }} />
    </div>
  );
};

export default FramingTool;

import React from 'react';
import { GridImage } from '../types';

interface FramingLayerSidebarProps {
  mainBatch: GridImage[];
  extraLayers: GridImage[];
  currentIndex: number;
  selectedId: string | null;
  onSelectMain: (index: number) => void;
  onSelectExtra: (id: string) => void;
  onRemoveExtra: (id: string) => void;
  isOpen: boolean;
  onToggle: () => void;
}

const FramingLayerSidebar: React.FC<FramingLayerSidebarProps> = ({ 
  mainBatch, extraLayers, currentIndex, selectedId, onSelectMain, onSelectExtra, onRemoveExtra, isOpen, onToggle 
}) => {
  return (
    <div className="relative flex h-full">
      <button 
        onClick={onToggle}
        className="absolute top-1/2 -translate-y-1/2 -left-6 z-50 w-6 h-20 bg-theme-panel border border-theme flex items-center justify-center rounded-l-xl hover:bg-theme-accent transition-all group shadow-[-5px_0_15px_rgba(0,0,0,0.1)]"
      >
        <i className={`fas ${isOpen ? 'fa-chevron-right' : 'fa-layer-group'} text-[10px] transition-transform duration-500 ${isOpen ? 'rotate-0' : 'rotate-12 group-hover:rotate-0'}`}></i>
      </button>

      <aside className={`border-l border-theme bg-theme-side transition-all duration-500 overflow-hidden flex flex-col relative ${isOpen ? 'w-64' : 'w-0'}`}>
        <div className="min-w-[256px] h-full flex flex-col">
          <div className="p-4 border-b border-theme/30 bg-black/10 flex items-center justify-between">
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-theme-accent">Gerenciador de Camadas</span>
            <span className="text-[9px] opacity-30 font-mono">{mainBatch.length + extraLayers.length} total</span>
          </div>

          <div className="flex-1 overflow-y-auto custom-scrollbar flex flex-col">
            {/* SEÇÃO LOTE PRINCIPAL */}
            <div className="p-4 space-y-3">
              <div className="flex items-center justify-between opacity-40 px-1">
                <span className="text-[8px] font-black uppercase tracking-widest">Lote Principal</span>
                <i className="fas fa-images text-[9px]"></i>
              </div>
              <div className="space-y-2">
                {mainBatch.length === 0 ? (
                  <p className="text-[9px] opacity-20 text-center py-4 uppercase">Vazio</p>
                ) : (
                  mainBatch.map((img, idx) => (
                    <button 
                      key={img.id}
                      onClick={() => onSelectMain(idx)}
                      className={`w-full group flex items-center gap-3 p-1.5 rounded-xl border transition-all ${currentIndex === idx && selectedId === 'main' ? 'border-theme-accent bg-theme-accent/5' : 'border-transparent bg-theme-panel/30 hover:bg-theme-panel/50'}`}
                    >
                      <div className="w-10 h-10 rounded-lg bg-black/20 overflow-hidden border border-theme/30 flex-shrink-0">
                        <img src={img.previewUrl} className="w-full h-full object-cover" />
                      </div>
                      <div className="flex-1 min-w-0 text-left">
                        <p className={`text-[9px] font-black truncate uppercase ${currentIndex === idx && selectedId === 'main' ? 'text-theme-accent' : 'opacity-60'}`}>Item #{idx + 1}</p>
                        <p className="text-[7px] opacity-30 truncate font-mono">{img.file.name}</p>
                      </div>
                      {currentIndex === idx && selectedId === 'main' && (
                        <div className="w-1.5 h-1.5 rounded-full bg-theme-accent mr-2 shadow-[0_0_8px_rgba(79,70,229,1)]"></div>
                      )}
                    </button>
                  ))
                )}
              </div>
            </div>

            {/* SEÇÃO EXTRAS */}
            <div className="p-4 space-y-3 border-t border-theme/10 bg-black/5 flex-1">
              <div className="flex items-center justify-between opacity-40 px-1">
                <span className="text-[8px] font-black uppercase tracking-widest text-theme-accent">Elementos Extras</span>
                <i className="fas fa-plus-circle text-[9px]"></i>
              </div>
              <div className="space-y-2">
                {extraLayers.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-10 opacity-10">
                    <i className="fas fa-layer-group text-2xl mb-2"></i>
                    <p className="text-[8px] font-black uppercase">Sem extras</p>
                  </div>
                ) : (
                  extraLayers.map((layer) => (
                    <div 
                      key={layer.id}
                      className={`group flex items-center gap-3 p-1.5 rounded-xl border transition-all cursor-pointer ${selectedId === layer.id ? 'border-theme-accent bg-theme-accent/5 shadow-inner' : 'border-transparent bg-theme-panel/30 hover:border-theme'}`}
                      onClick={() => onSelectExtra(layer.id)}
                    >
                      <div className="w-10 h-10 rounded-lg bg-black/20 overflow-hidden border border-theme/30 flex-shrink-0">
                        <img src={layer.previewUrl} className="w-full h-full object-cover" />
                      </div>
                      <div className="flex-1 min-w-0 text-left">
                        <p className={`text-[9px] font-black truncate uppercase ${selectedId === layer.id ? 'text-theme-accent' : 'opacity-60'}`}>Extra</p>
                        <p className="text-[7px] opacity-30 truncate font-mono">Layer #{layer.id.slice(0,4)}</p>
                      </div>
                      <button 
                        onClick={(e) => { e.stopPropagation(); onRemoveExtra(layer.id); }}
                        className="opacity-0 group-hover:opacity-100 p-2 text-theme-muted hover:text-red-500 transition-all"
                      >
                        <i className="fas fa-times text-[10px]"></i>
                      </button>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        </div>
      </aside>
    </div>
  );
};

export default FramingLayerSidebar;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GridImage, FrameSettings } from '../types';

interface InteractiveEditorProps {
  mainImage: (GridImage & { x: number, y: number, scale: number, rotation: number }) | null;
  loteImages: GridImage[];
  frameSettings: FrameSettings;
  onUpdateImage: (id: string, updates: Partial<GridImage>) => void;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  zoom?: number;
  hideLimbo?: boolean;
}

const InteractiveEditor: React.FC<InteractiveEditorProps> = ({ 
  mainImage,
  loteImages, 
  frameSettings, 
  onUpdateImage,
  selectedId,
  onSelect,
  zoom = 0.4,
  hideLimbo = false
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragInfo = useRef({
    startX: 0,
    startY: 0,
    initialPosX: 0,
    initialPosY: 0,
    id: '',
    animationFrameId: 0
  });

  const handleMouseDown = (e: React.MouseEvent, id: string, x: number, y: number) => {
    e.stopPropagation();
    onSelect(id);
    setIsDragging(true);

    dragInfo.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialPosX: x,
      initialPosY: y,
      id: id,
      animationFrameId: 0
    };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging || !selectedId) return;

    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }

    dragInfo.current.animationFrameId = requestAnimationFrame(() => {
      const dx = e.clientX - dragInfo.current.startX;
      const dy = e.clientY - dragInfo.current.startY;

      onUpdateImage(dragInfo.current.id, {
        x: dragInfo.current.initialPosX + (dx / zoom),
        y: dragInfo.current.initialPosY + (dy / zoom)
      });
    });
  }, [isDragging, selectedId, zoom, onUpdateImage]);

  const handleMouseUp = useCallback(() => {
    if (dragInfo.current.animationFrameId) {
      cancelAnimationFrame(dragInfo.current.animationFrameId);
    }
    setIsDragging(false);
  }, []);

  const handleWheel = useCallback((e: WheelEvent) => {
    if (!selectedId) return;
    e.preventDefault();

    const element = selectedId === 'main' 
      ? mainImage 
      : loteImages.find(img => img.id === selectedId);

    if (element) {
      const delta = e.deltaY > 0 ? -0.02 : 0.02;
      const currentScale = (element as any).scale || 1;
      const newScale = Math.max(0.01, Math.min(10, currentScale + delta));
      onUpdateImage(selectedId, { scale: newScale });
    }
  }, [selectedId, mainImage, loteImages, onUpdateImage]);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove, { passive: true });
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  useEffect(() => {
    const container = containerRef.current;
    if (container) {
      container.addEventListener('wheel', handleWheel, { passive: false });
    }
    return () => {
      if (container) container.removeEventListener('wheel', handleWheel);
    };
  }, [handleWheel]);

  const SelectionOverlay = ({ isActive }: { isActive: boolean }) => (
    isActive ? (
      <div className="absolute inset-[-2px] border-2 border-dashed border-theme-accent rounded-none shadow-[0_0_15px_rgba(79,70,229,0.3)] z-[100] pointer-events-none">
      </div>
    ) : null
  );

  return (
    <div 
      ref={containerRef}
      className="relative shadow-2xl border border-white/10 bg-theme-panel transition-[width,height] duration-300 ease-out"
      style={{ 
        width: frameSettings.canvasWidth * zoom, 
        height: frameSettings.canvasHeight * zoom,
        minWidth: frameSettings.canvasWidth * zoom,
        minHeight: frameSettings.canvasHeight * zoom,
        backgroundImage: 'linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)',
        backgroundSize: '20px 20px',
      }}
      onMouseDown={() => onSelect(null)}
    >
      {/* CAMADA DE LIMBO: Z-[110] para estar acima de tudo no editor */}
      {!hideLimbo && (
        <div className="absolute inset-[-5000px] pointer-events-none z-[110] bg-black/85" style={{ clipPath: 'polygon(0% 0%, 0% 100%, 100% 100%, 100% 0%, 0% 0%, 5000px 5000px, calc(100% - 5000px) 5000px, calc(100% - 5000px) calc(100% - 5000px), 5000px calc(100% - 5000px), 5000px 5000px)' }}></div>
      )}

      {/* Guia Visual: Z-[120] */}
      <div className="absolute inset-0 border border-theme-accent/40 border-dashed pointer-events-none z-[120]"></div>

      {/* IMAGEM PRINCIPAL: Z-index baixo [10]. Mesmo selecionada [15], fica abaixo da moldura [20] */}
      {mainImage && mainImage.visible !== false && (
        <div
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === 'main' ? 'z-[15] opacity-100' : 'z-[10] opacity-70'}`}
          style={{
            left: mainImage.x * zoom,
            top: mainImage.y * zoom,
            width: (mainImage.width * mainImage.scale) * zoom,
            transform: `rotate(${mainImage.rotation}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, 'main', mainImage.x, mainImage.y)}
        >
          <img src={mainImage.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === 'main'} />
        </div>
      )}

      {/* MOLDURA (FRAME): Z-[20]. Fica acima da imagem principal mas abaixo dos extras */}
      <div 
        className="absolute inset-0 pointer-events-none z-[20] transition-all duration-300"
        style={{
          border: frameSettings.frameImageUrl ? 'none' : `${frameSettings.borderWidth * zoom}px solid ${frameSettings.borderColor}`,
          borderRadius: `${frameSettings.borderRadius * zoom}px`,
          boxShadow: `inset 0 0 ${frameSettings.shadow * zoom}px rgba(0,0,0,0.2)`
        }}
      >
        {frameSettings.frameImageUrl && (
          <img src={frameSettings.frameImageUrl} className="w-full h-full object-fill" />
        )}
      </div>

      {/* EXTRAS: Z-index alto [30]. Se selecionado [40]. Sempre acima da moldura [20] */}
      {loteImages.map((img) => img.visible !== false && (
        <div
          key={img.id}
          className={`absolute cursor-move transition-opacity duration-300 ${selectedId === img.id ? 'z-[40] opacity-100' : 'z-[30] opacity-70'}`}
          style={{
            left: (img.x || 0) * zoom,
            top: (img.y || 0) * zoom,
            width: (img.width * (img.scale || 1)) * zoom,
            transform: `rotate(${img.rotation || 0}deg)`,
            pointerEvents: 'auto',
            willChange: 'transform, left, top'
          }}
          onMouseDown={(e) => handleMouseDown(e, img.id, img.x || 0, img.y || 0)}
        >
          <img src={img.previewUrl} className="w-full h-auto pointer-events-none select-none" />
          <SelectionOverlay isActive={selectedId === img.id} />
        </div>
      ))}
    </div>
  );
};

export default InteractiveEditor;

import React, { useState, useRef, useMemo, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarFraming from '../components/SidebarFraming';
import InteractiveEditor from '../components/InteractiveEditor';
import FramingPresetModal from '../components/FramingPresetModal';
import FramingLayerSidebar from '../components/FramingLayerSidebar';
import Header from '../components/Header';
import { GridImage, FrameSettings, FramingPreset } from '../types';

interface BatchItemState { x: number; y: number; scale: number; rotation: number; exportPrefix?: string; exportFilename?: string; }

interface FramingToolProps {
  cacheDirHandle?: any;
  isSettingsOpen?: boolean;
}

const FramingTool: React.FC<FramingToolProps> = ({ cacheDirHandle, isSettingsOpen = false }) => {
  const [mainBatch, setMainBatch] = useState<GridImage[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [batchStates, setBatchStates] = useState<Record<string, BatchItemState>>({});
  const [autoSave, setAutoSave] = useState(true);
  const [extraLayers, setExtraLayers] = useState<GridImage[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [zoom, setZoom] = useState(0.4); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [settings, setSettings] = useState<FrameSettings>({ borderWidth: 20, borderColor: '#ffffff', borderRadius: 0, padding: 0, shadow: 10, canvasWidth: 1080, canvasHeight: 1080 });

  const [showPresets, setShowPresets] = useState(false);
  const [isLayerSidebarOpen, setIsLayerSidebarOpen] = useState(false);
  const [showCachePicker, setShowCachePicker] = useState(false);
  const [cacheFiles, setCacheFiles] = useState<{name: string, handle: any, url: string}[]>([]);

  const [isScaling, setIsScaling] = useState(false);
  const scaleDragRef = useRef({ lastX: 0, currentScale: 1 });

  const mainFileInputRef = useRef<HTMLInputElement>(null);
  const extraFileInputRef = useRef<HTMLInputElement>(null);
  const frameInputRef = useRef<HTMLInputElement>(null);

  const currentMainImage = mainBatch[currentIndex];

  const currentTransform = useMemo(() => {
    if (!currentMainImage) return null;
    return batchStates[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 };
  }, [currentMainImage, batchStates, settings.canvasWidth, settings.canvasHeight]);

  useEffect(() => {
    if (currentMainImage && batchStates[currentMainImage.id]) {
      const state = batchStates[currentMainImage.id];
      setSettings(prev => ({ 
        ...prev, 
        exportPrefix: state.exportPrefix || '', 
        exportFilename: state.exportFilename || '' 
      }));
    }
  }, [currentIndex, currentMainImage]);

  const updateSettings = (newSettings: FrameSettings) => {
    setSettings(newSettings);
    if (currentMainImage) {
      setBatchStates(prev => ({
        ...prev,
        [currentMainImage.id]: {
          ...(prev[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 }),
          exportPrefix: newSettings.exportPrefix,
          exportFilename: newSettings.exportFilename
        }
      }));
    }
  };

  const applyPrefixToAll = () => {
    const prefix = settings.exportPrefix || '';
    setBatchStates(prev => {
      const newState = { ...prev };
      mainBatch.forEach(img => {
        newState[img.id] = { 
          ...(newState[img.id] || { x: (settings.canvasWidth / 2) - (img.width * 0.1), y: (settings.canvasHeight / 2) - (img.height * 0.1), scale: 0.2, rotation: 0 }), 
          exportPrefix: prefix 
        };
      });
      return newState;
    });
  };

  const selectedElement = useMemo(() => {
    if (selectedId === 'main') return { ...currentMainImage, ...currentTransform };
    return extraLayers.find(img => img.id === selectedId);
  }, [selectedId, currentMainImage, currentTransform, extraLayers]);

  const updateTransform = useCallback((id: string, updates: Partial<BatchItemState | GridImage>) => {
    if (id === 'main' && currentMainImage) {
      setBatchStates(prev => ({ 
        ...prev, 
        [currentMainImage.id]: { 
          ...(prev[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 }), 
          ...updates as any 
        } 
      }));
    } else {
      setExtraLayers(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
    }
  }, [currentMainImage, settings]);

  const onScaleMouseDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!selectedId || !selectedElement) return;
    const target = e.currentTarget;
    target.setPointerCapture(e.pointerId);
    setIsScaling(true);
    scaleDragRef.current = { lastX: e.clientX, currentScale: selectedElement.scale || 1 };
    document.body.style.userSelect = 'none';
  };

  useEffect(() => {
    if (!isScaling) return;
    const handleMouseMove = (e: MouseEvent) => {
      const deltaX = e.clientX - scaleDragRef.current.lastX;
      scaleDragRef.current.lastX = e.clientX;
      const sensitivity = 0.0035; 
      const newScale = Math.max(0.01, Math.min(10, scaleDragRef.current.currentScale + (deltaX * sensitivity)));
      scaleDragRef.current.currentScale = newScale;
      updateTransform(selectedId!, { scale: newScale });
    };
    const handleMouseUp = () => {
      setIsScaling(false);
      document.body.style.userSelect = '';
    };
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isScaling, selectedId, updateTransform]);

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image(); img.crossOrigin = "anonymous";
      img.onload = () => resolve(img); img.onerror = () => reject(new Error("Erro"));
      img.src = url;
    });
  };

  const handleLoadPreset = async (preset: FramingPreset) => {
    try {
      setIsProcessing(true);
      const dataUrlToBlob = (dataUrl: string) => fetch(dataUrl).then(r => r.blob());
      const restoredExtraLayers = await Promise.all(preset.extraLayers.map(async l => {
        const blob = await dataUrlToBlob(l.dataUrl);
        const file = new File([blob], l.name, { type: blob.type });
        const url = URL.createObjectURL(file);
        return { id: uuidv4(), file, previewUrl: url, width: l.width, height: l.height, aspectRatio: l.aspectRatio, x: l.x, y: l.y, scale: l.scale, rotation: l.rotation, visible: true };
      }));
      let restoredFrameUrl = undefined;
      let restoredFrameName = preset.settings.frameImageName;
      if (preset.frameImageDataUrl) {
        const blob = await dataUrlToBlob(preset.frameImageDataUrl);
        const file = new File([blob], restoredFrameName || 'frame.png', { type: blob.type });
        restoredFrameUrl = URL.createObjectURL(file);
      }
      setSettings({ ...preset.settings, frameImageUrl: restoredFrameUrl, frameImageName: restoredFrameName });
      setExtraLayers(restoredExtraLayers);
      setShowPresets(false);
    } catch (err) {
      console.error('Erro ao carregar preset:', err);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAddFrameClick = async () => {
    if (!cacheDirHandle) {
      frameInputRef.current?.click();
      return;
    }
    try {
      const moldurasDir = await cacheDirHandle.getDirectoryHandle('molduras', { create: true });
      const files: any[] = [];
      for await (const entry of moldurasDir.values()) {
        if (entry.kind === 'file' && (entry.name.endsWith('.png') || entry.name.endsWith('.jpg') || entry.name.endsWith('.webp'))) {
          const file = await entry.getFile();
          files.push({ name: entry.name, handle: entry, url: URL.createObjectURL(file) });
        }
      }
      setCacheFiles(files);
      setShowCachePicker(true);
    } catch (err) {
      console.error('Erro ao ler pasta de molduras:', err);
      frameInputRef.current?.click();
    }
  };

  const selectCacheFrame = async (fileData: any) => {
    const file = await fileData.handle.getFile();
    const url = fileData.url;
    const img = new Image();
    img.onload = () => {
      setSettings(prev => ({ ...prev, frameImageUrl: url, frameImageName: file.name, canvasWidth: img.width, canvasHeight: img.height }));
      setShowCachePicker(false);
    };
    img.src = url;
  };

  const handleProcessAll = async () => {
    if (mainBatch.length === 0) return;
    setIsProcessing(true); setProcessProgress(0);
    const canvas = document.createElement('canvas');
    canvas.width = settings.canvasWidth; canvas.height = settings.canvasHeight;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;
    const zip = downloadZip ? new JSZip() : null;
    try {
      const extraImgs = await Promise.all(extraLayers.map(l => loadImage(l.previewUrl)));
      let frameImg: HTMLImageElement | null = null;
      if (settings.frameImageUrl) frameImg = await loadImage(settings.frameImageUrl);
      for (let i = 0; i < mainBatch.length; i++) {
        setProcessProgress(i + 1);
        const item = mainBatch[i]; 
        const state = batchStates[item.id] || { x: (settings.canvasWidth / 2) - (item.width * 0.1), y: (settings.canvasHeight / 2) - (item.height * 0.1), scale: 0.2, rotation: 0 };
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const mainImgObj = await loadImage(item.previewUrl);

        // 1. Draw Main Image (Bottom)
        ctx.save();
        const drawW = item.width * state.scale, drawH = item.height * state.scale;
        ctx.translate(state.x + drawW / 2, state.y + drawH / 2); ctx.rotate((state.rotation * Math.PI) / 180);
        ctx.drawImage(mainImgObj, -drawW / 2, -drawH / 2, drawW, drawH); ctx.restore();

        // 2. Draw Frame (Middle)
        if (frameImg) ctx.drawImage(frameImg, 0, 0, canvas.width, canvas.height);
        else {
          ctx.strokeStyle = settings.borderColor; ctx.lineWidth = settings.borderWidth;
          ctx.strokeRect(settings.borderWidth / 2, settings.borderWidth / 2, canvas.width - settings.borderWidth, canvas.height - settings.borderWidth);
        }

        // 3. Draw Extra Elements (Top)
        extraLayers.forEach((layer, idx) => {
          if (layer.visible === false) return;
          ctx.save(); const lW = layer.width * (layer.scale || 1), lH = layer.height * (layer.scale || 1);
          ctx.translate((layer.x || 0) + lW / 2, (layer.y || 0) + lH / 2); ctx.rotate(((layer.rotation || 0) * Math.PI) / 180);
          ctx.drawImage(extraImgs[idx], -lW / 2, -lH / 2, lW, lH); ctx.restore();
        });

        const dataUrl = canvas.toDataURL('image/png', 1.0);
        const prefix = state.exportPrefix || '';
        const baseName = state.exportFilename?.trim() || item.file.name.replace(/\.[^/.]+$/, "");
        const fileName = `${prefix}${baseName}.png`;
        if (downloadIndividual) {
          const link = document.createElement('a'); link.download = fileName; link.href = dataUrl;
          document.body.appendChild(link); link.click(); document.body.removeChild(link);
          await new Promise(r => setTimeout(r, 400));
        }
        if (zip) zip.file(fileName, dataUrl.split(',')[1], { base64: true });
      }
      if (zip) {
        const zipBlob = await zip.generateAsync({ type: "blob" });
        const link = document.createElement('a'); link.href = URL.createObjectURL(zipBlob);
        link.download = `miau_tools_batch_${Date.now()}.zip`; link.click();
      }
    } finally { setIsProcessing(false); setProcessProgress(0); }
  };

  const handleMainFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const newItems = await Promise.all(files.map(async file => {
        const url = URL.createObjectURL(file);
        const img = await loadImage(url);
        return { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height, isActive: true };
      }));
      setMainBatch(prev => [...prev, ...newItems]);
    }
  };

  const handleExtraFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const newLayers = await Promise.all(files.map(async file => {
        const url = URL.createObjectURL(file);
        const img = await loadImage(url);
        return { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height, x: 0, y: 0, scale: 0.2, rotation: 0, visible: true };
      }));
      setExtraLayers(prev => [...prev, ...newLayers]);
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarFraming 
          settings={settings} onSettingsChange={updateSettings} 
          onAddLote={() => mainFileInputRef.current?.click()} 
          onAddExtras={() => extraFileInputRef.current?.click()} 
          onAddFrame={handleAddFrameClick} 
          onOpenPresets={() => setShowPresets(true)}
          autoSave={autoSave} onAutoSaveChange={setAutoSave} onProcessAll={handleProcessAll} 
          isProcessing={isProcessing} progress={processProgress} total={mainBatch.length} 
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onApplyPrefixToAll={applyPrefixToAll}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden bg-theme-main relative">
        <Header itemCount={mainBatch.length + extraLayers.length} onClear={() => {setMainBatch([]); setExtraLayers([]); setBatchStates({});}} />
        <div className={`h-14 border-b flex items-center px-6 gap-8 backdrop-blur-xl transition-all duration-300 ${isSettingsOpen ? 'z-0 opacity-20 pointer-events-none' : 'z-[60] opacity-100'} ${selectedId ? 'bg-theme-accent/15 border-theme-accent/40' : 'bg-theme-side/50 border-theme'}`}>
