import React, { useState, useRef, useMemo, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import SidebarFraming from '../components/SidebarFraming';
import InteractiveEditor from '../components/InteractiveEditor';
import FramingPresetModal from '../components/FramingPresetModal';
import FramingLayerSidebar from '../components/FramingLayerSidebar';
import Header from '../components/Header';
import { GridImage, FrameSettings, FramingPreset } from '../types';

interface BatchItemState { x: number; y: number; scale: number; rotation: number; exportPrefix?: string; exportFilename?: string; }

interface FramingToolProps {
  cacheDirHandle?: any;
  isSettingsOpen?: boolean;
}

const FramingTool: React.FC<FramingToolProps> = ({ cacheDirHandle, isSettingsOpen = false }) => {
  const [mainBatch, setMainBatch] = useState<GridImage[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [batchStates, setBatchStates] = useState<Record<string, BatchItemState>>({});
  const [autoSave, setAutoSave] = useState(true);
  const [extraLayers, setExtraLayers] = useState<GridImage[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [zoom, setZoom] = useState(0.4); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processProgress, setProcessProgress] = useState(0);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [settings, setSettings] = useState<FrameSettings>({ borderWidth: 20, borderColor: '#ffffff', borderRadius: 0, padding: 0, shadow: 10, canvasWidth: 1080, canvasHeight: 1080 });

  const [showPresets, setShowPresets] = useState(false);
  const [isLayerSidebarOpen, setIsLayerSidebarOpen] = useState(false);
  const [showCachePicker, setShowCachePicker] = useState(false);
  const [cacheFiles, setCacheFiles] = useState<{name: string, handle: any, url: string}[]>([]);

  const [isScaling, setIsScaling] = useState(false);
  const scaleDragRef = useRef({ lastX: 0, currentScale: 1 });

  const mainFileInputRef = useRef<HTMLInputElement>(null);
  const extraFileInputRef = useRef<HTMLInputElement>(null);
  const frameInputRef = useRef<HTMLInputElement>(null);

  const currentMainImage = mainBatch[currentIndex];

  const currentTransform = useMemo(() => {
    if (!currentMainImage) return null;
    return batchStates[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 };
  }, [currentMainImage, batchStates, settings.canvasWidth, settings.canvasHeight]);

  useEffect(() => {
    if (currentMainImage && batchStates[currentMainImage.id]) {
      const state = batchStates[currentMainImage.id];
      setSettings(prev => ({ 
        ...prev, 
        exportPrefix: state.exportPrefix || '', 
        exportFilename: state.exportFilename || '' 
      }));
    }
  }, [currentIndex, currentMainImage]);

  const updateSettings = (newSettings: FrameSettings) => {
    setSettings(newSettings);
    if (currentMainImage) {
      setBatchStates(prev => ({
        ...prev,
        [currentMainImage.id]: {
          ...(prev[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 }),
          exportPrefix: newSettings.exportPrefix,
          exportFilename: newSettings.exportFilename
        }
      }));
    }
  };

  const applyScaleToAllBatch = () => {
    if (!currentTransform) return;
    const currentScale = currentTransform.scale;
    setBatchStates(prev => {
      const newState = { ...prev };
      mainBatch.forEach(img => {
        newState[img.id] = { 
          ...(newState[img.id] || { x: (settings.canvasWidth / 2) - (img.width * 0.1), y: (settings.canvasHeight / 2) - (img.height * 0.1), scale: currentScale, rotation: 0 }), 
          scale: currentScale 
        };
      });
      return newState;
    });
  };

  const applyPrefixToAll = () => {
    const prefix = settings.exportPrefix || '';
    setBatchStates(prev => {
      const newState = { ...prev };
      mainBatch.forEach(img => {
        newState[img.id] = { 
          ...(newState[img.id] || { x: (settings.canvasWidth / 2) - (img.width * 0.1), y: (settings.canvasHeight / 2) - (img.height * 0.1), scale: 0.2, rotation: 0 }), 
          exportPrefix: prefix 
        };
      });
      return newState;
    });
  };

  const selectedElement = useMemo(() => {
    if (selectedId === 'main') return { ...currentMainImage, ...currentTransform };
    return extraLayers.find(img => img.id === selectedId);
  }, [selectedId, currentMainImage, currentTransform, extraLayers]);

  const updateTransform = useCallback((id: string, updates: Partial<BatchItemState | GridImage>) => {
    if (id === 'main' && currentMainImage) {
      setBatchStates(prev => ({ 
        ...prev, 
        [currentMainImage.id]: { 
          ...(prev[currentMainImage.id] || { x: (settings.canvasWidth / 2) - (currentMainImage.width * 0.1), y: (settings.canvasHeight / 2) - (currentMainImage.height * 0.1), scale: 0.2, rotation: 0 }), 
          ...updates as any 
        } 
      }));
    } else {
      setExtraLayers(prev => prev.map(img => img.id === id ? { ...img, ...updates } : img));
    }
  }, [currentMainImage, settings]);

  const onScaleMouseDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!selectedId || !selectedElement) return;
    const target = e.currentTarget;
    target.setPointerCapture(e.pointerId);
    setIsScaling(true);
    scaleDragRef.current = { lastX: e.clientX, currentScale: selectedElement.scale || 1 };
    document.body.style.userSelect = 'none';
  };

  useEffect(() => {
    if (!isScaling) return;
    const handleMouseMove = (e: MouseEvent) => {
      const deltaX = e.clientX - scaleDragRef.current.lastX;
      scaleDragRef.current.lastX = e.clientX;
      const sensitivity = 0.0035; 
      const newScale = Math.max(0.01, Math.min(10, scaleDragRef.current.currentScale + (deltaX * sensitivity)));
      scaleDragRef.current.currentScale = newScale;
      updateTransform(selectedId!, { scale: newScale });
    };
    const handleMouseUp = () => {
      setIsScaling(false);
      document.body.style.userSelect = '';
    };
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isScaling, selectedId, updateTransform]);

  const loadImage = (url: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image(); img.crossOrigin = "anonymous";
      img.onload = () => resolve(img); img.onerror = () => reject(new Error("Erro"));
      img.src = url;
    });
  };

  const handleLoadPreset = async (preset: FramingPreset) => {
    try {
      setIsProcessing(true);
      const dataUrlToBlob = (dataUrl: string) => fetch(dataUrl).then(r => r.blob());
      const restoredExtraLayers = await Promise.all(preset.extraLayers.map(async l => {
        const blob = await dataUrlToBlob(l.dataUrl);
        const file = new File([blob], l.name, { type: blob.type });
        const url = URL.createObjectURL(file);
        return { 
          id: uuidv4(), file, previewUrl: url, width: l.width, height: l.height, 
          aspectRatio: l.aspectRatio, x: l.x, y: l.y, scale: l.scale, rotation: l.rotation, 
          visible: l.visible !== false, // Respeita o estado salvo no preset
          aboveFrame: l.aboveFrame !== false // Respeita o posicionamento salvo no preset
        };
      }));
      let restoredFrameUrl = undefined;
      let restoredFrameName = preset.settings.frameImageName;
      if (preset.frameImageDataUrl) {
        const blob = await dataUrlToBlob(preset.frameImageDataUrl);
        const file = new File([blob], restoredFrameName || 'frame.png', { type: blob.type });
        restoredFrameUrl = URL.createObjectURL(file);
      }
      setSettings({ ...preset.settings, frameImageUrl: restoredFrameUrl, frameImageName: restoredFrameName });
      setExtraLayers(restoredExtraLayers);
      setShowPresets(false);
    } catch (err) {
      console.error('Erro ao carregar preset:', err);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAddFrameClick = async () => {
    if (!cacheDirHandle) {
      frameInputRef.current?.click();
      return;
    }
    try {
      const moldurasDir = await cacheDirHandle.getDirectoryHandle('molduras', { create: true });
      const files: any[] = [];
      for await (const entry of moldurasDir.values()) {
        if (entry.kind === 'file' && (entry.name.endsWith('.png') || entry.name.endsWith('.jpg') || entry.name.endsWith('.webp'))) {
          const file = await entry.getFile();
          files.push({ name: entry.name, handle: entry, url: URL.createObjectURL(file) });
        }
      }
      setCacheFiles(files);
      setShowCachePicker(true);
    } catch (err) {
      console.error('Erro ao ler pasta de molduras:', err);
      frameInputRef.current?.click();
    }
  };

  const selectCacheFrame = async (fileData: any) => {
    const file = await fileData.handle.getFile();
    const url = fileData.url;
    const img = new Image();
    img.onload = () => {
      setSettings(prev => ({ ...prev, frameImageUrl: url, frameImageName: file.name, canvasWidth: img.width, canvasHeight: img.height }));
      setShowCachePicker(false);
    };
    img.src = url;
  };

  const handleProcessAll = async () => {
    if (mainBatch.length === 0) return;
    setIsProcessing(true); setProcessProgress(0);
    const canvas = document.createElement('canvas');
    canvas.width = settings.canvasWidth; canvas.height = settings.canvasHeight;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;
    const zip = downloadZip ? new JSZip() : null;
    try {
      const extraImgs = await Promise.all(extraLayers.map(l => loadImage(l.previewUrl)));
      let frameImg: HTMLImageElement | null = null;
      if (settings.frameImageUrl) frameImg = await loadImage(settings.frameImageUrl);

      for (let i = 0; i < mainBatch.length; i++) {
        setProcessProgress(i + 1);
        const item = mainBatch[i]; 
        const state = batchStates[item.id] || { x: (settings.canvasWidth / 2) - (item.width * 0.1), y: (settings.canvasHeight / 2) - (item.height * 0.1), scale: 0.2, rotation: 0 };
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const mainImgObj = await loadImage(item.previewUrl);

        // --- ORDEM DE DESENHO (STACKING) ---

        // 1. Imagem Principal
        ctx.save();
        const drawW = item.width * state.scale, drawH = item.height * state.scale;
        ctx.translate(state.x + drawW / 2, state.y + drawH / 2); ctx.rotate((state.rotation * Math.PI) / 180);
        ctx.drawImage(mainImgObj, -drawW / 2, -drawH / 2, drawW, drawH); ctx.restore();

        // 2. Extras (Abaixo da Moldura)
        extraLayers.forEach((layer, idx) => {
          if (layer.visible === false || layer.aboveFrame !== false) return;
          ctx.save(); const lW = layer.width * (layer.scale || 1), lH = layer.height * (layer.scale || 1);
          ctx.translate((layer.x || 0) + lW / 2, (layer.y || 0) + lH / 2); ctx.rotate(((layer.rotation || 0) * Math.PI) / 180);
          ctx.drawImage(extraImgs[idx], -lW / 2, -lH / 2, lW, lH); ctx.restore();
        });

        // 3. Moldura
        if (frameImg) ctx.drawImage(frameImg, 0, 0, canvas.width, canvas.height);
        else {
          ctx.strokeStyle = settings.borderColor; ctx.lineWidth = settings.borderWidth;
          ctx.strokeRect(settings.borderWidth / 2, settings.borderWidth / 2, canvas.width - settings.borderWidth, canvas.height - settings.borderWidth);
        }

        // 4. Extras (Acima da Moldura)
        extraLayers.forEach((layer, idx) => {
          if (layer.visible === false || layer.aboveFrame === false) return;
          ctx.save(); const lW = layer.width * (layer.scale || 1), lH = layer.height * (layer.scale || 1);
          ctx.translate((layer.x || 0) + lW / 2, (layer.y || 0) + lH / 2); ctx.rotate(((layer.rotation || 0) * Math.PI) / 180);
          ctx.drawImage(extraImgs[idx], -lW / 2, -lH / 2, lW, lH); ctx.restore();
        });

        const dataUrl = canvas.toDataURL('image/png', 1.0);
        const prefix = state.exportPrefix || '';
        const baseName = state.exportFilename?.trim() || item.file.name.replace(/\.[^/.]+$/, "");
        const fileName = `${prefix}${baseName}.png`;
        if (downloadIndividual) {
          const link = document.createElement('a'); link.download = fileName; link.href = dataUrl;
          document.body.appendChild(link); link.click(); document.body.removeChild(link);
          await new Promise(r => setTimeout(r, 400));
        }
        if (zip) zip.file(fileName, dataUrl.split(',')[1], { base64: true });
      }
      if (zip) {
        const zipBlob = await zip.generateAsync({ type: "blob" });
        const link = document.createElement('a'); link.href = URL.createObjectURL(zipBlob);
        link.download = `miau_tools_batch_${Date.now()}.zip`; link.click();
      }
    } finally { setIsProcessing(false); setProcessProgress(0); }
  };

  const handleMainFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const newItems = await Promise.all(files.map(async file => {
        const url = URL.createObjectURL(file);
        const img = await loadImage(url);
        return { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height, isActive: true };
      }));
      setMainBatch(prev => [...prev, ...newItems]);
    }
  };

  const handleExtraFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const newLayers = await Promise.all(files.map(async file => {
        const url = URL.createObjectURL(file);
        const img = await loadImage(url);
        return { id: uuidv4(), file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width / img.height, x: 0, y: 0, scale: 0.2, rotation: 0, visible: true, aboveFrame: true };
      }));
      setExtraLayers(prev => [...prev, ...newLayers]);
    }
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarFraming 
          settings={settings} onSettingsChange={updateSettings} 
          onAddLote={() => mainFileInputRef.current?.click()} 
          onAddExtras={() => extraFileInputRef.current?.click()} 
          onAddFrame={handleAddFrameClick} 
          onOpenPresets={() => setShowPresets(true)}
          autoSave={autoSave} onAutoSaveChange={setAutoSave} onProcessAll={handleProcessAll} 
          isProcessing={isProcessing} progress={processProgress} total={mainBatch.length} 
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onApplyPrefixToAll={applyPrefixToAll}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden bg-theme-main relative">
        <Header itemCount={mainBatch.length + extraLayers.length} onClear={() => {setMainBatch([]); setExtraLayers([]); setBatchStates({});}} />
        <div className={`h-14 border-b flex items-center px-6 gap-8 backdrop-blur-xl transition-all duration-300 ${isSettingsOpen || showPresets ? 'z-0 opacity-20 pointer-events-none' : 'z-[60] opacity-100'} ${selectedId ? 'bg-theme-accent/15 border-theme-accent/40' : 'bg-theme-side/50 border-theme'}`}>
          <div className={`flex items-center gap-8 transition-all duration-500 ${!selectedElement ? 'opacity-5 grayscale pointer-events-none translate-y-2' : 'opacity-100 translate-y-0'}`}>
            <div className="flex flex-col gap-1">
              <span className={`text-[7px] font-black uppercase tracking-[0.2em] transition-colors ${selectedId ? 'text-theme-accent' : 'opacity-40'}`}>Scale Precision</span>
              <div className="flex items-center gap-2">
                <div onPointerDown={onScaleMouseDown} className={`flex items-center gap-3 bg-theme-panel/40 border px-4 py-1.5 rounded-lg cursor-ew-resize transition-all group ${isScaling ? 'border-theme-accent ring-2 ring-theme-accent/20 bg-theme-accent/5' : 'border-theme hover:border-theme-accent/50'}`}>
                  <i className={`fas fa-expand-alt text-[9px] ${isScaling ? 'text-theme-accent scale-125' : 'opacity-30'} transition-all`}></i>
                  <div className="w-24 h-1 bg-theme/20 rounded-full relative overflow-hidden">
                    <div className="absolute inset-y-0 left-0 bg-theme-accent transition-all duration-100" style={{ width: `${Math.min(100, (selectedElement?.scale || 1) * 20)}%` }}></div>
                  </div>
                  <span className="text-[10px] font-mono text-theme-accent font-black w-10 text-right">{Math.round((selectedElement?.scale || 1) * 100)}%</span>
                </div>
                {selectedId === 'main' && (
                  <button 
                    onClick={applyScaleToAllBatch}
                    className="h-9 px-3 rounded-lg border border-theme-accent/30 bg-theme-accent/10 text-theme-accent text-[9px] font-black uppercase tracking-widest hover:bg-theme-accent hover:text-white transition-all active:scale-95"
                    title="Aplicar escala desta imagem a todo o lote"
                  >
                    <i className="fas fa-check-double mr-1.5"></i>
                    Aplicar a Todos
                  </button>
                )}
              </div>
            </div>
            <div className={`h-8 w-[1px] transition-colors ${selectedId ? 'bg-theme-accent/30' : 'bg-theme/50'}`}></div>
            <div className="flex flex-col gap-1">
              <span className={`text-[7px] font-black uppercase tracking-[0.2em] transition-colors ${selectedId ? 'text-theme-accent' : 'opacity-40'}`}>Rotation</span>
              <div className="flex gap-1.5 bg-theme-panel/40 p-1 rounded-lg border border-theme">
                <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) - 15 })} className="w-7 h-7 flex items-center justify-center rounded hover:bg-theme-accent/20 transition-all active:scale-90"><i className="fas fa-undo text-[9px]"></i></button>
                <div className="w-10 flex items-center justify-center text-[10px] font-mono font-black opacity-60">{(selectedElement?.rotation || 0)}°</div>
                <button onClick={() => updateTransform(selectedId!, { rotation: (selectedElement?.rotation || 0) + 15 })} className="w-7 h-7 flex items-center justify-center rounded hover:bg-theme-accent/20 transition-all active:scale-90"><i className="fas fa-redo text-[9px]"></i></button>
              </div>
            </div>
          </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-8 overflow-hidden relative">
          <InteractiveEditor loteImages={extraLayers} mainImage={currentMainImage ? { ...currentMainImage, ...currentTransform! } : null} frameSettings={settings} selectedId={selectedId} onSelect={setSelectedId} onUpdateImage={updateTransform} zoom={zoom} hideLimbo={isSettingsOpen || showPresets} />
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme/40 py-1.5 px-6 rounded-full shadow-2xl backdrop-blur-md z-[70]">
            <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
              <i className="fas fa-search text-[10px] opacity-20"></i>
              <input type="range" min="0.05" max="2" step="0.01" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
            </div>
            <div className="flex items-center gap-4">
              <button disabled={currentIndex === 0} onClick={() => { setCurrentIndex(prev => prev - 1); setSelectedId('main'); }} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[9px]"></i></button>
              <span className="text-[10px] font-mono font-black text-theme-accent min-w-[60px] text-center">{mainBatch.length > 0 ? `${currentIndex + 1} / ${mainBatch.length}` : '0 / 0'}</span>
              <button disabled={currentIndex >= mainBatch.length - 1} onClick={() => { setCurrentIndex(prev => prev + 1); setSelectedId('main'); }} className="w-7 h-7 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[9px]"></i></button>
            </div>
          </div>
        </div>
      </section>

      <FramingLayerSidebar 
        mainBatch={mainBatch} 
        extraLayers={extraLayers} 
        currentIndex={currentIndex} 
        selectedId={selectedId} 
        onSelectMain={(idx) => { setCurrentIndex(idx); setSelectedId('main'); }}
        onSelectExtra={(id) => setSelectedId(id)}
        onUpdateExtra={updateTransform}
        onRemoveExtra={(id) => { setExtraLayers(prev => prev.filter(l => l.id !== id)); if (selectedId === id) setSelectedId(null); }}
        isOpen={isLayerSidebarOpen}
        onToggle={() => setIsLayerSidebarOpen(!isLayerSidebarOpen)}
      />

      {showCachePicker && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-8 bg-black/60 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="w-full max-w-4xl bg-theme-side border border-theme rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden h-[80vh]">
            <div className="p-8 border-b border-theme flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-2xl bg-theme-accent flex items-center justify-center text-white shadow-lg"><i className="fas fa-images"></i></div>
                <div><h3 className="text-xl font-black uppercase tracking-tighter">Molduras da Pasta Cache</h3><p className="text-[10px] opacity-40 uppercase tracking-widest">Localizadas em: /molduras</p></div>
              </div>
              <div className="flex gap-2">
                <button onClick={() => frameInputRef.current?.click()} className="px-6 py-2.5 rounded-xl border border-theme hover:bg-theme-accent/10 text-[10px] font-black uppercase tracking-widest transition-all">Outra Pasta...</button>
                <button onClick={() => setShowCachePicker(false)} className="w-10 h-10 flex items-center justify-center rounded-xl bg-theme-panel text-theme-muted hover:text-red-500 transition-all"><i className="fas fa-times"></i></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-8 grid grid-cols-4 gap-6 custom-scrollbar">
              {cacheFiles.length === 0 ? (<div className="col-span-4 flex flex-col items-center justify-center text-center opacity-20 py-20"><i className="fas fa-folder-open text-6xl mb-4"></i><p className="text-sm font-black uppercase">Pasta de molduras vazia</p></div>) : 
              (cacheFiles.map(f => (<div key={f.name} onClick={() => selectCacheFrame(f)} className="group cursor-pointer space-y-3"><div className="aspect-square rounded-2xl border-2 border-transparent group-hover:border-theme-accent bg-theme-panel overflow-hidden transition-all shadow-lg group-active:scale-95"><img src={f.url} className="w-full h-full object-cover" /></div><p className="text-[10px] font-black uppercase tracking-tight text-center truncate group-hover:text-theme-accent transition-colors">{f.name}</p></div>)))}
            </div>
          </div>
        </div>
      )}

      <FramingPresetModal isOpen={showPresets} onClose={() => setShowPresets(false)} currentSettings={settings} currentExtraLayers={extraLayers} onLoadPreset={handleLoadPreset} />

      <input type="file" multiple accept="image/*" className="hidden" ref={mainFileInputRef} onChange={handleMainFileChange} />
      <input type="file" multiple accept="image/*" className="hidden" ref={extraFileInputRef} onChange={handleExtraFileChange} />
      <input type="file" accept="image/png" className="hidden" ref={frameInputRef} onChange={(e) => {
        if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0]; const url = URL.createObjectURL(file);
          const img = new Image(); img.onload = () => {
            setSettings(prev => ({ ...prev, frameImageUrl: url, frameImageName: file.name, canvasWidth: img.width, canvasHeight: img.height }));
            setShowCachePicker(false);
          };
          img.src = url;
        }
      }} />
    </div>
  );
};

export default FramingTool;

