import React, { useRef, useEffect, useCallback, useState, useMemo } from 'react';
import { GridImage, GridSettings } from '../types';

interface GridPreviewProps {
  images: GridImage[];
  settings: GridSettings;
  zoom?: number;
  offset: { x: number, y: number };
  onOffsetChange: (offset: { x: number, y: number }) => void;
}

const GridPreview: React.FC<GridPreviewProps> = ({ 
  images, 
  settings, 
  zoom = 0.4,
  offset,
  onOffsetChange
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const imageCache = useRef<Map<string, HTMLImageElement>>(new Map());
  const [isDragging, setIsDragging] = useState(false);

  const activeImages = images.filter(img => img.isActive);

  // Carregamento de imagens com cache para performance
  useEffect(() => {
    let isMounted = true;
    const loadImages = async () => {
      const promises = activeImages.map(img => {
        if (imageCache.current.has(img.id)) return Promise.resolve();
        return new Promise<void>((resolve) => {
          const i = new Image();
          i.onload = () => {
            if (isMounted) imageCache.current.set(img.id, i);
            resolve();
          };
          i.src = img.previewUrl;
        });
      });
      await Promise.all(promises);
      if (isMounted) drawGrid();
    };
    loadImages();
    return () => { isMounted = false; };
  }, [images]);

  // Cálculo de dimensões memorizado - O coração da estabilidade da Grid
  const dimensions = useMemo(() => {
    const isAuto = settings.layoutMode === 'auto';
    const margin = settings.outerMargin;
    const spacing = settings.innerSpacing;
    const scaleFactor = 1 + ((settings.itemScale || 0) / 100);

    let cols = settings.columns;

    if (isAuto && activeImages.length > 0) {
      let targetRatio = 1;
      if (settings.targetShape === 'portrait') targetRatio = 0.75;
      if (settings.targetShape === 'landscape') targetRatio = 1.33;
      const avgItemRatio = activeImages.reduce((acc, img) => acc + img.aspectRatio, 0) / activeImages.length;
      cols = Math.max(1, Math.round(Math.sqrt((targetRatio * activeImages.length) / avgItemRatio)));
    }

    let finalW = settings.canvasWidth;
    let finalH = settings.canvasHeight;

    if (isAuto && activeImages.length > 0) {
      const baseCellWidth = (settings.canvasWidth - (2 * margin) - ((cols - 1) * spacing)) / cols;
      const cellWidth = baseCellWidth * scaleFactor;
      const rows = Math.ceil(activeImages.length / cols);
      finalW = (cols * cellWidth) + (2 * margin) + ((cols - 1) * spacing);
      finalH = (rows * cellWidth) + (2 * margin) + ((rows - 1) * spacing);
    }

    return { 
      width: Math.floor(finalW), 
      height: Math.floor(finalH), 
      cols: Math.max(1, cols) 
    };
  }, [settings, activeImages.length]);

  const drawGrid = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const { width, height, cols } = dimensions;
    const margin = settings.outerMargin;
    const spacing = settings.innerSpacing;

    // Sincroniza o canvas interno com os cálculos de dimensão
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!settings.isTransparent) {
      ctx.fillStyle = settings.backgroundColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    if (activeImages.length === 0) return;

    // Tamanho real de cada célula na grade
    const actualCellWidth = (canvas.width - (2 * margin) - ((cols - 1) * spacing)) / cols;
    const rows = Math.ceil(activeImages.length / cols);
    const actualCellHeight = (canvas.height - (2 * margin) - ((rows - 1) * spacing)) / rows;

    activeImages.forEach((imgObj, index) => {
      const img = imageCache.current.get(imgObj.id);
      if (!img) return;

      const col = index % cols;
      const row = Math.floor(index / cols);

      const x = margin + (col * (actualCellWidth + spacing));
      const y = margin + (row * (actualCellHeight + spacing));

      // Manter proporção da imagem dentro da célula
      let drawW = actualCellWidth;
      let drawH = actualCellWidth / imgObj.aspectRatio;

      if (drawH > actualCellHeight) {
        drawH = actualCellHeight;
        drawW = actualCellHeight * imgObj.aspectRatio;
      }

      // Centraliza a imagem na célula se ela for menor
      const offsetX = (actualCellWidth - drawW) / 2;
      const offsetY = (actualCellHeight - drawH) / 2;

      ctx.drawImage(img, x + offsetX, y + offsetY, drawW, drawH);
    });

    // DESENHO DAS GUIAS DE CORTE CORRIGIDAS (INVERTIDAS PARA DENTRO |_ )
    if (settings.showCuttingGuides) {
      const guideColor = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim() || '#4f46e5';
      const bleed = settings.guideOffset || 0; // O recuo da guia em relação ao canvas
      const len = settings.guideLength || 30;
      const thickness = settings.guideThickness || 2;

      ctx.strokeStyle = guideColor;
      ctx.lineWidth = thickness;
      ctx.lineCap = 'square';
      ctx.beginPath();

      // As guias definem o perímetro do corte final. 
      // Se margin = 0, as fotos tocam a guia. Se margin > 0, as fotos recuam da guia.
      const top = bleed;
      const left = bleed;
      const right = canvas.width - bleed;
      const bottom = canvas.height - bleed;

      // Canto: Top-Left |_ (Invertido para o centro)
      ctx.moveTo(left, top + len);
      ctx.lineTo(left, top);
      ctx.lineTo(left + len, top);

      // Canto: Top-Right _|
      ctx.moveTo(right - len, top);
      ctx.lineTo(right, top);
      ctx.lineTo(right, top + len);

      // Canto: Bottom-Left |¯
      ctx.moveTo(left, bottom - len);
      ctx.lineTo(left, bottom);
      ctx.lineTo(left + len, bottom);

      // Canto: Bottom-Right ¯|
      ctx.moveTo(right - len, bottom);
      ctx.lineTo(right, bottom);
      ctx.lineTo(right, bottom - len);

      ctx.stroke();

      // Guia Visual Extra (Opcional - Linha tracejada do corte real se necessário)
      /*
      ctx.setLineDash([5, 5]);
      ctx.lineWidth = 1;
      ctx.globalAlpha = 0.2;
      ctx.strokeRect(left, top, right - left, bottom - top);
      ctx.setLineDash([]);
      ctx.globalAlpha = 1.0;
      */
    }
  }, [activeImages, settings, dimensions]);

  useEffect(() => {
    drawGrid();
  }, [drawGrid]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return; // Só botão esquerdo
    setIsDragging(true);
    // @ts-ignore
    containerRef.current?.setPointerCapture(e.pointerId || 1);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    onOffsetChange({ x: offset.x + e.movementX, y: offset.y + e.movementY });
  };

  const handleMouseUp = () => setIsDragging(false);

  // Estilos de travamento para evitar distorção CSS
  const displayWidth = dimensions.width * zoom;
  const displayHeight = dimensions.height * zoom;

  return (
    <div 
      ref={containerRef}
      className="w-full h-full flex items-center justify-center relative select-none overflow-hidden bg-transparent"
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div 
        className="relative shadow-[0_30px_60px_-12px_rgba(0,0,0,0.5),0_18px_36px_-18px_rgba(0,0,0,0.5)] border border-white/10 transition-transform duration-75 rounded-none overflow-hidden"
        style={{
          width: displayWidth,
          height: displayHeight,
          minWidth: displayWidth, // Trava horizontal
          minHeight: displayHeight, // Trava vertical definitiva
          aspectRatio: `${dimensions.width} / ${dimensions.height}`,
          transform: `translate(${offset.x}px, ${offset.y}px)`,
          backgroundColor: settings.isTransparent ? 'transparent' : settings.backgroundColor,
          backgroundImage: settings.isTransparent ? 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)' : 'none',
          backgroundSize: '20px 20px'
        }}
      >
        <canvas 
          ref={canvasRef} 
          className="w-full h-full block pointer-events-none"
          style={{ width: '100%', height: '100%' }}
        />
      </div>
    </div>
  );
};

export default GridPreview;

