const drawStar = (ctx: CanvasRenderingContext2D, size: number) => {
  const spikes = 5;
  const outerRadius = size / 2;
  const innerRadius = size / 4;
  let rot = (Math.PI / 2) * 3;
  let x = 0;
  let y = 0;
  const step = Math.PI / spikes;
  ctx.beginPath();
  ctx.moveTo(0, -outerRadius);
  for (let i = 0; i < spikes; i++) {
    x = Math.cos(rot) * outerRadius; y = Math.sin(rot) * outerRadius; ctx.lineTo(x, y); rot += step;
    x = Math.cos(rot) * innerRadius; y = Math.sin(rot) * innerRadius; ctx.lineTo(x, y); rot += step;
  }
  ctx.lineTo(0, -outerRadius); ctx.closePath();
};

const drawCatPawClassic = (ctx: CanvasRenderingContext2D, size: number) => {
  const s = size / 2; ctx.save(); ctx.beginPath(); ctx.ellipse(0, s * 0.2, s * 0.65, s * 0.5, 0, 0, Math.PI * 2); ctx.fill();
  const toeRadius = s * 0.22; ctx.beginPath(); ctx.arc(-s * 0.5, -s * 0.25, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(-s * 0.18, -s * 0.5, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(s * 0.18, -s * 0.5, toeRadius, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(s * 0.5, -s * 0.25, toeRadius, 0, Math.PI * 2); ctx.fill(); ctx.restore();
};

const AlphaEdgeTool: React.FC<AlphaEdgeToolProps> = ({ globalPreviewQuality = 'fast' }) => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [zoom, setZoom] = useState(0.4);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [autoSave, setAutoSave] = useState(true);

  const [batchSettings, setBatchSettings] = useState<Record<string, AlphaEdgeSettings>>({});
  const [settings, setSettings] = useState<AlphaEdgeSettings>(DEFAULT_SETTINGS);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  const currentImg = images[selectedIdx];

  useEffect(() => {
    if (currentImg && batchSettings[currentImg.id]) {
      setSettings(batchSettings[currentImg.id]);
    }
  }, [selectedIdx, currentImg]);

  const handleSettingsChange = (newSettings: AlphaEdgeSettings) => {
    setSettings(newSettings);
    if (autoSave && currentImg) {
      setBatchSettings(prev => ({ ...prev, [currentImg.id]: newSettings }));
    }
  };

  const applyPrefixToAll = () => {
    const prefix = settings.exportPrefix || '';
    setBatchSettings(prev => {
      const newState = { ...prev };
      images.forEach(img => {
        newState[img.id] = { 
          ...(newState[img.id] || { ...settings }), 
          exportPrefix: prefix 
        };
      });
      return newState;
    });
  };

  const applyToAll = () => {
    const newBatch: Record<string, AlphaEdgeSettings> = {};
    images.forEach(img => { 
      newBatch[img.id] = { 
        ...settings, 
        exportPrefix: batchSettings[img.id]?.exportPrefix || settings.exportPrefix,
        exportFilename: batchSettings[img.id]?.exportFilename || '' 
      }; 
    });
    setBatchSettings(newBatch);
  };

  const navigateTo = (newIdx: number) => {
    const nextImg = images[newIdx];
    if (nextImg) {
      setSelectedIdx(newIdx);
    }
  };

  const getScaledPadding = useCallback((imgW: number, imgH: number, s: AlphaEdgeSettings) => {
    const scale = s.borderScale / 100;
    const effectiveBorder = (s.thickness + (s.softness * 1.5)) * scale;
    const offsetX = Math.abs(s.shapeOffsetX) * scale;
    const offsetY = Math.abs(s.shapeOffsetY) * scale;
    const paddingBase = Math.max(effectiveBorder, offsetX, offsetY) + 5;
    return Math.ceil(Math.max(2, paddingBase)); 
  }, []);

  const drawShape = (ctx: CanvasRenderingContext2D, type: string, size: number) => {
    if (type === 'none') return;
    const s = size / 2; ctx.beginPath();
    if (type === 'circle') ctx.arc(0, 0, s, 0, Math.PI * 2);
    else if (type === 'square') ctx.rect(-s, -s, size, size);
    else if (type === 'triangle') { ctx.moveTo(0, -s); ctx.lineTo(s, s); ctx.lineTo(-s, s); ctx.closePath(); }
    else if (type === 'heart') {
      const h = size * 0.4; ctx.moveTo(0, h);
      ctx.bezierCurveTo(-size * 0.7, -size * 0.1, -size * 0.5, -size * 0.9, 0, -size * 0.4);
      ctx.bezierCurveTo(size * 0.5, -size * 0.9, size * 0.7, -size * 0.1, 0, h);
    } else if (type === 'diamond') { ctx.moveTo(0, -s); ctx.lineTo(s, 0); ctx.lineTo(0, s); ctx.lineTo(-s, 0); ctx.closePath(); }
    else if (type === 'star') { drawStar(ctx, size); }
    else if (type === 'pata') { drawCatPawClassic(ctx, size); return; }
    ctx.fill();
  };

  const drawEdge = useCallback(async (img: HTMLImageElement, canvas: HTMLCanvasElement, config: AlphaEdgeSettings, isExport: boolean) => {
    const ctx = canvas.getContext('2d'); if (!ctx) return;
    const bScale = config.borderScale / 100;
    const finalPadding = getScaledPadding(img.width, img.height, config);

    canvas.width = img.width + (finalPadding * 2); 
    canvas.height = img.height + (finalPadding * 2);
    const centerX = canvas.width / 2; 
    const centerY = canvas.height / 2;

    const maskSize = Math.max(img.width, img.height) * 2;
    const silCanvas = document.createElement('canvas'); 
    silCanvas.width = maskSize; 
    silCanvas.height = maskSize;
    const sCtx = silCanvas.getContext('2d');

    if (sCtx) {
      sCtx.translate(maskSize / 2, maskSize / 2);
      if (config.boundaryMode === 'silhouette') { 
        sCtx.drawImage(img, -img.width/2, -img.height/2); 
        sCtx.globalCompositeOperation = 'source-in'; 
        sCtx.fillStyle = '#ffffff'; 
        sCtx.fillRect(-maskSize/2, -maskSize/2, maskSize, maskSize); 
      } 
      else { 
        drawShape(sCtx, config.geometricShape, Math.max(img.width, img.height)); 
      }
    }

    const maskCanvas = document.createElement('canvas'); 
    maskCanvas.width = maskSize; 
    maskCanvas.height = maskSize;
    const mCtx = maskCanvas.getContext('2d');

    if (mCtx) {
      mCtx.drawImage(silCanvas, 0, 0);
      const layers = isExport ? 20 : 6;
      for (let l = 1; l <= layers; l++) { 
        const r = (config.thickness / layers) * l; 
        for (let i = 0; i < 12; i++) { 
          const angle = (i / 12) * Math.PI * 2; 
          mCtx.drawImage(silCanvas, Math.cos(angle) * r, Math.sin(angle) * r); 
        } 
      }
      if (config.softness > 0) { 
        mCtx.filter = `blur(${config.softness}px)`; 
        const temp = document.createElement('canvas'); 
        temp.width = maskCanvas.width; 
        temp.height = maskCanvas.height; 
        temp.getContext('2d')?.drawImage(maskCanvas, 0, 0); 
        mCtx.clearRect(0,0,maskCanvas.width,maskCanvas.height); 
        mCtx.drawImage(temp, 0, 0); 
        mCtx.filter = 'none'; 
      }
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.save(); 
    ctx.globalAlpha = config.opacity / 100; 
    ctx.translate(centerX + config.shapeOffsetX * bScale, centerY + config.shapeOffsetY * bScale); 
    ctx.scale(bScale, bScale); 
    ctx.fillStyle = config.color; 
    ctx.drawImage(maskCanvas, -maskCanvas.width/2, -maskCanvas.height/2); 
    ctx.restore();

    ctx.save(); 
    ctx.translate(centerX - img.width/2, centerY - img.height/2); 
    ctx.drawImage(img, 0, 0); 
    ctx.restore();
  }, [getScaledPadding]);

  useEffect(() => {
    if (currentImg) {
      const img = new Image(); img.src = currentImg.previewUrl;
      img.onload = () => drawEdge(img, previewCanvasRef.current!, settings, false);
    }
  }, [selectedIdx, currentImg, settings, drawEdge]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const files = Array.from(e.target.files) as File[];
    const newImgs: GridImage[] = []; const newBatchStates: Record<string, AlphaEdgeSettings> = {};
    for (const file of files) {
      const id = uuidv4(); const url = URL.createObjectURL(file);
      const img = await new Promise<HTMLImageElement>((resolve) => { const i = new Image(); i.onload = () => resolve(i); i.src = url; });
      newImgs.push({ id, file, previewUrl: url, width: img.width, height: img.height, aspectRatio: img.width/img.height, isActive: true });
      newBatchStates[id] = { ...settings };
    }
    setImages(prev => [...prev, ...newImgs]);
    setBatchSettings(prev => ({ ...prev, ...newBatchStates }));
    if (e.target) e.target.value = '';
  };

  const handleSave = async () => {
    if (images.length === 0) return;
    setIsProcessing(true); setProgress(0);
    const canvas = document.createElement('canvas');
    const zip = downloadZip ? new JSZip() : null;
    for (let i = 0; i < images.length; i++) {
      setProgress(i + 1);
      const item = images[i]; 
      const currentConfig = batchSettings[item.id] || settings;
      const img = await new Promise<HTMLImageElement>((resolve) => { const im = new Image(); im.onload = () => resolve(im); im.src = item.previewUrl; });
      await drawEdge(img, canvas, currentConfig, true);

      const dataUrl = canvas.toDataURL('image/png');
      const prefix = currentConfig.exportPrefix || '';
      const baseName = currentConfig.exportFilename?.trim() || item.file.name.split('.')[0];
      const fileName = `${prefix}${baseName}.png`;

      if (downloadIndividual) {
        await MiauExportEngine.saveImage(dataUrl, fileName);
        if (!((window as any).__TAURI__)) await new Promise(r => setTimeout(r, 400));
      }
      if (zip) zip.file(fileName, dataUrl.split(',')[1], { base64: true });
    }

    if (zip) {
      const content = await zip.generateAsync({ type: "blob" });
      await MiauExportEngine.saveZip(content, `alpha_edge_pack_${Date.now()}.zip`);
    }
    setIsProcessing(false);
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 border-r flex flex-shrink-0 flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAlphaEdge 
          settings={settings} onSettingsChange={handleSettingsChange}
          onAdd={() => fileInputRef.current?.click()} onSave={handleSave}
          isProcessing={isProcessing} progress={progress} total={images.length}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onOpenAdvanced={() => setIsModalOpen(true)}
          autoSave={autoSave} onAutoSaveChange={setAutoSave}
          onApplyToAll={applyToAll}
          onExportGrid={() => {}}
          onApplyPrefixToAll={applyPrefixToAll}
        />
      </aside>
      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={() => { setImages([]); setBatchSettings({}); }} />
        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {currentImg && (
            <div className="flex-1 w-full flex flex-col items-center justify-center gap-10">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden transition-all duration-300 rounded-none"
                style={{ width: (currentImg.width + getScaledPadding(currentImg.width, currentImg.height, settings) * 2) * zoom, height: (currentImg.height + getScaledPadding(currentImg.width, currentImg.height, settings) * 2) * zoom }}
              >
                <canvas ref={previewCanvasRef} className="w-full h-full block" />
              </div>
            </div>
          )}
        </div>
        {currentImg && (
          <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-8 py-3 rounded-full shadow-2xl backdrop-blur-xl z-50">
            <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
              <i className="fas fa-search text-[10px] opacity-30"></i>
              <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-40 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
            </div>
            <div className="flex items-center gap-6">
              <button disabled={selectedIdx === 0} onClick={() => navigateTo(selectedIdx - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-left text-[10px]"></i></button>
              <span className="text-[11px] font-mono font-black text-theme-accent min-w-[70px] text-center">{selectedIdx + 1} / {images.length}</span>
              <button disabled={selectedIdx >= images.length - 1} onClick={() => navigateTo(selectedIdx + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main disabled:opacity-10 transition-all"><i className="fas fa-chevron-right text-[10px]"></i></button>
            </div>
          </div>
        )}
      </section>
      <aside className="w-80 border-l bg-theme-side border-theme flex flex-col overflow-hidden">
        <ImageList images={images} onRemove={(id) => setImages(prev => prev.filter(img => img.id !== id))} onMove={() => {}} onToggleActive={() => {}} />
      </aside>
      <input type="file" multiple accept="image/png, image/webp" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
      <AdvancedBorderModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} settings={settings.advanced!} onUpdate={(adv) => handleSettingsChange({ ...settings, advanced: adv })} baseImage={currentImg ? { url: currentImg.previewUrl, width: currentImg.width, height: currentImg.height } : null} />
    </div>
  );
};

export default AlphaEdgeTool;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { v4 as uuidv4 } from 'uuid';
import SidebarAILab from '../components/SidebarAILab';
import HistorySidebar from '../components/HistorySidebar';
import Header from '../components/Header';
import { GridImage, AISettings, HistoryState } from '../types';
import { MiauExportEngine } from '../utils/export';

const INITIAL_SETTINGS: AISettings = {
  mode: 'enhance',
  sharpness: 0,
  noiseReduction: 0,
  brightness: 100,
  contrast: 100,
  aiIntensity: 70,
  edgeSmoothness: 2,
  smartSharpen: false,
  highPassRadius: 1.5,
  isAdvancedSharpen: false,
  highFreqRadius: 1.2,
  highFreqOpacity: 100,
  lowFreqRadius: 8.0,
  lowFreqOpacity: 50
};

const AILabTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [currentHistoryIdx, setCurrentHistoryIdx] = useState(-1);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.4);
  const [compareSplit, setCompareSplit] = useState(50);
  const [isComparing, setIsComparing] = useState(true);

  const [baseImageLayer, setBaseImageLayer] = useState<string | null>(null);
  const [aiEnhancedLayer, setAiEnhancedLayer] = useState<string | null>(null);

  const [aiSettings, setAiSettings] = useState<AISettings>(INITIAL_SETTINGS);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentImg = images[0];

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const url = URL.createObjectURL(file);

      try {
        const img = await loadImage(url);
        const newImg: GridImage = {
          id: uuidv4(),
          file,
          previewUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height,
          isActive: true,
          visible: true
        };

        setImages([newImg]);
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0);
          const dataUrl = canvas.toDataURL('image/png');
          setBaseImageLayer(dataUrl);
          setAiEnhancedLayer(null);
          addToHistory(dataUrl, "Arquivo Original");
        }
      } catch (err) {
        console.error("Erro ao carregar imagem:", err);
      }
    }
    if (e.target) e.target.value = '';
  };

  const hasManualChanges = useMemo(() => {
    return aiSettings.sharpness !== 0 || 
           aiSettings.noiseReduction !== 0 || 
           aiSettings.brightness !== 100 || 
           aiSettings.contrast !== 100 || 
           aiSettings.smartSharpen === true;
  }, [aiSettings]);

  const handleClear = useCallback(() => {
    images.forEach(img => URL.revokeObjectURL(img.previewUrl));
    setImages([]);
    setHistory([]);
    setCurrentHistoryIdx(-1);
    setBaseImageLayer(null);
    setAiEnhancedLayer(null);
    setAiSettings(INITIAL_SETTINGS);
  }, [images]);

  const addToHistory = (url: string, label: string) => {
    const newState: HistoryState = {
      id: uuidv4(),
      url,
      label,
      timestamp: Date.now(),
      settingsSnapshot: { ...aiSettings }
    };
    const newHistory = [...history.slice(0, currentHistoryIdx + 1), newState];
    setHistory(newHistory);
    setCurrentHistoryIdx(newHistory.length - 1);
  };

  const handleRestoreHistory = (idx: number) => {
    const state = history[idx];
    if (!state) return;
    setCurrentHistoryIdx(idx);
    setBaseImageLayer(state.url);
    setAiEnhancedLayer(null);
    setAiSettings(state.settingsSnapshot);
  };

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error(`Erro ao carregar recurso visual.`));
      img.src = src;
    });
  };

  const bakeManualChanges = async () => {
    if (!baseImageLayer) return;
    setIsProcessing(true);
    try {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const mainImg = await loadImage(baseImageLayer);
      canvas.width = mainImg.width;
      canvas.height = mainImg.height;
      ctx.filter = getFilterString();
      ctx.drawImage(mainImg, 0, 0);
      ctx.filter = 'none';
      const bakedUrl = canvas.toDataURL('image/png', 1.0);
      setBaseImageLayer(bakedUrl);
      setAiSettings(prev => ({ 
        ...prev, 
        sharpness: 0,
        noiseReduction: 0,
        brightness: 100,
        contrast: 100,
        smartSharpen: false 
      }));
      addToHistory(bakedUrl, "Consolidação Manual");
    } catch (e) {
      console.error("Erro no bake:", e);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleExport = async () => {
    if (!baseImageLayer || !currentImg) return;
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const mainImg = await loadImage(baseImageLayer);
    canvas.width = mainImg.width;
    canvas.height = mainImg.height;
    ctx.filter = getFilterString();
    ctx.drawImage(mainImg, 0, 0);
    const dataUrl = canvas.toDataURL('image/png', 1.0);

    const fileName = `${currentImg.file.name.split('.')[0]}_miau_ai.png`;
    await MiauExportEngine.saveImage(dataUrl, fileName);
  };

  const processWithAI = async (mode: AISettings['mode']) => {
    if (!baseImageLayer) return;
    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = "Execute uma restauração de imagem de com fidelidade e upscale extremo para a imagem fornecida. O objetivo é aumentar drasticamente a resolução e a nitidez (sharpening) e remover ruidos, sem introduzir artefatos ou alterar o design original. Return only the image.";

      const base64Data = baseImageLayer.split(',')[1];
      const imagePart = {
        inlineData: {
          data: base64Data,
          mimeType: 'image/png'
        }
      };

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            imagePart,
            { text: prompt }
          ]
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const resultUrl = `data:image/png;base64,${part.inlineData.data}`;
            setBaseImageLayer(resultUrl);
            setAiEnhancedLayer(null);
            addToHistory(resultUrl, mode === 'enhance' ? "IA Restauração Extrema" : "IA Neural Clean");
            setIsProcessing(false);
            return;
          }
        }
      }
      throw new Error("A IA não retornou uma imagem válida.");
    } catch (error: any) {
      console.error("Miau AI Error:", error);
      alert(`Erro no Miau Lab: ${error.message || 'Falha na conexão.'}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const getFilterString = () => {
    const s = aiSettings.sharpness;
    const sharpen = s > 0 ? `contrast(${100 + s/2.5}%) brightness(${100 - s/25}%) saturate(${100 + s/10}%)` : '';
    const blur = aiSettings.noiseReduction > 0 ? `blur(${aiSettings.noiseReduction/30}px)` : '';
    return `brightness(${aiSettings.brightness}%) contrast(${aiSettings.contrast}%) ${sharpen} ${blur}`;
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main relative">
      <aside className="w-80 border-r flex flex-col bg-theme-side border-theme overflow-y-auto custom-scrollbar">
        <SidebarAILab 
          settings={aiSettings} 
          onSettingsChange={setAiSettings}
          onAdd={() => fileInputRef.current?.click()}
          onProcess={processWithAI}
          onBakeManual={bakeManualChanges}
          onSave={handleExport} 
          isProcessing={isProcessing}
          hasManualChanges={hasManualChanges}
        />
      </aside>

      <section className="flex-1 flex flex-col overflow-hidden relative">
        <Header itemCount={images.length} onClear={handleClear} />

        <div className="flex-1 flex flex-col items-center justify-center p-12 overflow-hidden bg-black/5 relative">
          {baseImageLayer ? (
            <div className="flex-1 w-full flex flex-col items-center justify-center">
              <div 
                className="relative shadow-2xl border border-theme bg-theme-panel overflow-hidden rounded-none"
                style={{ width: currentImg.width * zoom, height: currentImg.height * zoom }}
              >
                <img src={history[0]?.url || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" alt="original" />
                <div 
                  className="absolute inset-0 w-full h-full overflow-hidden"
                  style={{ clipPath: isComparing ? `inset(0 0 0 ${compareSplit}%)` : 'none' }}
                >
                  <img src={aiEnhancedLayer || baseImageLayer} className="absolute inset-0 w-full h-full object-cover" style={{ filter: getFilterString() }} alt="enhanced" />
                </div>
                {isComparing && (
                  <>
                    <div className="absolute top-0 bottom-0 w-0.5 bg-theme-accent z-10" style={{ left: `${compareSplit}%` }} />
                    <input type="range" min="0" max="100" value={compareSplit} onChange={(e) => setCompareSplit(parseInt(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-20" />
                  </>
                )}
                {isProcessing && (
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-xl flex flex-col items-center justify-center text-white z-50">
                    <div className="w-12 h-12 border-4 border-theme-accent border-t-transparent rounded-full animate-spin mb-4"></div>
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">Processando Restauração...</p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="text-center opacity-10 flex flex-col items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-9xl"></i>
              <p className="font-black text-2xl uppercase tracking-[0.3em]">Miau AI Lab</p>
            </div>
          )}

          {baseImageLayer && (
            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-theme-side/90 border border-theme px-6 py-2 rounded-full shadow-2xl backdrop-blur-md z-50">
              <div className="flex items-center gap-3 pr-6 border-r border-theme/50">
                <i className="fas fa-search text-[10px] opacity-30"></i>
                <input type="range" min="0.05" max="2" step="0.05" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-24 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
                <span className="text-[9px] font-mono opacity-40">{Math.round(zoom * 100)}%</span>
              </div>
              <button onClick={() => setIsComparing(!isComparing)} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase transition-all ${isComparing ? 'bg-theme-accent text-white' : 'bg-theme-panel opacity-40 hover:opacity-100'}`}>Comparar</button>
            </div>
          )}
        </div>
      </section>

      <HistorySidebar history={history} currentIndex={currentHistoryIdx} onRestore={handleRestoreHistory} isOpen={isHistoryOpen} onToggle={() => setIsHistoryOpen(!isHistoryOpen)} />
      <input type="file" accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
    </div>
  );
};

export default AILabTool;

