/**
 * MiauExportEngine - O motor de exportação da gatinha.
 * Adaptado para Tauri v2 com plugins independentes.
 */

export class MiauExportEngine {

  private static get tauri() {
    return (window as any).__TAURI__;
  }

  /**
   * Verifica se estamos rodando dentro do binário Tauri
   */
  public static isTauri(): boolean {
    return !!(window as any).__TAURI__;
  }

  /**
   * Acessa os plugins de forma segura no Tauri v2
   */
  private static getApis() {
    const t = this.tauri;
    if (!t) return null;

    // No Tauri v2, os plugins instalados via cargo e npm
    // ficam disponíveis no objeto global se withGlobalTauri estiver ativo.
    const dialog = t.plugins?.dialog || t.dialog;
    const fs = t.plugins?.fs || t.fs;

    return {
      save: dialog?.save,
      // No v2 o comando é writeFile, mas na ponte global pode variar
      writeBinaryFile: fs?.writeFile || fs?.writeBinaryFile
    };
  }

  private static async toUint8Array(source: string | Blob): Promise<Uint8Array> {
    if (source instanceof Blob) {
      const buffer = await source.arrayBuffer();
      return new Uint8Array(buffer);
    }
    const base64 = source.split(',')[1];
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }

  public static async saveImage(dataUrl: string, defaultName: string) {
    if (this.isTauri()) {
      try {
        const apis = this.getApis();

        if (apis && apis.save && apis.writeBinaryFile) {
          const path = await apis.save({
            defaultPath: defaultName,
            filters: [{ name: 'Imagens', extensions: ['png', 'jpg', 'webp'] }]
          });

          if (path) {
            const uint8 = await this.toUint8Array(dataUrl);
            // Na v2, writeFile espera o caminho e os bytes
            await apis.writeBinaryFile(path, uint8);
            console.debug(`[MiauExport] Salvo via Tauri v2 em: ${path}`);
            return;
          }
          return;
        }
      } catch (err) {
        console.error("[MiauExport] Erro na ponte Tauri:", err);
      }
    }

    // Fallback: Navegador comum
    this.webDownload(dataUrl, defaultName);
  }

  public static async saveZip(blob: Blob, defaultName: string) {
    if (this.isTauri()) {
      try {
        const apis = this.getApis();
        if (apis && apis.save && apis.writeBinaryFile) {
          const path = await apis.save({
            defaultPath: defaultName,
            filters: [{ name: 'Arquivo ZIP', extensions: ['zip'] }]
          });

          if (path) {
            const uint8 = await this.toUint8Array(blob);
            await apis.writeBinaryFile(path, uint8);
            return;
          }
        }
      } catch (err) {
        console.error("[MiauExport] Erro ZIP nativo:", err);
      }
    }

    const url = URL.createObjectURL(blob);
    this.webDownload(url, defaultName);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  }

  private static webDownload(url: string, name: string) {
    const link = document.createElement('a');
    link.href = url;
    link.download = name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
}

