import React, { useRef, useEffect, useCallback, useState, useMemo } from 'react';
import { GridImage, GridSettings, ImageAlignment } from '../types';

interface GridPreviewProps {
  images: GridImage[];
  settings: GridSettings;
  zoom?: number;
  offset: { x: number, y: number };
  onOffsetChange: (offset: { x: number, y: number }) => void;
}

const GridPreview: React.FC<GridPreviewProps> = ({ 
  images, 
  settings, 
  zoom = 0.4,
  offset,
  onOffsetChange
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const imageCache = useRef<Map<string, HTMLImageElement>>(new Map());
  const [isPanning, setIsPanning] = useState(false);

  const activeImages = useMemo(() => {
    const active = images.filter(img => img.isActive);
    if (settings.makerMode && active.length > 0) {
      const repeat = settings.makerRepeat || 1;
      return Array(repeat).fill(active[0]);
    }
    return active;
  }, [images, settings.makerMode, settings.makerRepeat]);

  useEffect(() => {
    let isMounted = true;
    const loadImages = async () => {
      const imagesToLoad = settings.makerMode && images.length > 0 ? [images[0]] : images.filter(img => img.isActive);

      const promises = imagesToLoad.map(img => {
        if (imageCache.current.has(img.id)) return Promise.resolve();
        return new Promise<void>((resolve) => {
          const i = new Image();
          i.onload = () => {
            if (isMounted) imageCache.current.set(img.id, i);
            resolve();
          };
          i.src = img.previewUrl;
        });
      });
      await Promise.all(promises);
      if (isMounted) drawGrid();
    };
    loadImages();
    return () => { isMounted = false; };
  }, [images, settings.makerMode]);

  const dimensions = useMemo(() => {
    const isAuto = settings.layoutMode === 'auto';
    const hSpacing = settings.innerSpacing;
    const vSpacing = settings.verticalSpacing ?? settings.innerSpacing;
    const bleed = settings.showCuttingGuides ? (settings.guideOffset || 0) : 0;
    const effectiveMargin = settings.outerMargin + bleed;

    let cols = settings.columns;
    if (isAuto && activeImages.length > 0) {
      let targetRatio = 1;
      if (settings.targetShape === 'portrait') targetRatio = 0.75;
      if (settings.targetShape === 'landscape') targetRatio = 1.33;
      const avgItemRatio = activeImages.reduce((acc, img) => acc + img.aspectRatio, 0) / activeImages.length;
      cols = Math.max(1, Math.round(Math.sqrt((targetRatio * activeImages.length) / avgItemRatio)));
    }

    let finalW = settings.canvasWidth;
    let finalH = settings.canvasHeight;

    if (isAuto && activeImages.length > 0) {
      const actualCellWidth = (settings.canvasWidth - (2 * effectiveMargin) - ((cols - 1) * hSpacing)) / cols;
      const rows = Math.ceil(activeImages.length / cols);
      finalW = settings.canvasWidth;
      finalH = (rows * actualCellWidth) + (2 * effectiveMargin) + ((rows - 1) * vSpacing);
    }

    return { width: Math.floor(finalW), height: Math.floor(finalH), cols: Math.max(1, cols), effectiveMargin };
  }, [settings, activeImages.length]);

  const calculateOffsets = (alignment: ImageAlignment, diffW: number, diffH: number) => {
    let offsetX = 0;
    let offsetY = 0;

    // Horizontal Alignment
    if (alignment.includes('center')) offsetX = diffW / 2;
    else if (alignment.includes('right')) offsetX = diffW;
    else if (alignment === 'center') offsetX = diffW / 2; // Caso específico de center puro

    // Vertical Alignment
    if (alignment.includes('middle')) offsetY = diffH / 2;
    else if (alignment.includes('bottom')) offsetY = diffH;
    else if (alignment === 'center') offsetY = diffH / 2;

    return { offsetX, offsetY };
  };

  const drawGrid = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const { width, height, cols, effectiveMargin } = dimensions;
    const hSpacing = settings.innerSpacing;
    const vSpacing = settings.verticalSpacing ?? settings.innerSpacing;

    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (!settings.isTransparent) {
      ctx.fillStyle = settings.backgroundColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    if (activeImages.length === 0) return;

    const actualCellWidth = (canvas.width - (2 * effectiveMargin) - ((cols - 1) * hSpacing)) / cols;
    const rows = Math.ceil(activeImages.length / cols);
    const actualCellHeight = settings.layoutMode === 'auto' 
      ? actualCellWidth 
      : (canvas.height - (2 * effectiveMargin) - ((rows - 1) * vSpacing)) / rows;

    activeImages.forEach((imgObj, index) => {
      const img = imageCache.current.get(imgObj.id);
      if (!img) return;
      const col = index % cols;
      const row = Math.floor(index / cols);
      const x = effectiveMargin + (col * (actualCellWidth + hSpacing));
      const y = effectiveMargin + (row * (actualCellHeight + vSpacing));

      let drawW, drawH;

      if (settings.forceOriginalSize) {
        drawW = imgObj.width;
        drawH = imgObj.height;
      } else {
        drawW = actualCellWidth;
        drawH = actualCellWidth / imgObj.aspectRatio;
        if (drawH > actualCellHeight) {
          drawH = actualCellHeight;
          drawW = actualCellHeight * imgObj.aspectRatio;
        }
      }

      // NOVA LÓGICA DE ALINHAMENTO EXPLÍCITO
      const { offsetX, offsetY } = calculateOffsets(settings.alignment, actualCellWidth - drawW, actualCellHeight - drawH);

      ctx.drawImage(img, x + offsetX, y + offsetY, drawW, drawH);
    });

    if (settings.showCuttingGuides) {
      const guideColor = settings.guideColor || '#4f46e5';
      const bleed = settings.guideOffset || 0;
      const len = settings.guideLength || 30;
      const thickness = settings.guideThickness || 2;
      ctx.strokeStyle = guideColor;
      ctx.lineWidth = thickness;
      ctx.lineCap = 'square';
      ctx.beginPath();
      const top = bleed; const left = bleed; const right = canvas.width - bleed; const bottom = canvas.height - bleed;
      ctx.moveTo(left, top + len); ctx.lineTo(left, top); ctx.lineTo(left + len, top);
      ctx.moveTo(right - len, top); ctx.lineTo(right, top); ctx.lineTo(right, top + len);
      ctx.moveTo(left, bottom - len); ctx.lineTo(left, bottom); ctx.lineTo(left + len, bottom);
      ctx.moveTo(right - len, bottom); ctx.lineTo(right, bottom); ctx.lineTo(right, bottom - len);
      ctx.stroke();
    }
  }, [activeImages, settings, dimensions]);

  useEffect(() => { drawGrid(); }, [drawGrid]);

  const renderDimensionBadge = (imgObj: GridImage, drawW: number, drawH: number, isLarge: boolean = false) => {
    const diffW = Math.round(drawW - imgObj.width);
    const diffH = Math.round(drawH - imgObj.height);

    let color = "text-[#22c55e]"; // Verde
    if (diffW > 1 || diffH > 1) color = "text-[#a855f7]"; // Roxo
    else if (diffW < -1 || diffH < -1) color = "text-[#ef4444]"; // Vermelho

    const labelW = `${Math.round(drawW)}${diffW !== 0 ? `(${diffW > 0 ? '+' : ''}${diffW})` : ''}`;
    const labelH = `${Math.round(drawH)}${diffH !== 0 ? `(${diffH > 0 ? '+' : ''}${diffH})` : ''}`;

    return (
      <div className={`pointer-events-none font-mono font-black flex items-center justify-center whitespace-nowrap bg-black/80 backdrop-blur-md border border-white/10 rounded-lg px-2 py-1 shadow-2xl ${isLarge ? 'text-[12px]' : 'text-[9px]'} ${color}`}>
        {labelW}px X {labelH}px
      </div>
    );
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button === 1) {
      e.preventDefault();
      setIsPanning(true);
      containerRef.current?.focus();
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isPanning) {
      onOffsetChange({ x: offset.x + e.movementX, y: offset.y + e.movementY });
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    if (e.button === 1) setIsPanning(false);
  };

  const uiOverlays = useMemo(() => {
    if (activeImages.length === 0) return null;
    const { cols, effectiveMargin } = dimensions;
    const hSpacing = settings.innerSpacing;
    const vSpacing = settings.verticalSpacing ?? settings.innerSpacing;
    const actualCellWidth = (dimensions.width - (2 * effectiveMargin) - ((cols - 1) * hSpacing)) / cols;
    const rows = Math.ceil(activeImages.length / cols);
    const actualCellHeight = settings.layoutMode === 'auto' 
      ? actualCellWidth 
      : (dimensions.height - (2 * effectiveMargin) - ((rows - 1) * vSpacing)) / rows;

    if (settings.makerMode && activeImages.length > 0) {
      const imgObj = activeImages[0];
      let drawW, drawH;
      if (settings.forceOriginalSize) {
        drawW = imgObj.width;
        drawH = imgObj.height;
      } else {
        drawW = actualCellWidth;
        drawH = actualCellWidth / imgObj.aspectRatio;
        if (drawH > actualCellHeight) {
          drawH = actualCellHeight;
          drawW = actualCellHeight * imgObj.aspectRatio;
        }
      }

      return (
        <div className="absolute top-4 right-4 z-[100] animate-in slide-in-from-top-4 duration-500">
          <div className="flex flex-col items-end gap-1">
            <span className="text-[9px] font-black uppercase tracking-widest text-theme-accent opacity-60">Status de Escala (Maker)</span>
            {renderDimensionBadge(imgObj, drawW, drawH, true)}
          </div>
        </div>
      );
    }

    return activeImages.map((imgObj, index) => {
      const col = index % cols;
      const row = Math.floor(index / cols);
      const x = effectiveMargin + (col * (actualCellWidth + hSpacing));
      const y = effectiveMargin + (row * (actualCellHeight + vSpacing));

      let drawW, drawH;
      if (settings.forceOriginalSize) {
        drawW = imgObj.width;
        drawH = imgObj.height;
      } else {
        drawW = actualCellWidth;
        drawH = actualCellWidth / imgObj.aspectRatio;
        if (drawH > actualCellHeight) {
          drawH = actualCellHeight;
          drawW = actualCellHeight * imgObj.aspectRatio;
        }
      }

      // Aplicamos a mesma lógica de ancoragem na UI Overlay
      const { offsetX, offsetY } = calculateOffsets(settings.alignment, actualCellWidth - drawW, actualCellHeight - drawH);

      return (
        <div 
          key={`badge-${index}`}
          className="absolute z-[90] pointer-events-none flex items-center justify-center transition-all duration-300"
          style={{
            left: (x + offsetX) * zoom,
            top: (y + offsetY) * zoom,
            width: drawW * zoom,
            height: drawH * zoom,
          }}
        >
          <div className="mt-auto mb-2 scale-[1.1]">
            {renderDimensionBadge(imgObj, drawW, drawH, true)}
          </div>
        </div>
      );
    });
  }, [activeImages, settings, dimensions, zoom]);

  return (
    <div 
      ref={containerRef}
      tabIndex={0}
      className={`w-full h-full flex items-center justify-center relative select-none overflow-hidden bg-transparent outline-none ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => setIsPanning(false)}
      onContextMenu={(e) => isPanning && e.preventDefault()}
    >
      <div 
        className="relative shadow-[0_30px_60px_-12px_rgba(0,0,0,0.5),0_18px_36px_-18px_rgba(0,0,0,0.5)] border border-white/10 transition-transform duration-75 rounded-none overflow-visible"
        style={{
          width: dimensions.width * zoom,
          height: dimensions.height * zoom,
          transform: `translate(${offset.x}px, ${offset.y}px)`,
          backgroundColor: settings.isTransparent ? 'transparent' : settings.backgroundColor,
          backgroundImage: settings.isTransparent ? 'linear-gradient(45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(-45deg, rgba(0,0,0,0.1) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.1) 75%), linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.1) 75%)' : 'none',
          backgroundSize: '20px 20px'
        }}
      >
        <canvas ref={canvasRef} className="w-full h-full block pointer-events-none" />

        <div className="absolute inset-0 pointer-events-none overflow-visible">
          {uiOverlays}
        </div>
      </div>
    </div>
  );
};

export default GridPreview;

import React from 'react';
import { GridSettings, GridImage, ImageAlignment } from '../types';
import MiauSlider from './MiauSlider';

interface SidebarProps {
  settings: GridSettings;
  onSettingsChange: (settings: GridSettings) => void;
  onAddFile: () => void;
  onAddFolder: () => void;
  onAddMaker: () => void;
  images: GridImage[];
  onUpdateActiveCount: (count: number) => void;
  exportOptions: {
    downloadIndividual: boolean;
    setDownloadIndividual: (v: boolean) => void;
    downloadZip: boolean;
    setDownloadZip: (v: boolean) => void;
  };
  onExport: () => void;
  isProcessing?: boolean;
}

const ALIGNMENT_OPTIONS: { id: ImageAlignment; label: string }[] = [
  { id: 'top-left', label: 'Canto Superior Esquerdo' },
  { id: 'top-center', label: 'Topo Central' },
  { id: 'top-right', label: 'Canto Superior Direito' },
  { id: 'middle-left', label: 'Centro Esquerda' },
  { id: 'center', label: 'Centro Total' },
  { id: 'middle-right', label: 'Centro Direita' },
  { id: 'bottom-left', label: 'Canto Inferior Esquerdo' },
  { id: 'bottom-center', label: 'Base Central' },
  { id: 'bottom-right', label: 'Canto Inferior Direito' },
];

const Sidebar: React.FC<SidebarProps> = ({ settings, onSettingsChange, onAddFile, onAddFolder, onAddMaker, images, onUpdateActiveCount, exportOptions, onExport, isProcessing = false }) => {
  const handleChange = (key: keyof GridSettings, value: any) => { 
    onSettingsChange({ ...settings, [key]: value }); 
  };

  const handleBackgroundChange = (color: string, transparent: boolean) => {
    onSettingsChange({
      ...settings,
      backgroundColor: color,
      isTransparent: transparent
    });
  };

  const activeCount = images.filter(img => img.isActive).length;
  const isAuto = settings.layoutMode === 'auto';
  const isMaker = settings.makerMode;

  return (
    <div className="p-5 space-y-6 h-full overflow-y-auto scrollbar-hide flex flex-col">
      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Entrada de Mídia</h3>
        <div className="space-y-2">
          <button 
            onClick={onAddMaker} 
            className={`w-full flex items-center justify-center gap-2 py-4 px-4 rounded-xl font-black text-[11px] transition-all active:scale-95 shadow-xl relative group overflow-hidden uppercase tracking-widest border-2 ${isMaker ? 'bg-theme-main border-theme-accent text-theme-accent' : 'bg-gradient-to-r from-theme-accent via-indigo-600 to-theme-accent border-transparent text-white'}`}
          >
            <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
            <i className={`fas ${isMaker ? 'fa-magic animate-pulse' : 'fa-th-large'} z-10 text-[13px]`}></i> 
            <span className="z-10">{isMaker ? 'Maker Ativo' : 'Grid Maker Pro'}</span>
            {!isMaker && <div className="absolute inset-[-100%] bg-gradient-to-r from-transparent via-white/20 to-transparent rotate-45 animate-[shimmer_2s_infinite]"></div>}
          </button>

          <button onClick={onAddFile} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-xl font-black text-[10px] transition-all active:scale-95 border border-theme bg-theme-panel text-theme-main opacity-80 hover:opacity-100 hover:bg-black/10">
            <i className="fas fa-plus-circle"></i> <span>Adicionar Fotos</span>
          </button>
          <button onClick={onAddFolder} className="w-full flex items-center justify-center gap-2 py-2 px-4 rounded-lg font-bold text-[9px] border border-theme bg-theme-panel text-theme-muted opacity-50 hover:opacity-100 transition-all">
            <i className="fas fa-folder"></i> <span>Pasta Completa</span>
          </button>
        </div>

        {isMaker && (
          <div className="pt-2 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="p-3 rounded-xl bg-theme-accent/5 border border-theme-accent/20">
              <MiauSlider label="Repetir Imagem" min={1} max={500} value={settings.makerRepeat || 1} onChange={(v) => handleChange('makerRepeat', v)} icon="fa-redo-alt" />
            </div>
          </div>
        )}
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <div className="flex items-center justify-between border-b border-theme pb-2">
          <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40">Layout & Ancoragem</h3>
          {(isAuto || isMaker) && <i className="fas fa-robot text-theme-accent text-[10px]"></i>}
        </div>

        {/* MATRIZ DE ANCORAGEM REFINADA */}
        <div className="flex flex-col items-center gap-3 py-2">
          <label className="text-[8px] font-black uppercase opacity-50 block tracking-widest w-full text-center">Ponto de Alinhamento</label>
          <div className="grid grid-cols-3 gap-2 bg-black/20 p-3 rounded-2xl border border-theme/40 relative">
            {ALIGNMENT_OPTIONS.map((opt) => (
              <button
                key={opt.id}
                onClick={() => handleChange('alignment', opt.id)}
                className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all duration-300 relative group
                  ${settings.alignment === opt.id 
                    ? 'bg-theme-accent text-white shadow-[0_0_20px_rgba(79,70,229,0.5)] scale-110 z-10' 
                    : 'bg-theme-panel/50 border border-theme/20 hover:border-theme-accent/50'
                }`}
                title={opt.label}
              >
                <div className={`w-1.5 h-1.5 rounded-full transition-all ${settings.alignment === opt.id ? 'bg-white scale-125' : 'bg-theme-muted opacity-30 group-hover:opacity-100'}`}></div>
                {settings.alignment === opt.id && <div className="absolute inset-0 rounded-lg animate-ping bg-theme-accent/20"></div>}
              </button>
            ))}
          </div>
          <span className="text-[7px] font-black uppercase opacity-30 tracking-tighter">{settings.alignment.replace('-', ' ')}</span>
        </div>

        <div className="flex p-1 bg-theme-panel/50 rounded-xl border border-theme">
          <button onClick={() => handleChange('layoutMode', 'grid')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${!isAuto ? 'bg-theme-accent text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}>Manual</button>
          <button onClick={() => handleChange('layoutMode', 'auto')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${isAuto ? 'bg-theme-accent text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}>Auto-Flow</button>
        </div>

        <label className="flex items-center gap-3 p-3 rounded-xl border border-theme bg-theme-panel/50 cursor-pointer group transition-all hover:bg-theme-accent/5">
          <div className={`w-4 h-4 rounded border border-theme flex items-center justify-center transition-all ${settings.forceOriginalSize ? 'bg-theme-accent border-theme-accent' : 'bg-transparent'}`}>
            {settings.forceOriginalSize && <i className="fas fa-check text-[8px] text-white"></i>}
            <input type="checkbox" className="hidden" checked={settings.forceOriginalSize} onChange={e => handleChange('forceOriginalSize', e.target.checked)} />
          </div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase tracking-tight text-theme-main">Forçar Tamanho Real</span>
            <span className="text-[8px] opacity-40 uppercase">Ignora Redimensionamento</span>
          </div>
        </label>

        {isAuto && !isMaker && (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
            <MiauSlider label="Itens na Grid" min={1} max={images.length || 1} value={activeCount} onChange={onUpdateActiveCount} icon="fa-layer-group" />
            <div className="space-y-2">
              <label className="text-[9px] font-bold opacity-60 uppercase tracking-wide px-1">Formato do Conjunto</label>
              <div className="grid grid-cols-3 gap-1.5">
                {[{ id: 'square', label: '1:1', icon: 'fa-square' }, { id: 'portrait', label: '3:4', icon: 'fa-columns' }, { id: 'landscape', label: '4:3', icon: 'fa-grip-horizontal' }].map(shape => (
                  <button key={shape.id} onClick={() => handleChange('targetShape', shape.id)} className={`flex flex-col items-center justify-center gap-1.5 py-3 rounded-xl border transition-all ${settings.targetShape === shape.id ? 'bg-theme-accent border-theme-accent text-white shadow-lg' : 'bg-theme-panel/50 border-theme opacity-50 hover:opacity-100'}`}>
                    <i className={`fas ${shape.icon} text-[10px]`}></i>
                    <span className="text-[7px] font-black uppercase">{shape.label}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-5">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Dimensões & Escala</h3>
        <div className={`grid grid-cols-2 gap-3 transition-all ${isAuto && !isMaker ? 'opacity-30 pointer-events-none grayscale' : ''}`}>
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase block">Largura</label>
            <input type="number" value={settings.canvasWidth} onChange={(e) => handleChange('canvasWidth', parseInt(e.target.value) || 0)} className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none font-mono" />
          </div>
          <div className="space-y-1">
            <label className="text-[8px] font-bold opacity-50 uppercase block">Altura</label>
            <input type="number" value={settings.canvasHeight} onChange={(e) => handleChange('canvasHeight', parseInt(e.target.value) || 0)} className="w-full bg-theme-panel border border-theme rounded p-2 text-[10px] outline-none font-mono" />
          </div>
        </div>
        <div className="space-y-4">
          <MiauSlider label="Espaçamento Vertical" min={-500} max={500} value={settings.verticalSpacing || 0} onChange={(v) => handleChange('verticalSpacing', v)} icon="fa-arrows-alt-v" />
          <MiauSlider label="Colunas" min={1} max={12} value={settings.columns} onChange={(v) => handleChange('columns', v)} icon="fa-grip-vertical" />
          <MiauSlider label="Espaçamento Horizontal" min={-500} max={500} value={settings.innerSpacing} onChange={(v) => handleChange('innerSpacing', v)} icon="fa-arrows-alt-h" />
          <MiauSlider 
            label={settings.showCuttingGuides ? "Margem p/ Corte" : "Margem Externa"} 
            min={0} max={500} 
            value={settings.outerMargin} 
            onChange={(v) => handleChange('outerMargin', v)} 
            icon="fa-border-outer" 
          />
        </div>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-5 animate-in slide-in-from-right-2 duration-300">
        <div className="flex items-center justify-between border-b border-theme pb-2">
           <h3 className="text-[10px] font-black uppercase tracking-widest text-theme-accent">Utilitários de Impressão</h3>
           <i className="fas fa-print opacity-30 text-[9px]"></i>
        </div>

        <label className="flex items-center gap-3 p-3 rounded-xl border border-theme bg-theme-panel/50 cursor-pointer group transition-all hover:bg-theme-accent/5">
          <div className={`w-4 h-4 rounded border border-theme flex items-center justify-center transition-all ${settings.showCuttingGuides ? 'bg-theme-accent border-theme-accent' : 'bg-transparent'}`}>
            {settings.showCuttingGuides && <i className="fas fa-check text-[8px] text-white"></i>}
            <input type="checkbox" className="hidden" checked={settings.showCuttingGuides} onChange={e => handleChange('showCuttingGuides', e.target.checked)} />
          </div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase tracking-tight text-theme-main">Guias de Corte</span>
            <span className="text-[8px] opacity-40 uppercase">Marcas de Registro</span>
          </div>
        </label>

        <div className={`space-y-4 transition-all duration-300 ${!settings.showCuttingGuides ? 'opacity-10 grayscale pointer-events-none' : 'opacity-100'}`}>
          <MiauSlider label="Recuo (Margem Papel)" min={0} max={200} value={settings.guideOffset || 0} onChange={(v) => handleChange('guideOffset', v)} icon="fa-arrows-alt" />
          <MiauSlider label="Comprimento Marca" min={10} max={200} value={settings.guideLength || 30} onChange={(v) => handleChange('guideLength', v)} icon="fa-ruler-horizontal" />
          <MiauSlider label="Grossura da Linha" min={1} max={30} value={settings.guideThickness || 2} onChange={(v) => handleChange('guideThickness', v)} unit="px" icon="fa-pen-nib" />
          <div className="flex items-center justify-between p-3 rounded-xl border border-theme bg-theme-panel/50">
            <label className="text-[9px] font-bold opacity-60 uppercase">Cor da Guia</label>
            <input type="color" value={settings.guideColor || '#4f46e5'} onChange={(e) => handleChange('guideColor', e.target.value)} className="w-8 h-8 rounded-lg border border-theme cursor-pointer bg-theme-panel p-0.5" />
          </div>
        </div>
      </div>

      <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-4">
        <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2 text-theme-accent">Estética do Fundo</h3>
        <div className="flex items-center gap-2">
          <button 
            onClick={() => handleBackgroundChange(settings.backgroundColor, !settings.isTransparent)} 
            className={`flex-1 flex items-center justify-center gap-2 py-3 px-3 rounded-xl border text-[9px] font-black transition-all ${settings.isTransparent ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-panel border-theme opacity-60'}`}
          >
            <i className={`fas ${settings.isTransparent ? 'fa-check-circle' : 'fa-circle-notch'}`}></i>
            <span>Transparência</span>
          </button>

          <div className="relative group">
            <input 
              type="color" 
              value={settings.backgroundColor} 
              onChange={(e) => handleBackgroundChange(e.target.value, false)} 
              className={`w-12 h-12 rounded-xl cursor-pointer border p-1 bg-theme-panel transition-all ${settings.isTransparent ? 'border-theme opacity-20' : 'border-theme-accent shadow-[0_0_15px_rgba(79,70,229,0.2)]'}`} 
            />
            {!settings.isTransparent && <div className="absolute -top-1 -right-1 w-3 h-3 bg-theme-accent rounded-full border-2 border-theme-side"></div>}
          </div>
        </div>
      </div>

      <div className="mt-auto pt-4 space-y-4">
        <div className="p-4 rounded-2xl border border-theme bg-theme-panel/10 space-y-3">
          <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 border-b border-theme pb-2">Exportação</h3>
          <div className="space-y-1 mb-3">
            <label className="text-[8px] font-black uppercase opacity-40 ml-1">Nome do Arquivo</label>
            <input 
              type="text" 
              placeholder="Ex: grid_final"
              value={settings.exportFilename || ''}
              onChange={(e) => handleChange('exportFilename', e.target.value)}
              className="w-full bg-theme-panel border border-theme rounded-xl p-2.5 text-[10px] outline-none font-bold focus:border-theme-accent transition-colors"
            />
          </div>

          <label className="flex items-center gap-3 p-3 rounded-xl border border-theme bg-theme-panel/50 cursor-pointer group transition-all hover:bg-theme-accent/5">
            <div className={`w-4 h-4 rounded border border-theme flex items-center justify-center transition-all ${exportOptions.downloadZip ? 'bg-theme-accent border-theme-accent' : 'bg-transparent'}`}>
              {exportOptions.downloadZip && <i className="fas fa-check text-[8px] text-white"></i>}
              <input type="checkbox" className="hidden" checked={exportOptions.downloadZip} onChange={e => {
                exportOptions.setDownloadZip(e.target.checked);
                exportOptions.setDownloadIndividual(!e.target.checked);
              }} />
            </div>
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase tracking-tight text-theme-main">Salvar Zipado</span>
              <span className="text-[8px] opacity-40 uppercase">Pacote Único (.zip)</span>
            </div>
          </label>
        </div>

        <button 
          disabled={images.length === 0 || isProcessing} 
          onClick={onExport} 
          className={`w-full flex items-center justify-center gap-3 py-4 px-4 rounded-xl font-black text-[11px] transition-all active:scale-95 shadow-2xl disabled:opacity-30 uppercase tracking-widest relative group overflow-hidden ${isProcessing ? 'bg-theme-panel text-theme-accent' : 'bg-theme-accent text-theme-inv'}`}
        >
          <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
          {isProcessing ? (
            <><i className="fas fa-spinner animate-spin"></i> <span>Processando...</span></>
          ) : (
            <><i className="fas fa-file-export z-10"></i> <span className="z-10">Exportar Resultado</span></>
          )}
        </button>
      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import JSZip from 'jszip';
import Sidebar from '../components/Sidebar';
import GridPreview from '../components/GridPreview';
import ImageList from '../components/ImageList';
import Header from '../components/Header';
import { GridImage, GridSettings } from '../types';
import { MiauExportEngine } from '../utils/export';

const PRESETS = [
  { name: 'Quadrado (2K)', w: 2048, h: 2048 },
  { name: 'Quadrado (4K)', w: 4096, h: 4096 },
  { name: 'A4 (300DPI)', w: 2480, h: 3508 },
  { name: 'Insta Story', w: 1080, h: 1920 },
  { name: 'Full HD', w: 1920, h: 1080 }
];

const GridTool: React.FC = () => {
  const [images, setImages] = useState<GridImage[]>([]);
  const [downloadIndividual, setDownloadIndividual] = useState(true);
  const [downloadZip, setDownloadZip] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [zoom, setZoom] = useState(0.3);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDraggingOver, setIsDraggingOver] = useState(false);
  const [settings, setSettings] = useState<GridSettings>({
    canvasWidth: 2048,
    canvasHeight: 2048,
    columns: 3,
    innerSpacing: 20,
    verticalSpacing: 20,
    outerMargin: 40,
    backgroundColor: '#0f172a',
    isTransparent: false,
    layoutMode: 'grid',
    itemScale: 0,
    targetShape: 'square',
    showCuttingGuides: false,
    guideOffset: 5,
    guideLength: 30,
    guideThickness: 2,
    guideColor: '#4f46e5',
    makerMode: false,
    makerRepeat: 10,
    alignment: 'center'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);
  const makerInputRef = useRef<HTMLInputElement>(null);

  const applyPreset = (w: number, h: number) => {
    setSettings(prev => ({ ...prev, canvasWidth: w, canvasHeight: h }));
  };

  const processFiles = async (files: File[], isMaker: boolean = false) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    const filteredFiles = files.filter(file => validTypes.includes(file.type));
    const newImages: GridImage[] = [];

    for (const file of filteredFiles) {
      try {
        const url = URL.createObjectURL(file);
        const img = await new Promise<HTMLImageElement>((resolve, reject) => {
          const i = new Image();
          i.onload = () => resolve(i);
          i.onerror = reject;
          i.src = url;
        });

        newImages.push({
          id: uuidv4(),
          file,
          previewUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height,
          isActive: true,
          visible: true
        });
      } catch (err) {
        console.error("Erro ao processar imagem:", file.name);
      }
    }

    if (newImages.length > 0) {
      if (isMaker) {
        setImages([newImages[0]]);
        setSettings(prev => ({ ...prev, makerMode: true, layoutMode: 'auto' }));
      } else {
        setImages(prev => [...prev, ...newImages]);
      }
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      let filesArray = Array.from(e.target.files) as File[];
      processFiles(filesArray);
    }
    if (e.target) e.target.value = '';
  };

  const handleMakerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processFiles([e.target.files[0]], true);
    }
    if (e.target) e.target.value = '';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDraggingOver(true);
  };

  const handleDragLeave = () => {
    setIsDraggingOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDraggingOver(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      processFiles(Array.from(e.dataTransfer.files));
    }
  };

  const removeImage = (id: string) => {
    setImages(prev => {
      const target = prev.find(img => img.id === id);
      if (target) URL.revokeObjectURL(target.previewUrl);
      return prev.filter(img => img.id !== id);
    });
    if (images.length <= 1) setSettings(prev => ({ ...prev, makerMode: false }));
  };

  const toggleActive = (id: string) => {
    setImages(prev => prev.map(img => img.id === id ? { ...img, isActive: !img.isActive } : img));
  };

  const updateActiveCount = (count: number) => {
    setImages(prev => prev.map((img, idx) => ({
      ...img,
      isActive: idx < count
    })));
  };

  const handleReorder = (dragIndex: number, hoverIndex: number) => {
    const newImages = [...images];
    const draggedItem = newImages[dragIndex];
    newImages.splice(dragIndex, 1);
    newImages.splice(hoverIndex, 0, draggedItem);
    setImages(newImages);
  };

  const handleExport = async () => {
    const canvas = document.querySelector('canvas') as HTMLCanvasElement;
    if (!canvas) return;

    setIsProcessing(true);
    try {
      const customName = settings.exportFilename?.trim();
      const fileName = `${customName || `grid_miau_${Date.now()}`}.png`;
      const dataUrl = canvas.toDataURL('image/png', 1.0);

      if (downloadIndividual) {
        await MiauExportEngine.saveImage(dataUrl, fileName);
      }

      if (downloadZip) {
        const zip = new JSZip();
        zip.file(fileName, dataUrl.split(',')[1], { base64: true });
        const content = await zip.generateAsync({ type: "blob" });
        await MiauExportEngine.saveZip(content, `grid_pack_miau_${Date.now()}.zip`);
      }
    } finally {
      setIsProcessing(false);
    }
  };

  const clearAll = useCallback(() => {
    images.forEach(img => { if (img.previewUrl) URL.revokeObjectURL(img.previewUrl); });
    setImages([]); setOffset({ x: 0, y: 0 }); setZoom(0.3);
    setSettings(prev => ({ ...prev, makerMode: false }));
  }, [images]);

  return (
    <div className="flex-1 flex overflow-hidden bg-theme-main">
      <aside className="w-80 flex-shrink-0 border-r overflow-y-auto bg-theme-side border-theme custom-scrollbar">
        <div className="p-4 border-b border-theme bg-black/5">
          <h3 className="text-[10px] font-black uppercase tracking-widest opacity-40 mb-3">Tamanho da Grid</h3>
          <div className="grid grid-cols-2 gap-2">
            {PRESETS.map(p => (
              <button 
                key={p.name} 
                onClick={() => applyPreset(p.w, p.h)}
                className="text-[8px] font-black uppercase p-2 border border-theme rounded-lg bg-theme-panel hover:bg-theme-accent hover:text-white transition-all"
              >
                {p.name}
              </button>
            ))}
          </div>
        </div>
        <Sidebar 
          settings={settings} 
          onSettingsChange={setSettings} 
          onAddFile={() => fileInputRef.current?.click()}
          onAddFolder={() => folderInputRef.current?.click()}
          onAddMaker={() => makerInputRef.current?.click()}
          images={images}
          onUpdateActiveCount={updateActiveCount}
          exportOptions={{ downloadIndividual, setDownloadIndividual, downloadZip, setDownloadZip }}
          onExport={handleExport}
          isProcessing={isProcessing}
        />
      </aside>

      <section 
        className="flex-1 overflow-hidden relative flex flex-col"
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        <Header itemCount={images.length} onClear={clearAll} />

        <div className="flex-1 relative flex flex-col items-center justify-center bg-black/5 overflow-hidden">
          {isDraggingOver && (
            <div className="absolute inset-0 z-[100] bg-theme-accent/20 backdrop-blur-sm flex items-center justify-center border-4 border-dashed border-theme-accent m-4 rounded-[3rem] animate-in fade-in zoom-in duration-300 pointer-events-none">
              <div className="flex flex-col items-center gap-4">
                <div className="w-20 h-20 rounded-full bg-theme-accent text-white flex items-center justify-center text-3xl shadow-2xl animate-bounce">
                  <i className="fas fa-file-import"></i>
                </div>
                <p className="text-xl font-black uppercase tracking-widest text-theme-accent">Solte para Adicionar</p>
              </div>
            </div>
          )}

          <div className="flex-1 w-full h-full">
            <GridPreview 
              images={images} 
              settings={settings} 
              zoom={zoom} 
              offset={offset}
              onOffsetChange={setOffset}
            />
          </div>

          <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-8 bg-theme-side/90 border border-theme/40 py-2.5 px-8 rounded-full shadow-2xl backdrop-blur-xl z-50">
            <div className="flex items-center gap-4 pr-8 border-r border-theme/30">
              <i className="fas fa-search text-[10px] opacity-30"></i>
              <input type="range" min="0.01" max="1" step="0.01" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-48 h-1 bg-theme-accent/10 rounded-lg appearance-none cursor-pointer accent-theme-accent" />
              <span className="text-[10px] font-mono opacity-40 w-12 text-center">{Math.round(zoom * 100)}%</span>
            </div>
            <button onClick={() => { setOffset({ x: 0, y: 0 }); setZoom(0.3); }} className="w-9 h-9 flex items-center justify-center rounded-full hover:bg-theme-accent/20 text-theme-main transition-all group active:scale-90" title="Reset Viewport">
              <i className="fas fa-undo-alt text-[10px] opacity-40 group-hover:opacity-100 group-hover:rotate-[-45deg] transition-all"></i>
            </button>
          </div>
        </div>
      </section>

      <aside className="w-80 flex-shrink-0 border-l overflow-hidden flex flex-col bg-theme-side border-theme">
        <div className="p-4 border-b font-black text-[10px] uppercase tracking-[0.2em] flex justify-between items-center text-theme-muted bg-black/5">
          <span>Item Manager</span>
          <i className="fas fa-layer-group opacity-30"></i>
        </div>
        <ImageList 
          images={images} 
          onRemove={removeImage} 
          onMove={() => {}}
          onToggleActive={toggleActive}
          onReorder={handleReorder}
        />
      </aside>

      <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
      <input type="file" {...({ webkitdirectory: "" } as any)} className="hidden" ref={folderInputRef} onChange={handleFileChange} />
      <input type="file" accept="image/*" className="hidden" ref={makerInputRef} onChange={handleMakerChange} />
    </div>
  );
};

export default GridTool;
